def _bounded_text(
    value: str,
    label: str,
    *,
    maximum: int = MAX_TEXT_LENGTH,
    allow_empty: bool = False,
) -> str:
    if not isinstance(value, str):
        raise ValidationError(f"{label} must be text")
    if (
        (not allow_empty and not value.strip())
        or len(value) > maximum
        or "\x00" in value
    ):
        raise ValidationError(f"{label} must be non-empty bounded text")
    return value


def _utc_timestamp(value: str, label: str) -> str:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise ValidationError(f"{label} must be UTC ISO-8601 with Z suffix")
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValidationError(f"{label} is malformed") from exc
    if parsed.utcoffset() is None or parsed.utcoffset().total_seconds() != 0:
        raise ValidationError(f"{label} must be UTC")
    return value


def _identifier_tuple(
    value: Any, label: str, *, allow_empty: bool = True
) -> tuple[str, ...]:
    if isinstance(value, (str, bytes)):
        raise ValidationError(f"{label} must be an identifier sequence")
    try:
        result = tuple(value)
    except TypeError as exc:
        raise ValidationError(f"{label} must be an identifier sequence") from exc
    if len(result) > MAX_SEQUENCE_ITEMS or (not allow_empty and not result):
        raise ValidationError(f"{label} has invalid bounded cardinality")
    for item in result:
        validate_identifier(item, label)
    if len(set(result)) != len(result):
        raise ValidationError(f"{label} must be unique")
    return result


def _text_tuple(value: Any, label: str, *, allow_empty: bool = True) -> tuple[str, ...]:
    if isinstance(value, (str, bytes)):
        raise ValidationError(f"{label} must be a text sequence")
    try:
        result = tuple(value)
    except TypeError as exc:
        raise ValidationError(f"{label} must be a text sequence") from exc
    if len(result) > MAX_SEQUENCE_ITEMS or (not allow_empty and not result):
        raise ValidationError(f"{label} has invalid bounded cardinality")
    for item in result:
        _bounded_text(item, label, maximum=MAX_SHORT_TEXT_LENGTH)
    if len(set(result)) != len(result):
        raise ValidationError(f"{label} must be unique")
    return result


def _hash_tuple(value: Any, label: str, *, allow_empty: bool = True) -> tuple[str, ...]:
    if isinstance(value, (str, bytes)):
        raise ValidationError(f"{label} must be a SHA-256 sequence")
    try:
        result = tuple(value)
    except TypeError as exc:
        raise ValidationError(f"{label} must be a SHA-256 sequence") from exc
    if len(result) > MAX_SEQUENCE_ITEMS or (not allow_empty and not result):
        raise ValidationError(f"{label} has invalid bounded cardinality")
    for item in result:
        validate_sha256(item, label)
    if len(set(result)) != len(result):
        raise ValidationError(f"{label} must be unique")
    return result


def _bounded_mapping(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ValidationError(f"{label} must be an object")
    frozen = freeze_json(value)
    encoded = canonical_json_bytes(thaw_json(frozen))
    if len(encoded) > MAX_CANONICAL_OBJECT_BYTES:
        raise ValidationError(f"{label} exceeds the canonical object byte limit")
    return frozen


def _enum_value(value: Any, enum_type: type[StrEnum], label: str) -> StrEnum:
    try:
        return enum_type(value)
    except (TypeError, ValueError) as exc:
        raise ValidationError(f"invalid {label}") from exc


def _serialize(value: Any) -> Any:
    if isinstance(value, StrEnum):
        return value.value
    if isinstance(value, Role):
        return value.value
    if isinstance(value, ObjectReference | ObjectLink | ClaimReview):
        return value.to_dict()
    if isinstance(value, Mapping):
        return {key: _serialize(child) for key, child in value.items()}
    if isinstance(value, tuple):
        return [_serialize(child) for child in value]
    return value


@dataclass(frozen=True)
class ObjectReference:
    """An exact, version-bound dependency on another research object."""

    object_type: str
    object_id: str
    content_hash: str
    relation: str
    evaluated: bool = False

    def __post_init__(self) -> None:
        if not isinstance(self.object_type, str) or not _OBJECT_TYPE_RE.fullmatch(
            self.object_type
        ):
            raise ValidationError("invalid referenced object type")
        validate_identifier(self.object_id, "referenced object ID")
        validate_sha256(self.content_hash, "referenced object content SHA-256")
        if not isinstance(self.relation, str) or not _RELATION_RE.fullmatch(
            self.relation
        ):
            raise ValidationError("invalid parent relation")
        if not isinstance(self.evaluated, bool):
            raise ValidationError("parent evaluated flag must be boolean")

    def to_dict(self) -> dict[str, Any]:
        return {
            "object_type": self.object_type,
            "object_id": self.object_id,
            "content_hash": self.content_hash,
            "relation": self.relation,
            "evaluated": self.evaluated,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ObjectReference":
        required = {"object_type", "object_id", "content_hash", "relation", "evaluated"}
        if not isinstance(value, Mapping) or set(value) != required:
            raise ValidationError(
                "object reference schema is incomplete or has unknown fields"
            )
        try:
            return cls(**dict(value))
        except TypeError as exc:
            raise ValidationError("malformed object reference") from exc


@dataclass(frozen=True)
class ObjectLink:
    """A logical relationship; unlike a parent it need not bind a revision."""

    object_type: str
    object_id: str
    relation: str
    required: bool = True

    def __post_init__(self) -> None:
        if not isinstance(self.object_type, str) or not _OBJECT_TYPE_RE.fullmatch(
            self.object_type
        ):
            raise ValidationError("invalid linked object type")
        validate_identifier(self.object_id, "linked object ID")
        if not isinstance(self.relation, str) or not _RELATION_RE.fullmatch(
            self.relation
        ):
            raise ValidationError("invalid relationship type")
        if not isinstance(self.required, bool):
            raise ValidationError("relationship required flag must be boolean")

    def to_dict(self) -> dict[str, Any]:
        return {
            "object_type": self.object_type,
            "object_id": self.object_id,
            "relation": self.relation,
            "required": self.required,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ObjectLink":
        required = {"object_type", "object_id", "relation", "required"}
        if not isinstance(value, Mapping) or set(value) != required:
            raise ValidationError(
                "object link schema is incomplete or has unknown fields"
            )
        try:
            return cls(**dict(value))
        except TypeError as exc:
            raise ValidationError("malformed object link") from exc


@dataclass(frozen=True)
class ClaimReview:
    reviewer: Role
    timestamp: str
    verification_status: VerificationStatus
    reason: str
    evidence_ids: tuple[str, ...] = ()
    source_artifact_ids: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not isinstance(self.reviewer, Role):
            raise ValidationError("claim reviewer must be a Role")
        _utc_timestamp(self.timestamp, "claim review timestamp")
        object.__setattr__(
            self,
            "verification_status",
            _enum_value(
                self.verification_status, VerificationStatus, "claim review status"
            ),
        )
        _bounded_text(self.reason, "claim review reason")
        object.__setattr__(
            self,
            "evidence_ids",
            _identifier_tuple(self.evidence_ids, "claim review evidence IDs"),
        )
        object.__setattr__(
            self,
            "source_artifact_ids",
            _hash_tuple(self.source_artifact_ids, "claim review source artifact IDs"),
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "reviewer": self.reviewer.value,
            "timestamp": self.timestamp,
            "verification_status": self.verification_status.value,
            "reason": self.reason,
            "evidence_ids": list(self.evidence_ids),
            "source_artifact_ids": list(self.source_artifact_ids),
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ClaimReview":
        required = {
            "reviewer",
            "timestamp",
            "verification_status",
            "reason",
            "evidence_ids",
            "source_artifact_ids",
        }
        if not isinstance(value, Mapping) or set(value) != required:
            raise ValidationError(
                "claim review schema is incomplete or has unknown fields"
            )
        try:
            return cls(
                reviewer=Role(value["reviewer"]),
                timestamp=value["timestamp"],
                verification_status=VerificationStatus(value["verification_status"]),
                reason=value["reason"],
                evidence_ids=tuple(value["evidence_ids"]),
                source_artifact_ids=tuple(value["source_artifact_ids"]),
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise ValidationError("malformed claim review") from exc


@dataclass(frozen=True, slots=True)
class ClaimSemanticsDependencyBinding:
    """Exact same-run canonical Claim revision named as a dependency."""

    claim_id: str
    content_hash: str
    state_artifact_hash: str
    state_artifact_record_hash: str
    materialization_event_id: str
    materialization_event_hash: str

    def __post_init__(self) -> None:
        validate_identifier(self.claim_id, "claim-semantics dependency claim ID")
        for label, value in (
            ("dependency content SHA-256", self.content_hash),
            ("dependency state artifact SHA-256", self.state_artifact_hash),
            ("dependency state artifact record hash", self.state_artifact_record_hash),
            ("dependency materialization event hash", self.materialization_event_hash),
        ):
            validate_sha256(value, label)
        validate_identifier(
            self.materialization_event_id,
            "dependency materialization event ID",
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "claim_id": self.claim_id,
            "content_hash": self.content_hash,
            "state_artifact_hash": self.state_artifact_hash,
            "state_artifact_record_hash": self.state_artifact_record_hash,
            "materialization_event_id": self.materialization_event_id,
            "materialization_event_hash": self.materialization_event_hash,
        }

    @classmethod
    def from_dict(
        cls,
        value: Mapping[str, Any],
    ) -> "ClaimSemanticsDependencyBinding":
        expected = {
            "claim_id",
            "content_hash",
            "state_artifact_hash",
            "state_artifact_record_hash",
            "materialization_event_id",
            "materialization_event_hash",
        }
        if not isinstance(value, Mapping) or set(value) != expected:
            raise ValidationError(
                "claim-semantics dependency binding schema is incomplete"
            )
        try:
            return cls(**dict(value))
        except TypeError as exc:
            raise ValidationError(
                "claim-semantics dependency binding is malformed"
            ) from exc


@dataclass(frozen=True, slots=True)
class ClaimSemanticsProposal:
    """Non-authoritative semantic projection retained for independent review."""

    proposal_id: str
    run_id: str
    claim_graph_artifact_hash: str
    claim_graph_artifact_record_hash: str
    claim_id: str
    claim_text: str
    claim_producer_role: Role
    claim_evidence_use: ClaimEvidenceUse
    claim_type: ClaimType
    scope: str
    confidence: float
    expressed_strength: ClaimStrength
    permitted_strength: ClaimStrength
    verification_method: str
    dependency_bindings: tuple[ClaimSemanticsDependencyBinding, ...]

    def __post_init__(self) -> None:
        validate_identifier(self.proposal_id, "claim-semantics proposal ID")
        validate_identifier(self.run_id, "claim-semantics proposal run ID")
        validate_identifier(self.claim_id, "claim-semantics proposal claim ID")
        validate_sha256(
            self.claim_graph_artifact_hash,
            "claim-semantics proposal graph SHA-256",
        )
        validate_sha256(
            self.claim_graph_artifact_record_hash,
            "claim-semantics proposal graph record hash",
        )
        _bounded_text(self.claim_text, "claim-semantics proposal claim text")
        if not isinstance(self.claim_producer_role, Role):
            raise ValidationError(
                "claim-semantics proposal producer role must be typed"
            )
        if self.claim_producer_role is Role.CLAIM_VERIFIER:
            raise AuthorizationError(
                "claim verifier cannot propose semantics for its own claim"
            )
        object.__setattr__(
            self,
            "claim_evidence_use",
            _enum_value(
                self.claim_evidence_use,
                ClaimEvidenceUse,
                "claim-semantics proposal evidence use",
            ),
        )
        if self.claim_evidence_use is not ClaimEvidenceUse.SCIENTIFIC:
            raise ValidationError(
                "scientific claim-semantics proposal requires SCIENTIFIC graph use"
            )
        object.__setattr__(
            self,
            "claim_type",
            _enum_value(
                self.claim_type,
                ClaimType,
                "claim-semantics proposal claim type",
            ),
        )
        _bounded_text(self.scope, "claim-semantics proposal scope")
        if (
            isinstance(self.confidence, bool)
            or not isinstance(self.confidence, (int, float))
            or not 0.0 <= float(self.confidence) <= 1.0
        ):
            raise ValidationError("claim-semantics proposal confidence is invalid")
        object.__setattr__(self, "confidence", float(self.confidence))
        object.__setattr__(
            self,
            "expressed_strength",
            _enum_value(
                self.expressed_strength,
                ClaimStrength,
                "claim-semantics proposal expressed strength",
            ),
        )
        object.__setattr__(
            self,
            "permitted_strength",
            _enum_value(
                self.permitted_strength,
                ClaimStrength,
                "claim-semantics proposal permitted strength",
            ),
        )
        if (
            _CLAIM_STRENGTH_RANK[self.expressed_strength]
            > _CLAIM_STRENGTH_RANK[self.permitted_strength]
        ):
            raise ValidationError(
                "claim-semantics proposal exceeds its proposed permitted strength"
            )
        _bounded_text(
            self.verification_method,
            "claim-semantics proposal verification method",
            maximum=MAX_SHORT_TEXT_LENGTH,
        )
        dependencies = tuple(
            item
            if isinstance(item, ClaimSemanticsDependencyBinding)
            else ClaimSemanticsDependencyBinding.from_dict(item)
            for item in self.dependency_bindings
        )
        if (
            len(dependencies) > MAX_SEQUENCE_ITEMS
            or len({item.claim_id for item in dependencies}) != len(dependencies)
            or len({item.state_artifact_hash for item in dependencies})
            != len(dependencies)
            or dependencies
            != tuple(sorted(dependencies, key=lambda item: item.claim_id))
        ):
            raise ValidationError(
                "claim-semantics proposal dependencies must be unique and canonical"
            )
        if self.claim_id in {item.claim_id for item in dependencies}:
            raise ValidationError(
                "claim-semantics proposal cannot depend on the same claim"
            )
        object.__setattr__(self, "dependency_bindings", dependencies)

    @property
    def dependency_claim_ids(self) -> tuple[str, ...]:
        return tuple(item.claim_id for item in self.dependency_bindings)

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": CLAIM_SEMANTICS_PROPOSAL_PAYLOAD_SCHEMA,
            "proposal_id": self.proposal_id,
            "run_id": self.run_id,
            "claim_graph_artifact_hash": self.claim_graph_artifact_hash,
            "claim_graph_artifact_record_hash": (self.claim_graph_artifact_record_hash),
            "claim_id": self.claim_id,
            "claim_text": self.claim_text,
            "claim_producer_role": self.claim_producer_role.value,
            "claim_evidence_use": self.claim_evidence_use.value,
            "claim_type": self.claim_type.value,
            "scope": self.scope,
            "confidence": self.confidence,
            "expressed_strength": self.expressed_strength.value,
            "permitted_strength": self.permitted_strength.value,
            "verification_method": self.verification_method,
            "dependency_bindings": [
                item.to_dict() for item in self.dependency_bindings
            ],
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ClaimSemanticsProposal":
        expected = {
            "schema_version",
            "proposal_id",
            "run_id",
            "claim_graph_artifact_hash",
            "claim_graph_artifact_record_hash",
            "claim_id",
            "claim_text",
            "claim_producer_role",
            "claim_evidence_use",
            "claim_type",
            "scope",
            "confidence",
            "expressed_strength",
            "permitted_strength",
            "verification_method",
            "dependency_bindings",
        }
        if not isinstance(value, Mapping) or set(value) != expected:
            raise ValidationError("claim-semantics proposal schema is incomplete")
        if value["schema_version"] != CLAIM_SEMANTICS_PROPOSAL_PAYLOAD_SCHEMA:
            raise ValidationError("unsupported claim-semantics proposal schema")
        if not isinstance(value["dependency_bindings"], list):
            raise ValidationError(
                "claim-semantics proposal dependencies must be a list"
            )
        try:
            return cls(
                proposal_id=value["proposal_id"],
                run_id=value["run_id"],
                claim_graph_artifact_hash=value["claim_graph_artifact_hash"],
                claim_graph_artifact_record_hash=(
                    value["claim_graph_artifact_record_hash"]
                ),
                claim_id=value["claim_id"],
                claim_text=value["claim_text"],
                claim_producer_role=Role(value["claim_producer_role"]),
                claim_evidence_use=ClaimEvidenceUse(value["claim_evidence_use"]),
                claim_type=ClaimType(value["claim_type"]),
                scope=value["scope"],
                confidence=value["confidence"],
                expressed_strength=ClaimStrength(value["expressed_strength"]),
                permitted_strength=ClaimStrength(value["permitted_strength"]),
                verification_method=value["verification_method"],
                dependency_bindings=tuple(
                    ClaimSemanticsDependencyBinding.from_dict(item)
                    for item in value["dependency_bindings"]
                ),
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise ValidationError("claim-semantics proposal is malformed") from exc


@dataclass(frozen=True, slots=True)
class ClaimSemanticsJudgmentRequest:
    """Exact retained inputs required for a live scientific semantics review."""

    subject_id: str
    accepted_outcome: str
    evidence_hashes: tuple[str, ...]
    context_hashes: tuple[str, ...]
    instructions: str
    input_text: str
    output_schema: Mapping[str, Any]
    prompt_template_id: str
    prompt_template_version: str
    prompt_template_hash: str
    governing_rule: str

    def __post_init__(self) -> None:
        validate_identifier(self.subject_id, "claim-semantics judgment subject ID")
        _bounded_text(self.accepted_outcome, "claim-semantics accepted outcome")
        object.__setattr__(
            self,
            "evidence_hashes",
            _hash_tuple(
                self.evidence_hashes,
                "claim-semantics judgment evidence hashes",
                allow_empty=False,
            ),
        )
        object.__setattr__(
            self,
            "context_hashes",
            _hash_tuple(
                self.context_hashes,
                "claim-semantics judgment context hashes",
                allow_empty=False,
            ),
        )
        if set(self.evidence_hashes).intersection(self.context_hashes):
            raise ValidationError(
                "claim-semantics judgment evidence and context must be distinct"
            )
        _bounded_text(self.instructions, "claim-semantics judgment instructions")
        _bounded_text(
            self.input_text,
            "claim-semantics judgment input",
            maximum=MAX_CANONICAL_OBJECT_BYTES,
        )
        object.__setattr__(
            self,
            "output_schema",
            freeze_json(dict(self.output_schema)),
        )
        validate_identifier(
            self.prompt_template_id,
            "claim-semantics prompt-template ID",
        )
        _bounded_text(
            self.prompt_template_version,
            "claim-semantics prompt-template version",
        )
        validate_sha256(
            self.prompt_template_hash,
            "claim-semantics prompt-template SHA-256",
        )
        _bounded_text(self.governing_rule, "claim-semantics governing rule")

    @property
    def instructions_bytes(self) -> bytes:
        return self.instructions.encode("utf-8")

    @property
    def input_bytes(self) -> bytes:
        return self.input_text.encode("utf-8")

    @property
    def output_schema_bytes(self) -> bytes:
        return canonical_json_bytes(thaw_json(self.output_schema))


@dataclass(frozen=True, slots=True)
class ScientificDatasetUsageJudgmentRequest(ClaimSemanticsJudgmentRequest):
    """Exact retained inputs for one audited Dataset usage/license review."""


@dataclass(frozen=True, slots=True)
class ScientificClaimQualifierAuthority:
    """Fresh audited authority for one exact claim qualifier assertion."""

    run_id: str
    subject_id: str
    evidence_id: str
    evidence_kind: GraphEvidenceKind
    claim_id: str
    claim_text: str
    claim_producer_role: Role
    claim_confirmatory: bool
    claim_evidence_use: ClaimEvidenceUse
    assertion_text: str
    qualifier_projection_sha256: str
    result_id: str
    result_content_hash: str
    result_state_artifact_hash: str
    result_state_record_hash: str
    result_materialization_event_id: str
    result_materialization_event_hash: str
    execution_run_id: str
    run_content_hash: str
    run_state_artifact_hash: str
    run_state_record_hash: str
    run_materialization_event_id: str
    run_materialization_event_hash: str
    bundle_completion_artifact_hash: str
    bundle_completion_record_hash: str
    bundle_completion_event_id: str
    bundle_completion_event_hash: str
    bundle_completion_event_index: int
    bundle_statistical_test_id: str | None
    source_artifact_hashes: tuple[str, ...]
    source_artifact_record_hashes: tuple[str, ...]
    semantic_judgment_artifact_hash: str
    semantic_judgment_record_hash: str
    authority_artifact_hash: str
    authority_record_hash: str

    def __post_init__(self) -> None:
        for label, value in (
            ("claim-qualifier run ID", self.run_id),
            ("claim-qualifier subject ID", self.subject_id),
            ("claim-qualifier evidence ID", self.evidence_id),
            ("claim-qualifier claim ID", self.claim_id),
            ("claim-qualifier Result ID", self.result_id),
            ("claim-qualifier execution Run ID", self.execution_run_id),
            (
                "claim-qualifier Result materialization event ID",
                self.result_materialization_event_id,
            ),
            (
                "claim-qualifier Run materialization event ID",
                self.run_materialization_event_id,
            ),
            (
                "claim-qualifier bundle-completion event ID",
                self.bundle_completion_event_id,
            ),
        ):
            validate_identifier(value, label)
        if self.evidence_kind not in {
            GraphEvidenceKind.SCOPE_QUALIFIER,
            GraphEvidenceKind.LIMITATION,
        }:
            raise ValidationError(
                "scientific claim qualifier requires a scope or limitation kind"
            )
        _bounded_text(self.claim_text, "claim-qualifier claim text")
        _bounded_text(self.assertion_text, "claim-qualifier assertion text")
        if (
            not isinstance(self.claim_producer_role, Role)
            or self.claim_producer_role is Role.CLAIM_VERIFIER
        ):
            raise AuthorizationError(
                "scientific claim qualifier requires a non-verifier claim producer"
            )
        if not isinstance(self.claim_confirmatory, bool):
            raise ValidationError(
                "scientific claim qualifier confirmatory flag must be boolean"
            )
        if not isinstance(self.claim_evidence_use, ClaimEvidenceUse):
            raise ValidationError(
                "scientific claim qualifier evidence use must be typed"
            )
        if self.bundle_statistical_test_id is not None:
            validate_identifier(
                self.bundle_statistical_test_id,
                "claim-qualifier bundle StatisticalTest ID",
            )
        if (
            not isinstance(self.bundle_completion_event_index, int)
            or isinstance(self.bundle_completion_event_index, bool)
            or self.bundle_completion_event_index < 0
        ):
            raise ValidationError(
                "claim-qualifier bundle-completion event index is invalid"
            )
        for label, value in (
            (
                "claim-qualifier projection SHA-256",
                self.qualifier_projection_sha256,
            ),
            ("claim-qualifier Result content hash", self.result_content_hash),
            (
                "claim-qualifier Result state artifact SHA-256",
                self.result_state_artifact_hash,
            ),
            (
                "claim-qualifier Result state record hash",
                self.result_state_record_hash,
            ),
            (
                "claim-qualifier Result materialization event hash",
                self.result_materialization_event_hash,
            ),
            ("claim-qualifier Run content hash", self.run_content_hash),
            (
                "claim-qualifier Run state artifact SHA-256",
                self.run_state_artifact_hash,
            ),
            ("claim-qualifier Run state record hash", self.run_state_record_hash),
            (
                "claim-qualifier Run materialization event hash",
                self.run_materialization_event_hash,
            ),
            (
                "claim-qualifier bundle-completion artifact SHA-256",
                self.bundle_completion_artifact_hash,
            ),
            (
                "claim-qualifier bundle-completion record hash",
                self.bundle_completion_record_hash,
            ),
            (
                "claim-qualifier bundle-completion event hash",
                self.bundle_completion_event_hash,
            ),
            (
                "claim-qualifier semantic judgment SHA-256",
                self.semantic_judgment_artifact_hash,
            ),
            (
                "claim-qualifier semantic judgment record hash",
                self.semantic_judgment_record_hash,
            ),
            (
                "claim-qualifier authority artifact SHA-256",
                self.authority_artifact_hash,
            ),
            ("claim-qualifier authority record hash", self.authority_record_hash),
        ):
            validate_sha256(value, label)
        object.__setattr__(
            self,
            "source_artifact_hashes",
            _hash_tuple(
                self.source_artifact_hashes,
                "claim-qualifier source artifact hashes",
                allow_empty=False,
            ),
        )
        object.__setattr__(
            self,
            "source_artifact_record_hashes",
            _hash_tuple(
                self.source_artifact_record_hashes,
                "claim-qualifier source record hashes",
                allow_empty=False,
            ),
        )
        if len(self.source_artifact_hashes) != len(self.source_artifact_record_hashes):
            raise ValidationError(
                "claim-qualifier source artifacts and record hashes differ"
            )

    @property
    def scientific_evidence_eligible(self) -> bool:
        """Eligibility is derived only after every fresh resolver succeeds."""

        return True


@dataclass(frozen=True, slots=True)
class ClaimSemanticsReceipt:
    """Claim-verifier attestation over every writer-visible semantic field.

    Non-evidentiary fixture semantics are retained without writer authority.
    Scientific semantics require fresh replay of the exact claim-specific
    audited judgment and every kind-specific source authority; the enum value
    and a verifier role alone never grant that authority.
    """

    receipt_id: str
    run_id: str
    claim_graph_artifact_hash: str
    claim_graph_artifact_record_hash: str
    claim_id: str
    claim_text: str
    claim_producer_role: Role
    claim_evidence_use: ClaimEvidenceUse
    claim_type: ClaimType
    scope: str
    confidence: float
    expressed_strength: ClaimStrength
    permitted_strength: ClaimStrength
    verification_method: str
    dependency_bindings: tuple[ClaimSemanticsDependencyBinding, ...]
    evidence_scope: ClaimSemanticsEvidenceScope
    semantic_proposal_artifact_hash: str | None = None
    reference_support_semantic_judgment_artifact_hash: str | None = None
    semantic_authority_artifact_hash: str | None = None
    scientific_writer_eligible: bool = field(init=False)

    def __post_init__(self) -> None:
        validate_identifier(self.receipt_id, "claim-semantics receipt ID")
        validate_identifier(self.run_id, "claim-semantics run ID")
        validate_identifier(self.claim_id, "claim-semantics claim ID")
        validate_sha256(
            self.claim_graph_artifact_hash,
            "claim-semantics graph artifact SHA-256",
        )
        validate_sha256(
            self.claim_graph_artifact_record_hash,
            "claim-semantics graph artifact record hash",
        )
        _bounded_text(self.claim_text, "claim-semantics claim text")
        if not isinstance(self.claim_producer_role, Role):
            raise ValidationError("claim-semantics producer role must be typed")
        if self.claim_producer_role is Role.CLAIM_VERIFIER:
            raise AuthorizationError(
                "claim verifier cannot produce the claim whose semantics it attests"
            )
        object.__setattr__(
            self,
            "claim_evidence_use",
            _enum_value(
                self.claim_evidence_use,
                ClaimEvidenceUse,
                "claim-semantics evidence use",
            ),
        )
        object.__setattr__(
            self,
            "claim_type",
            _enum_value(self.claim_type, ClaimType, "claim-semantics claim type"),
        )
        _bounded_text(self.scope, "claim-semantics scope")
        if (
            isinstance(self.confidence, bool)
            or not isinstance(self.confidence, (int, float))
            or not 0.0 <= float(self.confidence) <= 1.0
        ):
            raise ValidationError("claim-semantics confidence is invalid")
        object.__setattr__(self, "confidence", float(self.confidence))
        object.__setattr__(
            self,
            "expressed_strength",
            _enum_value(
                self.expressed_strength,
                ClaimStrength,
                "claim-semantics expressed strength",
            ),
        )
        object.__setattr__(
            self,
            "permitted_strength",
            _enum_value(
                self.permitted_strength,
                ClaimStrength,
                "claim-semantics permitted strength",
            ),
        )
        if (
            _CLAIM_STRENGTH_RANK[self.expressed_strength]
            > _CLAIM_STRENGTH_RANK[self.permitted_strength]
        ):
            raise ValidationError(
                "claim-semantics expression exceeds its attested permitted strength"
            )
        _bounded_text(
            self.verification_method,
            "claim-semantics verification method",
            maximum=MAX_SHORT_TEXT_LENGTH,
        )
        dependencies = tuple(
            item
            if isinstance(item, ClaimSemanticsDependencyBinding)
            else ClaimSemanticsDependencyBinding.from_dict(item)
            for item in self.dependency_bindings
        )
        if (
            len(dependencies) > MAX_SEQUENCE_ITEMS
            or len({item.claim_id for item in dependencies}) != len(dependencies)
            or len({item.state_artifact_hash for item in dependencies})
            != len(dependencies)
            or dependencies
            != tuple(sorted(dependencies, key=lambda item: item.claim_id))
        ):
            raise ValidationError(
                "claim-semantics dependency bindings must be bounded, unique, and canonical"
            )
        if self.claim_id in {item.claim_id for item in dependencies}:
            raise ValidationError("claim semantics cannot depend on the same claim")
        object.__setattr__(self, "dependency_bindings", dependencies)
        object.__setattr__(
            self,
            "evidence_scope",
            _enum_value(
                self.evidence_scope,
                ClaimSemanticsEvidenceScope,
                "claim-semantics evidence scope",
            ),
        )
        if self.semantic_proposal_artifact_hash is not None:
            validate_sha256(
                self.semantic_proposal_artifact_hash,
                "claim-semantics proposal artifact SHA-256",
            )
        if self.semantic_authority_artifact_hash is not None:
            validate_sha256(
                self.semantic_authority_artifact_hash,
                "claim-semantics semantic authority artifact SHA-256",
            )
        if self.reference_support_semantic_judgment_artifact_hash is not None:
            validate_sha256(
                self.reference_support_semantic_judgment_artifact_hash,
                "claim-semantics reference-support judgment SHA-256",
            )
        scientific = (
            self.evidence_scope is ClaimSemanticsEvidenceScope.SCIENTIFIC_EVIDENCE
        )
        if scientific != (
            self.semantic_proposal_artifact_hash is not None
            and self.reference_support_semantic_judgment_artifact_hash is not None
            and self.semantic_authority_artifact_hash is not None
        ) or (
            not scientific
            and (
                self.semantic_proposal_artifact_hash is not None
                or self.reference_support_semantic_judgment_artifact_hash is not None
                or self.semantic_authority_artifact_hash is not None
            )
        ):
            raise ValidationError(
                "scientific claim semantics require an explicit proposal, "
                "reference-support judgment, and authority"
            )
        if not scientific and self.claim_evidence_use is ClaimEvidenceUse.SCIENTIFIC:
            raise ValidationError(
                "non-evidentiary claim semantics cannot relabel scientific graph use"
            )
        object.__setattr__(self, "scientific_writer_eligible", scientific)

    @property
    def dependency_claim_ids(self) -> tuple[str, ...]:
        return tuple(item.claim_id for item in self.dependency_bindings)

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": CLAIM_SEMANTICS_RECEIPT_PAYLOAD_SCHEMA,
            "receipt_id": self.receipt_id,
            "run_id": self.run_id,
            "claim_graph_artifact_hash": self.claim_graph_artifact_hash,
            "claim_graph_artifact_record_hash": (self.claim_graph_artifact_record_hash),
            "claim_id": self.claim_id,
            "claim_text": self.claim_text,
            "claim_producer_role": self.claim_producer_role.value,
            "claim_evidence_use": self.claim_evidence_use.value,
            "claim_type": self.claim_type.value,
            "scope": self.scope,
            "confidence": self.confidence,
            "expressed_strength": self.expressed_strength.value,
            "permitted_strength": self.permitted_strength.value,
            "verification_method": self.verification_method,
            "dependency_bindings": [
                item.to_dict() for item in self.dependency_bindings
            ],
            "evidence_scope": self.evidence_scope.value,
            "semantic_proposal_artifact_hash": (self.semantic_proposal_artifact_hash),
            "reference_support_semantic_judgment_artifact_hash": (
                self.reference_support_semantic_judgment_artifact_hash
            ),
            "semantic_authority_artifact_hash": (self.semantic_authority_artifact_hash),
            "scientific_writer_eligible": self.scientific_writer_eligible,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ClaimSemanticsReceipt":
        expected = {
            "schema_version",
            "receipt_id",
            "run_id",
            "claim_graph_artifact_hash",
            "claim_graph_artifact_record_hash",
            "claim_id",
            "claim_text",
            "claim_producer_role",
            "claim_evidence_use",
            "claim_type",
            "scope",
            "confidence",
            "expressed_strength",
            "permitted_strength",
            "verification_method",
            "dependency_bindings",
            "evidence_scope",
            "semantic_proposal_artifact_hash",
            "reference_support_semantic_judgment_artifact_hash",
            "semantic_authority_artifact_hash",
            "scientific_writer_eligible",
        }
        if not isinstance(value, Mapping) or set(value) != expected:
            raise ValidationError("claim-semantics receipt schema is incomplete")
        if value["schema_version"] != CLAIM_SEMANTICS_RECEIPT_PAYLOAD_SCHEMA:
            raise ValidationError("unsupported claim-semantics receipt schema")
        if not isinstance(value["dependency_bindings"], list):
            raise ValidationError("claim-semantics dependencies must be a list")
        try:
            receipt = cls(
                receipt_id=value["receipt_id"],
                run_id=value["run_id"],
                claim_graph_artifact_hash=value["claim_graph_artifact_hash"],
                claim_graph_artifact_record_hash=(
                    value["claim_graph_artifact_record_hash"]
                ),
                claim_id=value["claim_id"],
                claim_text=value["claim_text"],
                claim_producer_role=Role(value["claim_producer_role"]),
                claim_evidence_use=ClaimEvidenceUse(value["claim_evidence_use"]),
                claim_type=ClaimType(value["claim_type"]),
                scope=value["scope"],
                confidence=value["confidence"],
                expressed_strength=ClaimStrength(value["expressed_strength"]),
                permitted_strength=ClaimStrength(value["permitted_strength"]),
                verification_method=value["verification_method"],
                dependency_bindings=tuple(
                    ClaimSemanticsDependencyBinding.from_dict(item)
                    for item in value["dependency_bindings"]
                ),
                evidence_scope=ClaimSemanticsEvidenceScope(value["evidence_scope"]),
                semantic_proposal_artifact_hash=(
                    value["semantic_proposal_artifact_hash"]
                ),
                reference_support_semantic_judgment_artifact_hash=(
                    value["reference_support_semantic_judgment_artifact_hash"]
                ),
                semantic_authority_artifact_hash=(
                    value["semantic_authority_artifact_hash"]
                ),
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise ValidationError("claim-semantics receipt is malformed") from exc
        if (
            value["scientific_writer_eligible"]
            is not receipt.scientific_writer_eligible
        ):
            raise ValidationError("claim-semantics writer eligibility was not derived")
        return receipt


@dataclass(frozen=True, slots=True)
class HypothesisEvaluationAuthority:
    """Source-owned evaluation of one preregistered Hypothesis revision.

    A non-evidentiary mechanical authority is still useful canonical negative
    or null state, but it cannot make a claim, Result, paper, or release
    scientifically eligible.  The scientific scope is derived only when the
    existing Result resolver itself establishes every required authority.
    """

    authority_id: str
    run_id: str
    evidence_scope: HypothesisEvaluationEvidenceScope
    hypothesis_id: str
    prior_hypothesis_content_hash: str
    prior_hypothesis_state_artifact_hash: str
    prior_hypothesis_state_record_hash: str
    result_id: str
    result_content_hash: str
    result_state_artifact_hash: str
    result_state_record_hash: str
    statistical_test_id: str
    statistical_test_content_hash: str
    statistical_test_state_artifact_hash: str
    statistical_test_state_record_hash: str
    evaluation_contract_artifact_hash: str
    evaluation_contract_record_hash: str
    evaluation_contract_sha256: str
    evaluation_policy_id: str
    evaluation_policy_sha256: str
    metric_id: str
    improvement_effect: float
    confidence_low: float
    confidence_high: float
    adjusted_p_value: float | None
    sample_size: int
    outcome: HypothesisStatus
    result_authority_artifact_hashes: tuple[str, ...]
    result_authority_record_hashes: tuple[str, ...]
    statistical_authority_artifact_hashes: tuple[str, ...]
    statistical_authority_record_hashes: tuple[str, ...]
    scientific_result_promotion_authority_artifact_hash: str | None
    backend_execution_authority_artifact_hash: str | None
    scientific_timeline_authority_artifact_hash: str | None
    confirmation_authority_artifact_hash: str | None
    domain_validity_authority_artifact_hash: str | None
    statistical_analysis_authority_artifact_hash: str | None
    evaluator_authority_artifact_hash: str | None
    scientific_obligations_authority_artifact_hash: str | None
    blocker_codes: tuple[str, ...]
    scientific_evidence_eligible: bool
    evaluation_event_id: str
    evaluation_event_hash: str
    evaluation_event_index: int
    ledger_prefix_head_hash: str
    inference_profile_id: str | None = None
    mean_zero_p_upper: float | None = None
    checked_result_assessment_artifact_hash: str | None = None
    checked_result_assessment_record_hash: str | None = None
    paired_metric_projection_authority_artifact_hash: str | None = None
    paired_metric_projection_authority_record_hash: str | None = None
    statistical_use_authority_artifact_hash: str | None = None
    statistical_use_authority_record_hash: str | None = None

    def __post_init__(self) -> None:
        if self.is_bounded_mean:
            from .bounded_mean_inference import BOUNDED_MEAN_PROFILE_ID

            if (
                type(self.inference_profile_id) is not str
                or self.inference_profile_id != BOUNDED_MEAN_PROFILE_ID
                or any(getattr(self, name) is not None
                       for name in _HYPOTHESIS_EVALUATION_V1_ONLY_FIELDS)
                or type(self.sample_size) is not int
                or not 1 <= self.sample_size <= 4096
            ):
                raise ValidationError("bounded hypothesis evaluation mixes inference profiles")
            for name in _HYPOTHESIS_EVALUATION_V2_ONLY_FIELDS - {
                "inference_profile_id", "mean_zero_p_upper",
            }:
                validate_sha256(getattr(self, name), name.replace("_", " "))
            for name in (
                "mean_zero_p_upper", "improvement_effect", "confidence_low", "confidence_high",
            ):
                value = getattr(self, name)
                try:
                    valid_number = type(value) in (int, float) and math.isfinite(value)
                except OverflowError:
                    valid_number = False
                if not valid_number:
                    raise ValidationError("bounded hypothesis evaluation requires finite native numbers")
            if not 0 < self.mean_zero_p_upper <= 1:
                raise ValidationError("bounded hypothesis evaluation requires a positive mean p upper bound")
            if not -1 <= self.confidence_low <= self.confidence_high <= 1:
                raise ValidationError("bounded hypothesis evaluation interval exceeds mean support")
            object.__setattr__(self, "mean_zero_p_upper", float(self.mean_zero_p_upper))
        elif any(getattr(self, name) is not None
                 for name in _HYPOTHESIS_EVALUATION_V2_ONLY_FIELDS):
            raise ValidationError("legacy hypothesis evaluation contains bounded inference fields")
        for name in (
            "authority_id",
            "run_id",
            "hypothesis_id",
            "result_id",
            "statistical_test_id",
            "evaluation_policy_id",
            "metric_id",
            "evaluation_event_id",
        ):
            validate_identifier(getattr(self, name), name.replace("_", " "))
        object.__setattr__(
            self,
            "evidence_scope",
            _enum_value(
                self.evidence_scope,
                HypothesisEvaluationEvidenceScope,
                "hypothesis evaluation evidence scope",
            ),
        )
        object.__setattr__(
            self,
            "outcome",
            _enum_value(
                self.outcome,
                HypothesisStatus,
                "hypothesis evaluation outcome",
            ),
        )
        if self.outcome in {HypothesisStatus.UNTESTED, HypothesisStatus.POST_HOC}:
            raise ValidationError(
                "hypothesis evaluation authority requires a terminal tested outcome"
            )
        for name in (
            "prior_hypothesis_content_hash",
            "prior_hypothesis_state_artifact_hash",
            "prior_hypothesis_state_record_hash",
            "result_content_hash",
            "result_state_artifact_hash",
            "result_state_record_hash",
            "statistical_test_content_hash",
            "statistical_test_state_artifact_hash",
            "statistical_test_state_record_hash",
            "evaluation_contract_artifact_hash",
            "evaluation_contract_record_hash",
            "evaluation_contract_sha256",
            "evaluation_policy_sha256",
            "evaluation_event_hash",
            "ledger_prefix_head_hash",
        ):
            validate_sha256(getattr(self, name), name.replace("_", " "))
        for name in (
            "scientific_result_promotion_authority_artifact_hash",
            "backend_execution_authority_artifact_hash",
            "scientific_timeline_authority_artifact_hash",
            "confirmation_authority_artifact_hash",
            "domain_validity_authority_artifact_hash",
            "statistical_analysis_authority_artifact_hash",
            "evaluator_authority_artifact_hash",
            "scientific_obligations_authority_artifact_hash",
        ):
            value = getattr(self, name)
            if value is not None:
                validate_sha256(value, name.replace("_", " "))
        for hashes_name, records_name in (
            (
                "result_authority_artifact_hashes",
                "result_authority_record_hashes",
            ),
            (
                "statistical_authority_artifact_hashes",
                "statistical_authority_record_hashes",
            ),
        ):
            hashes = _hash_tuple(
                getattr(self, hashes_name),
                hashes_name.replace("_", " "),
                allow_empty=False,
            )
            record_hashes = _hash_tuple(
                getattr(self, records_name),
                records_name.replace("_", " "),
                allow_empty=False,
            )
            if len(hashes) != len(record_hashes):
                raise ValidationError(
                    "hypothesis evaluation authority artifact/record bindings differ"
                )
            object.__setattr__(self, hashes_name, hashes)
            object.__setattr__(self, records_name, record_hashes)
        for name in ("improvement_effect", "confidence_low", "confidence_high"):
            value = getattr(self, name)
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValidationError(f"{name} must be numeric")
            object.__setattr__(self, name, float(value))
        if not self.confidence_low <= self.improvement_effect <= self.confidence_high:
            raise ValidationError(
                "hypothesis evaluation effect lies outside its confidence interval"
            )
        if self.adjusted_p_value is not None:
            if (
                isinstance(self.adjusted_p_value, bool)
                or not isinstance(self.adjusted_p_value, (int, float))
                or not 0.0 <= float(self.adjusted_p_value) <= 1.0
            ):
                raise ValidationError(
                    "hypothesis evaluation adjusted p-value is invalid"
                )
            object.__setattr__(self, "adjusted_p_value", float(self.adjusted_p_value))
        if (
            isinstance(self.sample_size, bool)
            or not isinstance(self.sample_size, int)
            or self.sample_size <= 0
        ):
            raise ValidationError("hypothesis evaluation sample size is invalid")
        object.__setattr__(
            self,
            "blocker_codes",
            _text_tuple(self.blocker_codes, "hypothesis evaluation blockers"),
        )
        if not isinstance(self.scientific_evidence_eligible, bool):
            raise ValidationError(
                "hypothesis evaluation scientific eligibility must be boolean"
            )
        required_scientific = (
            self.scientific_result_promotion_authority_artifact_hash,
            self.backend_execution_authority_artifact_hash,
            self.scientific_timeline_authority_artifact_hash,
            self.confirmation_authority_artifact_hash,
            self.domain_validity_authority_artifact_hash,
            self.statistical_analysis_authority_artifact_hash,
            self.evaluator_authority_artifact_hash,
            self.scientific_obligations_authority_artifact_hash,
        )
        if self.is_bounded_mean:
            # The projection-backed owner replaces legacy generic evaluator /
            # obligations receipts; those obsolete fields must not be invented.
            required_scientific = (
                self.scientific_result_promotion_authority_artifact_hash,
                self.backend_execution_authority_artifact_hash,
                self.scientific_timeline_authority_artifact_hash,
                self.confirmation_authority_artifact_hash,
                self.domain_validity_authority_artifact_hash,
                self.statistical_analysis_authority_artifact_hash,
                self.checked_result_assessment_artifact_hash,
                self.paired_metric_projection_authority_artifact_hash,
                self.statistical_use_authority_artifact_hash,
            )
        if self.scientific_evidence_eligible != (
            self.evidence_scope is HypothesisEvaluationEvidenceScope.SCIENTIFIC_EVIDENCE
            and not self.blocker_codes
            and all(value is not None for value in required_scientific)
        ):
            raise ValidationError(
                "hypothesis evaluation scientific eligibility was not derived"
            )
        if (
            isinstance(self.evaluation_event_index, bool)
            or not isinstance(self.evaluation_event_index, int)
            or self.evaluation_event_index < 0
            or self.ledger_prefix_head_hash != self.evaluation_event_hash
        ):
            raise ValidationError("hypothesis evaluation ledger binding is invalid")

    @property
    def is_bounded_mean(self) -> bool:
        return self.inference_profile_id is not None

    @property
    def artifact_schema_version(self) -> str:
        return "2.0" if self.is_bounded_mean else HYPOTHESIS_EVALUATION_AUTHORITY_SCHEMA_VERSION

    @property
    def evaluation_binding(self) -> dict[str, Any]:
        """Exact event projection, usable for nonrecursive historical custody."""

        facts = {
            "improvement_effect": self.improvement_effect,
            "confidence_low": self.confidence_low,
            "confidence_high": self.confidence_high,
            "sample_size": self.sample_size,
            **({"mean_zero_p_upper": self.mean_zero_p_upper} if self.is_bounded_mean
               else {"adjusted_p_value": self.adjusted_p_value}),
        }
        return {
            "schema_version": (HYPOTHESIS_EVALUATION_EVENT_SCHEMA_V2 if self.is_bounded_mean
                               else HYPOTHESIS_EVALUATION_EVENT_SCHEMA),
            "kind": "HYPOTHESIS_EVALUATED",
            **{name: getattr(self, name) for name in (
                "authority_id", "hypothesis_id", "prior_hypothesis_content_hash",
                "result_id", "result_content_hash", "statistical_test_id",
                "statistical_test_content_hash", "evaluation_contract_artifact_hash",
                "evaluation_policy_sha256",
            )},
            "outcome": self.outcome.value,
            "evidence_scope": self.evidence_scope.value,
            "scientific_evidence_eligible": self.scientific_evidence_eligible,
            "facts": facts,
            "source_artifact_hashes": list(self.source_artifact_hashes),
            **({name: getattr(self, name)
                for name in _HYPOTHESIS_EVALUATION_V2_ONLY_FIELDS - {"mean_zero_p_upper"}}
               if self.is_bounded_mean else {}),
        }

    @property
    def source_artifact_hashes(self) -> tuple[str, ...]:
        return tuple(
            sorted(
                {
                    self.prior_hypothesis_state_artifact_hash,
                    self.result_state_artifact_hash,
                    self.statistical_test_state_artifact_hash,
                    self.evaluation_contract_artifact_hash,
                    *self.result_authority_artifact_hashes,
                    *self.statistical_authority_artifact_hashes,
                    *(
                        value
                        for value in (
                            self.scientific_result_promotion_authority_artifact_hash,
                            self.backend_execution_authority_artifact_hash,
                            self.scientific_timeline_authority_artifact_hash,
                            self.confirmation_authority_artifact_hash,
                            self.domain_validity_authority_artifact_hash,
                            self.statistical_analysis_authority_artifact_hash,
                            self.evaluator_authority_artifact_hash,
                            self.scientific_obligations_authority_artifact_hash,
                            self.checked_result_assessment_artifact_hash,
                            self.paired_metric_projection_authority_artifact_hash,
                            self.statistical_use_authority_artifact_hash,
                        )
                        if value is not None
                    ),
                }
            )
        )

    def to_dict(self) -> dict[str, Any]:
        excluded = (_HYPOTHESIS_EVALUATION_V1_ONLY_FIELDS if self.is_bounded_mean
                    else _HYPOTHESIS_EVALUATION_V2_ONLY_FIELDS)
        value = {
            item.name: _serialize(getattr(self, item.name)) for item in fields(self)
            if item.name not in excluded
        }
        return {
            "schema_version": (HYPOTHESIS_EVALUATION_AUTHORITY_PAYLOAD_SCHEMA_V2
                               if self.is_bounded_mean
                               else HYPOTHESIS_EVALUATION_AUTHORITY_PAYLOAD_SCHEMA),
            **value,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "HypothesisEvaluationAuthority":
        if not isinstance(value, Mapping):
            raise ValidationError("hypothesis evaluation authority schema is incomplete")
        schema = value.get("schema_version")
        if schema == HYPOTHESIS_EVALUATION_AUTHORITY_PAYLOAD_SCHEMA_V2:
            excluded = _HYPOTHESIS_EVALUATION_V1_ONLY_FIELDS
        elif schema == HYPOTHESIS_EVALUATION_AUTHORITY_PAYLOAD_SCHEMA:
            excluded = _HYPOTHESIS_EVALUATION_V2_ONLY_FIELDS
        else:
            raise ValidationError("unsupported hypothesis evaluation authority schema")
        expected = ({item.name for item in fields(cls)} - excluded) | {"schema_version"}
        if not isinstance(value, Mapping) or set(value) != expected:
            raise ValidationError(
                "hypothesis evaluation authority schema is incomplete"
            )
        arguments = {item.name: (None if item.name in excluded else value[item.name])
                     for item in fields(cls)}
        try:
            arguments["evidence_scope"] = HypothesisEvaluationEvidenceScope(
                arguments["evidence_scope"]
            )
            arguments["outcome"] = HypothesisStatus(arguments["outcome"])
            for name in (
                "result_authority_artifact_hashes",
                "result_authority_record_hashes",
                "statistical_authority_artifact_hashes",
                "statistical_authority_record_hashes",
                "blocker_codes",
            ):
                arguments[name] = tuple(arguments[name])
            authority = cls(**arguments)
            if authority.is_bounded_mean != (schema == HYPOTHESIS_EVALUATION_AUTHORITY_PAYLOAD_SCHEMA_V2):
                raise ValidationError("hypothesis evaluation payload and inference profile differ")
            return authority
        except (KeyError, TypeError, ValueError) as exc:
            raise ValidationError(
                "hypothesis evaluation authority is malformed"
            ) from exc


