    def _normalize_specific(self) -> None:
        validate_identifier(self.experiment_id, "run experiment ID")
        _bounded_text(self.code_revision, "run code revision", maximum=512)
        if self.code_version is None:
            object.__setattr__(self, "code_version", self.code_revision)
        elif self.code_version != self.code_revision:
            # Canonical state is produced by the repository kernel, while the
            # executable named by a frozen run specification is an independent
            # content identity.  Preserve the legacy single-identity shape, but
            # permit the only source-owned dual-identity form used by the v2
            # result projection: an exact SHA-256 execution revision.
            execution_digest = self.code_revision.removeprefix("sha256:")
            if (
                not self.code_revision.startswith("sha256:")
                or len(execution_digest) != 64
                or any(
                    character not in "0123456789abcdef"
                    for character in execution_digest
                )
            ):
                raise ValidationError(
                    "run code revision and envelope code version disagree"
                )
        object.__setattr__(
            self, "dataset_ids", _identifier_tuple(self.dataset_ids, "run dataset IDs")
        )
        validate_sha256(
            self.configuration_artifact_hash, "run configuration artifact SHA-256"
        )
        object.__setattr__(
            self,
            "compute_profile",
            _enum_value(self.compute_profile, ComputeProfile, "run compute profile"),
        )
        if isinstance(self.random_seeds, (str, bytes)):
            raise ValidationError("run random seeds must be a sequence")
        seeds = tuple(self.random_seeds)
        if len(seeds) > MAX_SEQUENCE_ITEMS or any(
            isinstance(item, bool) or not isinstance(item, int) or item < 0
            for item in seeds
        ):
            raise ValidationError(
                "run random seeds must be bounded non-negative integers"
            )
        object.__setattr__(self, "random_seeds", seeds)
        object.__setattr__(
            self,
            "output_artifact_hashes",
            _hash_tuple(self.output_artifact_hashes, "run output artifact hashes"),
        )
        _bounded_text(self.evaluator_version, "run evaluator version", maximum=512)
        _utc_timestamp(self.started_at, "run start timestamp")
        if self.completed_at is not None:
            _utc_timestamp(self.completed_at, "run completion timestamp")
            started = datetime.fromisoformat(self.started_at.replace("Z", "+00:00"))
            completed = datetime.fromisoformat(self.completed_at.replace("Z", "+00:00"))
            if completed < started:
                raise ValidationError("run completion precedes start")


