@dataclass(frozen=True, kw_only=True)
class Result(CanonicalResearchObject):
    OBJECT_TYPE: ClassVar[str] = "Result"

    run_ids: tuple[str, ...] = ()
    metric_id: str = ""
    value: Any = None
    unit: str = "dimensionless"
