TResearchObject = TypeVar("TResearchObject", bound=CanonicalResearchObject)


def revise_research_object(
    record: TResearchObject,
    *,
    producer: Role | None = None,
    created_at: str | None = None,
    **changes: Any,
) -> TResearchObject:
    """Create the next immutable revision, explicitly binding its predecessor."""

    forbidden = {
        "object_id",
        "object_type",
        "revision",
        "supersedes_content_hash",
        "content_hash",
    }
    if forbidden & set(changes):
        raise ValidationError(
            "revision helper controls identity and supersession fields"
        )
    return replace(
        record,
        producer=producer or record.producer,
        created_at=created_at or utc_now(),
        revision=record.revision + 1,
        supersedes_content_hash=record.content_hash,
        content_hash=None,
        **changes,
    )


class StateIssueSeverity(StrEnum):
    INFO = "INFO"
    ERROR = "ERROR"


class StateIssueCode(StrEnum):
    ARTIFACT_REGISTRY_CORRUPT = "ARTIFACT_REGISTRY_CORRUPT"
    LEDGER_CORRUPT = "LEDGER_CORRUPT"
    ARTIFACT_METADATA_MISMATCH = "ARTIFACT_METADATA_MISMATCH"
    DUPLICATE_REVISION = "DUPLICATE_REVISION"
    SUPERSESSION_GAP = "SUPERSESSION_GAP"
    STALE_OBJECT = "STALE_OBJECT"
    MISSING_PARENT = "MISSING_PARENT"
    MISSING_RELATIONSHIP = "MISSING_RELATIONSHIP"
    CHANGED_AFTER_EVALUATION = "CHANGED_AFTER_EVALUATION"
    WRONG_CODE = "WRONG_CODE"
    OUTDATED_DERIVED_ARTIFACT = "OUTDATED_DERIVED_ARTIFACT"
    MISSING_PROVENANCE_EDGE = "MISSING_PROVENANCE_EDGE"
    MISSING_MATERIALIZATION_EVENT = "MISSING_MATERIALIZATION_EVENT"
    UNAUTHORIZED_PRODUCER = "UNAUTHORIZED_PRODUCER"
    SEMANTIC_AUTHORITY_INVALID = "SEMANTIC_AUTHORITY_INVALID"


@dataclass(frozen=True)
class StateIssue:
    code: StateIssueCode
    severity: StateIssueSeverity
    object_type: str | None
    object_id: str | None
    content_hash: str | None
    detail: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "code", StateIssueCode(self.code))
        object.__setattr__(self, "severity", StateIssueSeverity(self.severity))
        if self.object_type is not None and not _OBJECT_TYPE_RE.fullmatch(
            self.object_type
        ):
            raise ValidationError("invalid issue object type")
        if self.object_id is not None:
            validate_identifier(self.object_id, "issue object ID")
        if self.content_hash is not None:
            validate_sha256(self.content_hash, "issue content SHA-256")
        _bounded_text(
            self.detail, "state validation issue", maximum=MAX_SHORT_TEXT_LENGTH
        )


@dataclass(frozen=True)
class StateValidationReport:
    valid: bool
    issues: tuple[StateIssue, ...]
    object_count: int
    current_artifact_hashes: tuple[str, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.valid, bool):
            raise ValidationError("state report validity must be boolean")
        if (
            isinstance(self.object_count, bool)
            or not isinstance(self.object_count, int)
            or self.object_count < 0
        ):
            raise ValidationError("state report object count is invalid")
        if not isinstance(self.issues, tuple) or not all(
            isinstance(item, StateIssue) for item in self.issues
        ):
            raise ValidationError("state report issues must be typed")
        object.__setattr__(
            self,
            "current_artifact_hashes",
            _hash_tuple(
                self.current_artifact_hashes, "current research-state artifact hashes"
            ),
        )


@dataclass(frozen=True)
class MaterializedResearchObject:
    research_object: CanonicalResearchObject
    artifact: ArtifactRecord
    event: LedgerEvent


@dataclass(frozen=True)
class ResearchStateAuthorityBinding:
    """Fresh, registry-and-ledger-resolved authority for one canonical object."""

    research_object: CanonicalResearchObject
    artifact_sha256: str
    artifact_record_hash: str
    materialization_event_id: str
    materialization_event_hash: str
    materialization_event_index: int
    authority_artifact_hashes: tuple[str, ...]
    authority_artifact_record_hashes: tuple[str, ...]
    authority_logical_types: tuple[str, ...]
    authority_creator_roles: tuple[Role, ...]
    scientific_evidence_eligible: bool
    claim_semantics: ClaimSemanticsReceipt | None

    def __post_init__(self) -> None:
        if not isinstance(self.research_object, CanonicalResearchObject):
            raise ValidationError("state authority binding requires a canonical object")
        for label, value in (
            ("canonical artifact SHA-256", self.artifact_sha256),
            ("canonical artifact record hash", self.artifact_record_hash),
            ("materialization event hash", self.materialization_event_hash),
        ):
            validate_sha256(value, label)
        validate_identifier(self.materialization_event_id, "materialization event ID")
        if (
            isinstance(self.materialization_event_index, bool)
            or not isinstance(self.materialization_event_index, int)
            or self.materialization_event_index < 0
        ):
            raise ValidationError("materialization event index is invalid")
        hashes = _hash_tuple(
            self.authority_artifact_hashes,
            "resolved authority artifact hashes",
        )
        record_hashes = _hash_tuple(
            self.authority_artifact_record_hashes,
            "resolved authority artifact record hashes",
        )
        if not (
            len(hashes)
            == len(record_hashes)
            == len(self.authority_logical_types)
            == len(self.authority_creator_roles)
        ):
            raise ValidationError("resolved authority artifact bindings are incomplete")
        for value in self.authority_logical_types:
            _bounded_text(value, "authority logical type", maximum=256)
        if not all(isinstance(value, Role) for value in self.authority_creator_roles):
            raise ValidationError("authority creator roles must be typed")
        if not isinstance(self.scientific_evidence_eligible, bool):
            raise ValidationError("scientific evidence eligibility must be boolean")
        if self.claim_semantics is not None and not isinstance(
            self.claim_semantics,
            ClaimSemanticsReceipt,
        ):
            raise ValidationError("resolved claim semantics must be typed")
        if isinstance(self.research_object, Claim):
            if (
                self.research_object.verification_status is VerificationStatus.VERIFIED
                and self.claim_semantics is None
            ):
                raise ValidationError(
                    "verified Claim binding lacks resolved claim semantics"
                )
            if (
                self.claim_semantics is not None
                and self.scientific_evidence_eligible
                and not self.claim_semantics.scientific_writer_eligible
            ):
                raise ValidationError(
                    "Claim binding eligibility exceeds resolved semantics"
                )
        elif self.claim_semantics is not None:
            raise ValidationError(
                "non-Claim authority binding cannot carry claim semantics"
            )


@dataclass(frozen=True)
class ResearchStateAuthoritySnapshot:
    """Validated point-in-time canonical state for downstream evidence consumers."""

    run_id: str
    snapshot_artifact_sha256: str
    snapshot_artifact_record_hash: str
    ledger_head_hash: str
    ledger_event_count: int
    code_version: str
    configuration_hash: str
    entries: tuple[ResearchStateAuthorityBinding, ...]

    def __post_init__(self) -> None:
        validate_identifier(self.run_id, "research-state authority run ID")
        for label, value in (
            ("snapshot artifact SHA-256", self.snapshot_artifact_sha256),
            ("snapshot artifact record hash", self.snapshot_artifact_record_hash),
            ("ledger head hash", self.ledger_head_hash),
            ("configuration hash", self.configuration_hash),
        ):
            validate_sha256(value, label)
        if (
            isinstance(self.ledger_event_count, bool)
            or not isinstance(self.ledger_event_count, int)
            or self.ledger_event_count <= 0
        ):
            raise ValidationError("snapshot ledger event count is invalid")
        _bounded_text(self.code_version, "snapshot code version", maximum=512)
        if not isinstance(self.entries, tuple) or not all(
            isinstance(item, ResearchStateAuthorityBinding) for item in self.entries
        ):
            raise ValidationError("snapshot entries must be typed authority bindings")
        identities = tuple(
            (item.research_object.object_type, item.research_object.object_id)
            for item in self.entries
        )
        artifacts = tuple(item.artifact_sha256 for item in self.entries)
        if len(set(identities)) != len(identities) or len(set(artifacts)) != len(
            artifacts
        ):
            raise ValidationError("snapshot authority entries must be unique")

    def object(self, object_type: str, object_id: str) -> ResearchStateAuthorityBinding:
        if object_type not in _RECORD_TYPES:
            raise ValidationError("unknown research object type")
        validate_identifier(object_id, "research object ID")
        matches = tuple(
            item
            for item in self.entries
            if item.research_object.object_type == object_type
            and item.research_object.object_id == object_id
        )
        if len(matches) != 1:
            raise ValidationError("snapshot does not contain one exact research object")
        return matches[0]

    def metric(self, metric_id: str) -> Metric:
        value = self.object("Metric", metric_id).research_object
        if not isinstance(value, Metric):  # pragma: no cover - object() proves this
            raise ValidationError("snapshot metric binding is malformed")
        return value

    def method(self, method_id: str) -> Method:
        value = self.object("Method", method_id).research_object
        if not isinstance(value, Method):  # pragma: no cover - object() proves this
            raise ValidationError("snapshot method binding is malformed")
        return value

    def claim_semantics(self, claim_id: str) -> ClaimSemanticsReceipt:
        binding = self.object("Claim", claim_id)
        if binding.claim_semantics is None:
            raise ValidationError("snapshot Claim lacks resolved semantics")
        return binding.claim_semantics

    def binding_for_artifact(
        self, artifact_sha256: str
    ) -> ResearchStateAuthorityBinding:
        validate_sha256(artifact_sha256, "canonical research-state artifact SHA-256")
        matches = tuple(
            item for item in self.entries if item.artifact_sha256 == artifact_sha256
        )
        if len(matches) != 1:
            raise ValidationError(
                "snapshot does not contain one exact canonical artifact"
            )
        return matches[0]


@dataclass(frozen=True)
class ScopedResearchStateAuthority:
    """Live authority for named current state objects and their ancestors.

    Unlike :class:`ResearchStateAuthoritySnapshot`, this view deliberately does
    not assert that it contains every current canonical object.  It is for
    downstream authorities that must reopen exact Experiment/Result/
    StatisticalTest inputs after unrelated review objects have been added.
    Every returned target and canonical ancestor is still replayed from the
    live registry and ledger and must be the unsuperseded revision of its
    identity.
    """

    run_id: str
    ledger_head_hash: str
    ledger_event_count: int
    code_version: str
    configuration_hash: str
    entries: tuple[ResearchStateAuthorityBinding, ...]

    def __post_init__(self) -> None:
        validate_identifier(self.run_id, "scoped research-state run ID")
        validate_sha256(self.ledger_head_hash, "scoped ledger head hash")
        validate_sha256(
            self.configuration_hash,
            "scoped research-state configuration SHA-256",
        )
        _bounded_text(self.code_version, "scoped state code version", maximum=512)
        if (
            isinstance(self.ledger_event_count, bool)
            or not isinstance(self.ledger_event_count, int)
            or self.ledger_event_count <= 0
        ):
            raise ValidationError("scoped state ledger event count is invalid")
        if not self.entries or not all(
            isinstance(item, ResearchStateAuthorityBinding) for item in self.entries
        ):
            raise ValidationError("scoped state requires typed authority bindings")
        identities = tuple(
            (item.research_object.object_type, item.research_object.object_id)
            for item in self.entries
        )
        artifacts = tuple(item.artifact_sha256 for item in self.entries)
        if len(set(identities)) != len(identities) or len(set(artifacts)) != len(
            artifacts
        ):
            raise ValidationError("scoped state authority bindings must be unique")
        if any(
            item.research_object.object_type not in _RECORD_TYPES
            for item in self.entries
        ):
            raise ValidationError("scoped state contains an unsupported object type")

    def object(self, object_type: str, object_id: str) -> ResearchStateAuthorityBinding:
        if object_type not in _RECORD_TYPES:
            raise ValidationError("unsupported scoped research object type")
        validate_identifier(object_id, "scoped research object ID")
        matches = tuple(
            item
            for item in self.entries
            if item.research_object.object_type == object_type
            and item.research_object.object_id == object_id
        )
        if len(matches) != 1:
            raise ValidationError("scoped state does not contain one exact object")
        return matches[0]

    def binding_for_artifact(
        self, artifact_sha256: str
    ) -> ResearchStateAuthorityBinding:
        validate_sha256(artifact_sha256, "scoped canonical artifact SHA-256")
        matches = tuple(
            item for item in self.entries if item.artifact_sha256 == artifact_sha256
        )
        if len(matches) != 1:
            raise ValidationError("scoped state does not contain one exact artifact")
        return matches[0]


@dataclass(frozen=True)
class ScientificReproducibilityPackageAuthority:
    """Fresh canonical package joined to one clean-rerun source owner."""

    ledger_run_id: str
    package_binding: ResearchStateAuthorityBinding
    clean_rerun_authority_artifact_sha256: str
    clean_rerun_authority_record_hash: str
    clean_rerun_authority: Any
    original_result_binding: ResearchStateAuthorityBinding
    run_bindings: tuple[
        ResearchStateAuthorityBinding,
        ResearchStateAuthorityBinding,
    ]

    def __post_init__(self) -> None:
        validate_identifier(self.ledger_run_id, "scientific reproduction run ID")
        validate_sha256(
            self.clean_rerun_authority_artifact_sha256,
            "clean-rerun authority artifact SHA-256",
        )
        validate_sha256(
            self.clean_rerun_authority_record_hash,
            "clean-rerun authority record hash",
        )
        try:
            from .reproduction import ScientificCleanRerunAuthority
        except Exception as exc:  # pragma: no cover - import graph is static
            raise ValidationError(
                "scientific clean-rerun authority type is unavailable"
            ) from exc
        if (
            not isinstance(self.package_binding, ResearchStateAuthorityBinding)
            or not isinstance(
                self.original_result_binding,
                ResearchStateAuthorityBinding,
            )
            or not isinstance(self.run_bindings, tuple)
            or len(self.run_bindings) != 2
            or not all(
                isinstance(item, ResearchStateAuthorityBinding)
                for item in self.run_bindings
            )
            or not isinstance(
                self.clean_rerun_authority,
                ScientificCleanRerunAuthority,
            )
            or not isinstance(
                self.package_binding.research_object,
                ReproducibilityPackage,
            )
            or not isinstance(
                self.original_result_binding.research_object,
                Result,
            )
            or not all(
                isinstance(item.research_object, Run) for item in self.run_bindings
            )
        ):
            raise ValidationError(
                "scientific reproducibility package authority is malformed"
            )
        package = self.package_binding.research_object
        result = self.original_result_binding.research_object
        runs = tuple(item.research_object for item in self.run_bindings)
        if (
            package.run_ids != tuple(item.object_id for item in runs)
            or result.object_id != self.clean_rerun_authority.original_result_id
            or package.reproduction_status.value
            != self.clean_rerun_authority.outcome.value
            or self.clean_rerun_authority_artifact_sha256
            not in self.package_binding.authority_artifact_hashes
            or any(
                item.scientific_evidence_eligible is not True
                for item in (
                    self.package_binding,
                    self.original_result_binding,
                    *self.run_bindings,
                )
            )
        ):
            raise ValidationError(
                "scientific reproducibility package bindings disagree"
            )


def _resolve_claim_semantics_graph(
    registry: ArtifactRegistry,
    graph_artifact_hash: str,
    claim_id: str,
) -> tuple[ArtifactRecord, Any]:
    """Reopen the exact graph and return its one material claim."""

    validate_sha256(graph_artifact_hash, "claim-semantics graph SHA-256")
    validate_identifier(claim_id, "claim-semantics claim ID")
    try:
        from .gates import _resolve_claim_graph_authority

        graph_claim_ids = _resolve_claim_graph_authority(
            registry,
            graph_artifact_hash,
        )
    except Exception as exc:
        raise ValidationError(
            "claim-semantics graph failed fresh registry resolution"
        ) from exc
    if claim_id not in graph_claim_ids:
        raise ValidationError("claim-semantics graph does not contain the named claim")
    graph_record = registry.get_metadata(graph_artifact_hash)
    raw = registry.get_bytes(graph_artifact_hash)
    try:
        wrapper = safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        if not isinstance(wrapper, Mapping):
            raise ValidationError("claim-semantics graph wrapper is malformed")
        graph_value = wrapper.get("graph", wrapper)
        if not isinstance(graph_value, Mapping):
            raise ValidationError("claim-semantics graph payload is malformed")
        graph = ClaimEvidenceGraph.from_dict(
            graph_value,
            evidence_resolver=artifact_registry_resolver(
                registry,
                resolver_id=CLAIM_GRAPH_RESOLVER_ID,
            ),
        )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError("claim-semantics graph cannot be rehydrated") from exc
    matches = tuple(item for item in graph.claims if item.claim_id == claim_id)
    if len(matches) != 1:
        raise ValidationError("claim-semantics graph claim identity is ambiguous")
    return graph_record, matches[0]


def _resolve_claim_semantics_dependency(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    state_artifact_hash: str,
) -> ClaimSemanticsDependencyBinding:
    """Resolve one dependency Claim revision and its exact same-run event."""

    validate_sha256(
        state_artifact_hash,
        "claim-semantics dependency state artifact SHA-256",
    )
    try:
        if registry.verify(state_artifact_hash, raise_on_error=True) is not True:
            raise ValidationError("claim-semantics dependency is absent or corrupt")
        artifact = registry.get_metadata(state_artifact_hash)
        raw = registry.get_bytes(state_artifact_hash)
        value = safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        claim = CanonicalResearchObject.from_dict(value)
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "claim-semantics dependency cannot be safely rehydrated"
        ) from exc
    if (
        not isinstance(claim, Claim)
        or claim.status is not RecordStatus.VERIFIED
        or claim.verification_status is not VerificationStatus.VERIFIED
        or not claim.authority_artifact_hashes
        or artifact.logical_type != "research_state.claim"
        or artifact.creator_role is not claim.producer
        or artifact.schema_version != RESEARCH_STATE_SCHEMA_VERSION
        or artifact.mime_type != "application/json"
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or artifact.created_at != claim.created_at
        or raw != claim.canonical_bytes()
        or artifact.origin
        != f"research-state:Claim:{claim.object_id}:r{claim.revision}"
    ):
        raise ValidationError(
            "claim-semantics dependency is not an exact verified canonical Claim revision"
        )
    ledger_result = ledger.validate(raise_on_error=True)
    matches = tuple(
        event
        for event in ledger_result.events
        if event.run_id == run_id
        and event.actor_role is claim.producer
        and tuple(event.artifact_hashes) == (state_artifact_hash,)
        and event.metadata.get("research_state_operation")
        in {"MATERIALIZED", "SUPERSEDED"}
        and event.metadata.get("artifact_hash") == state_artifact_hash
        and event.metadata.get("object_type") == "Claim"
        and event.metadata.get("object_id") == claim.object_id
        and event.metadata.get("revision") == claim.revision
        and event.metadata.get("content_hash") == claim.content_hash
        and event.metadata.get("schema_version") == claim.schema_version
        and event.requested_state_after == event.state_before
    )
    if len(matches) != 1 or matches[0].event_hash is None:
        raise ValidationError(
            "claim-semantics dependency lacks one exact same-run materialization event"
        )
    event = matches[0]
    return ClaimSemanticsDependencyBinding(
        claim_id=claim.object_id,
        content_hash=claim.content_hash,
        state_artifact_hash=state_artifact_hash,
        state_artifact_record_hash=str(artifact.record_hash),
        materialization_event_id=event.event_id,
        materialization_event_hash=event.event_hash,
    )


def _require_scientific_claim_semantics_dependency(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    binding: ClaimSemanticsDependencyBinding,
) -> Claim:
    """Freshly re-resolve one dependency Claim's complete state authority."""

    current = _resolve_claim_semantics_dependency(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hash=binding.state_artifact_hash,
    )
    if current != binding:
        raise ValidationError(
            "scientific claim dependency binding changed during fresh replay"
        )
    root_artifact = registry.get_metadata(binding.state_artifact_hash)
    try:
        claim = CanonicalResearchObject.from_dict(
            safe_json_loads(
                registry.get_bytes(binding.state_artifact_hash),
                max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
            )
        )
    except Exception as exc:
        raise ValidationError(
            "scientific claim dependency cannot be rehydrated"
        ) from exc
    if not isinstance(claim, Claim):  # pragma: no cover - resolver proves this
        raise ValidationError("scientific claim dependency is not a Claim")

    pending = [binding.state_artifact_hash]
    state_objects: dict[str, _StoredObject] = {}
    while pending:
        digest = pending.pop(0)
        if digest in state_objects:
            continue
        if len(state_objects) >= MAX_SEQUENCE_ITEMS:
            raise ValidationError(
                "scientific claim dependency state closure exceeds the limit"
            )
        artifact = registry.get_metadata(digest)
        if not artifact.logical_type.startswith("research_state."):
            continue
        try:
            value = CanonicalResearchObject.from_dict(
                safe_json_loads(
                    registry.get_bytes(digest),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
            )
        except Exception as exc:
            raise ValidationError(
                "scientific claim dependency state closure is malformed"
            ) from exc
        state_objects[digest] = _StoredObject(value, artifact)
        for parent_hash in artifact.parent_artifacts:
            parent = registry.get_metadata(parent_hash)
            if parent.logical_type.startswith("research_state."):
                pending.append(parent_hash)
    by_content = {
        item.research_object.content_hash: item for item in state_objects.values()
    }
    ledger_result = ledger.validate(raise_on_error=True)
    events = tuple(
        event
        for event in ledger_result.events
        if event.event_id == binding.materialization_event_id
        and event.event_hash == binding.materialization_event_hash
        and event.run_id == run_id
    )
    if len(events) != 1:
        raise ValidationError(
            "scientific claim dependency lacks its exact same-run event"
        )
    event = events[0]
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=event.code_version,
        configuration_hash=event.configuration_hash,
        state=event.state_before,
        creation_command=root_artifact.creation_command,
    )
    resolved = repository._resolve_object_authority(claim, by_content)
    if (
        resolved.scientific_evidence_eligible is not True
        or resolved.claim_semantics is None
        or resolved.claim_semantics.scientific_writer_eligible is not True
    ):
        raise ValidationError(
            "scientific Claim cannot depend on non-writer-eligible state"
        )
    return claim


def _claim_semantics_proposal_slot(
    proposal: ClaimSemanticsProposal,
) -> tuple[object, ...]:
    """Return the source-bound slot shared by all semantic branches."""

    return (
        proposal.run_id,
        proposal.claim_graph_artifact_hash,
        proposal.claim_graph_artifact_record_hash,
        proposal.claim_id,
        proposal.claim_text,
        proposal.claim_producer_role,
        proposal.claim_evidence_use,
        tuple(
            sorted(
                proposal.dependency_bindings,
                key=lambda item: item.claim_id,
            )
        ),
    )


def register_claim_semantics_proposal(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    proposal_id: str,
    run_id: str,
    claim_graph_artifact_hash: str,
    claim_id: str,
    claim_type: ClaimType,
    scope: str,
    confidence: float,
    expressed_strength: ClaimStrength,
    permitted_strength: ClaimStrength,
    verification_method: str,
    dependency_claim_state_artifact_hashes: tuple[str, ...] = (),
) -> ArtifactRecord:
    """Retain a scientific semantic projection as review input, not authority."""

    if type(registry) is not ArtifactRegistry or type(ledger) is not EventLedger:
        raise ValidationError(
            "claim-semantics proposal registration requires registry and ledger"
        )
    if registry.policy.root != ledger.policy.root:
        raise ValidationError(
            "claim-semantics proposal registry and ledger roots differ"
        )
    validate_identifier(proposal_id, "claim-semantics proposal ID")
    validate_identifier(run_id, "claim-semantics proposal run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    graph_record, graph_claim = _resolve_claim_semantics_graph(
        registry,
        claim_graph_artifact_hash,
        claim_id,
    )
    dependency_hashes = _hash_tuple(
        dependency_claim_state_artifact_hashes,
        "claim-semantics proposal dependency state artifact hashes",
    )
    dependencies = tuple(
        sorted(
            (
                _resolve_claim_semantics_dependency(
                    registry,
                    ledger,
                    run_id=run_id,
                    state_artifact_hash=digest,
                )
                for digest in dependency_hashes
            ),
            key=lambda item: item.claim_id,
        )
    )
    for dependency in dependencies:
        _require_scientific_claim_semantics_dependency(
            registry,
            ledger,
            run_id=run_id,
            binding=dependency,
        )
    proposal = ClaimSemanticsProposal(
        proposal_id=proposal_id,
        run_id=run_id,
        claim_graph_artifact_hash=graph_record.sha256,
        claim_graph_artifact_record_hash=str(graph_record.record_hash),
        claim_id=graph_claim.claim_id,
        claim_text=graph_claim.text,
        claim_producer_role=graph_claim.producer_role,
        claim_evidence_use=graph_claim.evidence_use,
        claim_type=claim_type,
        scope=scope,
        confidence=confidence,
        expressed_strength=expressed_strength,
        permitted_strength=permitted_strength,
        verification_method=verification_method,
        dependency_bindings=dependencies,
    )
    existing = _valid_claim_semantics_proposals_in_slot(
        registry,
        ledger,
        slot=_claim_semantics_proposal_slot(proposal),
    )
    if existing:
        if len(existing) == 1 and existing[0][1].to_dict() == proposal.to_dict():
            retry_artifact = existing[0][0]
            require_claim_semantics_proposal(
                registry,
                ledger,
                proposal_artifact_hash=retry_artifact.sha256,
                expected_run_id=run_id,
                expected_claim_graph_artifact_hash=graph_record.sha256,
                expected_claim_id=claim_id,
            )
            return retry_artifact
        raise ValidationError(
            "claim-semantics proposal slot already contains a different semantic branch"
        )
    artifact = registry.put_json(
        proposal.to_dict(),
        logical_type=CLAIM_SEMANTICS_PROPOSAL_LOGICAL_TYPE,
        origin="candidate scientific claim semantics retained for independent review",
        creator_role=graph_claim.producer_role,
        creation_command=("scientist-one", "propose-claim-semantics"),
        parent_artifacts=(
            graph_record.sha256,
            *(item.state_artifact_hash for item in dependencies),
        ),
        schema_version=CLAIM_SEMANTICS_PROPOSAL_SCHEMA_VERSION,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
    )
    require_claim_semantics_proposal(
        registry,
        ledger,
        proposal_artifact_hash=artifact.sha256,
        expected_run_id=run_id,
        expected_claim_graph_artifact_hash=graph_record.sha256,
        expected_claim_id=claim_id,
    )
    return artifact


def _require_claim_semantics_proposal(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    proposal_artifact_hash: str,
    expected_run_id: str | None,
    expected_claim_graph_artifact_hash: str | None = None,
    expected_claim_id: str | None = None,
    enforce_slot_uniqueness: bool,
) -> ClaimSemanticsProposal:
    """Freshly replay one exact scientific semantic projection."""

    if not isinstance(registry, ArtifactRegistry) or not isinstance(
        ledger, EventLedger
    ):
        raise ValidationError(
            "claim-semantics proposal replay requires registry and ledger"
        )
    if registry.policy.root != ledger.policy.root:
        raise ValidationError(
            "claim-semantics proposal registry and ledger roots differ"
        )
    validate_sha256(proposal_artifact_hash, "claim-semantics proposal SHA-256")
    if expected_run_id is not None:
        validate_identifier(expected_run_id, "expected claim-semantics proposal run ID")
        _require_run_scoped_authority_paths(
            registry,
            ledger,
            run_id=expected_run_id,
        )
    if expected_claim_graph_artifact_hash is not None:
        validate_sha256(
            expected_claim_graph_artifact_hash,
            "expected claim-semantics proposal graph SHA-256",
        )
    if expected_claim_id is not None:
        validate_identifier(
            expected_claim_id, "expected claim-semantics proposal claim ID"
        )
    try:
        if registry.verify(proposal_artifact_hash, raise_on_error=True) is not True:
            raise ValidationError("claim-semantics proposal is absent or corrupt")
        artifact = registry.get_metadata(proposal_artifact_hash)
        raw = registry.get_bytes(proposal_artifact_hash)
        proposal = ClaimSemanticsProposal.from_dict(
            safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "claim-semantics proposal cannot be safely rehydrated"
        ) from exc
    replay_run_id = proposal.run_id if expected_run_id is None else expected_run_id
    _require_run_scoped_authority_paths(
        registry,
        ledger,
        run_id=replay_run_id,
    )
    if (
        artifact.logical_type != CLAIM_SEMANTICS_PROPOSAL_LOGICAL_TYPE
        or artifact.creator_role is not proposal.claim_producer_role
        or artifact.schema_version != CLAIM_SEMANTICS_PROPOSAL_SCHEMA_VERSION
        or artifact.mime_type != "application/json"
        or artifact.origin
        != "candidate scientific claim semantics retained for independent review"
        or artifact.creation_command != ("scientist-one", "propose-claim-semantics")
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or raw != canonical_json_bytes(proposal.to_dict()) + b"\n"
    ):
        raise ValidationError("claim-semantics proposal metadata is not exact")
    if (
        proposal.run_id != replay_run_id
        or (
            expected_claim_graph_artifact_hash is not None
            and proposal.claim_graph_artifact_hash != expected_claim_graph_artifact_hash
        )
        or (expected_claim_id is not None and proposal.claim_id != expected_claim_id)
    ):
        raise ValidationError("claim-semantics proposal identity was substituted")
    graph_record, graph_claim = _resolve_claim_semantics_graph(
        registry,
        proposal.claim_graph_artifact_hash,
        proposal.claim_id,
    )
    dependencies = tuple(
        sorted(
            (
                _resolve_claim_semantics_dependency(
                    registry,
                    ledger,
                    run_id=replay_run_id,
                    state_artifact_hash=item.state_artifact_hash,
                )
                for item in proposal.dependency_bindings
            ),
            key=lambda item: item.claim_id,
        )
    )
    for dependency in dependencies:
        _require_scientific_claim_semantics_dependency(
            registry,
            ledger,
            run_id=replay_run_id,
            binding=dependency,
        )
    fresh = ClaimSemanticsProposal(
        proposal_id=proposal.proposal_id,
        run_id=proposal.run_id,
        claim_graph_artifact_hash=graph_record.sha256,
        claim_graph_artifact_record_hash=str(graph_record.record_hash),
        claim_id=graph_claim.claim_id,
        claim_text=graph_claim.text,
        claim_producer_role=graph_claim.producer_role,
        claim_evidence_use=graph_claim.evidence_use,
        claim_type=proposal.claim_type,
        scope=proposal.scope,
        confidence=proposal.confidence,
        expressed_strength=proposal.expressed_strength,
        permitted_strength=proposal.permitted_strength,
        verification_method=proposal.verification_method,
        dependency_bindings=dependencies,
    )
    if fresh.to_dict() != proposal.to_dict() or artifact.parent_artifacts != (
        graph_record.sha256,
        *(item.state_artifact_hash for item in dependencies),
    ):
        raise ValidationError(
            "claim-semantics proposal differs from its exact graph or dependencies"
        )
    if enforce_slot_uniqueness:
        slot_matches = _valid_claim_semantics_proposals_in_slot(
            registry,
            ledger,
            slot=_claim_semantics_proposal_slot(fresh),
        )
        if len(slot_matches) != 1 or slot_matches[0][0].sha256 != artifact.sha256:
            raise ValidationError(
                "claim-semantics proposal slot contains multiple valid semantic branches"
            )
    return fresh


def _valid_claim_semantics_proposals_in_slot(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    slot: tuple[object, ...],
) -> tuple[tuple[ArtifactRecord, ClaimSemanticsProposal], ...]:
    """Replay every valid proposal and retain exact matches for one slot."""

    matches: list[tuple[ArtifactRecord, ClaimSemanticsProposal]] = []
    for artifact in registry.list_records():
        if artifact.logical_type != CLAIM_SEMANTICS_PROPOSAL_LOGICAL_TYPE:
            continue
        try:
            proposal = _require_claim_semantics_proposal(
                registry,
                ledger,
                proposal_artifact_hash=artifact.sha256,
                expected_run_id=None,
                enforce_slot_uniqueness=False,
            )
        except (ArtifactError, ValidationError):
            continue
        if _claim_semantics_proposal_slot(proposal) == slot:
            matches.append((artifact, proposal))
    return tuple(matches)


def require_claim_semantics_proposal(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    proposal_artifact_hash: str,
    expected_run_id: str,
    expected_claim_graph_artifact_hash: str | None = None,
    expected_claim_id: str | None = None,
) -> ClaimSemanticsProposal:
    """Freshly replay one unique exact scientific semantic projection."""

    return _require_claim_semantics_proposal(
        registry,
        ledger,
        proposal_artifact_hash=proposal_artifact_hash,
        expected_run_id=expected_run_id,
        expected_claim_graph_artifact_hash=expected_claim_graph_artifact_hash,
        expected_claim_id=expected_claim_id,
        enforce_slot_uniqueness=True,
    )


def register_scientific_claim_evidence_projection(
    registry: ArtifactRegistry,
    *,
    evidence_id: str,
    evidence_kind: GraphEvidenceKind,
    claim_id: str,
    claim_text: str,
    producer_role: Role,
    source_artifact_hashes: tuple[str, ...],
) -> ArtifactRecord:
    """Register an inert exact projection over source-owned evidence.

    This projection is not scientific authority.  It prevents producer prose,
    flags, or omitted parents from being substituted for the exact sources
    later replayed by the kind-specific ClaimSemantics resolvers.
    """

    if type(registry) is not ArtifactRegistry:
        raise ValidationError(
            "scientific claim-evidence projection requires ArtifactRegistry"
        )
    validate_identifier(evidence_id, "scientific claim-evidence ID")
    validate_identifier(claim_id, "scientific claim-evidence claim ID")
    _bounded_text(claim_text, "scientific claim-evidence claim text")
    if not isinstance(evidence_kind, GraphEvidenceKind):
        raise ValidationError("scientific claim-evidence kind must be typed")
    if not isinstance(producer_role, Role) or producer_role is Role.CLAIM_VERIFIER:
        raise AuthorizationError(
            "scientific claim-evidence projection requires a non-verifier producer"
        )
    parents = _hash_tuple(
        source_artifact_hashes,
        "scientific claim-evidence source artifacts",
        allow_empty=False,
    )
    records: list[ArtifactRecord] = []
    for digest in parents:
        try:
            if registry.verify(digest, raise_on_error=True) is not True:
                raise ValidationError(
                    "scientific claim-evidence source is absent or corrupt"
                )
            records.append(registry.get_metadata(digest))
        except ArtifactError as exc:
            raise ValidationError(
                "scientific claim-evidence source is absent or corrupt"
            ) from exc
    payload = {
        "schema_version": SCIENTIFIC_CLAIM_EVIDENCE_PAYLOAD_SCHEMA,
        "evidence_id": evidence_id,
        "evidence_kind": evidence_kind.value,
        "claim_id": claim_id,
        "claim_text": claim_text,
        "source_artifact_hashes": list(parents),
        "source_artifact_record_hashes": [str(item.record_hash) for item in records],
    }
    return registry.put_json(
        payload,
        logical_type=(
            f"{SCIENTIFIC_CLAIM_EVIDENCE_LOGICAL_TYPE_PREFIX}{evidence_kind.value}"
        ),
        origin=(
            f"exact scientific claim-evidence projection "
            f"{claim_id}:{evidence_kind.value}"
        ),
        creator_role=producer_role,
        creation_command=(
            "scientist-one",
            "project-scientific-claim-evidence",
        ),
        parent_artifacts=parents,
        schema_version=SCIENTIFIC_CLAIM_EVIDENCE_SCHEMA_VERSION,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
    )


def _require_scientific_claim_evidence_projection(
    registry: ArtifactRegistry,
    *,
    artifact: ArtifactRecord,
    evidence_id: str,
    evidence_kind: GraphEvidenceKind,
    claim_id: str,
    claim_text: str,
    claim_producer_role: Role,
) -> None:
    """Require an exact no-summary/no-flag source projection."""

    expected_type = (
        f"{SCIENTIFIC_CLAIM_EVIDENCE_LOGICAL_TYPE_PREFIX}{evidence_kind.value}"
    )
    try:
        raw = registry.get_bytes(artifact.sha256)
        payload = safe_json_loads(
            raw,
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
        source_records = tuple(
            registry.get_metadata(digest) for digest in artifact.parent_artifacts
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific claim-evidence projection cannot be reopened"
        ) from exc
    expected_payload = {
        "schema_version": SCIENTIFIC_CLAIM_EVIDENCE_PAYLOAD_SCHEMA,
        "evidence_id": evidence_id,
        "evidence_kind": evidence_kind.value,
        "claim_id": claim_id,
        "claim_text": claim_text,
        "source_artifact_hashes": list(artifact.parent_artifacts),
        "source_artifact_record_hashes": [
            str(item.record_hash) for item in source_records
        ],
    }
    if (
        not artifact.parent_artifacts
        or artifact.logical_type != expected_type
        or artifact.creator_role is not claim_producer_role
        or artifact.schema_version != SCIENTIFIC_CLAIM_EVIDENCE_SCHEMA_VERSION
        or artifact.mime_type != "application/json"
        or artifact.origin
        != (
            f"exact scientific claim-evidence projection "
            f"{claim_id}:{evidence_kind.value}"
        )
        or artifact.creation_command
        != ("scientist-one", "project-scientific-claim-evidence")
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or payload != expected_payload
        or raw != canonical_json_bytes(expected_payload) + b"\n"
    ):
        raise ValidationError(
            "scientific claim-evidence projection differs from its exact sources"
        )


def require_scientific_claim_evidence_projection(
    registry: ArtifactRegistry,
    *,
    artifact_sha256: str,
    expected_evidence_id: str,
    expected_evidence_kind: GraphEvidenceKind,
    expected_claim_id: str,
    expected_claim_text: str,
    expected_claim_producer_role: Role,
) -> ArtifactRecord:
    """Public fresh resolver for the exact no-summary evidence projection."""

    if type(registry) is not ArtifactRegistry:
        raise ValidationError(
            "scientific claim-evidence projection replay requires ArtifactRegistry"
        )
    validate_sha256(
        artifact_sha256,
        "scientific claim-evidence projection SHA-256",
    )
    try:
        if registry.verify(artifact_sha256, raise_on_error=True) is not True:
            raise ValidationError(
                "scientific claim-evidence projection is absent or corrupt"
            )
        artifact = registry.get_metadata(artifact_sha256)
    except ArtifactError as exc:
        raise ValidationError(
            "scientific claim-evidence projection is absent or corrupt"
        ) from exc
    _require_scientific_claim_evidence_projection(
        registry,
        artifact=artifact,
        evidence_id=expected_evidence_id,
        evidence_kind=expected_evidence_kind,
        claim_id=expected_claim_id,
        claim_text=expected_claim_text,
        claim_producer_role=expected_claim_producer_role,
    )
    return artifact


def _claim_semantics_source_closure(
    registry: ArtifactRegistry,
    root_hashes: tuple[str, ...],
) -> tuple[tuple[ArtifactRecord, bytes], ...]:
    """Resolve a bounded, ordered, transitive evidence-parent closure."""

    pending = list(
        _hash_tuple(
            root_hashes,
            "claim-semantics source-closure roots",
            allow_empty=False,
        )
    )
    seen: set[str] = set()
    resolved: list[tuple[ArtifactRecord, bytes]] = []
    while pending:
        digest = pending.pop(0)
        if digest in seen:
            continue
        if len(seen) >= MAX_SEQUENCE_ITEMS:
            raise ValidationError(
                "claim-semantics source closure exceeds the bounded artifact limit"
            )
        try:
            if registry.verify(digest, raise_on_error=True) is not True:
                raise ValidationError(
                    "claim-semantics source closure is absent or corrupt"
                )
            record = registry.get_metadata(digest)
            content = registry.get_bytes(digest)
        except ArtifactError as exc:
            raise ValidationError(
                "claim-semantics source closure cannot be rehydrated"
            ) from exc
        if record.validation_result != "PASS" or record.frozen is not True:
            raise ValidationError(
                "claim-semantics scientific review requires frozen PASS sources"
            )
        seen.add(digest)
        resolved.append((record, content))
        for parent_hash in record.parent_artifacts:
            if parent_hash not in seen and parent_hash not in pending:
                pending.append(parent_hash)
    return tuple(resolved)


def _claim_semantics_evidence_nodes(
    registry: ArtifactRegistry,
    *,
    graph_artifact_hash: str,
    claim_id: str,
) -> tuple[Any, ...]:
    """Reopen the exact linked evidence nodes for one graph Claim."""

    _graph_record, expected_claim = _resolve_claim_semantics_graph(
        registry,
        graph_artifact_hash,
        claim_id,
    )
    try:
        wrapper = safe_json_loads(
            registry.get_bytes(graph_artifact_hash),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
        if not isinstance(wrapper, Mapping):
            raise ValidationError("claim-semantics graph wrapper is malformed")
        graph_value = wrapper.get("graph", wrapper)
        if not isinstance(graph_value, Mapping):
            raise ValidationError("claim-semantics graph payload is malformed")
        graph = ClaimEvidenceGraph.from_dict(
            graph_value,
            evidence_resolver=artifact_registry_resolver(
                registry,
                resolver_id=CLAIM_GRAPH_RESOLVER_ID,
            ),
        )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "claim-semantics evidence nodes cannot be rehydrated"
        ) from exc
    claim_matches = tuple(
        item for item in graph.claims if item.claim_id == expected_claim.claim_id
    )
    if len(claim_matches) != 1 or claim_matches[0] != expected_claim:
        raise ValidationError("claim-semantics graph Claim changed during replay")
    nodes_by_id = {item.evidence_id: item for item in graph.evidence}
    linked: list[Any] = []
    for link in expected_claim.evidence_links:
        node = nodes_by_id.get(link.evidence_id)
        if node is None or node.kind is not link.kind:
            raise ValidationError(
                "claim-semantics graph has a missing or kind-spliced evidence node"
            )
        linked.append(node)
    if (
        len(linked) != len(nodes_by_id)
        or len({item.kind for item in linked}) != len(linked)
        or {item.kind for item in linked} != set(GraphEvidenceKind)
    ):
        raise ValidationError(
            "scientific claim semantics require exact one-per-kind evidence coverage"
        )
    return tuple(sorted(linked, key=lambda item: item.kind.value))


def _require_canonical_state_source(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    state_artifact_hash: str,
) -> tuple[
    CanonicalResearchObject,
    _ResolvedObjectAuthority,
    Mapping[str, _StoredObject],
    ResearchStateRepository,
]:
    """Freshly replay one latest same-run canonical state source.

    A frozen state-shaped payload is not sufficient.  This resolver requires
    the exact materialization event, validates the complete live canonical
    state, rejects stale revisions, and re-runs the object's typed semantic
    authority resolver.
    """

    validate_sha256(
        state_artifact_hash,
        "claim-semantics canonical source artifact SHA-256",
    )
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    try:
        if registry.verify(state_artifact_hash, raise_on_error=True) is not True:
            raise ValidationError("canonical source artifact is absent or corrupt")
        artifact = registry.get_metadata(state_artifact_hash)
        raw = registry.get_bytes(state_artifact_hash)
        record = CanonicalResearchObject.from_dict(
            safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "claim-semantics canonical source cannot be rehydrated"
        ) from exc
    if (
        artifact.logical_type != record.logical_type
        or artifact.creator_role is not record.producer
        or artifact.schema_version != RESEARCH_STATE_SCHEMA_VERSION
        or artifact.mime_type != "application/json"
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or artifact.created_at != record.created_at
        or artifact.origin
        != (
            f"research-state:{record.object_type}:{record.object_id}:r{record.revision}"
        )
        or raw != record.canonical_bytes()
    ):
        raise ValidationError(
            "claim-semantics source is not an exact canonical state artifact"
        )
    ledger_result = ledger.validate(raise_on_error=True)
    matches = tuple(
        event
        for event in ledger_result.events
        if event.run_id == run_id
        and event.actor_role is record.producer
        and tuple(event.artifact_hashes) == (state_artifact_hash,)
        and event.timestamp == record.created_at
        and event.metadata.get("research_state_operation")
        in {"MATERIALIZED", "SUPERSEDED"}
        and event.metadata.get("artifact_hash") == state_artifact_hash
        and event.metadata.get("object_type") == record.object_type
        and event.metadata.get("object_id") == record.object_id
        and event.metadata.get("revision") == record.revision
        and event.metadata.get("content_hash") == record.content_hash
        and event.metadata.get("schema_version") == record.schema_version
        and event.metadata.get("supersedes_content_hash")
        == record.supersedes_content_hash
        and event.requested_state_after == event.state_before
    )
    if len(matches) != 1:
        raise ValidationError(
            "claim-semantics canonical source lacks one exact same-run event"
        )
    event = matches[0]
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=event.code_version,
        configuration_hash=event.configuration_hash,
        state=event.state_before,
        creation_command=artifact.creation_command,
    )
    report = repository.validate_state(expected_code_version=event.code_version)
    if not report.valid or state_artifact_hash not in report.current_artifact_hashes:
        raise ValidationError(
            "claim-semantics canonical source is invalid or superseded"
        )
    stored = repository._stored_objects()
    by_content, _by_identity = repository._indexes(stored)
    matches_by_hash = tuple(
        item for item in stored if item.artifact.sha256 == state_artifact_hash
    )
    if len(matches_by_hash) != 1:
        raise ValidationError("canonical source does not resolve one state object")
    resolved = repository._resolve_object_authority(record, by_content)
    return record, resolved, by_content, repository


_CLAIM_SEMANTICS_SCOPED_SOURCE_TYPES = frozenset(
    {
        "Hypothesis",
        "Dataset",
        "Method",
        "Implementation",
        "Experiment",
        "Run",
        "Result",
        "StatisticalTest",
        "Ablation",
        "ReproducibilityPackage",
    }
)


def _require_scoped_canonical_state_source(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    state_artifact_hash: str,
) -> tuple[
    CanonicalResearchObject,
    _ResolvedObjectAuthority,
    Mapping[str, _StoredObject],
    ResearchStateRepository,
]:
    """Replay one upstream ClaimSemantics source without validating later state.

    The ordinary canonical-source resolver intentionally validates the complete
    live state.  That is cyclic once a canonical Claim consumes the semantics
    receipt being replayed.  This target-scoped path preserves exact current
    lineage, materialization, provenance, and semantic-authority checks while
    excluding Claim and other downstream review objects from its target set.
    """

    scoped = _resolve_current_research_state_bindings(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hashes=(state_artifact_hash,),
        allowed_object_types=_CLAIM_SEMANTICS_SCOPED_SOURCE_TYPES,
    )
    binding = scoped.binding_for_artifact(state_artifact_hash)
    events = ledger.events()
    if binding.materialization_event_index >= len(events):
        raise ValidationError("scoped canonical source event index is invalid")
    event = events[binding.materialization_event_index]
    if (
        event.event_id != binding.materialization_event_id
        or event.event_hash != binding.materialization_event_hash
    ):
        raise ValidationError("scoped canonical source event binding changed")
    artifact = registry.get_metadata(state_artifact_hash)
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=scoped.code_version,
        configuration_hash=scoped.configuration_hash,
        state=event.state_before,
        creation_command=artifact.creation_command,
    )
    stored = repository._stored_objects()
    by_content, _by_identity = repository._indexes(stored)
    record = binding.research_object
    target = by_content.get(record.content_hash)
    if (
        target is None
        or target.research_object != record
        or target.artifact.sha256 != state_artifact_hash
        or str(target.artifact.record_hash) != binding.artifact_record_hash
    ):
        raise ValidationError("scoped canonical source identity was substituted")
    resolved = repository._resolve_object_authority(record, by_content)
    if (
        tuple(item.sha256 for item in resolved.records)
        != binding.authority_artifact_hashes
        or tuple(str(item.record_hash) for item in resolved.records)
        != binding.authority_artifact_record_hashes
        or tuple(item.logical_type for item in resolved.records)
        != binding.authority_logical_types
        or tuple(item.creator_role for item in resolved.records)
        != binding.authority_creator_roles
        or resolved.scientific_evidence_eligible
        is not binding.scientific_evidence_eligible
        or resolved.claim_semantics != binding.claim_semantics
    ):
        raise ValidationError("scoped canonical source authority changed during replay")
    return record, resolved, by_content, repository


def _require_run_scoped_authority_paths(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
) -> None:
    if (
        type(registry) is not ArtifactRegistry
        or type(ledger) is not EventLedger
        or registry.policy.root != ledger.policy.root
        or registry.base_path.as_posix() != f"runs/{run_id}/registry"
        or ledger.relative_path.as_posix() != f"runs/{run_id}/events.jsonl"
    ):
        raise ValidationError(
            "scientific source authority registry or ledger belongs to another run"
        )


_SCIENTIFIC_DATASET_PUBLIC_LICENSES: Mapping[str, str] = {
    "CC0-1.0": "https://creativecommons.org/publicdomain/zero/1.0/",
    "CC-BY-4.0": "https://creativecommons.org/licenses/by/4.0/",
    "ODC-BY-1.0": "https://opendatacommons.org/licenses/by/1-0/",
    "PDDL-1.0": "https://opendatacommons.org/licenses/pddl/1-0/",
}

_SCIENTIFIC_DATASET_LICENSE_OBLIGATIONS: Mapping[str, tuple[str, ...]] = {
    "CC0-1.0": ("preserve-source-provenance",),
    "CC-BY-4.0": ("attribute-source", "link-license", "mark-changes"),
    "ODC-BY-1.0": (
        "attribute-database-source",
        "preserve-notice",
        "mark-produced-database",
    ),
    "PDDL-1.0": ("preserve-source-provenance",),
}
_SCIENTIFIC_DATASET_REDISTRIBUTION_PLANS = frozenset(
    {
        "NO_REDISTRIBUTION",
        "DERIVED_AGGREGATES_ONLY",
        "REDISTRIBUTE_WITH_LICENSE_AND_ATTRIBUTION",
    }
)


def _canonical_scientific_dataset_source_url(value: str) -> tuple[str, str]:
    _bounded_text(value, "scientific dataset source URL", maximum=2048)
    try:
        parsed = urlsplit(value)
        query = tuple(parse_qsl(parsed.query, keep_blank_values=True))
        port = parsed.port
    except (TypeError, ValueError) as exc:
        raise ValidationError("scientific dataset source URL is malformed") from exc
    if (
        parsed.scheme != "https"
        or parsed.username is not None
        or parsed.password is not None
        or parsed.hostname is None
        or parsed.hostname != parsed.hostname.casefold()
        or port not in {None, 443}
        or not parsed.path.startswith("/")
        or parsed.path in {"", "/"}
        or parsed.fragment
        or query != tuple(sorted(query))
        or len({name for name, _item in query}) != len(query)
        or parsed.geturl() != value
    ):
        raise ValidationError(
            "scientific dataset source URL must be canonical pinned HTTPS"
        )
    return value, parsed.hostname


def _scientific_dataset_acquisition_plan_payload(
    *,
    run_id: str,
    dataset_id: str,
    name: str,
    version: str,
    source_url: str,
    expected_body_sha256: str,
    license_identifier: str,
    license_url: str,
    intended_use: str,
    processing_scope: tuple[str, ...],
    derivative_output_scope: tuple[str, ...],
    redistribution_plan: str,
    attribution_notice: str,
    unit_id_field: str,
) -> dict[str, Any]:
    canonical_url, source_host = _canonical_scientific_dataset_source_url(source_url)
    validate_identifier(run_id, "scientific dataset acquisition-plan run ID")
    validate_identifier(dataset_id, "scientific dataset acquisition-plan ID")
    _bounded_text(name, "scientific dataset acquisition-plan name")
    _bounded_text(version, "scientific dataset acquisition-plan version")
    validate_sha256(
        expected_body_sha256,
        "scientific dataset acquisition expected body SHA-256",
    )
    if _SCIENTIFIC_DATASET_PUBLIC_LICENSES.get(license_identifier) != license_url:
        raise ValidationError(
            "scientific dataset acquisition plan lacks a supported exact license"
        )
    intended_use = _bounded_text(
        intended_use,
        "scientific dataset intended use",
    )
    processing = _text_tuple(
        processing_scope,
        "scientific dataset processing scope",
    )
    derivatives = _text_tuple(
        derivative_output_scope,
        "scientific dataset derivative-output scope",
    )
    if not processing or not derivatives:
        raise ValidationError(
            "scientific dataset use must define processing and derivative outputs"
        )
    if redistribution_plan not in _SCIENTIFIC_DATASET_REDISTRIBUTION_PLANS:
        raise ValidationError("scientific dataset redistribution plan is unsupported")
    _bounded_text(
        attribution_notice,
        "scientific dataset attribution notice",
    )
    if license_identifier in {"CC-BY-4.0", "ODC-BY-1.0"} and not (
        attribution_notice.strip()
    ):
        raise ValidationError(
            "attribution-bearing Dataset license requires an attribution notice"
        )
    validate_identifier(unit_id_field, "scientific dataset unit ID field")
    return {
        "schema_version": SCIENTIFIC_DATASET_ACQUISITION_PLAN_PAYLOAD_SCHEMA,
        "run_id": run_id,
        "dataset_id": dataset_id,
        "name": name,
        "version": version,
        "source_url": canonical_url,
        "source_host": source_host,
        "expected_body_sha256": expected_body_sha256,
        "license_identifier": license_identifier,
        "license_url": license_url,
        "intended_use": intended_use,
        "processing_scope": list(processing),
        "derivative_output_scope": list(derivatives),
        "redistribution_plan": redistribution_plan,
        "attribution_notice": attribution_notice,
        "license_obligations": list(
            _SCIENTIFIC_DATASET_LICENSE_OBLIGATIONS[license_identifier]
        ),
        "unit_id_field": unit_id_field,
        "policy_id": SCIENTIFIC_DATASET_ACQUISITION_POLICY_ID,
        "adapter_id": SCIENTIFIC_DATASET_ACQUISITION_ADAPTER_ID,
        "method": "GET",
        "request_content_type": "application/json",
        "expected_response_content_type": "application/json",
        "human_authority": False,
        "e4_authority": False,
        "scientific_authority": False,
    }


def register_scientific_dataset_acquisition_plan(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    dataset_id: str,
    name: str,
    version: str,
    source_url: str,
    expected_body_sha256: str,
    license_identifier: str,
    license_url: str,
    intended_use: str,
    processing_scope: tuple[str, ...],
    derivative_output_scope: tuple[str, ...],
    redistribution_plan: str,
    attribution_notice: str,
    unit_id_field: str = "unit_id",
) -> ArtifactRecord:
    """Prospectively freeze one exact source snapshot before external access.

    Publish the first protected Dataset root under paired source CAS. Exact
    interrupted or completed publications retain the original record timestamp;
    retrying a plan never grants external access or scientific authority.
    """

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    publication_snapshot = _scientific_dataset_publication_snapshot(
        registry, ledger, run_id=run_id,
    )
    payload = _scientific_dataset_acquisition_plan_payload(
        run_id=run_id,
        dataset_id=dataset_id,
        name=name,
        version=version,
        source_url=source_url,
        expected_body_sha256=expected_body_sha256,
        license_identifier=license_identifier,
        license_url=license_url,
        intended_use=intended_use,
        processing_scope=processing_scope,
        derivative_output_scope=derivative_output_scope,
        redistribution_plan=redistribution_plan,
        attribution_notice=attribution_notice,
        unit_id_field=unit_id_field,
    )
    ledger_result = publication_snapshot[1]
    if not ledger_result.events:
        raise ValidationError(
            "scientific dataset acquisition plan requires an initialized run ledger"
        )
    digest = sha256_bytes(canonical_json_bytes(payload) + b"\n")
    existing = next(
        (record for record in publication_snapshot[0].records if record.sha256 == digest),
        None,
    )
    created_at = utc_now() if existing is None else existing.created_at
    plan_bytes, plan = _scientific_dataset_artifact_plan(
        registry,
        payload,
        logical_type=SCIENTIFIC_DATASET_ACQUISITION_PLAN_LOGICAL_TYPE,
        origin=f"prospective scientific Dataset acquisition {dataset_id}",
        creator_role=Role.PROTOCOL_DESIGNER,
        creation_command=("scientist-one", "plan-scientific-dataset-acquisition"),
        parent_artifacts=(),
        schema_version=SCIENTIFIC_DATASET_ACQUISITION_PLAN_SCHEMA_VERSION,
        created_at=created_at,
    )
    missing, event_to_append = _preflight_scientific_dataset_publication(
        registry, ledger,
        run_id=run_id,
        plans=((plan_bytes, plan),),
        actor_role=Role.PROTOCOL_DESIGNER,
        event_artifact_hashes=(plan.sha256,),
        reason="prospectively froze one exact external Dataset acquisition policy",
        event_id=f"scientific-dataset-plan-{plan.sha256[:24]}",
        event_timestamp=created_at,
        metadata={
            "schema_version": SCIENTIFIC_DATASET_ACQUISITION_EVENT_SCHEMA,
            "dataset_id": dataset_id,
            "dataset_version": version,
            "plan_artifact_hash": plan.sha256,
            "plan_record_hash": plan.record_hash,
            "expected_body_sha256": expected_body_sha256,
            "source_url": source_url,
            "policy_id": SCIENTIFIC_DATASET_ACQUISITION_POLICY_ID,
            "adapter_id": SCIENTIFIC_DATASET_ACQUISITION_ADAPTER_ID,
        },
    )
    (committed,) = _commit_scientific_dataset_publication(
        registry, ledger, plans=((plan_bytes, plan),), missing=missing,
        event_to_append=event_to_append, source_snapshot=publication_snapshot,
    )
    require_scientific_dataset_acquisition_plan(
        registry,
        ledger,
        run_id=run_id,
        plan_artifact_hash=plan.sha256,
        expected_dataset_id=dataset_id,
        expected_version=version,
    )
    return committed


def require_scientific_dataset_acquisition_plan(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    plan_artifact_hash: str,
    expected_dataset_id: str | None = None,
    expected_version: str | None = None,
) -> ScientificDatasetAcquisitionPlan:
    """Freshly resolve the exact prospective plan and its ledger checkpoint."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(plan_artifact_hash, "scientific dataset plan SHA-256")
    try:
        registry.verify(plan_artifact_hash, raise_on_error=True)
        record = registry.get_metadata(plan_artifact_hash)
        raw = registry.get_bytes(plan_artifact_hash)
        value = safe_json_loads(
            raw,
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific dataset acquisition plan cannot be reopened"
        ) from exc
    expected_keys = {
        "schema_version",
        "run_id",
        "dataset_id",
        "name",
        "version",
        "source_url",
        "source_host",
        "expected_body_sha256",
        "license_identifier",
        "license_url",
        "intended_use",
        "processing_scope",
        "derivative_output_scope",
        "redistribution_plan",
        "attribution_notice",
        "license_obligations",
        "unit_id_field",
        "policy_id",
        "adapter_id",
        "method",
        "request_content_type",
        "expected_response_content_type",
        "human_authority",
        "e4_authority",
        "scientific_authority",
    }
    if not isinstance(value, Mapping) or set(value) != expected_keys:
        raise ValidationError(
            "scientific dataset acquisition-plan schema is incomplete"
        )
    expected = _scientific_dataset_acquisition_plan_payload(
        run_id=run_id,
        dataset_id=str(value.get("dataset_id")),
        name=str(value.get("name")),
        version=str(value.get("version")),
        source_url=str(value.get("source_url")),
        expected_body_sha256=str(value.get("expected_body_sha256")),
        license_identifier=str(value.get("license_identifier")),
        license_url=str(value.get("license_url")),
        intended_use=str(value.get("intended_use")),
        processing_scope=tuple(value.get("processing_scope", ())),
        derivative_output_scope=tuple(value.get("derivative_output_scope", ())),
        redistribution_plan=str(value.get("redistribution_plan")),
        attribution_notice=str(value.get("attribution_notice")),
        unit_id_field=str(value.get("unit_id_field")),
    )
    if (
        record.logical_type != SCIENTIFIC_DATASET_ACQUISITION_PLAN_LOGICAL_TYPE
        or record.creator_role is not Role.PROTOCOL_DESIGNER
        or record.schema_version != SCIENTIFIC_DATASET_ACQUISITION_PLAN_SCHEMA_VERSION
        or record.mime_type != "application/json"
        or record.origin
        != f"prospective scientific Dataset acquisition {value.get('dataset_id')}"
        or record.creation_command
        != ("scientist-one", "plan-scientific-dataset-acquisition")
        or record.parent_artifacts
        or record.validation_result != "PASS"
        or record.frozen is not True
        or dict(value) != expected
        or raw != canonical_json_bytes(expected) + b"\n"
        or (
            expected_dataset_id is not None
            and value.get("dataset_id") != expected_dataset_id
        )
        or (expected_version is not None and value.get("version") != expected_version)
    ):
        raise ValidationError(
            "scientific dataset acquisition plan differs from exact policy"
        )
    ledger_result = ledger.validate(raise_on_error=True)
    events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.run_id == run_id
        and event.event_id == f"scientific-dataset-plan-{record.sha256[:24]}"
        and event.actor_role is Role.PROTOCOL_DESIGNER
        and event.event_type == "CHECKPOINT"
        and event.state_before == event.requested_state_after
        and tuple(event.artifact_hashes) == (record.sha256,)
        and event.timestamp == record.created_at
        and dict(event.metadata)
        == {
            "schema_version": SCIENTIFIC_DATASET_ACQUISITION_EVENT_SCHEMA,
            "dataset_id": value["dataset_id"],
            "dataset_version": value["version"],
            "plan_artifact_hash": record.sha256,
            "plan_record_hash": record.record_hash,
            "expected_body_sha256": value["expected_body_sha256"],
            "source_url": value["source_url"],
            "policy_id": SCIENTIFIC_DATASET_ACQUISITION_POLICY_ID,
            "adapter_id": SCIENTIFIC_DATASET_ACQUISITION_ADAPTER_ID,
        }
    )
    if (
        len(events) != 1
        or events[0][0] == 0
        or events[0][1].prior_event_hash
        != ledger_result.events[events[0][0] - 1].event_hash
        or events[0][1].state_before
        != ledger_result.events[events[0][0] - 1].requested_state_after
        or events[0][1].code_version
        != ledger_result.events[events[0][0] - 1].code_version
        or events[0][1].configuration_hash
        != ledger_result.events[events[0][0] - 1].configuration_hash
        or events[0][1].event_hash is None
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == events[0][1].event_id
            for later in ledger_result.events[events[0][0] + 1 :]
        )
    ):
        raise ValidationError(
            "scientific dataset acquisition-plan ledger authority is absent or stale"
        )
    event_index, event = events[0]
    return ScientificDatasetAcquisitionPlan(
        run_id=run_id,
        dataset_id=str(value["dataset_id"]),
        name=str(value["name"]),
        version=str(value["version"]),
        source_url=str(value["source_url"]),
        source_host=str(value["source_host"]),
        expected_body_sha256=str(value["expected_body_sha256"]),
        license_identifier=str(value["license_identifier"]),
        license_url=str(value["license_url"]),
        intended_use=str(value["intended_use"]),
        processing_scope=tuple(value["processing_scope"]),
        derivative_output_scope=tuple(value["derivative_output_scope"]),
        redistribution_plan=str(value["redistribution_plan"]),
        attribution_notice=str(value["attribution_notice"]),
        license_obligations=tuple(value["license_obligations"]),
        unit_id_field=str(value["unit_id_field"]),
        policy_id=str(value["policy_id"]),
        adapter_id=str(value["adapter_id"]),
        artifact_hash=record.sha256,
        record_hash=str(record.record_hash),
        ledger_event_id=event.event_id,
        ledger_event_hash=str(event.event_hash),
        ledger_event_index=event_index,
    )


def _scientific_dataset_source_projection(
    raw: bytes,
    *,
    unit_id_field: str = "unit_id",
) -> Mapping[str, Any]:
    """Parse the closed external dataset envelope and derive its projection."""

    try:
        value = safe_json_loads(
            raw,
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except Exception as exc:
        raise ValidationError(
            "scientific dataset response is not bounded JSON"
        ) from exc
    if not isinstance(value, Mapping) or set(value) != {
        "schema_version",
        "dataset_id",
        "name",
        "version",
        "license",
        "data",
    }:
        raise ValidationError("scientific dataset source envelope is incomplete")
    if value.get("schema_version") != SCIENTIFIC_DATASET_SOURCE_PAYLOAD_SCHEMA:
        raise ValidationError("unsupported scientific dataset source schema")
    dataset_id = value.get("dataset_id")
    name = value.get("name")
    version = value.get("version")
    license_value = value.get("license")
    data = value.get("data")
    validate_identifier(dataset_id, "scientific dataset source ID")
    _bounded_text(name, "scientific dataset source name")
    _bounded_text(version, "scientific dataset source version")
    if not isinstance(license_value, Mapping) or set(license_value) != {
        "spdx_id",
        "canonical_url",
    }:
        raise ValidationError("scientific dataset license evidence is malformed")
    license_identifier = license_value.get("spdx_id")
    license_url = license_value.get("canonical_url")
    if (
        not isinstance(license_identifier, str)
        or not isinstance(license_url, str)
        or _SCIENTIFIC_DATASET_PUBLIC_LICENSES.get(license_identifier) != license_url
    ):
        raise ValidationError(
            "scientific dataset lacks one exact supported public license"
        )
    validate_identifier(unit_id_field, "scientific dataset unit ID field")
    if not isinstance(data, list) or not data:
        raise ValidationError(
            "scientific dataset data must be a non-empty unit-record list"
        )
    if len(data) > MAX_SEQUENCE_ITEMS:
        raise ValidationError(
            "scientific dataset exceeds the supported unit-record bound"
        )
    unit_ids: list[str] = []
    unit_hashes: list[str] = []
    for item in data:
        if not isinstance(item, Mapping) or unit_id_field not in item:
            raise ValidationError(
                "scientific dataset unit lacks its exact stable identifier"
            )
        unit_id = item.get(unit_id_field)
        validate_identifier(unit_id, "scientific dataset unit ID")
        unit_ids.append(unit_id)
        unit_hashes.append(
            sha256_bytes(canonical_json_bytes(thaw_json(freeze_json(item))))
        )
    if len(set(unit_ids)) != len(unit_ids):
        raise ValidationError("scientific dataset unit IDs are duplicated")
    data_bytes = canonical_json_bytes(thaw_json(freeze_json(data)))
    if len(data_bytes) > MAX_CANONICAL_OBJECT_BYTES:
        raise ValidationError(
            "scientific dataset data projection exceeds the bounded v1 contract"
        )
    return MappingProxyType(
        {
            "dataset_id": dataset_id,
            "name": name,
            "version": version,
            "license_identifier": license_identifier,
            "license_url": license_url,
            "data_projection_sha256": sha256_bytes(data_bytes),
            "data_item_count": len(data),
            "unit_id_field": unit_id_field,
            "unit_ids": tuple(unit_ids),
            "unit_hashes": tuple(unit_hashes),
        }
    )


def _scientific_dataset_manifest_payload(
    source: Mapping[str, Any],
    *,
    acquisition_plan: ScientificDatasetAcquisitionPlan,
    evaluation_contract_record: ArtifactRecord,
    raw_record: ArtifactRecord,
    transport_authority_record: ArtifactRecord,
    response_receipt_record: ArtifactRecord,
) -> dict[str, Any]:
    return {
        "schema_version": SCIENTIFIC_DATASET_MANIFEST_PAYLOAD_SCHEMA,
        "dataset_id": source["dataset_id"],
        "name": source["name"],
        "version": source["version"],
        "source_kind": ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA.value,
        "raw_data_artifact_sha256": raw_record.sha256,
        "raw_data_record_hash": str(raw_record.record_hash),
        "raw_data_sha256": raw_record.sha256,
        "body_size": raw_record.size,
        "content_type": "application/json",
        "data_projection_sha256": source["data_projection_sha256"],
        "data_item_count": source["data_item_count"],
        "unit_id_field": source["unit_id_field"],
        "unit_ids": list(source["unit_ids"]),
        "unit_hashes": list(source["unit_hashes"]),
        "acquisition_plan_artifact_sha256": acquisition_plan.artifact_hash,
        "acquisition_plan_record_hash": acquisition_plan.record_hash,
        "evaluation_contract_artifact_sha256": evaluation_contract_record.sha256,
        "evaluation_contract_record_hash": str(evaluation_contract_record.record_hash),
        "source_url": acquisition_plan.source_url,
        "source_host": acquisition_plan.source_host,
        "policy_id": acquisition_plan.policy_id,
        "adapter_id": acquisition_plan.adapter_id,
        "transport_authority_artifact_sha256": transport_authority_record.sha256,
        "transport_authority_record_hash": str(transport_authority_record.record_hash),
        "response_receipt_artifact_sha256": response_receipt_record.sha256,
        "response_receipt_record_hash": str(response_receipt_record.record_hash),
    }


