def _scientific_dataset_usage_proposal_payload(
    source: Mapping[str, Any],
    *,
    run_id: str,
    acquisition_plan: ScientificDatasetAcquisitionPlan,
    evaluation_contract_record: ArtifactRecord,
    manifest_record: ArtifactRecord,
    transport: Any,
) -> dict[str, Any]:
    return {
        "schema_version": SCIENTIFIC_DATASET_USAGE_PROPOSAL_PAYLOAD_SCHEMA,
        "run_id": run_id,
        "dataset_id": source["dataset_id"],
        "name": source["name"],
        "version": source["version"],
        "source_kind": ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA.value,
        "proposed_usage_basis": ScientificDatasetUsageBasis.PUBLIC_LICENSE.value,
        "license_identifier": source["license_identifier"],
        "license_url": source["license_url"],
        "intended_use": acquisition_plan.intended_use,
        "processing_scope": list(acquisition_plan.processing_scope),
        "derivative_output_scope": list(acquisition_plan.derivative_output_scope),
        "redistribution_plan": acquisition_plan.redistribution_plan,
        "attribution_notice": acquisition_plan.attribution_notice,
        "license_obligations": list(acquisition_plan.license_obligations),
        "unit_id_field": source["unit_id_field"],
        "unit_ids": list(source["unit_ids"]),
        "unit_hashes": list(source["unit_hashes"]),
        "acquisition_plan_artifact_sha256": acquisition_plan.artifact_hash,
        "acquisition_plan_record_hash": acquisition_plan.record_hash,
        "evaluation_contract_artifact_sha256": evaluation_contract_record.sha256,
        "evaluation_contract_record_hash": str(evaluation_contract_record.record_hash),
        "manifest_artifact_sha256": manifest_record.sha256,
        "manifest_record_hash": str(manifest_record.record_hash),
        "transport_authority_artifact_sha256": transport.authority_artifact.sha256,
        "transport_authority_record_hash": str(
            transport.authority_artifact.record_hash
        ),
        "request_artifact_sha256": transport.request_artifact.sha256,
        "request_record_hash": str(transport.request_artifact.record_hash),
        "response_receipt_artifact_sha256": (
            transport.response_receipt_artifact.sha256
        ),
        "response_receipt_record_hash": str(
            transport.response_receipt_artifact.record_hash
        ),
        "raw_data_artifact_sha256": transport.raw_response_artifact.sha256,
        "raw_data_record_hash": str(transport.raw_response_artifact.record_hash),
        "raw_data_sha256": transport.body_sha256,
        "data_projection_sha256": source["data_projection_sha256"],
        "data_item_count": source["data_item_count"],
        "body_size": transport.body_size,
        "human_authority_requested": False,
        "e4_authority_requested": False,
    }


def _resolve_scientific_dataset_transport(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    acquisition_plan_artifact_hash: str,
    evaluation_contract_artifact_hash: str,
    transport_authority_artifact_hash: str,
    response_receipt_artifact_hash: str,
) -> tuple[
    Any,
    Mapping[str, Any],
    bytes,
    ScientificDatasetAcquisitionPlan,
    ArtifactRecord,
]:
    plan = require_scientific_dataset_acquisition_plan(
        registry,
        ledger,
        run_id=run_id,
        plan_artifact_hash=acquisition_plan_artifact_hash,
    )
    validate_sha256(
        evaluation_contract_artifact_hash,
        "scientific dataset evaluation-contract SHA-256",
    )
    try:
        from .external import require_audited_live_transport_execution

        transport = require_audited_live_transport_execution(
            registry,
            ledger,
            run_id=run_id,
            authority_artifact_sha256=transport_authority_artifact_hash,
            response_receipt_artifact_sha256=response_receipt_artifact_hash,
        )
    except Exception as exc:
        raise ValidationError(
            "scientific dataset lacks accepted audited-live transport authority"
        ) from exc
    if (
        transport.authority_artifact.sha256 != transport_authority_artifact_hash
        or transport.response_receipt_artifact.sha256 != response_receipt_artifact_hash
        or transport.run_id != run_id
        or transport.policy_id != plan.policy_id
        or transport.status_code < 200
        or transport.status_code > 299
        or transport.content_type != "application/json"
    ):
        raise ValidationError("scientific dataset transport identity was substituted")
    try:
        from .scientific_design import require_frozen_evaluation_contract

        contract = require_frozen_evaluation_contract(
            registry,
            contract_artifact_sha256=evaluation_contract_artifact_hash,
        )
        contract_record = registry.get_metadata(evaluation_contract_artifact_hash)
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific dataset lacks one frozen evaluation contract"
        ) from exc
    if (
        contract.dataset.dataset_id != plan.dataset_id
        or contract_record.parent_artifacts.count(plan.artifact_hash) != 1
    ):
        raise ValidationError(
            "scientific dataset acquisition plan is not bound by its contract"
        )
    raw = registry.get_bytes(transport.raw_response_artifact.sha256)
    if (
        len(raw) != transport.body_size
        or sha256_bytes(raw) != transport.body_sha256
        or transport.raw_response_artifact.sha256 != transport.body_sha256
    ):
        raise ValidationError("scientific dataset raw bytes differ from transport")
    try:
        request = safe_json_loads(
            registry.get_bytes(transport.request_artifact.sha256),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except Exception as exc:
        raise ValidationError(
            "scientific dataset acquisition request cannot be reopened"
        ) from exc
    expected_request_parents = (
        plan.artifact_hash,
        contract_record.sha256,
    )
    if (
        not isinstance(request, Mapping)
        or request.get("policy_id") != plan.policy_id
        or request.get("adapter_id") != plan.adapter_id
        or request.get("method") != "GET"
        or request.get("url") != plan.source_url
        or request.get("body_sha256") != sha256_bytes(b"")
        or request.get("body_size") != 0
        or request.get("content_type") != "application/json"
        or request.get("credential_present") is not False
        or tuple(request.get("parent_artifacts", ())) != expected_request_parents
        or transport.request_artifact.parent_artifacts != expected_request_parents
        or transport.body_sha256 != plan.expected_body_sha256
    ):
        raise ValidationError(
            "scientific dataset transport differs from prospective acquisition policy"
        )
    source = _scientific_dataset_source_projection(
        raw,
        unit_id_field=plan.unit_id_field,
    )
    if (
        source["dataset_id"] != plan.dataset_id
        or source["name"] != plan.name
        or source["version"] != plan.version
        or source["license_identifier"] != plan.license_identifier
        or source["license_url"] != plan.license_url
    ):
        raise ValidationError(
            "scientific dataset response differs from prospective source identity"
        )
    transport_index, _event = _scientific_dataset_transport_event_index(
        ledger,
        run_id=run_id,
        transport=transport,
    )
    if transport_index <= plan.ledger_event_index:
        raise ValidationError(
            "scientific dataset transport predates its acquisition plan"
        )
    return transport, source, raw, plan, contract_record


def _scientific_dataset_transport_event_index(
    ledger: EventLedger,
    *,
    run_id: str,
    transport: Any,
) -> tuple[int, LedgerEvent]:
    ledger_result = ledger.validate(raise_on_error=True)
    matches = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.run_id == run_id
        and event.event_id == transport.ledger_event_id
        and event.event_hash == transport.ledger_event_hash
        and tuple(event.artifact_hashes) == (transport.authority_artifact.sha256,)
    )
    if len(matches) != 1:
        raise ValidationError("scientific dataset transport event is absent")
    return matches[0]


def register_scientific_dataset_usage_proposal(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    acquisition_plan_artifact_hash: str,
    evaluation_contract_artifact_hash: str,
    transport_authority_artifact_hash: str,
    response_receipt_artifact_hash: str,
) -> ArtifactRecord:
    """Retain one non-authoritative Dataset/license projection for live review."""

    validate_identifier(run_id, "scientific dataset run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    transport, source, _raw, acquisition_plan, contract_record = (
        _resolve_scientific_dataset_transport(
            registry,
            ledger,
            run_id=run_id,
            acquisition_plan_artifact_hash=acquisition_plan_artifact_hash,
            evaluation_contract_artifact_hash=evaluation_contract_artifact_hash,
            transport_authority_artifact_hash=transport_authority_artifact_hash,
            response_receipt_artifact_hash=response_receipt_artifact_hash,
        )
    )
    transport_index, _transport_event = _scientific_dataset_transport_event_index(
        ledger,
        run_id=run_id,
        transport=transport,
    )
    ledger_result = ledger.validate(raise_on_error=True)
    if transport_index != len(ledger_result.events) - 1:
        raise ValidationError(
            "scientific Dataset proposal must be retained at first post-transport visibility"
        )
    manifest_payload = _scientific_dataset_manifest_payload(
        source,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        raw_record=transport.raw_response_artifact,
        transport_authority_record=transport.authority_artifact,
        response_receipt_record=transport.response_receipt_artifact,
    )
    manifest = registry.put_json(
        manifest_payload,
        logical_type=SCIENTIFIC_DATASET_MANIFEST_LOGICAL_TYPE,
        origin=f"audited external scientific dataset manifest {source['dataset_id']}",
        creator_role=Role.EVIDENCE_CURATOR,
        creation_command=("scientist-one", "manifest-audited-scientific-dataset"),
        parent_artifacts=(
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            transport.authority_artifact.sha256,
            transport.response_receipt_artifact.sha256,
            transport.raw_response_artifact.sha256,
        ),
        schema_version=SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
    )
    payload = _scientific_dataset_usage_proposal_payload(
        source,
        run_id=run_id,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        manifest_record=manifest,
        transport=transport,
    )
    proposal = registry.put_json(
        payload,
        logical_type=SCIENTIFIC_DATASET_USAGE_PROPOSAL_LOGICAL_TYPE,
        origin=(
            f"non-authoritative audited Dataset usage proposal {source['dataset_id']}"
        ),
        creator_role=Role.EVIDENCE_CURATOR,
        creation_command=("scientist-one", "propose-scientific-dataset-usage"),
        parent_artifacts=(
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            transport.authority_artifact.sha256,
            transport.request_artifact.sha256,
            transport.response_receipt_artifact.sha256,
            transport.raw_response_artifact.sha256,
            manifest.sha256,
        ),
        schema_version=SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
    )
    _require_scientific_dataset_usage_proposal(
        registry,
        ledger,
        run_id=run_id,
        proposal_artifact_hash=proposal.sha256,
    )
    return proposal


def _require_scientific_dataset_usage_proposal(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    proposal_artifact_hash: str,
    expected_dataset_id: str | None = None,
    expected_version: str | None = None,
) -> tuple[
    ArtifactRecord,
    Mapping[str, Any],
    Any,
    Mapping[str, Any],
    ArtifactRecord,
    ScientificDatasetAcquisitionPlan,
    ArtifactRecord,
]:
    validate_identifier(run_id, "scientific dataset run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(proposal_artifact_hash, "Dataset usage proposal SHA-256")
    if expected_dataset_id is not None:
        validate_identifier(expected_dataset_id, "expected scientific dataset ID")
    if expected_version is not None:
        _bounded_text(expected_version, "expected scientific dataset version")
    try:
        registry.verify(proposal_artifact_hash, raise_on_error=True)
        proposal = registry.get_metadata(proposal_artifact_hash)
        value = safe_json_loads(
            registry.get_bytes(proposal_artifact_hash),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific Dataset usage proposal cannot be reopened"
        ) from exc
    expected_keys = {
        "schema_version",
        "run_id",
        "dataset_id",
        "name",
        "version",
        "source_kind",
        "proposed_usage_basis",
        "license_identifier",
        "license_url",
        "intended_use",
        "processing_scope",
        "derivative_output_scope",
        "redistribution_plan",
        "attribution_notice",
        "license_obligations",
        "unit_id_field",
        "unit_ids",
        "unit_hashes",
        "acquisition_plan_artifact_sha256",
        "acquisition_plan_record_hash",
        "evaluation_contract_artifact_sha256",
        "evaluation_contract_record_hash",
        "manifest_artifact_sha256",
        "manifest_record_hash",
        "transport_authority_artifact_sha256",
        "transport_authority_record_hash",
        "request_artifact_sha256",
        "request_record_hash",
        "response_receipt_artifact_sha256",
        "response_receipt_record_hash",
        "raw_data_artifact_sha256",
        "raw_data_record_hash",
        "raw_data_sha256",
        "data_projection_sha256",
        "data_item_count",
        "body_size",
        "human_authority_requested",
        "e4_authority_requested",
    }
    if not isinstance(value, Mapping) or set(value) != expected_keys:
        raise ValidationError("scientific Dataset usage proposal schema is incomplete")
    if (
        proposal.logical_type != SCIENTIFIC_DATASET_USAGE_PROPOSAL_LOGICAL_TYPE
        or proposal.creator_role is not Role.EVIDENCE_CURATOR
        or proposal.schema_version != SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION
        or proposal.mime_type != "application/json"
        or proposal.origin
        != f"non-authoritative audited Dataset usage proposal {value.get('dataset_id')}"
        or proposal.creation_command
        != ("scientist-one", "propose-scientific-dataset-usage")
        or proposal.validation_result != "PASS"
        or proposal.frozen is not True
        or value.get("schema_version")
        != SCIENTIFIC_DATASET_USAGE_PROPOSAL_PAYLOAD_SCHEMA
        or value.get("run_id") != run_id
        or value.get("source_kind")
        != ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA.value
        or value.get("proposed_usage_basis")
        != ScientificDatasetUsageBasis.PUBLIC_LICENSE.value
        or value.get("human_authority_requested") is not False
        or value.get("e4_authority_requested") is not False
        or (
            expected_dataset_id is not None
            and value.get("dataset_id") != expected_dataset_id
        )
        or (expected_version is not None and value.get("version") != expected_version)
    ):
        raise ValidationError("scientific Dataset usage proposal identity is invalid")
    transport, source, _raw, acquisition_plan, contract_record = (
        _resolve_scientific_dataset_transport(
            registry,
            ledger,
            run_id=run_id,
            acquisition_plan_artifact_hash=str(
                value["acquisition_plan_artifact_sha256"]
            ),
            evaluation_contract_artifact_hash=str(
                value["evaluation_contract_artifact_sha256"]
            ),
            transport_authority_artifact_hash=str(
                value["transport_authority_artifact_sha256"]
            ),
            response_receipt_artifact_hash=str(
                value["response_receipt_artifact_sha256"]
            ),
        )
    )
    manifest = registry.get_metadata(str(value["manifest_artifact_sha256"]))
    expected_manifest = _scientific_dataset_manifest_payload(
        source,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        raw_record=transport.raw_response_artifact,
        transport_authority_record=transport.authority_artifact,
        response_receipt_record=transport.response_receipt_artifact,
    )
    if (
        manifest.logical_type != SCIENTIFIC_DATASET_MANIFEST_LOGICAL_TYPE
        or manifest.creator_role is not Role.EVIDENCE_CURATOR
        or manifest.schema_version != SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION
        or manifest.mime_type != "application/json"
        or manifest.origin
        != f"audited external scientific dataset manifest {source['dataset_id']}"
        or manifest.creation_command
        != ("scientist-one", "manifest-audited-scientific-dataset")
        or manifest.validation_result != "PASS"
        or manifest.frozen is not True
        or manifest.parent_artifacts
        != (
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            transport.authority_artifact.sha256,
            transport.response_receipt_artifact.sha256,
            transport.raw_response_artifact.sha256,
        )
        or registry.get_bytes(manifest.sha256)
        != canonical_json_bytes(expected_manifest) + b"\n"
    ):
        raise ValidationError(
            "scientific Dataset manifest differs from raw acquisition"
        )
    expected_value = _scientific_dataset_usage_proposal_payload(
        source,
        run_id=run_id,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        manifest_record=manifest,
        transport=transport,
    )
    expected_parents = (
        acquisition_plan.artifact_hash,
        contract_record.sha256,
        transport.authority_artifact.sha256,
        transport.request_artifact.sha256,
        transport.response_receipt_artifact.sha256,
        transport.raw_response_artifact.sha256,
        manifest.sha256,
    )
    if (
        dict(value) != expected_value
        or registry.get_bytes(proposal.sha256)
        != canonical_json_bytes(expected_value) + b"\n"
        or proposal.parent_artifacts != expected_parents
    ):
        raise ValidationError("scientific Dataset usage proposal substituted a source")
    _scientific_dataset_transport_event_index(
        ledger,
        run_id=run_id,
        transport=transport,
    )
    return (
        proposal,
        value,
        transport,
        source,
        manifest,
        acquisition_plan,
        contract_record,
    )


def build_scientific_dataset_usage_judgment_request(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    proposal_artifact_hash: str,
) -> ScientificDatasetUsageJudgmentRequest:
    """Build the exact retained provider inputs for Dataset usage review."""

    (
        proposal,
        value,
        transport,
        _source,
        manifest,
        acquisition_plan,
        contract_record,
    ) = _require_scientific_dataset_usage_proposal(
        registry,
        ledger,
        run_id=run_id,
        proposal_artifact_hash=proposal_artifact_hash,
    )
    evidence_records = (
        registry.get_metadata(acquisition_plan.artifact_hash),
        contract_record,
        transport.authority_artifact,
        transport.request_artifact,
        transport.response_receipt_artifact,
        transport.raw_response_artifact,
        manifest,
    )
    retained_sources = tuple(
        _claim_semantics_retained_source(
            record,
            registry.get_bytes(record.sha256),
        )
        for record in evidence_records
    )
    accepted_outcome = f"DATASET_USAGE_ACCEPTED:{proposal.sha256}"
    input_payload = {
        "schema_version": "scientific-dataset-usage-judgment-input/v2",
        "subject_kind": "DATASET_USAGE",
        "subject_id": value["dataset_id"],
        "accepted_outcome": accepted_outcome,
        "usage_proposal_artifact_sha256": proposal.sha256,
        "usage_proposal_record_hash": str(proposal.record_hash),
        "usage_proposal": dict(value),
        "source_artifacts": list(retained_sources),
    }
    output_schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "subject_kind": {"type": "string", "enum": ["DATASET_USAGE"]},
            "subject_id": {"type": "string", "enum": [value["dataset_id"]]},
            "outcome": {
                "type": "string",
                "enum": [accepted_outcome, "DATASET_USAGE_REJECTED"],
            },
            "rationale": {
                "type": "string",
                "minLength": 1,
                "maxLength": MAX_SHORT_TEXT_LENGTH,
            },
        },
        "required": ["subject_kind", "subject_id", "outcome", "rationale"],
    }
    return ScientificDatasetUsageJudgmentRequest(
        subject_id=str(value["dataset_id"]),
        accepted_outcome=accepted_outcome,
        evidence_hashes=tuple(record.sha256 for record in evidence_records),
        context_hashes=(proposal.sha256,),
        instructions=SCIENTIFIC_DATASET_USAGE_PROMPT_INSTRUCTIONS,
        input_text=canonical_json_bytes(input_payload).decode("utf-8"),
        output_schema=output_schema,
        prompt_template_id=SCIENTIFIC_DATASET_USAGE_PROMPT_TEMPLATE_ID,
        prompt_template_version=SCIENTIFIC_DATASET_USAGE_PROMPT_TEMPLATE_VERSION,
        prompt_template_hash=sha256_bytes(
            SCIENTIFIC_DATASET_USAGE_PROMPT_INSTRUCTIONS.encode("utf-8")
        ),
        governing_rule=SCIENTIFIC_DATASET_USAGE_GOVERNING_RULE,
    )


def _require_scientific_dataset_usage_semantic_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    proposal_artifact_hash: str,
    semantic_authority_artifact_hash: str,
) -> tuple[
    ScientificDatasetUsageJudgmentRequest,
    ArtifactRecord,
    Mapping[str, Any],
    Any,
    Mapping[str, Any],
    ArtifactRecord,
    ArtifactRecord,
    str,
    ScientificDatasetAcquisitionPlan,
    ArtifactRecord,
]:
    request = build_scientific_dataset_usage_judgment_request(
        registry,
        ledger,
        run_id=run_id,
        proposal_artifact_hash=proposal_artifact_hash,
    )
    (
        proposal,
        value,
        transport,
        source,
        manifest,
        acquisition_plan,
        contract_record,
    ) = _require_scientific_dataset_usage_proposal(
        registry,
        ledger,
        run_id=run_id,
        proposal_artifact_hash=proposal_artifact_hash,
        expected_dataset_id=request.subject_id,
    )
    try:
        from .gates import (
            JudgmentSubjectKind,
            require_scientific_semantic_judgment_receipt,
        )

        judgment = require_scientific_semantic_judgment_receipt(
            registry,
            ledger,
            run_id=run_id,
            receipt_artifact_hash=semantic_authority_artifact_hash,
            subject_kind=JudgmentSubjectKind.DATASET_USAGE,
            subject_id=request.subject_id,
            outcome=request.accepted_outcome,
            evidence_hashes=request.evidence_hashes,
            context_hashes=request.context_hashes,
        )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific Dataset usage lacks audited-live semantic authority"
        ) from exc
    semantic_record = registry.get_metadata(semantic_authority_artifact_hash)
    try:
        provider_record = registry.get_metadata(
            judgment.provider_response_artifact_hash
        )
        instructions = registry.get_bytes(judgment.instructions_artifact_hash)
        judged_input = registry.get_bytes(judgment.input_artifact_hash)
        output_schema = registry.get_bytes(judgment.output_schema_artifact_hash)
    except ArtifactError as exc:
        raise ValidationError(
            "scientific Dataset usage retained provider inputs are absent"
        ) from exc
    if (
        judgment.prompt_template_id != request.prompt_template_id
        or judgment.prompt_template_version != request.prompt_template_version
        or judgment.prompt_template_hash != request.prompt_template_hash
        or judgment.governing_rule != request.governing_rule
        or instructions != request.instructions_bytes
        or judged_input != request.input_bytes
        or output_schema != request.output_schema_bytes
        or len(provider_record.parent_artifacts) != 3
    ):
        raise ValidationError(
            "scientific Dataset usage prompt, input, schema, or custody was substituted"
        )
    semantic_transport_authority_hash = provider_record.parent_artifacts[2]
    return (
        request,
        proposal,
        value,
        transport,
        source,
        manifest,
        semantic_record,
        semantic_transport_authority_hash,
        acquisition_plan,
        contract_record,
    )


def _scientific_dataset_artifact_plan(
    registry: ArtifactRegistry,
    payload: Mapping[str, Any],
    *,
    logical_type: str,
    origin: str,
    creator_role: Role,
    creation_command: tuple[str, ...],
    parent_artifacts: tuple[str, ...],
    schema_version: str,
    created_at: str,
) -> tuple[bytes, ArtifactRecord]:
    """Build exact immutable Dataset metadata without publishing any bytes."""

    data = canonical_json_bytes(payload) + b"\n"
    digest = sha256_bytes(data)
    object_path = registry.objects_path / digest[:2] / digest
    metadata_path = registry.metadata_path / digest[:2] / f"{digest}.json"
    return data, ArtifactRecord(
        sha256=digest,
        path=object_path.as_posix(),
        relative_path=object_path.as_posix(),
        metadata_path=metadata_path.as_posix(),
        logical_type=logical_type,
        schema_version=schema_version,
        mime_type="application/json",
        size=len(data),
        origin=origin,
        creator_role=creator_role,
        creation_command=creation_command,
        parent_artifacts=parent_artifacts,
        validation_result="PASS",
        frozen=True,
        created_at=created_at,
    )


def _scientific_dataset_identity_candidates(
    registry: ArtifactRegistry,
    records: tuple[ArtifactRecord, ...],
    *,
    logical_type: str,
    identity: Mapping[str, Any],
) -> tuple[ArtifactRecord, ...]:
    """Find every frozen artifact claiming one Dataset semantic identity."""

    candidates: list[ArtifactRecord] = []
    for record in records:
        if record.logical_type != logical_type:
            continue
        try:
            value = safe_json_loads(
                registry.get_bytes(record.sha256),
                max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
            )
        except (ArtifactError, ValidationError):
            raise
        except Exception as exc:
            raise ValidationError(
                "scientific Dataset publication candidate is unreadable"
            ) from exc
        if not isinstance(value, Mapping):
            raise ValidationError(
                "scientific Dataset publication candidate is malformed"
            )
        if all(value.get(key) == expected for key, expected in identity.items()):
            candidates.append(record)
    return tuple(candidates)


def _preflight_scientific_dataset_publication(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    plans: tuple[tuple[bytes, ArtifactRecord], ...],
    event_id: str,
    actor_role: Role,
    event_artifact_hashes: tuple[str, ...],
    event_timestamp: str,
    reason: str,
    metadata: Mapping[str, Any],
) -> tuple[frozenset[str], LedgerEvent | None]:
    """Validate one append-only Dataset publication before its first write."""

    registry.verify_all(raise_on_error=True)
    ledger_result = ledger.validate(raise_on_error=True)
    if not ledger_result.events:
        raise ValidationError(
            "scientific Dataset publication requires an initialized ledger"
        )
    expected_by_hash = {record.sha256: (data, record) for data, record in plans}
    if len(expected_by_hash) != len(plans):
        raise ValidationError("scientific Dataset publication artifacts must be unique")
    registry_records = {record.sha256: record for record in registry.list_records()}
    missing: set[str] = set()
    for digest, (data, expected) in expected_by_hash.items():
        existing = registry_records.get(digest)
        if existing is None:
            missing.add(digest)
            continue
        if existing != expected or registry.get_bytes(digest) != data:
            raise ValidationError("scientific Dataset publication artifact collides")

    matching_events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.event_id == event_id
    )
    if len(matching_events) > 1:
        raise ValidationError("scientific Dataset publication event is ambiguous")
    event_to_append: LedgerEvent | None = None
    if matching_events:
        event_index, event = matching_events[0]
        if missing or event_index == 0:
            raise ValidationError(
                "scientific Dataset publication event precedes its artifacts"
            )
        prior = ledger_result.events[event_index - 1]
        expected_event = LedgerEvent.create(
            run_id=run_id,
            actor_role=actor_role,
            state_before=prior.requested_state_after,
            requested_state_after=prior.requested_state_after,
            artifact_hashes=event_artifact_hashes,
            code_version=prior.code_version,
            configuration_hash=prior.configuration_hash,
            reason=reason,
            prior_event_hash=prior.event_hash,
            event_id=event_id,
            timestamp=event_timestamp,
            event_type="CHECKPOINT",
            metadata=metadata,
        )
        if event != expected_event or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in ledger_result.events[event_index + 1 :]
        ):
            raise ValidationError(
                "scientific Dataset publication event collides or is stale"
            )
    else:
        if any(
            tuple(event.artifact_hashes) == event_artifact_hashes
            for event in ledger_result.events
        ):
            raise ValidationError(
                "scientific Dataset publication artifacts name another event"
            )
        current = ledger_result.events[-1]
        event_to_append = LedgerEvent.create(
            run_id=run_id,
            actor_role=actor_role,
            state_before=current.requested_state_after,
            requested_state_after=current.requested_state_after,
            artifact_hashes=event_artifact_hashes,
            code_version=current.code_version,
            configuration_hash=current.configuration_hash,
            reason=reason,
            prior_event_hash=current.event_hash,
            event_id=event_id,
            timestamp=event_timestamp,
            event_type="CHECKPOINT",
            metadata=metadata,
        )

    if len(registry_records) + len(missing) > MAX_REGISTRY_RECORDS:
        raise ValidationError(
            "scientific Dataset publication exceeds registry capacity"
        )
    if event_to_append is not None:
        event_bytes = canonical_json_bytes(event_to_append.to_dict()) + b"\n"
        if len(ledger_result.events) + 1 > MAX_LEDGER_EVENTS:
            raise ValidationError(
                "scientific Dataset publication exceeds ledger capacity"
            )
        if ledger_result.valid_prefix_bytes + len(event_bytes) > MAX_LEDGER_BYTES:
            raise ValidationError(
                "scientific Dataset publication exceeds ledger byte capacity"
            )
    return frozenset(missing), event_to_append


def _scientific_dataset_publication_snapshot(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
) -> tuple[RegistryValidationResult, LedgerValidationResult]:
    """Pin prospective Dataset sources and reject possible operational exposure."""

    from .seed_reporting import reject_operational_seed_exposure

    snapshot = _locked_research_state_source_snapshot(registry, ledger, run_id=run_id)
    reject_operational_seed_exposure(
        registry, snapshot[0].records, snapshot[1].events,
        complete_registry_population=True,
    )
    return snapshot


def _require_current_scientific_dataset_publication_contract(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    contract_record: ArtifactRecord,
    missing: frozenset[str],
    event_to_append: LedgerEvent | None,
    source_snapshot: tuple[RegistryValidationResult, LedgerValidationResult],
) -> None:
    """Require current lineage for new writes, never refresh their source pair.

    Only complete, preflighted no-op retries are historical use. An exact
    record-only orphan still needs a new event and must pass this check. The
    unchanged commit CAS closes changes after this unlocked lineage read.
    """

    if not missing and event_to_append is None:
        return
    from .evaluation_contract_amendment import _require_current_evaluation_contract_lineage

    lineage = _require_current_evaluation_contract_lineage(
        registry, ledger, expected_run_id=run_id,
        contract_artifact_sha256=contract_record.sha256,
    )
    if lineage.contract_record != contract_record:
        raise ValidationError("scientific Dataset current contract record differs")
    if (lineage.registry_snapshot, lineage.ledger_snapshot) != source_snapshot:
        raise ValidationError("scientific Dataset sources changed during current-contract resolution")


def _commit_scientific_dataset_publication(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    plans: tuple[tuple[bytes, ArtifactRecord], ...],
    missing: frozenset[str],
    event_to_append: LedgerEvent | None,
    source_snapshot: tuple[RegistryValidationResult, LedgerValidationResult],
) -> tuple[ArtifactRecord, ...]:
    """Publish under paired source CAS, resuming only exact inert orphans.

    Holding both namespaces closes an admission interleaving with non-isolated
    operational work. Partial disk failures remain recoverable prefixes, not a
    claim of filesystem transactionality or independent scientific authority.
    """

    from .seed_reporting import reject_operational_seed_exposure

    committed: list[ArtifactRecord] = []
    registry_guard = registry._open_mutation_lock()
    try:
        ledger_guard = ledger._open_lock()
        try:
            locked_registry = registry._verify_all_locked(registry_guard, raise_on_error=True)
            locked_ledger_bytes = ledger._read_raw_locked(ledger_guard)
            locked_ledger = ledger._validate_bytes(locked_ledger_bytes)
            if not locked_ledger.valid or (locked_registry, locked_ledger) != source_snapshot:
                raise ValidationError("scientific Dataset sources changed before publication")
            reject_operational_seed_exposure(
                registry, locked_registry.records, locked_ledger.events,
                complete_registry_population=True,
            )
            by_sha = {record.sha256: record for record in locked_registry.records}
            if len({record.sha256 for _, record in plans}) != len(plans):
                raise ValidationError("scientific Dataset publication artifacts must be unique")
            actual_missing = frozenset(
                record.sha256 for _, record in plans if record.sha256 not in by_sha
            )
            if actual_missing != missing:
                raise ValidationError("scientific Dataset missing-artifact plan changed")
            detached_plans: list[tuple[bytes, ArtifactRecord]] = []
            available_parents = set(by_sha)
            for data, expected in plans:
                if type(data) is not bytes or type(expected) is not ArtifactRecord:
                    raise ValidationError("scientific Dataset plan requires native bytes and metadata")
                detached = ArtifactRecord.from_dict(safe_json_loads(
                    canonical_json_bytes(expected.to_dict()),
                ))
                object_path = (registry.objects_path / detached.sha256[:2] / detached.sha256).as_posix()
                metadata_path = (
                    registry.metadata_path / detached.sha256[:2] / f"{detached.sha256}.json"
                ).as_posix()
                if (
                    sha256_bytes(data) != expected.sha256 or len(data) != expected.size
                    or detached != expected
                    or detached.path != object_path or detached.relative_path != object_path
                    or detached.metadata_path != metadata_path
                    or (expected.sha256 in by_sha and by_sha[expected.sha256] != expected)
                    or any(parent not in available_parents for parent in detached.parent_artifacts)
                ):
                    raise ValidationError("scientific Dataset planned artifact differs")
                available_parents.add(detached.sha256)
                detached_plans.append((data, detached))
            plans = tuple(detached_plans)
            if locked_registry.count + len(missing) > MAX_REGISTRY_RECORDS:
                raise ValidationError("scientific Dataset publication exceeds registry capacity")
            if event_to_append is not None:
                if type(event_to_append) is not LedgerEvent:
                    raise ValidationError("scientific Dataset plan requires one native event")
                event_to_append = LedgerEvent.from_dict(safe_json_loads(
                    canonical_json_bytes(event_to_append.to_dict()),
                ))
                if (
                    event_to_append.prior_event_hash != locked_ledger.head_hash
                    or any(event.event_id == event_to_append.event_id for event in locked_ledger.events)
                ):
                    raise ValidationError("scientific Dataset planned event is stale")
                event_bytes = canonical_json_bytes(event_to_append.to_dict()) + b"\n"
                if locked_ledger.event_count + 1 > MAX_LEDGER_EVENTS:
                    raise ValidationError("scientific Dataset publication exceeds ledger capacity")
                if locked_ledger.valid_prefix_bytes + len(event_bytes) > MAX_LEDGER_BYTES:
                    raise ValidationError("scientific Dataset publication exceeds ledger byte capacity")
                prospective = ledger._validate_bytes(locked_ledger_bytes + event_bytes)
                if (
                    not prospective.valid
                    or prospective.event_count != locked_ledger.event_count + 1
                    or prospective.events[-1] != event_to_append
                ):
                    raise ValidationError("scientific Dataset prospective event is invalid")
            for data, expected in plans:
                if expected.sha256 in missing:
                    actual = registry._put_bytes_locked(
                        registry_guard, data,
                        logical_type=expected.logical_type,
                        origin=expected.origin,
                        creator_role=expected.creator_role,
                        creation_command=expected.creation_command,
                        parent_artifacts=expected.parent_artifacts,
                        schema_version=expected.schema_version,
                        mime_type=expected.mime_type,
                        validation_result=expected.validation_result,
                        frozen=expected.frozen,
                        created_at=expected.created_at,
                    )
                else:
                    actual = registry._get_metadata_locked(registry_guard, expected.sha256)
                if actual != expected:
                    raise ValidationError("scientific Dataset publication changed during commit")
                committed.append(actual)
            if event_to_append is not None:
                def build_event(current: LedgerValidationResult) -> LedgerEvent:
                    if current != locked_ledger:
                        raise ValidationError("scientific Dataset ledger changed during commit")
                    return event_to_append

                appended = ledger._append_locked(ledger_guard, build_event)
                if appended != event_to_append:
                    raise ValidationError("scientific Dataset publication event changed during commit")
            registry._verify_mutation_namespace(registry_guard)
        finally:
            ledger._unlock(ledger_guard)
    finally:
        registry._unlock_mutation(registry_guard)
    return tuple(committed)


def register_scientific_dataset_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    usage_proposal_artifact_hash: str,
    semantic_authority_artifact_hash: str,
) -> ArtifactRecord:
    """Materialize Dataset authority only after exact audited-live usage review."""

    validate_identifier(run_id, "scientific dataset run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    publication_snapshot = _scientific_dataset_publication_snapshot(
        registry, ledger, run_id=run_id,
    )
    (
        _request,
        proposal,
        _proposal_value,
        transport,
        source,
        manifest,
        semantic_record,
        semantic_transport_authority_hash,
        acquisition_plan,
        contract_record,
    ) = _require_scientific_dataset_usage_semantic_authority(
        registry,
        ledger,
        run_id=run_id,
        proposal_artifact_hash=usage_proposal_artifact_hash,
        semantic_authority_artifact_hash=semantic_authority_artifact_hash,
    )
    ledger_result = ledger.validate(raise_on_error=True)
    semantic_transport_events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.run_id == run_id
        and tuple(event.artifact_hashes) == (semantic_transport_authority_hash,)
    )
    if len(semantic_transport_events) != 1:
        raise ValidationError(
            "scientific Dataset usage-review transport event is absent"
        )
    semantic_event_index, semantic_event = semantic_transport_events[0]
    if any(
        later.event_type == "CORRECTION"
        and later.supersedes_event_id == semantic_event.event_id
        for later in ledger_result.events[semantic_event_index + 1 :]
    ):
        raise ValidationError(
            "scientific Dataset usage-review transport event is stale"
        )
    created_at = semantic_event.timestamp
    usage_payload = _scientific_dataset_usage_payload(
        source,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        manifest_record=manifest,
        proposal_record=proposal,
        semantic_authority_record=semantic_record,
    )
    usage_plan = _scientific_dataset_artifact_plan(
        registry,
        usage_payload,
        logical_type=SCIENTIFIC_DATASET_USAGE_LOGICAL_TYPE,
        origin=f"audited-review public license basis {source['dataset_id']}",
        creator_role=Role.EVIDENCE_CURATOR,
        creation_command=("scientist-one", "verify-scientific-dataset-usage"),
        parent_artifacts=(
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            proposal.sha256,
            semantic_record.sha256,
            manifest.sha256,
        ),
        schema_version=SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION,
        created_at=created_at,
    )
    usage = usage_plan[1]
    authority_payload = {
        "schema_version": SCIENTIFIC_DATASET_AUTHORITY_PAYLOAD_SCHEMA,
        "run_id": run_id,
        "dataset_id": source["dataset_id"],
        "name": source["name"],
        "version": source["version"],
        "source_kind": ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA.value,
        "usage_basis": ScientificDatasetUsageBasis.PUBLIC_LICENSE.value,
        "license_identifier": source["license_identifier"],
        "license_url": source["license_url"],
        "acquisition_plan_artifact_sha256": acquisition_plan.artifact_hash,
        "acquisition_plan_record_hash": acquisition_plan.record_hash,
        "evaluation_contract_artifact_sha256": contract_record.sha256,
        "evaluation_contract_record_hash": str(contract_record.record_hash),
        "manifest_artifact_sha256": manifest.sha256,
        "manifest_record_hash": str(manifest.record_hash),
        "usage_artifact_sha256": usage.sha256,
        "usage_record_hash": str(usage.record_hash),
        "usage_proposal_artifact_sha256": proposal.sha256,
        "usage_proposal_record_hash": str(proposal.record_hash),
        "semantic_authority_artifact_sha256": semantic_record.sha256,
        "semantic_authority_record_hash": str(semantic_record.record_hash),
        "semantic_transport_authority_artifact_sha256": (
            semantic_transport_authority_hash
        ),
        "transport_authority_artifact_sha256": transport.authority_artifact.sha256,
        "transport_authority_record_hash": str(
            transport.authority_artifact.record_hash
        ),
        "request_artifact_sha256": transport.request_artifact.sha256,
        "request_record_hash": str(transport.request_artifact.record_hash),
        "response_receipt_artifact_sha256": (
            transport.response_receipt_artifact.sha256
        ),
        "response_receipt_record_hash": str(
            transport.response_receipt_artifact.record_hash
        ),
        "raw_data_artifact_sha256": transport.raw_response_artifact.sha256,
        "raw_data_record_hash": str(transport.raw_response_artifact.record_hash),
        "raw_data_sha256": transport.body_sha256,
        "data_projection_sha256": source["data_projection_sha256"],
        "body_size": transport.body_size,
        "human_authority": False,
        "e4_authority": False,
    }
    authority_plan = _scientific_dataset_artifact_plan(
        registry,
        authority_payload,
        logical_type=SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE,
        origin=f"audited external scientific dataset authority {source['dataset_id']}",
        creator_role=Role.EVIDENCE_CURATOR,
        creation_command=("scientist-one", "authorize-audited-scientific-dataset"),
        parent_artifacts=(
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            proposal.sha256,
            semantic_record.sha256,
            transport.authority_artifact.sha256,
            transport.request_artifact.sha256,
            transport.response_receipt_artifact.sha256,
            transport.raw_response_artifact.sha256,
            manifest.sha256,
            usage.sha256,
        ),
        schema_version=SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION,
        created_at=created_at,
    )
    authority = authority_plan[1]
    registry_records = registry.list_records()
    usage_candidates = _scientific_dataset_identity_candidates(
        registry,
        registry_records,
        logical_type=SCIENTIFIC_DATASET_USAGE_LOGICAL_TYPE,
        identity={
            "dataset_id": source["dataset_id"],
            "version": source["version"],
        },
    )
    authority_candidates = _scientific_dataset_identity_candidates(
        registry,
        registry_records,
        logical_type=SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE,
        identity={
            "run_id": run_id,
            "dataset_id": source["dataset_id"],
            "version": source["version"],
        },
    )
    if (
        any(record.sha256 != usage.sha256 for record in usage_candidates)
        or any(record.sha256 != authority.sha256 for record in authority_candidates)
        or len(usage_candidates) > 1
        or len(authority_candidates) > 1
    ):
        raise ValidationError("scientific Dataset authority semantic identity collides")
    event_id = f"scientific-dataset-{authority.sha256[:32]}"
    event_metadata = {
        "schema_version": SCIENTIFIC_DATASET_AUTHORITY_EVENT_SCHEMA,
        "dataset_id": source["dataset_id"],
        "dataset_version": source["version"],
        "authority_artifact_hash": authority.sha256,
        "authority_record_hash": authority.record_hash,
        "acquisition_plan_artifact_hash": acquisition_plan.artifact_hash,
        "evaluation_contract_artifact_hash": contract_record.sha256,
        "transport_authority_artifact_hash": transport.authority_artifact.sha256,
        "response_receipt_artifact_hash": (transport.response_receipt_artifact.sha256),
        "raw_data_artifact_hash": transport.raw_response_artifact.sha256,
        "manifest_artifact_hash": manifest.sha256,
        "usage_artifact_hash": usage.sha256,
        "usage_proposal_artifact_hash": proposal.sha256,
        "semantic_authority_artifact_hash": semantic_record.sha256,
        "semantic_transport_authority_artifact_hash": (
            semantic_transport_authority_hash
        ),
    }
    matching_event_indexes = tuple(
        index
        for index, event in enumerate(ledger_result.events)
        if event.event_id == event_id
    )
    if matching_event_indexes:
        if matching_event_indexes != (semantic_event_index + 1,):
            raise ValidationError(
                "scientific Dataset authority event is not immediately after review"
            )
    elif semantic_event_index != len(ledger_result.events) - 1:
        raise ValidationError(
            "scientific Dataset authority must be minted immediately after usage review"
        )
    plans = (usage_plan, authority_plan)
    missing, event_to_append = _preflight_scientific_dataset_publication(
        registry,
        ledger,
        run_id=run_id,
        plans=plans,
        event_id=event_id,
        actor_role=Role.EVIDENCE_CURATOR,
        event_artifact_hashes=(authority.sha256,),
        event_timestamp=created_at,
        reason="verified exact Dataset identity, manifest, and public-license basis",
        metadata=event_metadata,
    )
    _require_current_scientific_dataset_publication_contract(
        registry, ledger, run_id=run_id, contract_record=contract_record,
        missing=missing, event_to_append=event_to_append,
        source_snapshot=publication_snapshot,
    )
    committed = _commit_scientific_dataset_publication(
        registry,
        ledger,
        plans=plans,
        missing=missing,
        event_to_append=event_to_append,
        source_snapshot=publication_snapshot,
    )
    authority = committed[1]
    require_scientific_dataset_authority(
        registry,
        ledger,
        run_id=run_id,
        authority_artifact_hash=authority.sha256,
        expected_dataset_id=str(source["dataset_id"]),
        expected_version=str(source["version"]),
    )
    return authority


def require_scientific_dataset_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    authority_artifact_hash: str,
    expected_dataset_id: str | None = None,
    expected_version: str | None = None,
) -> ScientificDatasetAuthority:
    """Freshly replay transport, raw bytes, manifest, license, and ledger event."""

    validate_identifier(run_id, "scientific dataset run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(authority_artifact_hash, "scientific dataset authority SHA-256")
    if expected_dataset_id is not None:
        validate_identifier(expected_dataset_id, "expected scientific dataset ID")
    if expected_version is not None:
        _bounded_text(expected_version, "expected scientific dataset version")
    try:
        registry.verify(authority_artifact_hash, raise_on_error=True)
        authority_record = registry.get_metadata(authority_artifact_hash)
        authority_value = safe_json_loads(
            registry.get_bytes(authority_artifact_hash),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific dataset authority cannot be rehydrated"
        ) from exc
    if not isinstance(authority_value, Mapping) or set(authority_value) != {
        "schema_version",
        "run_id",
        "dataset_id",
        "name",
        "version",
        "source_kind",
        "usage_basis",
        "license_identifier",
        "license_url",
        "acquisition_plan_artifact_sha256",
        "acquisition_plan_record_hash",
        "evaluation_contract_artifact_sha256",
        "evaluation_contract_record_hash",
        "manifest_artifact_sha256",
        "manifest_record_hash",
        "usage_artifact_sha256",
        "usage_record_hash",
        "usage_proposal_artifact_sha256",
        "usage_proposal_record_hash",
        "semantic_authority_artifact_sha256",
        "semantic_authority_record_hash",
        "semantic_transport_authority_artifact_sha256",
        "transport_authority_artifact_sha256",
        "transport_authority_record_hash",
        "request_artifact_sha256",
        "request_record_hash",
        "response_receipt_artifact_sha256",
        "response_receipt_record_hash",
        "raw_data_artifact_sha256",
        "raw_data_record_hash",
        "raw_data_sha256",
        "data_projection_sha256",
        "body_size",
        "human_authority",
        "e4_authority",
    }:
        raise ValidationError("scientific dataset authority schema is incomplete")
    if (
        authority_record.logical_type != SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE
        or authority_record.creator_role is not Role.EVIDENCE_CURATOR
        or authority_record.schema_version
        != SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION
        or authority_record.mime_type != "application/json"
        or authority_record.origin
        != (
            "audited external scientific dataset authority "
            f"{authority_value.get('dataset_id')}"
        )
        or authority_record.creation_command
        != ("scientist-one", "authorize-audited-scientific-dataset")
        or authority_record.validation_result != "PASS"
        or authority_record.frozen is not True
        or authority_value.get("schema_version")
        != SCIENTIFIC_DATASET_AUTHORITY_PAYLOAD_SCHEMA
        or authority_value.get("run_id") != run_id
        or authority_value.get("source_kind")
        != ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA.value
        or authority_value.get("usage_basis")
        != ScientificDatasetUsageBasis.PUBLIC_LICENSE.value
        or authority_value.get("human_authority") is not False
        or authority_value.get("e4_authority") is not False
        or (
            expected_dataset_id is not None
            and authority_value.get("dataset_id") != expected_dataset_id
        )
        or (
            expected_version is not None
            and authority_value.get("version") != expected_version
        )
    ):
        raise ValidationError("scientific dataset authority identity is invalid")
    (
        _request,
        proposal,
        _proposal_value,
        transport,
        source,
        manifest,
        semantic_record,
        semantic_transport_authority_hash,
        acquisition_plan,
        contract_record,
    ) = _require_scientific_dataset_usage_semantic_authority(
        registry,
        ledger,
        run_id=run_id,
        proposal_artifact_hash=str(authority_value["usage_proposal_artifact_sha256"]),
        semantic_authority_artifact_hash=str(
            authority_value["semantic_authority_artifact_sha256"]
        ),
    )
    usage = registry.get_metadata(str(authority_value["usage_artifact_sha256"]))
    expected_manifest = _scientific_dataset_manifest_payload(
        source,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        raw_record=transport.raw_response_artifact,
        transport_authority_record=transport.authority_artifact,
        response_receipt_record=transport.response_receipt_artifact,
    )
    expected_usage = _scientific_dataset_usage_payload(
        source,
        acquisition_plan=acquisition_plan,
        evaluation_contract_record=contract_record,
        manifest_record=manifest,
        proposal_record=proposal,
        semantic_authority_record=semantic_record,
    )
    if (
        manifest.logical_type != SCIENTIFIC_DATASET_MANIFEST_LOGICAL_TYPE
        or manifest.creator_role is not Role.EVIDENCE_CURATOR
        or manifest.schema_version != SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION
        or manifest.mime_type != "application/json"
        or manifest.origin
        != f"audited external scientific dataset manifest {source['dataset_id']}"
        or manifest.creation_command
        != ("scientist-one", "manifest-audited-scientific-dataset")
        or manifest.validation_result != "PASS"
        or manifest.frozen is not True
        or manifest.parent_artifacts
        != (
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            transport.authority_artifact.sha256,
            transport.response_receipt_artifact.sha256,
            transport.raw_response_artifact.sha256,
        )
        or registry.get_bytes(manifest.sha256)
        != canonical_json_bytes(expected_manifest) + b"\n"
        or usage.logical_type != SCIENTIFIC_DATASET_USAGE_LOGICAL_TYPE
        or usage.creator_role is not Role.EVIDENCE_CURATOR
        or usage.schema_version != SCIENTIFIC_DATASET_AUTHORITY_SCHEMA_VERSION
        or usage.mime_type != "application/json"
        or usage.origin != f"audited-review public license basis {source['dataset_id']}"
        or usage.creation_command
        != ("scientist-one", "verify-scientific-dataset-usage")
        or usage.validation_result != "PASS"
        or usage.frozen is not True
        or usage.parent_artifacts
        != (
            acquisition_plan.artifact_hash,
            contract_record.sha256,
            proposal.sha256,
            semantic_record.sha256,
            manifest.sha256,
        )
        or registry.get_bytes(usage.sha256)
        != canonical_json_bytes(expected_usage) + b"\n"
    ):
        raise ValidationError("scientific dataset manifest or usage basis is invalid")
    expected_authority = {
        "schema_version": SCIENTIFIC_DATASET_AUTHORITY_PAYLOAD_SCHEMA,
        "run_id": run_id,
        "dataset_id": source["dataset_id"],
        "name": source["name"],
        "version": source["version"],
        "source_kind": ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA.value,
        "usage_basis": ScientificDatasetUsageBasis.PUBLIC_LICENSE.value,
        "license_identifier": source["license_identifier"],
        "license_url": source["license_url"],
        "acquisition_plan_artifact_sha256": acquisition_plan.artifact_hash,
        "acquisition_plan_record_hash": acquisition_plan.record_hash,
        "evaluation_contract_artifact_sha256": contract_record.sha256,
        "evaluation_contract_record_hash": str(contract_record.record_hash),
        "manifest_artifact_sha256": manifest.sha256,
        "manifest_record_hash": str(manifest.record_hash),
        "usage_artifact_sha256": usage.sha256,
        "usage_record_hash": str(usage.record_hash),
        "usage_proposal_artifact_sha256": proposal.sha256,
        "usage_proposal_record_hash": str(proposal.record_hash),
        "semantic_authority_artifact_sha256": semantic_record.sha256,
        "semantic_authority_record_hash": str(semantic_record.record_hash),
        "semantic_transport_authority_artifact_sha256": (
            semantic_transport_authority_hash
        ),
        "transport_authority_artifact_sha256": transport.authority_artifact.sha256,
        "transport_authority_record_hash": str(
            transport.authority_artifact.record_hash
        ),
        "request_artifact_sha256": transport.request_artifact.sha256,
        "request_record_hash": str(transport.request_artifact.record_hash),
        "response_receipt_artifact_sha256": (
            transport.response_receipt_artifact.sha256
        ),
        "response_receipt_record_hash": str(
            transport.response_receipt_artifact.record_hash
        ),
        "raw_data_artifact_sha256": transport.raw_response_artifact.sha256,
        "raw_data_record_hash": str(transport.raw_response_artifact.record_hash),
        "raw_data_sha256": transport.body_sha256,
        "data_projection_sha256": source["data_projection_sha256"],
        "body_size": transport.body_size,
        "human_authority": False,
        "e4_authority": False,
    }
    expected_parents = (
        acquisition_plan.artifact_hash,
        contract_record.sha256,
        proposal.sha256,
        semantic_record.sha256,
        transport.authority_artifact.sha256,
        transport.request_artifact.sha256,
        transport.response_receipt_artifact.sha256,
        transport.raw_response_artifact.sha256,
        manifest.sha256,
        usage.sha256,
    )
    if (
        dict(authority_value) != expected_authority
        or registry.get_bytes(authority_record.sha256)
        != canonical_json_bytes(expected_authority) + b"\n"
        or authority_record.parent_artifacts != expected_parents
    ):
        raise ValidationError("scientific dataset authority differs from exact sources")
    ledger_result = ledger.validate(raise_on_error=True)
    semantic_transport_indexes = tuple(
        index
        for index, event in enumerate(ledger_result.events)
        if event.run_id == run_id
        and tuple(event.artifact_hashes) == (semantic_transport_authority_hash,)
    )
    if len(semantic_transport_indexes) != 1:
        raise ValidationError(
            "scientific Dataset usage-review transport event is absent"
        )
    semantic_event_index = semantic_transport_indexes[0]
    semantic_event = ledger_result.events[semantic_event_index]
    if (
        usage.created_at != semantic_event.timestamp
        or authority_record.created_at != semantic_event.timestamp
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == semantic_event.event_id
            for later in ledger_result.events[semantic_event_index + 1 :]
        )
    ):
        raise ValidationError(
            "scientific Dataset authority timestamp or review event differs"
        )
    events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.event_id == f"scientific-dataset-{authority_record.sha256[:32]}"
    )
    event_metadata = {
        "schema_version": SCIENTIFIC_DATASET_AUTHORITY_EVENT_SCHEMA,
        "dataset_id": source["dataset_id"],
        "dataset_version": source["version"],
        "authority_artifact_hash": authority_record.sha256,
        "authority_record_hash": authority_record.record_hash,
        "acquisition_plan_artifact_hash": acquisition_plan.artifact_hash,
        "evaluation_contract_artifact_hash": contract_record.sha256,
        "transport_authority_artifact_hash": transport.authority_artifact.sha256,
        "response_receipt_artifact_hash": (transport.response_receipt_artifact.sha256),
        "raw_data_artifact_hash": transport.raw_response_artifact.sha256,
        "manifest_artifact_hash": manifest.sha256,
        "usage_artifact_hash": usage.sha256,
        "usage_proposal_artifact_hash": proposal.sha256,
        "semantic_authority_artifact_hash": semantic_record.sha256,
        "semantic_transport_authority_artifact_hash": (
            semantic_transport_authority_hash
        ),
    }
    expected_event = LedgerEvent.create(
        run_id=run_id,
        actor_role=Role.EVIDENCE_CURATOR,
        state_before=semantic_event.requested_state_after,
        requested_state_after=semantic_event.requested_state_after,
        artifact_hashes=(authority_record.sha256,),
        code_version=semantic_event.code_version,
        configuration_hash=semantic_event.configuration_hash,
        reason="verified exact Dataset identity, manifest, and public-license basis",
        prior_event_hash=semantic_event.event_hash,
        event_id=f"scientific-dataset-{authority_record.sha256[:32]}",
        timestamp=authority_record.created_at,
        event_type="CHECKPOINT",
        metadata=event_metadata,
    )
    if (
        len(events) != 1
        or events[0][0] != semantic_event_index + 1
        or events[0][1] != expected_event
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == events[0][1].event_id
            for later in ledger_result.events[events[0][0] + 1 :]
        )
    ):
        raise ValidationError("scientific dataset ledger authority is absent or stale")
    event_index, event = events[0]
    return ScientificDatasetAuthority(
        run_id=run_id,
        dataset_id=str(source["dataset_id"]),
        name=str(source["name"]),
        version=str(source["version"]),
        source_kind=ScientificDatasetSourceKind.AUDITED_EXTERNAL_DATA,
        usage_basis=ScientificDatasetUsageBasis.PUBLIC_LICENSE,
        license_identifier=str(source["license_identifier"]),
        license_url=str(source["license_url"]),
        acquisition_plan_artifact_hash=acquisition_plan.artifact_hash,
        acquisition_plan_record_hash=acquisition_plan.record_hash,
        evaluation_contract_artifact_hash=contract_record.sha256,
        evaluation_contract_record_hash=str(contract_record.record_hash),
        authority_artifact_hash=authority_record.sha256,
        authority_record_hash=str(authority_record.record_hash),
        manifest_artifact_hash=manifest.sha256,
        manifest_record_hash=str(manifest.record_hash),
        usage_artifact_hash=usage.sha256,
        usage_record_hash=str(usage.record_hash),
        usage_proposal_artifact_hash=proposal.sha256,
        usage_proposal_record_hash=str(proposal.record_hash),
        semantic_authority_artifact_hash=semantic_record.sha256,
        semantic_authority_record_hash=str(semantic_record.record_hash),
        semantic_transport_authority_artifact_hash=(semantic_transport_authority_hash),
        transport_authority_artifact_hash=transport.authority_artifact.sha256,
        transport_authority_record_hash=str(transport.authority_artifact.record_hash),
        request_artifact_hash=transport.request_artifact.sha256,
        request_record_hash=str(transport.request_artifact.record_hash),
        response_receipt_artifact_hash=transport.response_receipt_artifact.sha256,
        response_receipt_record_hash=str(
            transport.response_receipt_artifact.record_hash
        ),
        raw_data_artifact_hash=transport.raw_response_artifact.sha256,
        raw_data_record_hash=str(transport.raw_response_artifact.record_hash),
        raw_data_sha256=transport.body_sha256,
        data_projection_sha256=str(source["data_projection_sha256"]),
        body_size=transport.body_size,
        ledger_event_id=event.event_id,
        ledger_event_hash=str(event.event_hash),
        ledger_event_index=event_index,
    )


def _scientific_dataset_partition_projection(
    registry: ArtifactRegistry,
    *,
    dataset_authority: ScientificDatasetAuthority,
    evaluation_contract_artifact_hash: str,
) -> tuple[
    str,
    tuple[
        tuple[SplitRole, str, tuple[str, ...], tuple[str, ...]],
        ...,
    ],
    tuple[str, ...],
    str,
]:
    """Derive one exhaustive disjoint four-role partition from exact units."""

    if (
        evaluation_contract_artifact_hash
        != dataset_authority.evaluation_contract_artifact_hash
    ):
        raise ValidationError(
            "scientific split contract differs from Dataset acquisition authority"
        )
    try:
        from .scientific_design import require_frozen_evaluation_contract

        contract = require_frozen_evaluation_contract(
            registry,
            contract_artifact_sha256=evaluation_contract_artifact_hash,
        )
        manifest_value = safe_json_loads(
            registry.get_bytes(dataset_authority.manifest_artifact_hash),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific split lacks its exact Dataset manifest or contract"
        ) from exc
    if contract.dataset.dataset_id != dataset_authority.dataset_id or not isinstance(
        manifest_value, Mapping
    ):
        raise ValidationError(
            "scientific split Dataset identity differs from its contract"
        )
    unit_ids_value = manifest_value.get("unit_ids")
    unit_hashes_value = manifest_value.get("unit_hashes")
    unit_type = manifest_value.get("unit_id_field")
    if (
        not isinstance(unit_ids_value, list)
        or not isinstance(unit_hashes_value, list)
        or len(unit_ids_value) != len(unit_hashes_value)
        or len(unit_ids_value) < 4
        or not isinstance(unit_type, str)
    ):
        raise ValidationError(
            "scientific split Dataset lacks stable unit-level membership"
        )
    unit_ids = _identifier_tuple(
        tuple(unit_ids_value),
        "scientific split Dataset unit IDs",
        allow_empty=False,
    )
    unit_hashes = _hash_tuple(
        tuple(unit_hashes_value),
        "scientific split Dataset unit hashes",
        allow_empty=False,
    )
    if len(set(unit_ids)) != len(unit_ids):
        raise ValidationError("scientific split Dataset unit IDs are duplicated")
    unit_hash_by_id = dict(zip(unit_ids, unit_hashes, strict=True))
    excluded: list[str] = []
    for exclusion in contract.dataset.exclusions:
        if not exclusion.startswith("unit_id:"):
            raise ValidationError(
                "scientific split v1 requires exclusions as exact unit_id entries"
            )
        unit_id = exclusion.removeprefix("unit_id:")
        validate_identifier(unit_id, "scientific split excluded unit ID")
        if unit_id not in unit_hash_by_id or unit_id in excluded:
            raise ValidationError("scientific split exclusion is absent or duplicated")
        excluded.append(unit_id)
    eligible = tuple(
        sorted(
            (unit_id for unit_id in unit_ids if unit_id not in set(excluded)),
            key=lambda unit_id: sha256_bytes(
                (f"{dataset_authority.data_projection_sha256}:{unit_id}").encode(
                    "utf-8"
                )
            ),
        )
    )
    if len(eligible) < 4:
        raise ValidationError(
            "scientific split requires at least four non-excluded units"
        )
    confirmatory_count = max(1, len(eligible) // 10)
    validation_count = max(1, len(eligible) // 10)
    exploratory_count = max(1, len(eligible) // 10)
    train_count = (
        len(eligible) - confirmatory_count - validation_count - exploratory_count
    )
    if train_count < 1:
        raise ValidationError("scientific split cannot allocate a training role")
    split_specs = (
        (
            SplitRole.TRAIN,
            contract.dataset.train_split_id,
            eligible[:train_count],
        ),
        (
            SplitRole.EXPLORATORY,
            contract.dataset.development_split_id,
            eligible[train_count : train_count + exploratory_count],
        ),
        (
            SplitRole.VALIDATION,
            contract.dataset.validation_split_id,
            eligible[
                train_count + exploratory_count : train_count
                + exploratory_count
                + validation_count
            ],
        ),
        (
            SplitRole.CONFIRMATORY,
            contract.dataset.confirmatory_split_id,
            eligible[-confirmatory_count:],
        ),
    )
    memberships = tuple(
        (
            role,
            split_id,
            tuple(members),
            tuple(unit_hash_by_id[unit_id] for unit_id in members),
        )
        for role, split_id, members in split_specs
    )
    flattened = tuple(
        unit_id
        for _role, _split_id, members, _hashes in memberships
        for unit_id in members
    )
    if len(set(flattened)) != len(flattened) or set(flattened) != set(eligible):
        raise ValidationError("scientific split partition is overlapping or incomplete")
    partition_value = {
        "schema_version": SCIENTIFIC_DATASET_SPLIT_AUTHORITY_PAYLOAD_SCHEMA,
        "algorithm_id": SCIENTIFIC_DATASET_SPLIT_ALGORITHM_ID,
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "dataset_authority_artifact_sha256": (
            dataset_authority.authority_artifact_hash
        ),
        "evaluation_contract_artifact_sha256": (evaluation_contract_artifact_hash),
        "data_projection_sha256": dataset_authority.data_projection_sha256,
        "unit_type": unit_type,
        "excluded_unit_ids": sorted(excluded),
        "splits": [
            {
                "split_id": split_id,
                "split_role": role.value,
                "member_unit_ids": list(members),
                "member_unit_hashes": list(member_hashes),
            }
            for role, split_id, members, member_hashes in memberships
        ],
    }
    return (
        sha256_bytes(canonical_json_bytes(partition_value)),
        memberships,
        tuple(sorted(excluded)),
        unit_type,
    )


def _scientific_dataset_split_payload(
    *,
    run_id: str,
    dataset_authority: ScientificDatasetAuthority,
    evaluation_contract_record: ArtifactRecord,
    partition_sha256: str,
    split_role: SplitRole,
    split_id: str,
    member_unit_ids: tuple[str, ...],
    member_unit_hashes: tuple[str, ...],
    excluded_unit_ids: tuple[str, ...],
    unit_type: str,
) -> dict[str, Any]:
    return {
        "schema_version": SCIENTIFIC_DATASET_SPLIT_AUTHORITY_PAYLOAD_SCHEMA,
        "run_id": run_id,
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "split_id": split_id,
        "split_role": split_role.value,
        "unit_type": unit_type,
        "algorithm_id": SCIENTIFIC_DATASET_SPLIT_ALGORITHM_ID,
        "member_unit_ids": list(member_unit_ids),
        "member_unit_hashes": list(member_unit_hashes),
        "excluded_unit_ids": list(excluded_unit_ids),
        "partition_sha256": partition_sha256,
        "dataset_authority_artifact_sha256": (
            dataset_authority.authority_artifact_hash
        ),
        "dataset_authority_record_hash": dataset_authority.authority_record_hash,
        "evaluation_contract_artifact_sha256": evaluation_contract_record.sha256,
        "evaluation_contract_record_hash": str(evaluation_contract_record.record_hash),
        "protected_confirmatory": split_role is SplitRole.CONFIRMATORY,
        "human_authority": False,
        "e4_authority": False,
    }


def _scientific_experiment_dataset_projection_payload(
    dataset_authority: ScientificDatasetAuthority,
    *,
    evaluation_contract_record: ArtifactRecord,
) -> dict[str, Any]:
    return {
        "schema_version": (SCIENTIFIC_EXPERIMENT_DATASET_PROJECTION_PAYLOAD_SCHEMA),
        "run_id": dataset_authority.run_id,
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "dataset_authority_artifact_sha256": (
            dataset_authority.authority_artifact_hash
        ),
        "dataset_authority_record_hash": dataset_authority.authority_record_hash,
        "raw_data_artifact_sha256": dataset_authority.raw_data_artifact_hash,
        "raw_data_record_hash": dataset_authority.raw_data_record_hash,
        "raw_data_sha256": dataset_authority.raw_data_sha256,
        "data_projection_sha256": dataset_authority.data_projection_sha256,
        "evaluation_contract_artifact_sha256": (evaluation_contract_record.sha256),
    }


def register_scientific_experiment_dataset_projection(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    dataset_authority_artifact_hash: str,
    evaluation_contract_artifact_hash: str,
) -> ArtifactRecord:
    """Project audited Dataset authority into one frozen-run input artifact."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    publication_snapshot = _scientific_dataset_publication_snapshot(
        registry, ledger, run_id=run_id,
    )
    dataset_authority = require_scientific_dataset_authority(
        registry,
        ledger,
        run_id=run_id,
        authority_artifact_hash=dataset_authority_artifact_hash,
    )
    try:
        from .scientific_design import require_frozen_evaluation_contract

        require_frozen_evaluation_contract(
            registry,
            contract_artifact_sha256=evaluation_contract_artifact_hash,
        )
        contract_record = registry.get_metadata(evaluation_contract_artifact_hash)
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific experiment Dataset projection contract is invalid"
        ) from exc
    if dataset_authority.evaluation_contract_artifact_hash != contract_record.sha256:
        raise ValidationError(
            "scientific experiment Dataset projection names another contract"
        )
    ledger_result = ledger.validate(raise_on_error=True)
    if any(
        _scientific_result_visibility_event(registry, event)
        for event in ledger_result.events
    ):
        raise ValidationError(
            "scientific experiment Dataset must be projected before result visibility"
        )
    payload = _scientific_experiment_dataset_projection_payload(
        dataset_authority,
        evaluation_contract_record=contract_record,
    )
    dataset_event = ledger_result.events[dataset_authority.ledger_event_index]
    projection_plan = _scientific_dataset_artifact_plan(
        registry,
        payload,
        logical_type="experiment_dataset",
        origin=(
            "audited scientific experiment Dataset projection "
            f"{dataset_authority.dataset_id}:{dataset_authority.version}"
        ),
        creator_role=Role.EVIDENCE_CURATOR,
        creation_command=(
            "scientist-one",
            "project-scientific-experiment-dataset",
        ),
        parent_artifacts=(
            dataset_authority.authority_artifact_hash,
            contract_record.sha256,
            dataset_authority.raw_data_artifact_hash,
        ),
        schema_version=(SCIENTIFIC_EXPERIMENT_DATASET_PROJECTION_SCHEMA_VERSION),
        created_at=dataset_event.timestamp,
    )
    projection = projection_plan[1]
    candidates = _scientific_dataset_identity_candidates(
        registry,
        registry.list_records(),
        logical_type="experiment_dataset",
        identity={
            "run_id": run_id,
            "dataset_id": dataset_authority.dataset_id,
            "dataset_version": dataset_authority.version,
        },
    )
    if len(candidates) > 1 or any(
        record.sha256 != projection.sha256 for record in candidates
    ):
        raise ValidationError(
            "scientific experiment Dataset projection identity collides"
        )
    event_id = f"scientific-experiment-dataset-{projection.sha256[:32]}"
    event_metadata = {
        "schema_version": (SCIENTIFIC_EXPERIMENT_DATASET_PROJECTION_PAYLOAD_SCHEMA),
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "dataset_authority_artifact_hash": (dataset_authority.authority_artifact_hash),
        "evaluation_contract_artifact_hash": contract_record.sha256,
        "projection_artifact_hash": projection.sha256,
        "projection_record_hash": projection.record_hash,
    }
    plans = (projection_plan,)
    missing, event_to_append = _preflight_scientific_dataset_publication(
        registry,
        ledger,
        run_id=run_id,
        plans=plans,
        event_id=event_id,
        actor_role=Role.EVIDENCE_CURATOR,
        event_artifact_hashes=(projection.sha256,),
        event_timestamp=projection.created_at,
        reason="projected exact audited Dataset bytes into a frozen-run input",
        metadata=event_metadata,
    )
    _require_current_scientific_dataset_publication_contract(
        registry, ledger, run_id=run_id, contract_record=contract_record,
        missing=missing, event_to_append=event_to_append,
        source_snapshot=publication_snapshot,
    )
    projection = _commit_scientific_dataset_publication(
        registry,
        ledger,
        plans=plans,
        missing=missing,
        event_to_append=event_to_append,
        source_snapshot=publication_snapshot,
    )[0]
    require_scientific_experiment_dataset_projection(
        registry,
        ledger,
        run_id=run_id,
        projection_artifact_hash=projection.sha256,
        expected_dataset_authority_artifact_hash=(
            dataset_authority.authority_artifact_hash
        ),
        expected_evaluation_contract_artifact_hash=contract_record.sha256,
    )
    return projection


def require_scientific_experiment_dataset_projection(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    projection_artifact_hash: str,
    expected_dataset_authority_artifact_hash: str | None = None,
    expected_evaluation_contract_artifact_hash: str | None = None,
) -> ArtifactRecord:
    """Replay exact Dataset acquisition, contract, projection bytes, and event."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(
        projection_artifact_hash,
        "scientific experiment Dataset projection SHA-256",
    )
    try:
        record = registry.get_metadata(projection_artifact_hash)
        value = safe_json_loads(
            registry.get_bytes(projection_artifact_hash),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific experiment Dataset projection cannot be reopened"
        ) from exc
    expected_keys = {
        "schema_version",
        "run_id",
        "dataset_id",
        "dataset_version",
        "dataset_authority_artifact_sha256",
        "dataset_authority_record_hash",
        "raw_data_artifact_sha256",
        "raw_data_record_hash",
        "raw_data_sha256",
        "data_projection_sha256",
        "evaluation_contract_artifact_sha256",
    }
    if not isinstance(value, Mapping) or set(value) != expected_keys:
        raise ValidationError(
            "scientific experiment Dataset projection schema is not exact"
        )
    dataset_authority_hash = str(value["dataset_authority_artifact_sha256"])
    contract_hash = str(value["evaluation_contract_artifact_sha256"])
    if (
        expected_dataset_authority_artifact_hash is not None
        and dataset_authority_hash != expected_dataset_authority_artifact_hash
    ) or (
        expected_evaluation_contract_artifact_hash is not None
        and contract_hash != expected_evaluation_contract_artifact_hash
    ):
        raise ValidationError(
            "scientific experiment Dataset projection context was substituted"
        )
    dataset_authority = require_scientific_dataset_authority(
        registry,
        ledger,
        run_id=run_id,
        authority_artifact_hash=dataset_authority_hash,
        expected_dataset_id=str(value["dataset_id"]),
        expected_version=str(value["dataset_version"]),
    )
    try:
        from .scientific_design import require_frozen_evaluation_contract

        require_frozen_evaluation_contract(
            registry,
            contract_artifact_sha256=contract_hash,
        )
        contract_record = registry.get_metadata(contract_hash)
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific experiment Dataset projection contract failed replay"
        ) from exc
    expected_payload = _scientific_experiment_dataset_projection_payload(
        dataset_authority,
        evaluation_contract_record=contract_record,
    )
    expected_parents = (
        dataset_authority.authority_artifact_hash,
        contract_record.sha256,
        dataset_authority.raw_data_artifact_hash,
    )
    if (
        dataset_authority.evaluation_contract_artifact_hash != contract_record.sha256
        or record.logical_type != "experiment_dataset"
        or record.creator_role is not Role.EVIDENCE_CURATOR
        or record.schema_version
        != SCIENTIFIC_EXPERIMENT_DATASET_PROJECTION_SCHEMA_VERSION
        or record.mime_type != "application/json"
        or record.origin
        != (
            "audited scientific experiment Dataset projection "
            f"{dataset_authority.dataset_id}:{dataset_authority.version}"
        )
        or record.creation_command
        != (
            "scientist-one",
            "project-scientific-experiment-dataset",
        )
        or record.parent_artifacts != expected_parents
        or record.validation_result != "PASS"
        or record.frozen is not True
        or value != expected_payload
    ):
        raise ValidationError(
            "scientific experiment Dataset projection was substituted"
        )
    expected_metadata = {
        "schema_version": (SCIENTIFIC_EXPERIMENT_DATASET_PROJECTION_PAYLOAD_SCHEMA),
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "dataset_authority_artifact_hash": (dataset_authority.authority_artifact_hash),
        "evaluation_contract_artifact_hash": contract_record.sha256,
        "projection_artifact_hash": record.sha256,
        "projection_record_hash": record.record_hash,
    }
    events = ledger.events()
    if (
        dataset_authority.ledger_event_index >= len(events)
        or record.created_at != events[dataset_authority.ledger_event_index].timestamp
    ):
        raise ValidationError(
            "scientific experiment Dataset projection timestamp differs"
        )
    matching = tuple(
        (index, event)
        for index, event in enumerate(events)
        if event.event_id == f"scientific-experiment-dataset-{record.sha256[:32]}"
    )
    if len(matching) != 1:
        raise ValidationError(
            "scientific experiment Dataset projection event is absent or ambiguous"
        )
    event_index, event = matching[0]
    prior_event = events[event_index - 1] if event_index else None
    expected_event = (
        LedgerEvent.create(
            run_id=run_id,
            actor_role=Role.EVIDENCE_CURATOR,
            state_before=prior_event.requested_state_after,
            requested_state_after=prior_event.requested_state_after,
            artifact_hashes=(record.sha256,),
            code_version=prior_event.code_version,
            configuration_hash=prior_event.configuration_hash,
            reason=("projected exact audited Dataset bytes into a frozen-run input"),
            prior_event_hash=prior_event.event_hash,
            event_id=f"scientific-experiment-dataset-{record.sha256[:32]}",
            timestamp=record.created_at,
            event_type="CHECKPOINT",
            metadata=expected_metadata,
        )
        if prior_event is not None
        else None
    )
    if (
        prior_event is None
        or event != expected_event
        or event_index <= dataset_authority.ledger_event_index
        or any(
            _scientific_result_visibility_event(registry, earlier)
            for earlier in events[: event_index + 1]
        )
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in events[event_index + 1 :]
        )
    ):
        raise ValidationError(
            "scientific experiment Dataset projection event differs or is late"
        )
    return record


def _scientific_result_visibility_event(
    registry: ArtifactRegistry,
    event: LedgerEvent,
) -> bool:
    # An operational reservation permits possible dispatch/exposure, including
    # when later capture fails. This conservative chronology classifier does
    # not authenticate an execution or grant scientific evidence. Presence is
    # intentional: a malformed marker must not restore pre-exposure freshness.
    if (
        "operational_seed_admission" in event.metadata
        or "operational_best_of_n_report" in event.metadata
    ):
        return True
    if (
        event.metadata.get("promotion") == "EXPERIMENT_OUTPUTS_REGISTERED"
        or event.metadata.get("research_state_operation")
        in {"MATERIALIZED", "SUPERSEDED"}
        and event.metadata.get("object_type") in {"Run", "Result", "StatisticalTest"}
    ):
        return True
    for digest in event.artifact_hashes:
        try:
            logical_type = registry.get_metadata(digest).logical_type
        except ArtifactError:
            continue
        if logical_type.startswith("experiment_output.") or logical_type in {
            "operational_seed_admission",
            "local_terminal_observation",
            "operational_best_of_n_report",
            "aggregate_experiment_result",
            "statistical_analysis",
            "scientific_result_state_projection",
            "scientific_statistical_state_projection",
            "scientific_result_promotion_authority",
            "research_state.run",
            "research_state.result",
            "research_state.statistical_test",
        }:
            return True
    return False


def register_scientific_dataset_split_authorities(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    dataset_authority_artifact_hash: str,
    evaluation_contract_artifact_hash: str,
) -> tuple[ArtifactRecord, ...]:
    """Mint all four exact split roles in one pre-result ledger checkpoint."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    publication_snapshot = _scientific_dataset_publication_snapshot(
        registry, ledger, run_id=run_id,
    )
    dataset_authority = require_scientific_dataset_authority(
        registry,
        ledger,
        run_id=run_id,
        authority_artifact_hash=dataset_authority_artifact_hash,
    )
    contract_record = registry.get_metadata(evaluation_contract_artifact_hash)
    (
        partition_sha256,
        memberships,
        excluded_unit_ids,
        unit_type,
    ) = _scientific_dataset_partition_projection(
        registry,
        dataset_authority=dataset_authority,
        evaluation_contract_artifact_hash=evaluation_contract_artifact_hash,
    )
    ledger_result = ledger.validate(raise_on_error=True)
    if any(
        _scientific_result_visibility_event(registry, event)
        for event in ledger_result.events
    ):
        raise ValidationError(
            "scientific Dataset splits must be frozen before Run/result visibility"
        )
    created_at = ledger_result.events[dataset_authority.ledger_event_index].timestamp
    plan_values: list[tuple[bytes, ArtifactRecord]] = []
    for role, split_id, members, member_hashes in memberships:
        payload = _scientific_dataset_split_payload(
            run_id=run_id,
            dataset_authority=dataset_authority,
            evaluation_contract_record=contract_record,
            partition_sha256=partition_sha256,
            split_role=role,
            split_id=split_id,
            member_unit_ids=members,
            member_unit_hashes=member_hashes,
            excluded_unit_ids=excluded_unit_ids,
            unit_type=unit_type,
        )
        plan_values.append(
            _scientific_dataset_artifact_plan(
                registry,
                payload,
                logical_type=SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE,
                origin=(
                    f"deterministic scientific Dataset split {split_id}:{role.value}"
                ),
                creator_role=Role.PROTOCOL_DESIGNER,
                creation_command=(
                    "scientist-one",
                    "freeze-scientific-dataset-splits",
                ),
                parent_artifacts=(
                    dataset_authority.authority_artifact_hash,
                    contract_record.sha256,
                ),
                schema_version=(SCIENTIFIC_DATASET_SPLIT_AUTHORITY_SCHEMA_VERSION),
                created_at=created_at,
            )
        )
    plans = tuple(plan_values)
    records = tuple(plan[1] for plan in plans)
    registry_records = registry.list_records()
    for record, (_role, split_id, _members, _hashes) in zip(
        records,
        memberships,
        strict=True,
    ):
        candidates = _scientific_dataset_identity_candidates(
            registry,
            registry_records,
            logical_type=SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE,
            identity={"run_id": run_id, "split_id": split_id},
        )
        if len(candidates) > 1 or any(
            item.sha256 != record.sha256 for item in candidates
        ):
            raise ValidationError("scientific Dataset split semantic identity collides")
    artifact_hashes = tuple(record.sha256 for record in records)
    event_metadata = {
        "schema_version": SCIENTIFIC_DATASET_SPLIT_EVENT_SCHEMA,
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "dataset_authority_artifact_hash": (dataset_authority.authority_artifact_hash),
        "evaluation_contract_artifact_hash": contract_record.sha256,
        "algorithm_id": SCIENTIFIC_DATASET_SPLIT_ALGORITHM_ID,
        "partition_sha256": partition_sha256,
        "split_artifact_hashes": list(artifact_hashes),
        "split_record_hashes": [record.record_hash for record in records],
    }
    missing, event_to_append = _preflight_scientific_dataset_publication(
        registry,
        ledger,
        run_id=run_id,
        plans=plans,
        event_id=f"scientific-dataset-splits-{partition_sha256[:24]}",
        actor_role=Role.PROTOCOL_DESIGNER,
        event_artifact_hashes=artifact_hashes,
        event_timestamp=created_at,
        reason=("froze one exhaustive disjoint Dataset partition before execution"),
        metadata=event_metadata,
    )
    _require_current_scientific_dataset_publication_contract(
        registry, ledger, run_id=run_id, contract_record=contract_record,
        missing=missing, event_to_append=event_to_append,
        source_snapshot=publication_snapshot,
    )
    records = _commit_scientific_dataset_publication(
        registry,
        ledger,
        plans=plans,
        missing=missing,
        event_to_append=event_to_append,
        source_snapshot=publication_snapshot,
    )
    for record, (role, split_id, _members, _hashes) in zip(
        records,
        memberships,
        strict=True,
    ):
        require_scientific_dataset_split_authority(
            registry,
            ledger,
            run_id=run_id,
            split_authority_artifact_hash=record.sha256,
            expected_split_id=split_id,
            expected_split_role=role,
            expected_unit_type=unit_type,
        )
    return records


def require_scientific_dataset_split_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    split_authority_artifact_hash: str,
    expected_split_id: str | None = None,
    expected_split_role: SplitRole | None = None,
    expected_unit_type: str | None = None,
) -> ScientificDatasetSplitAuthority:
    """Replay the full partition; one valid-looking role is never sufficient."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(
        split_authority_artifact_hash,
        "scientific Dataset split-authority SHA-256",
    )
    try:
        target_record = registry.get_metadata(split_authority_artifact_hash)
        target_value = safe_json_loads(
            registry.get_bytes(split_authority_artifact_hash),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific Dataset split authority cannot be reopened"
        ) from exc
    if not isinstance(target_value, Mapping):
        raise ValidationError("scientific Dataset split authority is malformed")
    dataset_authority = require_scientific_dataset_authority(
        registry,
        ledger,
        run_id=run_id,
        authority_artifact_hash=str(
            target_value.get("dataset_authority_artifact_sha256")
        ),
        expected_dataset_id=str(target_value.get("dataset_id")),
        expected_version=str(target_value.get("dataset_version")),
    )
    authority_events = ledger.events()
    if dataset_authority.ledger_event_index >= len(authority_events):
        raise ValidationError(
            "scientific Dataset split authority names an absent Dataset event"
        )
    expected_created_at = authority_events[
        dataset_authority.ledger_event_index
    ].timestamp
    contract_hash = str(target_value.get("evaluation_contract_artifact_sha256"))
    contract_record = registry.get_metadata(contract_hash)
    (
        partition_sha256,
        memberships,
        excluded_unit_ids,
        unit_type,
    ) = _scientific_dataset_partition_projection(
        registry,
        dataset_authority=dataset_authority,
        evaluation_contract_artifact_hash=contract_hash,
    )
    created_by_hash: dict[str, tuple[ArtifactRecord, Mapping[str, Any]]] = {}
    expected_records: list[ArtifactRecord] = []
    for role, split_id, members, member_hashes in memberships:
        payload = _scientific_dataset_split_payload(
            run_id=run_id,
            dataset_authority=dataset_authority,
            evaluation_contract_record=contract_record,
            partition_sha256=partition_sha256,
            split_role=role,
            split_id=split_id,
            member_unit_ids=members,
            member_unit_hashes=member_hashes,
            excluded_unit_ids=excluded_unit_ids,
            unit_type=unit_type,
        )
        digest = sha256_bytes(canonical_json_bytes(payload) + b"\n")
        record = registry.get_metadata(digest)
        if (
            record.logical_type != SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE
            or record.creator_role is not Role.PROTOCOL_DESIGNER
            or record.schema_version
            != SCIENTIFIC_DATASET_SPLIT_AUTHORITY_SCHEMA_VERSION
            or record.mime_type != "application/json"
            or record.origin
            != f"deterministic scientific Dataset split {split_id}:{role.value}"
            or record.creation_command
            != ("scientist-one", "freeze-scientific-dataset-splits")
            or record.parent_artifacts
            != (
                dataset_authority.authority_artifact_hash,
                contract_record.sha256,
            )
            or record.validation_result != "PASS"
            or record.frozen is not True
            or record.created_at != expected_created_at
            or registry.get_bytes(record.sha256)
            != canonical_json_bytes(payload) + b"\n"
        ):
            raise ValidationError(
                "scientific Dataset split artifact differs from deterministic partition"
            )
        created_by_hash[record.sha256] = (record, payload)
        expected_records.append(record)
    if target_record.sha256 not in created_by_hash:
        raise ValidationError(
            "scientific Dataset split is not a member of the exact partition"
        )
    target_record, target_payload = created_by_hash[target_record.sha256]
    try:
        target_role = SplitRole(str(target_payload["split_role"]))
    except ValueError as exc:
        raise ValidationError("scientific Dataset split role is invalid") from exc
    if (
        (
            expected_split_id is not None
            and target_payload["split_id"] != expected_split_id
        )
        or (expected_split_role is not None and target_role is not expected_split_role)
        or (
            expected_unit_type is not None
            and target_payload["unit_type"] != expected_unit_type
        )
    ):
        raise ValidationError("scientific Dataset split assertion was substituted")
    ledger_result = ledger.validate(raise_on_error=True)
    artifact_hashes = tuple(record.sha256 for record in expected_records)
    expected_metadata = {
        "schema_version": SCIENTIFIC_DATASET_SPLIT_EVENT_SCHEMA,
        "dataset_id": dataset_authority.dataset_id,
        "dataset_version": dataset_authority.version,
        "dataset_authority_artifact_hash": (dataset_authority.authority_artifact_hash),
        "evaluation_contract_artifact_hash": contract_record.sha256,
        "algorithm_id": SCIENTIFIC_DATASET_SPLIT_ALGORITHM_ID,
        "partition_sha256": partition_sha256,
        "split_artifact_hashes": list(artifact_hashes),
        "split_record_hashes": [record.record_hash for record in expected_records],
    }
    events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.event_id == f"scientific-dataset-splits-{partition_sha256[:24]}"
    )
    prior_event = (
        ledger_result.events[events[0][0] - 1]
        if len(events) == 1 and events[0][0] > 0
        else None
    )
    expected_event = (
        LedgerEvent.create(
            run_id=run_id,
            actor_role=Role.PROTOCOL_DESIGNER,
            state_before=prior_event.requested_state_after,
            requested_state_after=prior_event.requested_state_after,
            artifact_hashes=artifact_hashes,
            code_version=prior_event.code_version,
            configuration_hash=prior_event.configuration_hash,
            reason=("froze one exhaustive disjoint Dataset partition before execution"),
            prior_event_hash=prior_event.event_hash,
            event_id=f"scientific-dataset-splits-{partition_sha256[:24]}",
            timestamp=expected_created_at,
            event_type="CHECKPOINT",
            metadata=expected_metadata,
        )
        if prior_event is not None
        else None
    )
    if (
        len(events) != 1
        or events[0][1] != expected_event
        or len({record.created_at for record in expected_records}) != 1
        or events[0][1].timestamp
        != next(iter({record.created_at for record in expected_records}))
    ):
        raise ValidationError("scientific Dataset split ledger authority is absent")
    event_index, event = events[0]
    if (
        event_index <= dataset_authority.ledger_event_index
        or any(
            _scientific_result_visibility_event(registry, earlier)
            for earlier in ledger_result.events[:event_index]
        )
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in ledger_result.events[event_index + 1 :]
        )
    ):
        raise ValidationError(
            "scientific Dataset split authority is retrospective or stale"
        )
    return ScientificDatasetSplitAuthority(
        run_id=run_id,
        dataset_id=dataset_authority.dataset_id,
        dataset_version=dataset_authority.version,
        split_id=str(target_payload["split_id"]),
        split_role=target_role,
        unit_type=str(target_payload["unit_type"]),
        algorithm_id=str(target_payload["algorithm_id"]),
        member_unit_ids=tuple(target_payload["member_unit_ids"]),
        member_unit_hashes=tuple(target_payload["member_unit_hashes"]),
        excluded_unit_ids=tuple(target_payload["excluded_unit_ids"]),
        partition_sha256=partition_sha256,
        artifact_hash=target_record.sha256,
        record_hash=str(target_record.record_hash),
        dataset_authority_artifact_hash=(dataset_authority.authority_artifact_hash),
        evaluation_contract_artifact_hash=contract_record.sha256,
        ledger_event_id=event.event_id,
        ledger_event_hash=str(event.event_hash),
        ledger_event_index=event_index,
    )


def _scientific_result_table_bytes(
    result: Result,
    metric: Metric,
    statistical_test: StatisticalTest,
) -> bytes:
    """Render one canonical one-row CSV directly from typed state."""

    stream = io.StringIO(newline="")
    writer = csv.writer(
        stream,
        dialect="excel",
        lineterminator="\n",
        quoting=csv.QUOTE_MINIMAL,
    )
    writer.writerow(
        (
            "result_id",
            "metric_id",
            "metric_name",
            "unit",
            "direction",
            "value_json",
            "uncertainty_json",
            "statistical_test_id",
            "test_name",
            "outcome_json",
        )
    )
    writer.writerow(
        (
            result.object_id,
            result.metric_id,
            metric.name,
            result.unit,
            result.direction.value,
            json.dumps(
                thaw_json(result.value),
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ),
            json.dumps(
                thaw_json(result.uncertainty),
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ),
            statistical_test.object_id,
            statistical_test.test_name,
            json.dumps(
                thaw_json(statistical_test.outcome),
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            ),
        )
    )
    return stream.getvalue().encode("utf-8")


def _require_promoted_statistical_test_result(
    statistical_test: StatisticalTest,
    authority: _ResolvedObjectAuthority,
    by_content: Mapping[str, _StoredObject],
) -> Result:
    """Resolve the one exact source-promoted Result tested by ``statistical_test``.

    A complete generic StatisticalTest and an evaluated Result-shaped parent are
    not scientific authority.  The test must itself have replayed its full
    promotion receipt and must retain the source-owned canonical ``tests`` edge
    with no additional parents.
    """

    if authority.scientific_evidence_eligible is not True:
        raise ValidationError(
            "scientific StatisticalTest lacks source-owned promotion authority"
        )
    if len(statistical_test.parents) != 1:
        raise ValidationError(
            "scientific StatisticalTest requires one exact Result parent"
        )
    reference = statistical_test.parents[0]
    stored = by_content.get(reference.content_hash)
    if (
        reference.object_type != "Result"
        or reference.object_id not in statistical_test.result_ids
        or statistical_test.result_ids != (reference.object_id,)
        or reference.relation != "tests"
        or reference.evaluated is not True
        or stored is None
        or not isinstance(stored.research_object, Result)
        or stored.research_object.object_id != reference.object_id
        or stored.research_object.content_hash != reference.content_hash
    ):
        raise ValidationError(
            "scientific StatisticalTest has a substituted Result tests edge"
        )
    return stored.research_object


def _resolve_scientific_result_table_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    result_state_artifact_hash: str,
    statistical_test_state_artifact_hash: str,
) -> tuple[
    Result,
    StatisticalTest,
    Metric,
    ArtifactRecord,
    ArtifactRecord,
    ResearchStateRepository,
]:
    result_source = _require_scoped_canonical_state_source(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hash=result_state_artifact_hash,
    )
    test_source = _require_scoped_canonical_state_source(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hash=statistical_test_state_artifact_hash,
    )
    result = result_source[0]
    statistical_test = test_source[0]
    if (
        not isinstance(result, Result)
        or result.status is not RecordStatus.COMPLETE
        or result_source[1].scientific_evidence_eligible is not True
    ):
        raise ValidationError(
            "scientific result table requires an eligible complete Result"
        )
    if (
        not isinstance(statistical_test, StatisticalTest)
        or statistical_test.status is not RecordStatus.COMPLETE
    ):
        raise ValidationError(
            "scientific result table requires a complete StatisticalTest"
        )
    if (
        result_source[3].code_version != test_source[3].code_version
        or result_source[3].configuration_hash != test_source[3].configuration_hash
        or result_source[3].state is not test_source[3].state
    ):
        raise ValidationError("scientific result table mixes state execution contexts")
    tested_result = _require_promoted_statistical_test_result(
        statistical_test,
        test_source[1],
        test_source[2],
    )
    metrics = ResearchStateRepository._resolved_parent_objects(
        result,
        result_source[2],
        "Metric",
    )
    if (
        tested_result.content_hash != result.content_hash
        or len(metrics) != 1
        or metrics[0].object_id != result.metric_id
        or metrics[0].status is not RecordStatus.FROZEN
    ):
        raise ValidationError(
            "scientific result table Result/Test/Metric binding is not exact"
        )
    return (
        result,
        statistical_test,
        metrics[0],
        registry.get_metadata(result_state_artifact_hash),
        registry.get_metadata(statistical_test_state_artifact_hash),
        result_source[3],
    )


def register_scientific_result_table(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    result_state_artifact_hash: str,
    statistical_test_state_artifact_hash: str,
) -> ArtifactRecord:
    """Deterministically render and ledger-anchor one scientific CSV table."""

    validate_identifier(run_id, "scientific result-table run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    (
        result,
        statistical_test,
        metric,
        result_record,
        test_record,
        repository,
    ) = _resolve_scientific_result_table_sources(
        registry,
        ledger,
        run_id=run_id,
        result_state_artifact_hash=result_state_artifact_hash,
        statistical_test_state_artifact_hash=statistical_test_state_artifact_hash,
    )
    table_bytes = _scientific_result_table_bytes(result, metric, statistical_test)
    table_hash = sha256_bytes(table_bytes)
    registry_validation = registry.verify_all(raise_on_error=True)
    ledger_result = ledger.validate(raise_on_error=True)
    if not ledger_result.events:
        raise ValidationError(
            "scientific result-table publication requires an initialized ledger"
        )
    registry_records = {record.sha256: record for record in registry_validation.records}
    existing = registry_records.get(table_hash)
    created_at = existing.created_at if existing is not None else utc_now()
    object_path = registry.objects_path / table_hash[:2] / table_hash
    metadata_path = registry.metadata_path / table_hash[:2] / f"{table_hash}.json"
    expected_table = ArtifactRecord(
        sha256=table_hash,
        path=object_path.as_posix(),
        relative_path=object_path.as_posix(),
        metadata_path=metadata_path.as_posix(),
        logical_type=SCIENTIFIC_RESULT_TABLE_LOGICAL_TYPE,
        schema_version=SCIENTIFIC_RESULT_TABLE_SCHEMA_VERSION,
        mime_type="text/csv",
        size=len(table_bytes),
        origin=(
            f"deterministic scientific Result table {result.object_id}:"
            f"{statistical_test.object_id}"
        ),
        creator_role=Role.STATISTICIAN,
        creation_command=(
            "scientist-one",
            "render-scientific-result-table",
        ),
        parent_artifacts=(result_record.sha256, test_record.sha256),
        validation_result="PASS",
        frozen=True,
        created_at=created_at,
    )
    artifact_missing = existing is None
    if existing is not None and (
        existing != expected_table or registry.get_bytes(table_hash) != table_bytes
    ):
        raise ValidationError("scientific result-table publication artifact collides")
    if len(registry_records) + int(artifact_missing) > MAX_REGISTRY_RECORDS:
        raise ValidationError(
            "scientific result-table publication exceeds registry capacity"
        )

    event_id = f"scientific-result-table-{table_hash[:32]}"
    event_metadata = {
        "scientific_result_table": SCIENTIFIC_RESULT_TABLE_RENDERER_ID,
        "table_artifact_hash": table_hash,
        "table_record_hash": expected_table.record_hash,
        "result_state_artifact_hash": result_record.sha256,
        "result_state_record_hash": result_record.record_hash,
        "statistical_test_state_artifact_hash": test_record.sha256,
        "statistical_test_state_record_hash": test_record.record_hash,
    }
    reason = "rendered one deterministic table from eligible canonical state"
    matching_events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.event_id == event_id
    )
    if len(matching_events) > 1:
        raise ValidationError("scientific result-table publication event is ambiguous")
    event_to_append: LedgerEvent | None = None
    if matching_events:
        event_index, event = matching_events[0]
        if artifact_missing or event_index == 0:
            raise ValidationError(
                "scientific result-table event precedes its exact artifact"
            )
        prior = ledger_result.events[event_index - 1]
        expected_event = LedgerEvent.create(
            run_id=run_id,
            actor_role=Role.STATISTICIAN,
            state_before=repository.state,
            requested_state_after=repository.state,
            artifact_hashes=(table_hash,),
            code_version=repository.code_version,
            configuration_hash=repository.configuration_hash,
            reason=reason,
            prior_event_hash=prior.event_hash,
            event_id=event_id,
            timestamp=created_at,
            event_type="CHECKPOINT",
            metadata=event_metadata,
        )
        if event != expected_event or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in ledger_result.events[event_index + 1 :]
        ):
            raise ValidationError(
                "scientific result-table publication event collides or is stale"
            )
    else:
        if any(
            tuple(event.artifact_hashes) == (table_hash,)
            for event in ledger_result.events
        ):
            raise ValidationError(
                "scientific result-table artifact names another event"
            )
        current = ledger_result.events[-1]
        event_to_append = LedgerEvent.create(
            run_id=run_id,
            actor_role=Role.STATISTICIAN,
            state_before=repository.state,
            requested_state_after=repository.state,
            artifact_hashes=(table_hash,),
            code_version=repository.code_version,
            configuration_hash=repository.configuration_hash,
            reason=reason,
            prior_event_hash=current.event_hash,
            event_id=event_id,
            timestamp=created_at,
            event_type="CHECKPOINT",
            metadata=event_metadata,
        )
        event_bytes = canonical_json_bytes(event_to_append.to_dict()) + b"\n"
        if len(ledger_result.events) + 1 > MAX_LEDGER_EVENTS:
            raise ValidationError(
                "scientific result-table publication exceeds ledger capacity"
            )
        if ledger_result.valid_prefix_bytes + len(event_bytes) > MAX_LEDGER_BYTES:
            raise ValidationError(
                "scientific result-table publication exceeds ledger byte capacity"
            )

    # Hold the registry lock before the ledger lock, then retain both across
    # the registry-first/ledger-second commit.  The exact preflight snapshots
    # are rechecked after both locks are held, so no cooperating writer can
    # consume capacity or the deterministic event ID between publication and
    # append.  Abrupt termination may still leave the exact inert registry
    # prefix, which the retry path above deliberately completes.
    registry_guard = registry._open_mutation_lock()
    try:
        ledger_guard = ledger._open_lock()
        try:
            locked_registry = registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            locked_ledger_bytes = ledger._read_raw_locked(ledger_guard)
            locked_ledger = ledger._validate_bytes(locked_ledger_bytes)
            if not locked_ledger.valid:
                raise ValidationError(
                    "scientific result-table ledger changed before commit"
                )
            if locked_registry != registry_validation or locked_ledger != ledger_result:
                raise ValidationError(
                    "scientific result-table preflight changed before commit"
                )
            if artifact_missing:
                table = registry._put_bytes_locked(
                    registry_guard,
                    table_bytes,
                    logical_type=expected_table.logical_type,
                    origin=expected_table.origin,
                    creator_role=expected_table.creator_role,
                    creation_command=expected_table.creation_command,
                    parent_artifacts=expected_table.parent_artifacts,
                    schema_version=expected_table.schema_version,
                    mime_type=expected_table.mime_type,
                    validation_result=expected_table.validation_result,
                    frozen=expected_table.frozen,
                    created_at=expected_table.created_at,
                )
            else:
                table = registry._get_metadata_locked(
                    registry_guard,
                    table_hash,
                )
            if table != expected_table:
                raise ValidationError(
                    "scientific result-table publication changed during commit"
                )
            if event_to_append is not None:

                def build_locked_event(
                    current: LedgerValidationResult,
                ) -> LedgerEvent:
                    if current != locked_ledger:
                        raise ValidationError(
                            "scientific result-table ledger changed during commit"
                        )
                    return event_to_append

                appended = ledger._append_locked(
                    ledger_guard,
                    build_locked_event,
                )
                if appended != event_to_append:
                    raise ValidationError(
                        "scientific result-table event changed during commit"
                    )
            registry._verify_mutation_namespace(registry_guard)
        finally:
            ledger._unlock(ledger_guard)
    finally:
        registry._unlock_mutation(registry_guard)
    require_scientific_result_table(
        registry,
        ledger,
        run_id=run_id,
        table_artifact_hash=table.sha256,
        expected_result_state_artifact_hash=result_record.sha256,
        expected_statistical_test_state_artifact_hash=test_record.sha256,
    )
    return table


def require_scientific_result_table(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    table_artifact_hash: str,
    expected_result_state_artifact_hash: str,
    expected_statistical_test_state_artifact_hash: str,
) -> ScientificResultTableAuthority:
    """Freshly recompute table bytes, state sources, and ledger ordering."""

    validate_identifier(run_id, "scientific result-table run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(table_artifact_hash, "scientific result-table SHA-256")
    (
        result,
        statistical_test,
        metric,
        result_record,
        test_record,
        repository,
    ) = _resolve_scientific_result_table_sources(
        registry,
        ledger,
        run_id=run_id,
        result_state_artifact_hash=expected_result_state_artifact_hash,
        statistical_test_state_artifact_hash=(
            expected_statistical_test_state_artifact_hash
        ),
    )
    try:
        if registry.verify(table_artifact_hash, raise_on_error=True) is not True:
            raise ValidationError("scientific result table is absent or corrupt")
        table = registry.get_metadata(table_artifact_hash)
        table_bytes = registry.get_bytes(table_artifact_hash)
    except ArtifactError as exc:
        raise ValidationError("scientific result table is absent or corrupt") from exc
    expected_bytes = _scientific_result_table_bytes(
        result,
        metric,
        statistical_test,
    )
    if (
        table.logical_type != SCIENTIFIC_RESULT_TABLE_LOGICAL_TYPE
        or table.creator_role is not Role.STATISTICIAN
        or table.schema_version != SCIENTIFIC_RESULT_TABLE_SCHEMA_VERSION
        or table.mime_type != "text/csv"
        or table.origin
        != (
            f"deterministic scientific Result table {result.object_id}:"
            f"{statistical_test.object_id}"
        )
        or table.creation_command != ("scientist-one", "render-scientific-result-table")
        or table.validation_result != "PASS"
        or table.frozen is not True
        or table.parent_artifacts != (result_record.sha256, test_record.sha256)
        or table_bytes != expected_bytes
        or table.sha256 != sha256_bytes(expected_bytes)
    ):
        raise ValidationError(
            "scientific result table differs from deterministic canonical state"
        )
    ledger_result = ledger.validate(raise_on_error=True)
    source_indexes: list[int] = []
    for source_hash in (result_record.sha256, test_record.sha256):
        matches = tuple(
            index
            for index, event in enumerate(ledger_result.events)
            if event.run_id == run_id
            and tuple(event.artifact_hashes) == (source_hash,)
            and event.metadata.get("research_state_operation")
            in {"MATERIALIZED", "SUPERSEDED"}
            and event.metadata.get("artifact_hash") == source_hash
        )
        if len(matches) != 1:
            raise ValidationError(
                "scientific result table source lacks one exact state event"
            )
        source_indexes.append(matches[0])
    events = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.run_id == run_id
        and event.actor_role is Role.STATISTICIAN
        and event.event_type == "CHECKPOINT"
        and event.state_before is repository.state
        and event.requested_state_after is repository.state
        and event.code_version == repository.code_version
        and event.configuration_hash == repository.configuration_hash
        and tuple(event.artifact_hashes) == (table.sha256,)
        and event.timestamp == table.created_at
        and event.metadata.get("scientific_result_table")
        == SCIENTIFIC_RESULT_TABLE_RENDERER_ID
        and event.metadata.get("table_artifact_hash") == table.sha256
        and event.metadata.get("table_record_hash") == table.record_hash
        and event.metadata.get("result_state_artifact_hash") == result_record.sha256
        and event.metadata.get("result_state_record_hash") == result_record.record_hash
        and event.metadata.get("statistical_test_state_artifact_hash")
        == test_record.sha256
        and event.metadata.get("statistical_test_state_record_hash")
        == test_record.record_hash
    )
    if len(events) != 1 or events[0][0] <= max(source_indexes):
        raise ValidationError(
            "scientific result table lacks one post-source ledger checkpoint"
        )
    event_index, event = events[0]
    if event.event_hash is None or any(
        later.event_type == "CORRECTION" and later.supersedes_event_id == event.event_id
        for later in ledger_result.events[event_index + 1 :]
    ):
        raise ValidationError(
            "scientific result-table checkpoint is absent or superseded"
        )
    return ScientificResultTableAuthority(
        run_id=run_id,
        table_artifact_hash=table.sha256,
        table_record_hash=str(table.record_hash),
        result_state_artifact_hash=result_record.sha256,
        result_state_record_hash=str(result_record.record_hash),
        statistical_test_state_artifact_hash=test_record.sha256,
        statistical_test_state_record_hash=str(test_record.record_hash),
        result_id=result.object_id,
        statistical_test_id=statistical_test.object_id,
        renderer_id=SCIENTIFIC_RESULT_TABLE_RENDERER_ID,
        ledger_event_id=event.event_id,
        ledger_event_hash=event.event_hash,
        ledger_event_index=event_index,
    )


def _require_bounded_estimand_source_bindings(
    *,
    result: Result,
    statistical_test: StatisticalTest,
    projection: Any,
    assessment: Any,
    contract: Any,
    contract_record: ArtifactRecord,
    experiment_id: str,
) -> None:
    """Join already owner-replayed sources without creating another authority.

    Production callers must obtain assessment/projection from the full result
    owner and the contract from its registry-only public parser. This private
    linkage check does not validate arbitrary caller-owned contract/assessment
    DTOs or prove Dataset sampling assumptions. The full statistical-use owner
    binds the actual split unit and complete grid; no resampling-unit alias is
    added to the conditional native mean configuration.
    """

    from .scientific_design import (
        CheckedResultAssessment,
        EvaluationContract,
        ScientificResultCanonicalProjectionV4,
    )

    if (
        type(projection) is not ScientificResultCanonicalProjectionV4
        or type(assessment) is not CheckedResultAssessment
        or type(contract) is not EvaluationContract
        or type(contract_record) is not ArtifactRecord
        or type(experiment_id) is not str
    ):
        raise ValidationError("bounded estimand requires exact owned native sources")
    policy = contract.hypothesis_evaluation_policy(projection.hypothesis_id)
    # This shared helper is pure numeric/canonical-view replay, not a current
    # Hypothesis owner. Ignore its outcome: adverse results remain evidence.
    _bounded_hypothesis_projection_outcome(
        projection, policy, result, statistical_test,
    )
    if (
        not assessment.is_bounded_mean
        or projection.contract_artifact_sha256 != contract_record.sha256
        or assessment.contract_artifact_sha256 != contract_record.sha256
        or assessment.contract_record_hash != contract_record.record_hash
        or assessment.contract_sha256 != contract.sha256
        or projection.hypothesis_policy.sha256 != policy.sha256
        or projection.experiment_id != experiment_id
        or contract.hypothesis_register.hypothesis(
            projection.hypothesis_id
        ).planned_experiment != experiment_id
        or assessment.ledger_run_id != projection.ledger_run_id
        or assessment.execution_run_id != projection.execution_run_id
        or assessment.hypothesis_id != projection.hypothesis_id
        or assessment.metric_id != projection.metric_id
        or contract.primary_metric.metric_id != projection.metric_id
        or contract.primary_metric.unit is not projection.metric_unit
        or contract.primary_metric.direction is not projection.metric_direction
        or contract.primary_metric.scope is not projection.metric_scope
        or contract.statistical_plan.primary_test != projection.contract_primary_test
        or assessment.statistical_use_authority_artifact_sha256
        != projection.statistical_use_authority_artifact_sha256
        or assessment.statistical_use_authority_record_hash
        != projection.statistical_use_authority_record_hash
        or not contract.statistical_plan.effect_size.strip()
    ):
        raise ValidationError("bounded estimand differs from its exact frozen source closure")


def _require_scientific_state_evidence_source(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    evidence_kind: GraphEvidenceKind,
    evidence_artifact: ArtifactRecord,
    evidence_id: str,
    claim_id: str,
    claim_text: str,
    claim_producer_role: Role,
    claim_confirmatory: bool,
    claim_evidence_use: ClaimEvidenceUse,
    assertion_text: str,
) -> None:
    """Require a kind-specific canonical authority for non-citation evidence."""

    if evidence_kind in {
        GraphEvidenceKind.SCOPE_QUALIFIER,
        GraphEvidenceKind.LIMITATION,
    }:
        if len(evidence_artifact.parent_artifacts) != 1:
            raise ValidationError(
                f"{evidence_kind.value} evidence requires exactly one qualifier "
                "authority parent"
            )
        authority_record = registry.get_metadata(evidence_artifact.parent_artifacts[0])
        if (
            authority_record.logical_type
            != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_LOGICAL_TYPE
            or authority_record.creator_role is not Role.SCIENTIFIC_REVIEWER
        ):
            raise ValidationError(
                f"{evidence_kind.value} evidence lacks source-owned qualifier authority"
            )
        require_scientific_claim_qualifier_authority(
            registry,
            ledger,
            authority_artifact_hash=authority_record.sha256,
            expected_run_id=run_id,
            expected_evidence_id=evidence_id,
            expected_evidence_kind=evidence_kind,
            expected_claim_id=claim_id,
            expected_claim_text=claim_text,
            expected_claim_producer_role=claim_producer_role,
            expected_claim_confirmatory=claim_confirmatory,
            expected_claim_evidence_use=claim_evidence_use,
            expected_assertion_text=assertion_text,
        )
        return

    if evidence_kind is GraphEvidenceKind.FIGURE_OR_TABLE:
        parents = evidence_artifact.parent_artifacts
        if len(parents) != 3:
            raise ValidationError(
                "figure/table evidence requires exact table, Result, and "
                "StatisticalTest parents"
            )
        table_record = registry.get_metadata(parents[0])
        result_record = registry.get_metadata(parents[1])
        test_record = registry.get_metadata(parents[2])
        if (
            table_record.logical_type != SCIENTIFIC_RESULT_TABLE_LOGICAL_TYPE
            or result_record.logical_type != "research_state.result"
            or test_record.logical_type != "research_state.statistical_test"
        ):
            raise ValidationError(
                "figure/table evidence has substituted or reordered parents"
            )
        require_scientific_result_table(
            registry,
            ledger,
            run_id=run_id,
            table_artifact_hash=table_record.sha256,
            expected_result_state_artifact_hash=result_record.sha256,
            expected_statistical_test_state_artifact_hash=test_record.sha256,
        )
        return

    state_parent_hashes = tuple(
        digest
        for digest in evidence_artifact.parent_artifacts
        if registry.get_metadata(digest).logical_type.startswith("research_state.")
    )
    if not state_parent_hashes:
        raise ValidationError(
            f"{evidence_kind.value} lacks a direct canonical state authority"
        )
    if tuple(evidence_artifact.parent_artifacts) != state_parent_hashes:
        raise ValidationError(
            f"{evidence_kind.value} has unrelated or reordered direct parents"
        )
    sources = tuple(
        _require_scoped_canonical_state_source(
            registry,
            ledger,
            run_id=run_id,
            state_artifact_hash=digest,
        )
        for digest in state_parent_hashes
    )
    objects = tuple(item[0] for item in sources)
    if evidence_kind is GraphEvidenceKind.HYPOTHESIS:
        if (
            len(objects) != 1
            or not isinstance(objects[0], Hypothesis)
            or objects[0].status is not RecordStatus.FROZEN
            or objects[0].hypothesis_status is not HypothesisStatus.UNTESTED
        ):
            raise ValidationError(
                "hypothesis evidence requires one freshly replayed preregistration"
            )
        return

    if evidence_kind is GraphEvidenceKind.ESTIMAND:
        if (
            len(objects) != 1
            or not isinstance(objects[0], StatisticalTest)
            or objects[0].status is not RecordStatus.COMPLETE
        ):
            raise ValidationError(
                "estimand evidence requires one complete canonical StatisticalTest"
            )
        statistical_test = objects[0]
        by_content = sources[0][2]
        repository = sources[0][3]
        result = _require_promoted_statistical_test_result(
            statistical_test,
            sources[0][1],
            by_content,
        )
        results = (result,)
        result_authority = repository._resolve_object_authority(result, by_content)
        if result_authority.scientific_evidence_eligible is not True:
            raise ValidationError(
                "estimand evidence requires scientifically eligible Results"
            )
        experiments: dict[str, Experiment] = {}
        contracts: dict[str, Mapping[str, Any]] = {}
        owned_contract_records: dict[str, ArtifactRecord] = {}
        for result in results:
            runs = ResearchStateRepository._resolved_parent_objects(
                result,
                by_content,
                "Run",
            )
            if not runs:
                raise ValidationError(
                    "estimand Result lacks its evaluated canonical Run"
                )
            for run in runs:
                run_experiments = ResearchStateRepository._resolved_parent_objects(
                    run,
                    by_content,
                    "Experiment",
                )
                if len(run_experiments) != 1:
                    raise ValidationError("estimand Run lacks one frozen Experiment")
                experiment = run_experiments[0]
                resolved_experiment = repository._resolve_object_authority(
                    experiment,
                    by_content,
                )
                contract_records = tuple(
                    item
                    for item in resolved_experiment.records
                    if item.logical_type == "evaluation_contract"
                )
                if (
                    experiment.status is not RecordStatus.FROZEN
                    or len(contract_records) != 1
                    or {item.logical_type for item in resolved_experiment.records}
                    != {"experiment_configuration", "evaluation_contract"}
                ):
                    raise ValidationError(
                        "estimand lacks one scientific frozen evaluation contract"
                    )
                experiments[experiment.object_id] = experiment
                owned_contract_records[experiment.object_id] = contract_records[0]
                contracts[experiment.object_id] = (
                    ResearchStateRepository._nested_mapping(
                        repository._read_authority_json(contract_records[0]),
                        "evaluation_contract",
                    )
                )
        if len(experiments) != 1:
            raise ValidationError(
                "estimand evidence mixes multiple Experiment contracts"
            )
        from .scientific_design import (
            SCIENTIFIC_RESULT_CANONICAL_STATE_SCHEMA_V4,
            SCIENTIFIC_STATISTICAL_CANONICAL_STATE_SCHEMA_V4,
            require_frozen_evaluation_contract,
        )

        result_format = result.metadata.get("schema_version")
        test_format = statistical_test.metadata.get("schema_version")
        if (
            result_format == SCIENTIFIC_RESULT_CANONICAL_STATE_SCHEMA_V4
            or test_format == SCIENTIFIC_STATISTICAL_CANONICAL_STATE_SCHEMA_V4
        ):
            if (
                result_format != SCIENTIFIC_RESULT_CANONICAL_STATE_SCHEMA_V4
                or test_format != SCIENTIFIC_STATISTICAL_CANONICAL_STATE_SCHEMA_V4
                or len(result.run_ids) != 1
            ):
                raise ValidationError("estimand mixes native and legacy canonical sources")
            resolution, projection, _promotion_record = (
                repository._resolve_scientific_result_promotion_v3(
                    result_authority.records,
                    expected_result_id=result.object_id,
                    expected_execution_run_id=result.run_ids[0],
                )
            )
            experiment_id, contract_record = next(iter(owned_contract_records.items()))
            native_contract = require_frozen_evaluation_contract(
                registry, contract_artifact_sha256=contract_record.sha256,
            )
            _require_bounded_estimand_source_bindings(
                result=result,
                statistical_test=statistical_test,
                projection=projection,
                assessment=resolution.assessment,
                contract=native_contract,
                contract_record=contract_record,
                experiment_id=experiment_id,
            )
            return
        contract = next(iter(contracts.values()))
        plan = ResearchStateRepository._nested_mapping(
            contract,
            "statistical_plan",
        )
        primary_metric = ResearchStateRepository._nested_mapping(
            contract,
            "primary_metric",
        )
        if (
            statistical_test.test_name != plan.get("primary_test")
            or statistical_test.method_configuration.get("resampling_unit")
            != plan.get("resampling_unit")
            or {result.metric_id for result in results}
            != {primary_metric.get("metric_id")}
            or not isinstance(plan.get("effect_size"), str)
            or not plan["effect_size"].strip()
        ):
            raise ValidationError(
                "estimand differs from its preregistered metric/effect/test plan"
            )
        return

    if evidence_kind is GraphEvidenceKind.DATASET_OR_FIXTURE:
        if (
            len(objects) != 2
            or not isinstance(objects[0], Dataset)
            or not isinstance(objects[1], Result)
        ):
            raise ValidationError(
                "dataset evidence requires ordered canonical Dataset and Result parents"
            )
        dataset = objects[0]
        result = objects[1]
        fixture_types = {
            "dataset_fixture",
            "autonomous_implementation.fixture_data",
            "autonomous_implementation.fixture_data_derivation",
        }
        if {item.logical_type for item in sources[0][1].records}.intersection(
            fixture_types
        ):
            raise ValidationError(
                "fixture Dataset authority cannot promote scientific claim semantics"
            )
        if (
            dataset.status is not RecordStatus.FROZEN
            or sources[0][1].scientific_evidence_eligible is not True
            or result.status is not RecordStatus.COMPLETE
            or sources[1][1].scientific_evidence_eligible is not True
        ):
            raise ValidationError(
                "dataset evidence requires a scientific Dataset and evaluated Result"
            )
        by_content = sources[1][2]
        runs = ResearchStateRepository._resolved_parent_objects(
            result,
            by_content,
            "Run",
        )
        if not runs:
            raise ValidationError(
                "dataset evidence Result lacks evaluated canonical Runs"
            )
        matched_dataset_hashes: set[str] = set()
        for run in runs:
            experiments = ResearchStateRepository._resolved_parent_objects(
                run,
                by_content,
                "Experiment",
            )
            if len(experiments) != 1 or dataset.object_id not in set(
                experiments[0].dataset_ids
            ):
                raise ValidationError(
                    "dataset evidence was not evaluated by the Result Experiment"
                )
            dataset_parents = ResearchStateRepository._resolved_parent_objects(
                experiments[0],
                by_content,
                "Dataset",
            )
            matched_dataset_hashes.update(
                item.content_hash
                for item in dataset_parents
                if item.object_id == dataset.object_id
            )
        if matched_dataset_hashes != {dataset.content_hash}:
            raise ValidationError(
                "dataset evidence differs from the exact evaluated Dataset revision"
            )
        return

    if evidence_kind is GraphEvidenceKind.CODE:
        if (
            len(objects) != 1
            or not isinstance(objects[0], Implementation)
            or objects[0].status is not RecordStatus.FROZEN
        ):
            raise ValidationError(
                "code evidence requires one freshly replayed frozen Implementation"
            )
        autonomous_types = {
            "autonomous_implementation.reviewed_worker_code",
            "autonomous_implementation.worker_configuration",
            "autonomous_implementation.validation_receipt",
            "autonomous_implementation.admitted_descriptor",
        }
        if {item.logical_type for item in sources[0][1].records}.intersection(
            autonomous_types
        ):
            raise ValidationError(
                "non-evidentiary autonomous code cannot promote claim semantics"
            )
        implementation = objects[0]
        by_content = sources[0][2]
        methods = ResearchStateRepository._resolved_parent_objects(
            implementation,
            by_content,
            "Method",
        )
        if (
            len(methods) != 1
            or methods[0].object_id != implementation.method_id
            or methods[0].status is not RecordStatus.FROZEN
        ):
            raise ValidationError(
                "code evidence lacks one exact frozen canonical Method binding"
            )
        method_authority = sources[0][3]._resolve_object_authority(
            methods[0],
            by_content,
        )
        if {item.logical_type for item in method_authority.records}.intersection(
            {
                "autonomous_implementation.validation_receipt",
                "autonomous_implementation.admitted_descriptor",
            }
        ):
            raise ValidationError(
                "non-evidentiary autonomous Method cannot promote claim semantics"
            )
        return

    if evidence_kind is GraphEvidenceKind.PROTOCOL_VERSION:
        if (
            len(objects) != 1
            or not isinstance(objects[0], Experiment)
            or objects[0].status is not RecordStatus.FROZEN
        ):
            raise ValidationError(
                "protocol evidence requires one frozen canonical Experiment"
            )
        if {item.logical_type for item in sources[0][1].records} != {
            "experiment_configuration",
            "evaluation_contract",
        }:
            raise ValidationError(
                "protocol evidence requires one exact scientific evaluation contract"
            )
        return

    if evidence_kind is GraphEvidenceKind.RESULT:
        if (
            len(objects) != 1
            or not isinstance(objects[0], Result)
            or objects[0].status is not RecordStatus.COMPLETE
            or sources[0][1].scientific_evidence_eligible is not True
        ):
            raise ValidationError(
                "result evidence requires one scientifically eligible canonical Result"
            )
        return

    if evidence_kind is GraphEvidenceKind.STATISTICAL_ANALYSIS:
        if (
            len(objects) != 1
            or not isinstance(objects[0], StatisticalTest)
            or objects[0].status is not RecordStatus.COMPLETE
        ):
            raise ValidationError(
                "statistical evidence requires one complete StatisticalTest"
            )
        by_content = sources[0][2]
        result_parent = _require_promoted_statistical_test_result(
            objects[0],
            sources[0][1],
            by_content,
        )
        repository = sources[0][3]
        if (
            repository._resolve_object_authority(
                result_parent, by_content
            ).scientific_evidence_eligible
            is not True
        ):
            raise ValidationError(
                "statistical evidence is derived from a non-scientific Result"
            )
        return

    if evidence_kind is GraphEvidenceKind.ROBUSTNESS:
        if len(objects) != 1 or not isinstance(
            objects[0], (Ablation, ReproducibilityPackage)
        ):
            raise ValidationError(
                "robustness evidence requires one Ablation or reproduction package"
            )
        from .scientific_numeric_ablation_canonical import is_numeric_ablation_metadata

        if isinstance(objects[0], Ablation) and is_numeric_ablation_metadata(objects[0].metadata):
            raise ValidationError("descriptive numeric intervention is not generic robustness evidence")
        resolved = sources[0][1]
        by_content = sources[0][2]
        if resolved.scientific_evidence_eligible is not True:
            source_kind = (
                "reproduction"
                if isinstance(objects[0], ReproducibilityPackage)
                else "ablation"
            )
            raise ValidationError(
                f"robustness {source_kind} is not scientifically eligible"
            )
        if isinstance(objects[0], Ablation):
            result_parents = ResearchStateRepository._resolved_parent_objects(
                objects[0],
                by_content,
                "Result",
            )
            if not result_parents:
                raise ValidationError("ablation lacks an evaluated Result")
            repository = sources[0][3]
            if any(
                repository._resolve_object_authority(
                    parent, by_content
                ).scientific_evidence_eligible
                is not True
                for parent in result_parents
            ):
                raise ValidationError(
                    "ablation evidence is derived from a non-scientific Result"
                )
        return

    raise ValidationError(
        f"{evidence_kind.value} lacks an implemented source-owned resolver"
    )


def _scientific_evidence_state_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    evidence_kind: GraphEvidenceKind,
    evidence_artifact: ArtifactRecord,
) -> tuple[
    tuple[
        CanonicalResearchObject,
        _ResolvedObjectAuthority,
        Mapping[str, _StoredObject],
        ResearchStateRepository,
    ],
    ...,
]:
    """Return the exact state parents already admitted by a kind resolver."""

    if evidence_kind is GraphEvidenceKind.SOURCE_CITATION:
        return ()
    if evidence_kind in {
        GraphEvidenceKind.SCOPE_QUALIFIER,
        GraphEvidenceKind.LIMITATION,
    }:
        if len(evidence_artifact.parent_artifacts) != 1:
            raise ValidationError(
                f"scientific {evidence_kind.value} authority is ambiguous"
            )
        authority = require_scientific_claim_qualifier_authority(
            registry,
            ledger,
            authority_artifact_hash=evidence_artifact.parent_artifacts[0],
            expected_run_id=run_id,
            expected_evidence_kind=evidence_kind,
        )
        return (
            _require_scoped_canonical_state_source(
                registry,
                ledger,
                run_id=run_id,
                state_artifact_hash=authority.result_state_artifact_hash,
            ),
            _require_scoped_canonical_state_source(
                registry,
                ledger,
                run_id=run_id,
                state_artifact_hash=authority.run_state_artifact_hash,
            ),
        )
    state_hashes = tuple(
        digest
        for digest in evidence_artifact.parent_artifacts
        if registry.get_metadata(digest).logical_type.startswith("research_state.")
    )
    return tuple(
        _require_scoped_canonical_state_source(
            registry,
            ledger,
            run_id=run_id,
            state_artifact_hash=digest,
        )
        for digest in state_hashes
    )


def _scientific_reproduction_matches_anchor(
    *,
    anchor_result: Result,
    anchor_experiment: Experiment,
    reproduction_results: tuple[CanonicalResearchObject, ...],
    reproduction_experiments: tuple[tuple[CanonicalResearchObject, ...], ...],
) -> bool:
    """Prevent a package for another Result from laundering robustness."""

    return (
        len(reproduction_results) == 1
        and isinstance(reproduction_results[0], Result)
        and reproduction_results[0].content_hash == anchor_result.content_hash
        and bool(reproduction_experiments)
        and all(
            len(experiments) == 1
            and isinstance(experiments[0], Experiment)
            and experiments[0].content_hash == anchor_experiment.content_hash
            for experiments in reproduction_experiments
        )
    )


def _require_scientific_claim_evidence_coherence(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    nodes: tuple[Any, ...],
    dependency_claim_ids: tuple[str, ...],
) -> None:
    """Join every kind to one exact Result/Run/Experiment authority graph."""

    state_sources: dict[
        GraphEvidenceKind,
        tuple[
            tuple[
                CanonicalResearchObject,
                _ResolvedObjectAuthority,
                Mapping[str, _StoredObject],
                ResearchStateRepository,
            ],
            ...,
        ],
    ] = {}
    for node in nodes:
        artifact = registry.get_metadata(node.artifact_hash)
        state_sources[node.kind] = _scientific_evidence_state_sources(
            registry,
            ledger,
            run_id=run_id,
            evidence_kind=node.kind,
            evidence_artifact=artifact,
        )

    contexts = {
        (
            source[3].code_version,
            source[3].configuration_hash,
            source[3].state,
        )
        for sources in state_sources.values()
        for source in sources
    }
    if len(contexts) != 1:
        raise ValidationError(
            "scientific claim evidence mixes canonical execution contexts"
        )

    result_sources = state_sources[GraphEvidenceKind.RESULT]
    if len(result_sources) != 1 or not isinstance(result_sources[0][0], Result):
        raise ValidationError(
            "scientific claim coherence requires one exact Result anchor"
        )
    anchor_result = result_sources[0][0]
    anchor_by_content = result_sources[0][2]
    anchor_repository = result_sources[0][3]
    anchor_runs = ResearchStateRepository._resolved_parent_objects(
        anchor_result,
        anchor_by_content,
        "Run",
    )
    if not anchor_runs:
        raise ValidationError("scientific Result anchor lacks evaluated Runs")
    anchor_experiment_candidates: list[Experiment] = []
    for run in anchor_runs:
        experiments = ResearchStateRepository._resolved_parent_objects(
            run,
            anchor_by_content,
            "Experiment",
        )
        if len(experiments) != 1:
            raise ValidationError(
                "scientific Result Runs do not name one exact Experiment"
            )
        anchor_experiment_candidates.append(experiments[0])
    experiment_hashes = {item.content_hash for item in anchor_experiment_candidates}
    if len(experiment_hashes) != 1:
        raise ValidationError(
            "scientific Result anchor mixes multiple Experiment revisions"
        )
    anchor_experiment = anchor_experiment_candidates[0]
    anchor_implementations = ResearchStateRepository._resolved_parent_objects(
        anchor_experiment,
        anchor_by_content,
        "Implementation",
    )
    anchor_datasets = ResearchStateRepository._resolved_parent_objects(
        anchor_experiment,
        anchor_by_content,
        "Dataset",
    )
    anchor_splits = ResearchStateRepository._resolved_parent_objects(
        anchor_experiment,
        anchor_by_content,
        "Split",
    )
    anchor_hypotheses = ResearchStateRepository._resolved_parent_objects(
        anchor_experiment,
        anchor_by_content,
        "Hypothesis",
    )
    if (
        len(anchor_implementations) != 1
        or len(anchor_datasets) != 1
        or len(anchor_splits) != 4
        or not anchor_hypotheses
        or {item.object_id for item in anchor_datasets}
        != set(anchor_experiment.dataset_ids)
        or {item.object_id for item in anchor_hypotheses}
        != set(anchor_experiment.hypothesis_ids)
    ):
        raise ValidationError(
            "scientific Result Experiment has an ambiguous input authority graph"
        )
    expected_split_roles = {
        SplitRole.TRAIN,
        SplitRole.EXPLORATORY,
        SplitRole.VALIDATION,
        SplitRole.CONFIRMATORY,
    }
    resolved_splits = tuple(
        anchor_repository._resolve_object_authority(split, anchor_by_content)
        for split in anchor_splits
    )
    if (
        {split.split_role for split in anchor_splits} != expected_split_roles
        or {split.dataset_id for split in anchor_splits}
        != {anchor_datasets[0].object_id}
        or {split.object_id for split in anchor_splits}
        != set(anchor_experiment.split_ids)
        or any(
            resolved.scientific_evidence_eligible is not True
            or len(resolved.records) != 1
            or resolved.records[0].logical_type
            != SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE
            for resolved in resolved_splits
        )
    ):
        raise ValidationError(
            "scientific Result Experiment lacks one protected disjoint split bundle"
        )

    protocol_sources = state_sources[GraphEvidenceKind.PROTOCOL_VERSION]
    code_sources = state_sources[GraphEvidenceKind.CODE]
    hypothesis_sources = state_sources[GraphEvidenceKind.HYPOTHESIS]
    dataset_sources = state_sources[GraphEvidenceKind.DATASET_OR_FIXTURE]
    if (
        len(protocol_sources) != 1
        or not isinstance(protocol_sources[0][0], Experiment)
        or protocol_sources[0][0].content_hash != anchor_experiment.content_hash
        or len(code_sources) != 1
        or not isinstance(code_sources[0][0], Implementation)
        or code_sources[0][0].content_hash != anchor_implementations[0].content_hash
        or len(hypothesis_sources) != 1
        or not isinstance(hypothesis_sources[0][0], Hypothesis)
        or hypothesis_sources[0][0].content_hash
        not in {item.content_hash for item in anchor_hypotheses}
        or len(dataset_sources) != 2
        or not isinstance(dataset_sources[0][0], Dataset)
        or not isinstance(dataset_sources[1][0], Result)
        or dataset_sources[0][0].content_hash != anchor_datasets[0].content_hash
        or dataset_sources[1][0].content_hash != anchor_result.content_hash
    ):
        raise ValidationError(
            "scientific claim evidence splices unrelated Protocol, Code, "
            "Hypothesis, Dataset, or Result state"
        )

    statistical_sources = state_sources[GraphEvidenceKind.STATISTICAL_ANALYSIS]
    estimand_sources = state_sources[GraphEvidenceKind.ESTIMAND]
    figure_sources = state_sources[GraphEvidenceKind.FIGURE_OR_TABLE]
    if (
        len(statistical_sources) != 1
        or not isinstance(statistical_sources[0][0], StatisticalTest)
        or len(estimand_sources) != 1
        or not isinstance(estimand_sources[0][0], StatisticalTest)
        or len(figure_sources) != 2
        or not isinstance(figure_sources[0][0], Result)
        or not isinstance(figure_sources[1][0], StatisticalTest)
        or figure_sources[0][0].content_hash != anchor_result.content_hash
    ):
        raise ValidationError(
            "scientific claim evidence lacks one exact Result/Test/Estimand/Figure join"
        )
    anchor_test_hash = statistical_sources[0][0].content_hash
    if (
        estimand_sources[0][0].content_hash != anchor_test_hash
        or figure_sources[1][0].content_hash != anchor_test_hash
    ):
        raise ValidationError(
            "scientific claim evidence splices different StatisticalTest revisions"
        )
    anchor_test_results = ResearchStateRepository._resolved_parent_objects(
        statistical_sources[0][0],
        statistical_sources[0][2],
        "Result",
    )
    if (
        len(anchor_test_results) != 1
        or anchor_test_results[0].content_hash != anchor_result.content_hash
    ):
        raise ValidationError(
            "scientific StatisticalTest does not evaluate the Result anchor"
        )

    robustness_sources = state_sources[GraphEvidenceKind.ROBUSTNESS]
    if len(robustness_sources) != 1:
        raise ValidationError("scientific robustness authority is ambiguous")
    robustness = robustness_sources[0][0]
    if isinstance(robustness, Ablation):
        from .scientific_numeric_ablation_canonical import is_numeric_ablation_metadata

        if is_numeric_ablation_metadata(robustness.metadata):
            raise ValidationError("descriptive numeric intervention cannot anchor a generic robustness claim")
        if set(robustness.experiment_ids) != {
            anchor_experiment.object_id
        } or robustness.hypothesis_id not in {
            item.object_id for item in anchor_hypotheses
        }:
            raise ValidationError(
                "scientific Ablation is unrelated to the Result Experiment"
            )
        robustness_results = ResearchStateRepository._resolved_parent_objects(
            robustness,
            robustness_sources[0][2],
            "Result",
        )
        for result in robustness_results:
            runs = ResearchStateRepository._resolved_parent_objects(
                result,
                robustness_sources[0][2],
                "Run",
            )
            if not runs or any(
                len(
                    ResearchStateRepository._resolved_parent_objects(
                        run,
                        robustness_sources[0][2],
                        "Experiment",
                    )
                )
                != 1
                or ResearchStateRepository._resolved_parent_objects(
                    run,
                    robustness_sources[0][2],
                    "Experiment",
                )[0].content_hash
                != anchor_experiment.content_hash
                for run in runs
            ):
                raise ValidationError(
                    "scientific Ablation results belong to another Experiment"
                )
    elif isinstance(robustness, ReproducibilityPackage):
        reproduction_results = ResearchStateRepository._resolved_parent_objects(
            robustness,
            robustness_sources[0][2],
            "Result",
        )
        reproduction_runs = ResearchStateRepository._resolved_parent_objects(
            robustness,
            robustness_sources[0][2],
            "Run",
        )
        reproduction_experiments = tuple(
            ResearchStateRepository._resolved_parent_objects(
                run,
                robustness_sources[0][2],
                "Experiment",
            )
            for run in reproduction_runs
        )
        if not _scientific_reproduction_matches_anchor(
            anchor_result=anchor_result,
            anchor_experiment=anchor_experiment,
            reproduction_results=reproduction_results,
            reproduction_experiments=reproduction_experiments,
        ):
            raise ValidationError(
                "scientific reproduction belongs to another Result or Experiment"
            )
    else:  # pragma: no cover - the kind resolver proves this first
        raise ValidationError("unsupported scientific robustness source")

    _ = dependency_claim_ids
    for kind in (GraphEvidenceKind.SCOPE_QUALIFIER, GraphEvidenceKind.LIMITATION):
        sources = state_sources[kind]
        if (
            len(sources) != 2
            or not isinstance(sources[0][0], Result)
            or not isinstance(sources[1][0], Run)
        ):
            raise ValidationError(f"scientific {kind.value} authority is ambiguous")
        if sources[0][0].content_hash != anchor_result.content_hash or sources[1][
            0
        ].content_hash not in {item.content_hash for item in anchor_runs}:
            raise ValidationError(
                f"scientific {kind.value} names another Result or Run"
            )

    # Force fresh replay of the anchor authorities in this exact context after
    # all cross-kind identity checks; caller object labels are never the join.
    anchor_repository._resolve_object_authority(anchor_result, anchor_by_content)
    anchor_repository._resolve_object_authority(anchor_experiment, anchor_by_content)


def _require_claim_bound_literature_evidence_source(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    claim_id: str,
    claim_semantics_proposal_artifact_hash: str,
    reference_support_semantic_judgment_artifact_hash: str,
    evidence_artifact: ArtifactRecord,
    source_closure: tuple[tuple[ArtifactRecord, bytes], ...],
) -> None:
    """Require exact L5 claim support plus audited-live literature custody."""

    if len(evidence_artifact.parent_artifacts) != 3:
        raise ValidationError(
            "source-citation evidence requires exact reference, graph, and "
            "transport parents"
        )
    reference_record = registry.get_metadata(evidence_artifact.parent_artifacts[0])
    citation_graph_record = registry.get_metadata(evidence_artifact.parent_artifacts[1])
    transport_record = registry.get_metadata(evidence_artifact.parent_artifacts[2])
    if (
        reference_record.logical_type != "reference_verification"
        or reference_record.creator_role is not Role.CLAIM_VERIFIER
        or citation_graph_record.logical_type != "citation_graph"
        or citation_graph_record.creator_role is not Role.EVIDENCE_CURATOR
        or transport_record.logical_type != "audited_transport_execution_authority"
        or transport_record.creator_role is not Role.EVIDENCE_CURATOR
    ):
        raise ValidationError(
            "source-citation evidence reordered or substituted typed authority"
        )
    try:
        from .literature import CitationGraphNode, ScholarlyRecord
        from .scientific_design import (
            require_audited_claim_bound_reference_authority,
        )

        reference_wrapper = safe_json_loads(
            registry.get_bytes(reference_record.sha256),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
        if not isinstance(reference_wrapper, Mapping):
            raise ValidationError("source-citation reference wrapper is not an object")
        scholarly_record_hash = reference_wrapper.get("scholarly_record_artifact_hash")
        if not isinstance(scholarly_record_hash, str):
            raise ValidationError(
                "source-citation reference omits its normalized record"
            )
        scholarly_record = ScholarlyRecord.from_dict(
            safe_json_loads(
                registry.get_bytes(scholarly_record_hash),
                max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
            )
        )
        expected_node = CitationGraphNode.from_record(scholarly_record)
        authority = require_audited_claim_bound_reference_authority(
            registry,
            ledger,
            expected_run_id=run_id,
            expected_claim_id=claim_id,
            expected_citation_node_id=expected_node.node_id,
            source_citation_evidence_artifact_sha256=evidence_artifact.sha256,
            claim_semantics_proposal_artifact_sha256=(
                claim_semantics_proposal_artifact_hash
            ),
            reference_support_semantic_judgment_artifact_sha256=(
                reference_support_semantic_judgment_artifact_hash
            ),
        )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "source citation lacks audited-live claim-bound reference authority"
        ) from exc
    closure_by_hash = {item.sha256: item for item, _content in source_closure}
    if (
        authority.run_id != run_id
        or authority.claim_id != claim_id
        or authority.source_citation_evidence_artifact_sha256
        != evidence_artifact.sha256
        or authority.source_citation_evidence_record_hash
        != str(evidence_artifact.record_hash)
        or authority.reference_verification_artifact_sha256 != reference_record.sha256
        or authority.citation_graph_artifact_sha256 != citation_graph_record.sha256
        or authority.transport_execution_authority_artifact_sha256
        != transport_record.sha256
        or authority.claim_semantics_proposal_artifact_sha256
        != claim_semantics_proposal_artifact_hash
        or authority.semantic_judgment_artifact_sha256
        != reference_support_semantic_judgment_artifact_hash
        or authority.semantic_support is not True
        or authority.material_contextual_contradiction is not False
        or not set(authority.evidence_artifact_hashes).issubset(closure_by_hash)
        or len(authority.evidence_artifact_hashes)
        != len(authority.evidence_record_hashes)
        or any(
            str(closure_by_hash[digest].record_hash) != record_hash
            for digest, record_hash in zip(
                authority.evidence_artifact_hashes,
                authority.evidence_record_hashes,
                strict=True,
            )
        )
    ):
        raise ValidationError(
            "claim-bound reference authority differs from retained source closure"
        )


def _require_scientific_claim_semantics_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    graph_artifact_hash: str,
    claim_id: str,
    dependency_claim_ids: tuple[str, ...],
    claim_semantics_proposal_artifact_hash: str,
    reference_support_semantic_judgment_artifact_hash: str | None,
) -> None:
    """Fail closed unless every linked kind has source-owned authority."""

    _graph_record, claim = _resolve_claim_semantics_graph(
        registry,
        graph_artifact_hash,
        claim_id,
    )
    nodes = _claim_semantics_evidence_nodes(
        registry,
        graph_artifact_hash=graph_artifact_hash,
        claim_id=claim_id,
    )
    for node in nodes:
        artifact = registry.get_metadata(node.artifact_hash)
        if artifact.logical_type != f"claim_evidence.{node.kind.value}":
            raise ValidationError(
                "claim-semantics evidence has a substituted logical type"
            )
        if not artifact.parent_artifacts:
            raise ValidationError(
                f"{node.kind.value} lacks explicit source authority parents"
            )
        closure = _claim_semantics_source_closure(
            registry,
            (
                artifact.sha256,
                *(
                    (reference_support_semantic_judgment_artifact_hash,)
                    if node.kind is GraphEvidenceKind.SOURCE_CITATION
                    and reference_support_semantic_judgment_artifact_hash is not None
                    else ()
                ),
            ),
        )
        if node.kind is GraphEvidenceKind.SOURCE_CITATION:
            if reference_support_semantic_judgment_artifact_hash is None:
                raise ValidationError(
                    "scientific claim semantics require one explicit "
                    "reference-support judgment"
                )
            _require_claim_bound_literature_evidence_source(
                registry,
                ledger,
                run_id=run_id,
                claim_id=claim_id,
                claim_semantics_proposal_artifact_hash=(
                    claim_semantics_proposal_artifact_hash
                ),
                reference_support_semantic_judgment_artifact_hash=(
                    reference_support_semantic_judgment_artifact_hash
                ),
                evidence_artifact=artifact,
                source_closure=closure,
            )
        else:
            _require_scientific_state_evidence_source(
                registry,
                ledger,
                run_id=run_id,
                evidence_kind=node.kind,
                evidence_artifact=artifact,
                evidence_id=node.evidence_id,
                claim_id=claim.claim_id,
                claim_text=claim.text,
                claim_producer_role=claim.producer_role,
                claim_confirmatory=claim.confirmatory,
                claim_evidence_use=claim.evidence_use,
                assertion_text=node.description,
            )
    _require_scientific_claim_evidence_coherence(
        registry,
        ledger,
        run_id=run_id,
        nodes=nodes,
        dependency_claim_ids=dependency_claim_ids,
    )
    # Only after every source-owned resolver succeeds do we inspect the
    # producer projection.  This ordering ensures that a perfectly formatted
    # wrapper can never hide a missing scientific source.
    for node in nodes:
        _require_scientific_claim_evidence_projection(
            registry,
            artifact=registry.get_metadata(node.artifact_hash),
            evidence_id=node.evidence_id,
            evidence_kind=node.kind,
            claim_id=claim.claim_id,
            claim_text=claim.text,
            claim_producer_role=claim.producer_role,
        )


def _claim_semantics_retained_source(
    record: ArtifactRecord,
    content: bytes,
) -> dict[str, Any]:
    """Project every provenance-significant registry field for live review."""

    try:
        content_text = content.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValidationError(
            "claim-semantics positive review has non-textual source evidence; "
            "a source-owned multimodal resolver is required"
        ) from exc
    return {
        "artifact_sha256": record.sha256,
        "artifact_record_hash": str(record.record_hash),
        "path": record.path,
        "relative_path": record.relative_path,
        "metadata_path": record.metadata_path,
        "logical_type": record.logical_type,
        "creator_role": record.creator_role.value,
        "schema_version": record.schema_version,
        "mime_type": record.mime_type,
        "size": record.size,
        "origin": record.origin,
        "creation_command": list(record.creation_command),
        "validation_result": record.validation_result,
        "frozen": record.frozen,
        "created_at": record.created_at,
        "parent_artifacts": list(record.parent_artifacts),
        "content_utf8": content_text,
    }


@dataclass(frozen=True, slots=True)
class _ScientificClaimQualifierSource:
    result: Result
    result_artifact: ArtifactRecord
    result_event: LedgerEvent
    execution_run: Run
    run_artifact: ArtifactRecord
    run_event: LedgerEvent
    bundle_completion_artifact: ArtifactRecord
    bundle_completion_event: LedgerEvent
    bundle_completion_event_index: int
    bundle_statistical_test_id: str | None
    source_closure: tuple[tuple[ArtifactRecord, bytes], ...]


def _resolve_scientific_claim_qualifier_source(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    result_state_artifact_hash: str,
) -> _ScientificClaimQualifierSource:
    """Freshly replay the exact eligible Result/Run qualifier anchor."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    # A qualifier is replayed again while validating the later canonical Claim
    # that consumes it.  Whole-state validation here would therefore recurse
    # Claim -> semantics -> qualifier -> whole state -> Claim.  Reuse the
    # public, target-scoped state resolver: it replays the exact current Result
    # and its source-bound parent lineage while deliberately ignoring unrelated
    # later review/Claim objects.
    scoped = resolve_current_research_state_bindings(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hashes=(result_state_artifact_hash,),
    )
    result_binding = scoped.binding_for_artifact(result_state_artifact_hash)
    result = result_binding.research_object
    if (
        not isinstance(result, Result)
        or result.status is not RecordStatus.COMPLETE
        or result_binding.scientific_evidence_eligible is not True
        or len(result.run_ids) != 1
    ):
        raise ValidationError(
            "scientific claim qualifier requires one scientifically eligible Result"
        )
    events = ledger.events()
    if result_binding.materialization_event_index >= len(events):
        raise ValidationError(
            "scientific claim qualifier Result event index is invalid"
        )
    result_event = events[result_binding.materialization_event_index]
    if (
        result_event.event_id != result_binding.materialization_event_id
        or result_event.event_hash != result_binding.materialization_event_hash
    ):
        raise ValidationError("scientific claim qualifier Result event binding changed")
    result_artifact = registry.get_metadata(result_state_artifact_hash)
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=scoped.code_version,
        configuration_hash=scoped.configuration_hash,
        state=result_event.state_before,
        creation_command=result_artifact.creation_command,
    )
    stored = repository._stored_objects()
    by_content, _by_identity = repository._indexes(stored)
    result_stored = by_content.get(result.content_hash)
    if (
        result_stored is None
        or result_stored.research_object != result
        or result_stored.artifact.sha256 != result_state_artifact_hash
        or str(result_stored.artifact.record_hash)
        != result_binding.artifact_record_hash
    ):
        raise ValidationError(
            "scientific claim qualifier Result state identity was substituted"
        )
    resolved = repository._resolve_object_authority(result, by_content)
    if (
        resolved.scientific_evidence_eligible
        is not result_binding.scientific_evidence_eligible
        or tuple(item.sha256 for item in resolved.records)
        != result_binding.authority_artifact_hashes
        or tuple(str(item.record_hash) for item in resolved.records)
        != result_binding.authority_artifact_record_hashes
    ):
        raise ValidationError(
            "scientific claim qualifier Result authority changed during replay"
        )
    run_parents = ResearchStateRepository._resolved_parent_objects(
        result,
        by_content,
        "Run",
    )
    if (
        len(run_parents) != 1
        or result.run_ids != (run_parents[0].object_id,)
        or not any(
            parent.object_type == "Run"
            and parent.object_id == run_parents[0].object_id
            and parent.content_hash == run_parents[0].content_hash
            and parent.relation == "aggregates"
            and parent.evaluated is True
            for parent in result.parents
        )
    ):
        raise ValidationError(
            "scientific claim qualifier Result lacks one exact evaluated Run"
        )
    run_stored = by_content.get(run_parents[0].content_hash)
    if run_stored is None or not isinstance(run_stored.research_object, Run):
        raise ValidationError("scientific claim qualifier Run state artifact is absent")
    execution_run = run_stored.research_object
    run_resolved = repository._resolve_object_authority(execution_run, by_content)
    if (
        execution_run.content_hash != run_parents[0].content_hash
        or execution_run.status is not RecordStatus.COMPLETE
        or execution_run.completed_at is None
        or not run_resolved.records
    ):
        raise ValidationError(
            "scientific claim qualifier Run authority was substituted"
        )
    run_event = repository._materialization_event(
        run_stored.artifact.sha256,
        execution_run,
    )
    if run_event is None:
        raise ValidationError(
            "scientific claim qualifier source lacks exact materialization events"
        )
    event_indexes = {event.event_id: index for index, event in enumerate(events)}
    if (
        result_event.event_id not in event_indexes
        or run_event.event_id not in event_indexes
        or event_indexes[result_event.event_id] <= event_indexes[run_event.event_id]
    ):
        raise ValidationError(
            "scientific claim qualifier Result does not follow its evaluated Run"
        )
    promotion_records = tuple(
        item
        for item in resolved.records
        if item.logical_type == "scientific_result_promotion_authority"
    )
    if len(promotion_records) != 1:
        raise ValidationError(
            "scientific claim qualifier Result lacks one exact promotion authority"
        )
    bundle_completion = repository._require_scientific_result_bundle_completion(
        result,
        by_content,
        promotion_record=promotion_records[0],
        expected_scientific_evidence_eligible=True,
    )
    completion_payload = repository._read_authority_json(bundle_completion)
    completion_event_id = f"rsb-{bundle_completion.sha256[:48]}"
    completion_events = tuple(
        (index, event)
        for index, event in enumerate(events)
        if event.event_id == completion_event_id
    )
    if (
        len(completion_events) != 1
        or completion_events[0][1].event_hash is None
        or completion_events[0][0] <= event_indexes[result_event.event_id]
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == completion_event_id
            for later in events[completion_events[0][0] + 1 :]
        )
    ):
        raise ValidationError(
            "scientific claim qualifier bundle completion is absent or superseded"
        )
    bundle_statistical_test_id = completion_payload.get("statistical_test_id")
    if bundle_statistical_test_id is not None and not isinstance(
        bundle_statistical_test_id,
        str,
    ):
        raise ValidationError(
            "scientific claim qualifier bundle StatisticalTest identity is invalid"
        )
    closure = _claim_semantics_source_closure(
        registry,
        (result_stored.artifact.sha256, bundle_completion.sha256),
    )
    closure_hashes = {record.sha256 for record, _content in closure}
    if (
        result_stored.artifact.sha256 not in closure_hashes
        or run_stored.artifact.sha256 not in closure_hashes
        or bundle_completion.sha256 not in closure_hashes
        or promotion_records[0].sha256 not in closure_hashes
        or not set(item.sha256 for item in resolved.records).issubset(closure_hashes)
        or not set(item.sha256 for item in run_resolved.records).issubset(
            closure_hashes
        )
    ):
        raise ValidationError("scientific claim qualifier source closure is incomplete")
    return _ScientificClaimQualifierSource(
        result=result,
        result_artifact=result_stored.artifact,
        result_event=result_event,
        execution_run=execution_run,
        run_artifact=run_stored.artifact,
        run_event=run_event,
        bundle_completion_artifact=bundle_completion,
        bundle_completion_event=completion_events[0][1],
        bundle_completion_event_index=completion_events[0][0],
        bundle_statistical_test_id=bundle_statistical_test_id,
        source_closure=closure,
    )


def _scientific_claim_qualifier_slot(
    *,
    run_id: str,
    evidence_kind: GraphEvidenceKind,
    claim_id: str,
    source: _ScientificClaimQualifierSource,
) -> dict[str, Any]:
    """Return the coarse one-branch slot, excluding caller qualifier prose."""

    return {
        "schema_version": "scientific-claim-qualifier-slot/v1",
        "run_id": run_id,
        "claim_id": claim_id,
        "evidence_kind": evidence_kind.value,
        "result_id": source.result.object_id,
        "result_content_hash": source.result.content_hash,
        "result_state_artifact_hash": source.result_artifact.sha256,
        "result_state_record_hash": str(source.result_artifact.record_hash),
        "execution_run_id": source.execution_run.object_id,
        "run_content_hash": source.execution_run.content_hash,
        "run_state_artifact_hash": source.run_artifact.sha256,
        "run_state_record_hash": str(source.run_artifact.record_hash),
    }


def _scientific_claim_qualifier_projection(
    *,
    run_id: str,
    evidence_id: str,
    evidence_kind: GraphEvidenceKind,
    claim_id: str,
    claim_text: str,
    claim_producer_role: Role,
    claim_confirmatory: bool,
    claim_evidence_use: ClaimEvidenceUse,
    assertion_text: str,
    source: _ScientificClaimQualifierSource,
) -> tuple[str, Mapping[str, Any]]:
    slot = _scientific_claim_qualifier_slot(
        run_id=run_id,
        evidence_kind=evidence_kind,
        claim_id=claim_id,
        source=source,
    )
    subject_id = f"claim-qualifier-{sha256_bytes(canonical_json_bytes(slot))}"
    projection = {
        "schema_version": SCIENTIFIC_CLAIM_QUALIFIER_PROJECTION_PAYLOAD_SCHEMA,
        "subject_id": subject_id,
        "run_id": run_id,
        "evidence_id": evidence_id,
        "evidence_kind": evidence_kind.value,
        "claim_id": claim_id,
        "claim_text": claim_text,
        "claim_producer_role": claim_producer_role.value,
        "claim_confirmatory": claim_confirmatory,
        "claim_evidence_use": claim_evidence_use.value,
        "assertion_text": assertion_text,
        "result_id": source.result.object_id,
        "result_content_hash": source.result.content_hash,
        "result_state_artifact_hash": source.result_artifact.sha256,
        "result_state_record_hash": str(source.result_artifact.record_hash),
        "result_materialization_event_id": source.result_event.event_id,
        "result_materialization_event_hash": source.result_event.event_hash,
        "execution_run_id": source.execution_run.object_id,
        "run_content_hash": source.execution_run.content_hash,
        "run_state_artifact_hash": source.run_artifact.sha256,
        "run_state_record_hash": str(source.run_artifact.record_hash),
        "run_materialization_event_id": source.run_event.event_id,
        "run_materialization_event_hash": source.run_event.event_hash,
        "bundle_completion_artifact_hash": (source.bundle_completion_artifact.sha256),
        "bundle_completion_record_hash": str(
            source.bundle_completion_artifact.record_hash
        ),
        "bundle_completion_event_id": source.bundle_completion_event.event_id,
        "bundle_completion_event_hash": source.bundle_completion_event.event_hash,
        "bundle_completion_event_index": source.bundle_completion_event_index,
        "bundle_statistical_test_id": source.bundle_statistical_test_id,
    }
    return subject_id, freeze_json(projection)


def build_scientific_claim_qualifier_judgment_request(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    evidence_id: str,
    evidence_kind: GraphEvidenceKind,
    claim_id: str,
    claim_text: str,
    claim_producer_role: Role,
    claim_confirmatory: bool,
    claim_evidence_use: ClaimEvidenceUse,
    assertion_text: str,
    result_state_artifact_hash: str,
) -> ClaimSemanticsJudgmentRequest:
    """Build retained audited-review inputs without creating authority."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_identifier(evidence_id, "claim-qualifier evidence ID")
    validate_identifier(claim_id, "claim-qualifier claim ID")
    if evidence_kind not in {
        GraphEvidenceKind.SCOPE_QUALIFIER,
        GraphEvidenceKind.LIMITATION,
    }:
        raise ValidationError(
            "claim qualifier judgment requires SCOPE_QUALIFIER or LIMITATION"
        )
    _bounded_text(claim_text, "claim-qualifier claim text")
    _bounded_text(assertion_text, "claim-qualifier assertion text")
    if (
        not isinstance(claim_producer_role, Role)
        or claim_producer_role is Role.CLAIM_VERIFIER
    ):
        raise AuthorizationError(
            "claim qualifier judgment requires a non-verifier claim producer"
        )
    if not isinstance(claim_confirmatory, bool):
        raise ValidationError(
            "claim qualifier judgment confirmatory flag must be boolean"
        )
    if not isinstance(claim_evidence_use, ClaimEvidenceUse):
        raise ValidationError("claim qualifier judgment evidence use must be typed")
    validate_sha256(
        result_state_artifact_hash,
        "claim-qualifier Result state artifact SHA-256",
    )
    source = _resolve_scientific_claim_qualifier_source(
        registry,
        ledger,
        run_id=run_id,
        result_state_artifact_hash=result_state_artifact_hash,
    )
    subject_id, frozen_projection = _scientific_claim_qualifier_projection(
        run_id=run_id,
        evidence_id=evidence_id,
        evidence_kind=evidence_kind,
        claim_id=claim_id,
        claim_text=claim_text,
        claim_producer_role=claim_producer_role,
        claim_confirmatory=claim_confirmatory,
        claim_evidence_use=claim_evidence_use,
        assertion_text=assertion_text,
        source=source,
    )
    projection = thaw_json(frozen_projection)
    qualifier_projection_sha256 = sha256_bytes(canonical_json_bytes(projection))
    accepted_outcome = f"CLAIM_QUALIFIER_ACCEPTED:{qualifier_projection_sha256}"
    evidence_closure = tuple(
        item
        for item in source.source_closure
        if item[0].sha256 != source.result_artifact.sha256
    )
    if not evidence_closure or source.run_artifact.sha256 not in {
        item.sha256 for item, _content in evidence_closure
    }:
        raise ValidationError(
            "claim qualifier judgment lacks the exact Result authority closure"
        )
    input_payload = {
        "schema_version": "scientific-claim-qualifier-judgment-input/v1",
        "subject_kind": "CLAIM_QUALIFIER",
        "subject_id": subject_id,
        "accepted_outcome": accepted_outcome,
        "qualifier_projection_sha256": qualifier_projection_sha256,
        "qualifier_projection": projection,
        "source_artifact_closure_hashes": [
            record.sha256 for record, _content in source.source_closure
        ],
        "source_artifacts": [
            _claim_semantics_retained_source(record, content)
            for record, content in source.source_closure
        ],
    }
    output_schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "subject_kind": {"type": "string", "enum": ["CLAIM_QUALIFIER"]},
            "subject_id": {"type": "string", "enum": [subject_id]},
            "outcome": {
                "type": "string",
                "enum": [accepted_outcome, "CLAIM_QUALIFIER_REJECTED"],
            },
            "rationale": {
                "type": "string",
                "minLength": 1,
                "maxLength": MAX_SHORT_TEXT_LENGTH,
            },
        },
        "required": ["subject_kind", "subject_id", "outcome", "rationale"],
    }
    return ClaimSemanticsJudgmentRequest(
        subject_id=subject_id,
        accepted_outcome=accepted_outcome,
        evidence_hashes=tuple(record.sha256 for record, _content in evidence_closure),
        context_hashes=(source.result_artifact.sha256,),
        instructions=SCIENTIFIC_CLAIM_QUALIFIER_PROMPT_INSTRUCTIONS,
        input_text=canonical_json_bytes(input_payload).decode("utf-8"),
        output_schema=output_schema,
        prompt_template_id=SCIENTIFIC_CLAIM_QUALIFIER_PROMPT_TEMPLATE_ID,
        prompt_template_version=SCIENTIFIC_CLAIM_QUALIFIER_PROMPT_TEMPLATE_VERSION,
        prompt_template_hash=sha256_bytes(
            SCIENTIFIC_CLAIM_QUALIFIER_PROMPT_INSTRUCTIONS.encode("utf-8")
        ),
        governing_rule=SCIENTIFIC_CLAIM_QUALIFIER_GOVERNING_RULE,
    )


def _claim_qualifier_request_from_retained_input(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    retained_input: bytes,
) -> ClaimSemanticsJudgmentRequest:
    try:
        value = safe_json_loads(
            retained_input,
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except Exception as exc:
        raise ValidationError(
            "claim-qualifier retained judgment input is malformed"
        ) from exc
    if (
        not isinstance(value, Mapping)
        or set(value)
        != {
            "schema_version",
            "subject_kind",
            "subject_id",
            "accepted_outcome",
            "qualifier_projection_sha256",
            "qualifier_projection",
            "source_artifact_closure_hashes",
            "source_artifacts",
        }
        or value["schema_version"] != "scientific-claim-qualifier-judgment-input/v1"
        or value["subject_kind"] != "CLAIM_QUALIFIER"
        or not isinstance(value["qualifier_projection"], Mapping)
    ):
        raise ValidationError(
            "claim-qualifier retained judgment input schema is incomplete"
        )
    projection = value["qualifier_projection"]
    expected_projection_keys = {
        "schema_version",
        "subject_id",
        "run_id",
        "evidence_id",
        "evidence_kind",
        "claim_id",
        "claim_text",
        "claim_producer_role",
        "claim_confirmatory",
        "claim_evidence_use",
        "assertion_text",
        "result_id",
        "result_content_hash",
        "result_state_artifact_hash",
        "result_state_record_hash",
        "result_materialization_event_id",
        "result_materialization_event_hash",
        "execution_run_id",
        "run_content_hash",
        "run_state_artifact_hash",
        "run_state_record_hash",
        "run_materialization_event_id",
        "run_materialization_event_hash",
        "bundle_completion_artifact_hash",
        "bundle_completion_record_hash",
        "bundle_completion_event_id",
        "bundle_completion_event_hash",
        "bundle_completion_event_index",
        "bundle_statistical_test_id",
    }
    if (
        set(projection) != expected_projection_keys
        or projection.get("schema_version")
        != SCIENTIFIC_CLAIM_QUALIFIER_PROJECTION_PAYLOAD_SCHEMA
        or projection.get("run_id") != run_id
    ):
        raise ValidationError(
            "claim-qualifier retained projection schema is incomplete"
        )
    try:
        rebuilt = build_scientific_claim_qualifier_judgment_request(
            registry,
            ledger,
            run_id=run_id,
            evidence_id=projection["evidence_id"],
            evidence_kind=GraphEvidenceKind(projection["evidence_kind"]),
            claim_id=projection["claim_id"],
            claim_text=projection["claim_text"],
            claim_producer_role=Role(projection["claim_producer_role"]),
            claim_confirmatory=projection["claim_confirmatory"],
            claim_evidence_use=ClaimEvidenceUse(projection["claim_evidence_use"]),
            assertion_text=projection["assertion_text"],
            result_state_artifact_hash=projection["result_state_artifact_hash"],
        )
    except (KeyError, TypeError, ValueError) as exc:
        raise ValidationError(
            "claim-qualifier retained projection is malformed"
        ) from exc
    if rebuilt.input_bytes != retained_input:
        raise ValidationError(
            "claim-qualifier retained input differs from fresh source replay"
        )
    return rebuilt


def _require_unique_scientific_claim_qualifier_judgment(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    request: ClaimSemanticsJudgmentRequest,
    selected_artifact_hash: str,
    expected_outcome: str | None = None,
) -> Any:
    """Reject favorable-hash selection across any coarse-slot outcome."""

    try:
        from .gates import (
            JudgmentSubjectKind,
            SemanticJudgmentReceipt,
            require_scientific_semantic_judgment_receipt,
        )
    except Exception as exc:  # pragma: no cover - import topology is fixed
        raise ValidationError(
            "claim-qualifier semantic resolver is unavailable"
        ) from exc
    matching: list[tuple[str, Any]] = []
    for artifact in registry.list_records():
        if (
            artifact.logical_type != "scientific_semantic_judgment_receipt"
            or artifact.creator_role is not Role.SCIENTIFIC_REVIEWER
        ):
            continue
        try:
            candidate = SemanticJudgmentReceipt.from_dict(
                safe_json_loads(
                    registry.get_bytes(artifact.sha256),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
            )
            if (
                candidate.subject_kind is not JudgmentSubjectKind.CLAIM_QUALIFIER
                or candidate.subject_id != request.subject_id
                or candidate.prompt_template_id != request.prompt_template_id
                or candidate.prompt_template_version != request.prompt_template_version
                or candidate.prompt_template_hash != request.prompt_template_hash
                or candidate.governing_rule != request.governing_rule
            ):
                continue
            resolved = require_scientific_semantic_judgment_receipt(
                registry,
                ledger,
                run_id=run_id,
                receipt_artifact_hash=artifact.sha256,
                subject_kind=JudgmentSubjectKind.CLAIM_QUALIFIER,
                subject_id=candidate.subject_id,
                outcome=candidate.outcome,
                evidence_hashes=candidate.evidence_hashes,
                context_hashes=candidate.context_hashes,
            )
            retained_input = registry.get_bytes(resolved.input_artifact_hash)
            rebuilt = _claim_qualifier_request_from_retained_input(
                registry,
                ledger,
                run_id=run_id,
                retained_input=retained_input,
            )
            if (
                rebuilt.subject_id != request.subject_id
                or resolved.evidence_hashes != rebuilt.evidence_hashes
                or resolved.context_hashes != rebuilt.context_hashes
                or resolved.outcome
                not in {
                    rebuilt.accepted_outcome,
                    "CLAIM_QUALIFIER_REJECTED",
                }
                or registry.get_bytes(resolved.instructions_artifact_hash)
                != rebuilt.instructions_bytes
                or registry.get_bytes(resolved.output_schema_artifact_hash)
                != rebuilt.output_schema_bytes
            ):
                continue
        except (ArtifactError, ValidationError):
            continue
        matching.append((artifact.sha256, resolved))
    if len(matching) != 1 or matching[0][0] != selected_artifact_hash:
        raise ValidationError("scientific claim-qualifier judgment branch is ambiguous")
    selected = matching[0][1]
    resolved_outcome = (
        request.accepted_outcome if expected_outcome is None else expected_outcome
    )
    if resolved_outcome not in {
        request.accepted_outcome,
        "CLAIM_QUALIFIER_REJECTED",
    }:
        raise ValidationError(
            "claim-qualifier expected outcome is outside the frozen schema"
        )
    if (
        selected.outcome != resolved_outcome
        or selected.evidence_hashes != request.evidence_hashes
        or selected.context_hashes != request.context_hashes
        or registry.get_bytes(selected.instructions_artifact_hash)
        != request.instructions_bytes
        or registry.get_bytes(selected.input_artifact_hash) != request.input_bytes
        or registry.get_bytes(selected.output_schema_artifact_hash)
        != request.output_schema_bytes
    ):
        raise ValidationError(
            "selected claim-qualifier judgment differs from the exact request outcome"
        )
    return selected


def _scientific_claim_qualifier_authority_payload(
    *,
    request: ClaimSemanticsJudgmentRequest,
    source: _ScientificClaimQualifierSource,
    semantic_judgment_artifact: ArtifactRecord,
) -> dict[str, Any]:
    input_value = safe_json_loads(
        request.input_bytes,
        max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
    )
    projection = input_value["qualifier_projection"]
    closure = source.source_closure
    return {
        "schema_version": SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_PAYLOAD_SCHEMA,
        "subject_id": request.subject_id,
        "accepted_outcome": request.accepted_outcome,
        "run_id": projection["run_id"],
        "evidence_id": projection["evidence_id"],
        "evidence_kind": projection["evidence_kind"],
        "claim_id": projection["claim_id"],
        "claim_text": projection["claim_text"],
        "claim_producer_role": projection["claim_producer_role"],
        "claim_confirmatory": projection["claim_confirmatory"],
        "claim_evidence_use": projection["claim_evidence_use"],
        "assertion_text": projection["assertion_text"],
        "qualifier_projection_sha256": input_value["qualifier_projection_sha256"],
        "result_id": projection["result_id"],
        "result_content_hash": projection["result_content_hash"],
        "result_state_artifact_hash": projection["result_state_artifact_hash"],
        "result_state_record_hash": projection["result_state_record_hash"],
        "result_materialization_event_id": projection[
            "result_materialization_event_id"
        ],
        "result_materialization_event_hash": projection[
            "result_materialization_event_hash"
        ],
        "execution_run_id": projection["execution_run_id"],
        "run_content_hash": projection["run_content_hash"],
        "run_state_artifact_hash": projection["run_state_artifact_hash"],
        "run_state_record_hash": projection["run_state_record_hash"],
        "run_materialization_event_id": projection["run_materialization_event_id"],
        "run_materialization_event_hash": projection["run_materialization_event_hash"],
        "bundle_completion_artifact_hash": projection[
            "bundle_completion_artifact_hash"
        ],
        "bundle_completion_record_hash": projection["bundle_completion_record_hash"],
        "bundle_completion_event_id": projection["bundle_completion_event_id"],
        "bundle_completion_event_hash": projection["bundle_completion_event_hash"],
        "bundle_completion_event_index": projection["bundle_completion_event_index"],
        "bundle_statistical_test_id": projection["bundle_statistical_test_id"],
        "source_artifact_hashes": [record.sha256 for record, _content in closure],
        "source_artifact_record_hashes": [
            str(record.record_hash) for record, _content in closure
        ],
        "semantic_judgment_artifact_hash": semantic_judgment_artifact.sha256,
        "semantic_judgment_record_hash": str(semantic_judgment_artifact.record_hash),
    }


def _require_scientific_claim_qualifier_authority_internal(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    authority_artifact_hash: str,
    expected_run_id: str,
) -> ScientificClaimQualifierAuthority:
    validate_sha256(
        authority_artifact_hash,
        "scientific claim-qualifier authority SHA-256",
    )
    _require_run_scoped_authority_paths(
        registry,
        ledger,
        run_id=expected_run_id,
    )
    try:
        registry.verify(authority_artifact_hash, raise_on_error=True)
        artifact = registry.get_metadata(authority_artifact_hash)
        raw = registry.get_bytes(authority_artifact_hash)
        payload = safe_json_loads(
            raw,
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific claim-qualifier authority cannot be reopened"
        ) from exc
    expected_keys = {
        "schema_version",
        "subject_id",
        "accepted_outcome",
        "run_id",
        "evidence_id",
        "evidence_kind",
        "claim_id",
        "claim_text",
        "claim_producer_role",
        "claim_confirmatory",
        "claim_evidence_use",
        "assertion_text",
        "qualifier_projection_sha256",
        "result_id",
        "result_content_hash",
        "result_state_artifact_hash",
        "result_state_record_hash",
        "result_materialization_event_id",
        "result_materialization_event_hash",
        "execution_run_id",
        "run_content_hash",
        "run_state_artifact_hash",
        "run_state_record_hash",
        "run_materialization_event_id",
        "run_materialization_event_hash",
        "bundle_completion_artifact_hash",
        "bundle_completion_record_hash",
        "bundle_completion_event_id",
        "bundle_completion_event_hash",
        "bundle_completion_event_index",
        "bundle_statistical_test_id",
        "source_artifact_hashes",
        "source_artifact_record_hashes",
        "semantic_judgment_artifact_hash",
        "semantic_judgment_record_hash",
    }
    if (
        not isinstance(payload, Mapping)
        or set(payload) != expected_keys
        or payload["schema_version"]
        != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_PAYLOAD_SCHEMA
        or payload["run_id"] != expected_run_id
    ):
        raise ValidationError(
            "scientific claim-qualifier authority schema is incomplete"
        )
    try:
        request = build_scientific_claim_qualifier_judgment_request(
            registry,
            ledger,
            run_id=expected_run_id,
            evidence_id=payload["evidence_id"],
            evidence_kind=GraphEvidenceKind(payload["evidence_kind"]),
            claim_id=payload["claim_id"],
            claim_text=payload["claim_text"],
            claim_producer_role=Role(payload["claim_producer_role"]),
            claim_confirmatory=payload["claim_confirmatory"],
            claim_evidence_use=ClaimEvidenceUse(payload["claim_evidence_use"]),
            assertion_text=payload["assertion_text"],
            result_state_artifact_hash=payload["result_state_artifact_hash"],
        )
    except (KeyError, TypeError, ValueError) as exc:
        raise ValidationError(
            "scientific claim-qualifier authority fields are malformed"
        ) from exc
    source = _resolve_scientific_claim_qualifier_source(
        registry,
        ledger,
        run_id=expected_run_id,
        result_state_artifact_hash=payload["result_state_artifact_hash"],
    )
    judgment_record = registry.get_metadata(payload["semantic_judgment_artifact_hash"])
    selected = _require_unique_scientific_claim_qualifier_judgment(
        registry,
        ledger,
        run_id=expected_run_id,
        request=request,
        selected_artifact_hash=judgment_record.sha256,
    )
    expected_payload = _scientific_claim_qualifier_authority_payload(
        request=request,
        source=source,
        semantic_judgment_artifact=judgment_record,
    )
    expected_origin = (
        "audited scientific claim qualifier "
        f"{payload['claim_id']}:{payload['evidence_kind']}"
    )
    if (
        artifact.logical_type != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_LOGICAL_TYPE
        or artifact.creator_role is not Role.SCIENTIFIC_REVIEWER
        or artifact.schema_version
        != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_SCHEMA_VERSION
        or artifact.mime_type != "application/json"
        or artifact.origin != expected_origin
        or artifact.creation_command
        != ("scientist-one", "record-scientific-claim-qualifier")
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or artifact.created_at != judgment_record.created_at
        or artifact.parent_artifacts
        != (
            source.result_artifact.sha256,
            source.run_artifact.sha256,
            judgment_record.sha256,
        )
        or payload != expected_payload
        or raw != canonical_json_bytes(expected_payload) + b"\n"
        or selected.outcome != request.accepted_outcome
    ):
        raise ValidationError(
            "scientific claim-qualifier authority metadata or sources differ"
        )
    return ScientificClaimQualifierAuthority(
        run_id=payload["run_id"],
        subject_id=payload["subject_id"],
        evidence_id=payload["evidence_id"],
        evidence_kind=GraphEvidenceKind(payload["evidence_kind"]),
        claim_id=payload["claim_id"],
        claim_text=payload["claim_text"],
        claim_producer_role=Role(payload["claim_producer_role"]),
        claim_confirmatory=payload["claim_confirmatory"],
        claim_evidence_use=ClaimEvidenceUse(payload["claim_evidence_use"]),
        assertion_text=payload["assertion_text"],
        qualifier_projection_sha256=payload["qualifier_projection_sha256"],
        result_id=payload["result_id"],
        result_content_hash=payload["result_content_hash"],
        result_state_artifact_hash=payload["result_state_artifact_hash"],
        result_state_record_hash=payload["result_state_record_hash"],
        result_materialization_event_id=payload["result_materialization_event_id"],
        result_materialization_event_hash=payload["result_materialization_event_hash"],
        execution_run_id=payload["execution_run_id"],
        run_content_hash=payload["run_content_hash"],
        run_state_artifact_hash=payload["run_state_artifact_hash"],
        run_state_record_hash=payload["run_state_record_hash"],
        run_materialization_event_id=payload["run_materialization_event_id"],
        run_materialization_event_hash=payload["run_materialization_event_hash"],
        bundle_completion_artifact_hash=payload["bundle_completion_artifact_hash"],
        bundle_completion_record_hash=payload["bundle_completion_record_hash"],
        bundle_completion_event_id=payload["bundle_completion_event_id"],
        bundle_completion_event_hash=payload["bundle_completion_event_hash"],
        bundle_completion_event_index=payload["bundle_completion_event_index"],
        bundle_statistical_test_id=payload["bundle_statistical_test_id"],
        source_artifact_hashes=tuple(payload["source_artifact_hashes"]),
        source_artifact_record_hashes=tuple(payload["source_artifact_record_hashes"]),
        semantic_judgment_artifact_hash=payload["semantic_judgment_artifact_hash"],
        semantic_judgment_record_hash=payload["semantic_judgment_record_hash"],
        authority_artifact_hash=artifact.sha256,
        authority_record_hash=str(artifact.record_hash),
    )


def _claim_qualifier_authority_branch(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    authority: ScientificClaimQualifierAuthority,
) -> tuple[ArtifactRecord, ...]:
    matching: list[ArtifactRecord] = []
    for artifact in registry.list_records():
        if artifact.logical_type != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_LOGICAL_TYPE:
            continue
        try:
            candidate = _require_scientific_claim_qualifier_authority_internal(
                registry,
                ledger,
                authority_artifact_hash=artifact.sha256,
                expected_run_id=authority.run_id,
            )
        except (ArtifactError, ValidationError):
            continue
        if candidate.subject_id == authority.subject_id:
            matching.append(artifact)
    return tuple(matching)


def require_scientific_claim_qualifier_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    authority_artifact_hash: str,
    expected_run_id: str,
    expected_evidence_id: str | None = None,
    expected_evidence_kind: GraphEvidenceKind | None = None,
    expected_claim_id: str | None = None,
    expected_claim_text: str | None = None,
    expected_claim_producer_role: Role | None = None,
    expected_claim_confirmatory: bool | None = None,
    expected_claim_evidence_use: ClaimEvidenceUse | None = None,
    expected_assertion_text: str | None = None,
    expected_result_state_artifact_hash: str | None = None,
) -> ScientificClaimQualifierAuthority:
    """Freshly replay one exact audited qualifier and its unique branch."""

    authority = _require_scientific_claim_qualifier_authority_internal(
        registry,
        ledger,
        authority_artifact_hash=authority_artifact_hash,
        expected_run_id=expected_run_id,
    )
    if (
        (
            expected_evidence_id is not None
            and authority.evidence_id != expected_evidence_id
        )
        or (
            expected_evidence_kind is not None
            and authority.evidence_kind is not expected_evidence_kind
        )
        or (expected_claim_id is not None and authority.claim_id != expected_claim_id)
        or (
            expected_claim_text is not None
            and authority.claim_text != expected_claim_text
        )
        or (
            expected_claim_producer_role is not None
            and authority.claim_producer_role is not expected_claim_producer_role
        )
        or (
            expected_claim_confirmatory is not None
            and authority.claim_confirmatory is not expected_claim_confirmatory
        )
        or (
            expected_claim_evidence_use is not None
            and authority.claim_evidence_use is not expected_claim_evidence_use
        )
        or (
            expected_assertion_text is not None
            and authority.assertion_text != expected_assertion_text
        )
        or (
            expected_result_state_artifact_hash is not None
            and authority.result_state_artifact_hash
            != expected_result_state_artifact_hash
        )
    ):
        raise ValidationError(
            "scientific claim-qualifier authority identity was substituted"
        )
    branch = _claim_qualifier_authority_branch(
        registry,
        ledger,
        authority=authority,
    )
    if len(branch) != 1 or branch[0].sha256 != authority_artifact_hash:
        raise ValidationError(
            "scientific claim-qualifier authority branch is ambiguous"
        )
    return authority


def register_scientific_claim_qualifier_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    evidence_id: str,
    evidence_kind: GraphEvidenceKind,
    claim_id: str,
    claim_text: str,
    claim_producer_role: Role,
    claim_confirmatory: bool,
    claim_evidence_use: ClaimEvidenceUse,
    assertion_text: str,
    result_state_artifact_hash: str,
    semantic_judgment_artifact_hash: str,
) -> ArtifactRecord:
    """Atomically retain one reviewed qualifier after complete preflight."""

    request = build_scientific_claim_qualifier_judgment_request(
        registry,
        ledger,
        run_id=run_id,
        evidence_id=evidence_id,
        evidence_kind=evidence_kind,
        claim_id=claim_id,
        claim_text=claim_text,
        claim_producer_role=claim_producer_role,
        claim_confirmatory=claim_confirmatory,
        claim_evidence_use=claim_evidence_use,
        assertion_text=assertion_text,
        result_state_artifact_hash=result_state_artifact_hash,
    )
    source = _resolve_scientific_claim_qualifier_source(
        registry,
        ledger,
        run_id=run_id,
        result_state_artifact_hash=result_state_artifact_hash,
    )
    judgment_record = registry.get_metadata(semantic_judgment_artifact_hash)
    _require_unique_scientific_claim_qualifier_judgment(
        registry,
        ledger,
        run_id=run_id,
        request=request,
        selected_artifact_hash=judgment_record.sha256,
    )
    payload = _scientific_claim_qualifier_authority_payload(
        request=request,
        source=source,
        semantic_judgment_artifact=judgment_record,
    )
    expected_sha256 = sha256_bytes(canonical_json_bytes(payload) + b"\n")
    expected_origin = (
        f"audited scientific claim qualifier {claim_id}:{evidence_kind.value}"
    )
    existing_exact: ArtifactRecord | None = None
    for artifact in registry.list_records():
        if artifact.sha256 == expected_sha256:
            if (
                artifact.logical_type
                != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_LOGICAL_TYPE
                or artifact.creator_role is not Role.SCIENTIFIC_REVIEWER
                or artifact.schema_version
                != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_SCHEMA_VERSION
                or artifact.mime_type != "application/json"
                or artifact.origin != expected_origin
                or artifact.creation_command
                != ("scientist-one", "record-scientific-claim-qualifier")
                or artifact.validation_result != "PASS"
                or artifact.frozen is not True
                or artifact.created_at != judgment_record.created_at
                or artifact.parent_artifacts
                != (
                    source.result_artifact.sha256,
                    source.run_artifact.sha256,
                    judgment_record.sha256,
                )
            ):
                raise ValidationError(
                    "claim-qualifier content identity has conflicting metadata"
                )
            existing_exact = artifact
    if existing_exact is not None:
        require_scientific_claim_qualifier_authority(
            registry,
            ledger,
            authority_artifact_hash=existing_exact.sha256,
            expected_run_id=run_id,
            expected_evidence_id=evidence_id,
            expected_evidence_kind=evidence_kind,
            expected_claim_id=claim_id,
            expected_claim_text=claim_text,
            expected_claim_producer_role=claim_producer_role,
            expected_claim_confirmatory=claim_confirmatory,
            expected_claim_evidence_use=claim_evidence_use,
            expected_assertion_text=assertion_text,
            expected_result_state_artifact_hash=result_state_artifact_hash,
        )
        return existing_exact
    if len(registry.list_records()) >= MAX_REGISTRY_RECORDS:
        raise ValidationError(
            "artifact registry has no capacity for claim-qualifier authority"
        )
    # Before the only write, reject any already-valid coarse-slot authority.
    for artifact in registry.list_records():
        if artifact.logical_type != SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_LOGICAL_TYPE:
            continue
        try:
            candidate = _require_scientific_claim_qualifier_authority_internal(
                registry,
                ledger,
                authority_artifact_hash=artifact.sha256,
                expected_run_id=run_id,
            )
        except (ArtifactError, ValidationError):
            continue
        if candidate.subject_id == request.subject_id:
            raise ValidationError(
                "scientific claim-qualifier authority branch already exists"
            )
    artifact = registry.put_json(
        payload,
        logical_type=SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_LOGICAL_TYPE,
        origin=expected_origin,
        creator_role=Role.SCIENTIFIC_REVIEWER,
        creation_command=("scientist-one", "record-scientific-claim-qualifier"),
        parent_artifacts=(
            source.result_artifact.sha256,
            source.run_artifact.sha256,
            judgment_record.sha256,
        ),
        schema_version=SCIENTIFIC_CLAIM_QUALIFIER_AUTHORITY_SCHEMA_VERSION,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
        created_at=judgment_record.created_at,
    )
    require_scientific_claim_qualifier_authority(
        registry,
        ledger,
        authority_artifact_hash=artifact.sha256,
        expected_run_id=run_id,
        expected_evidence_id=evidence_id,
        expected_evidence_kind=evidence_kind,
        expected_claim_id=claim_id,
        expected_claim_text=claim_text,
        expected_claim_producer_role=claim_producer_role,
        expected_claim_confirmatory=claim_confirmatory,
        expected_claim_evidence_use=claim_evidence_use,
        expected_assertion_text=assertion_text,
        expected_result_state_artifact_hash=result_state_artifact_hash,
    )
    return artifact


def build_claim_semantics_judgment_request(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    proposal_artifact_hash: str,
    expected_run_id: str,
    reference_support_semantic_judgment_artifact_hash: str | None = None,
) -> ClaimSemanticsJudgmentRequest:
    """Build exact provider inputs for an independently reviewed projection."""

    proposal = require_claim_semantics_proposal(
        registry,
        ledger,
        proposal_artifact_hash=proposal_artifact_hash,
        expected_run_id=expected_run_id,
    )
    graph_record, _ = _resolve_claim_semantics_graph(
        registry,
        proposal.claim_graph_artifact_hash,
        proposal.claim_id,
    )
    if reference_support_semantic_judgment_artifact_hash is not None:
        validate_sha256(
            reference_support_semantic_judgment_artifact_hash,
            "claim-semantics reference-support judgment SHA-256",
        )
    _require_scientific_claim_semantics_sources(
        registry,
        ledger,
        run_id=expected_run_id,
        graph_artifact_hash=graph_record.sha256,
        claim_id=proposal.claim_id,
        dependency_claim_ids=proposal.dependency_claim_ids,
        claim_semantics_proposal_artifact_hash=proposal_artifact_hash,
        reference_support_semantic_judgment_artifact_hash=(
            reference_support_semantic_judgment_artifact_hash
        ),
    )
    try:
        graph_payload = safe_json_loads(
            registry.get_bytes(graph_record.sha256),
            max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
        )
    except Exception as exc:
        raise ValidationError(
            "claim-semantics judgment graph input cannot be retained"
        ) from exc
    closure_roots = (
        graph_record.sha256,
        *(
            (reference_support_semantic_judgment_artifact_hash,)
            if reference_support_semantic_judgment_artifact_hash is not None
            else ()
        ),
        *(item.state_artifact_hash for item in proposal.dependency_bindings),
    )
    source_closure = tuple(
        item
        for item in _claim_semantics_source_closure(registry, closure_roots)
        if item[0].sha256 != proposal_artifact_hash
    )
    retained_sources = [
        _claim_semantics_retained_source(record, content)
        for record, content in source_closure
    ]
    accepted_outcome = f"CLAIM_SEMANTICS_ACCEPTED:{proposal_artifact_hash}"
    input_payload = {
        "schema_version": "claim-semantics-judgment-input/v1",
        "subject_kind": "CLAIM_SEMANTICS",
        "subject_id": proposal.claim_id,
        "accepted_outcome": accepted_outcome,
        "claim_graph_artifact_hash": graph_record.sha256,
        "claim_graph_artifact_record_hash": str(graph_record.record_hash),
        "claim_graph_evidence_closure_hashes": list(graph_record.parent_artifacts),
        "claim_graph": graph_payload,
        "source_artifact_closure_hashes": [
            record.sha256 for record, _ in source_closure
        ],
        "source_artifacts": retained_sources,
        "proposal_artifact_hash": proposal_artifact_hash,
        "proposal": proposal.to_dict(),
    }
    output_schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "subject_kind": {
                "type": "string",
                "enum": ["CLAIM_SEMANTICS"],
            },
            "subject_id": {
                "type": "string",
                "enum": [proposal.claim_id],
            },
            "outcome": {
                "type": "string",
                "enum": [accepted_outcome, "CLAIM_SEMANTICS_REJECTED"],
            },
            "rationale": {
                "type": "string",
                "minLength": 1,
                "maxLength": MAX_SHORT_TEXT_LENGTH,
            },
        },
        "required": ["subject_kind", "subject_id", "outcome", "rationale"],
    }
    return ClaimSemanticsJudgmentRequest(
        subject_id=proposal.claim_id,
        accepted_outcome=accepted_outcome,
        evidence_hashes=tuple(record.sha256 for record, _ in source_closure),
        context_hashes=(proposal_artifact_hash,),
        instructions=CLAIM_SEMANTICS_PROMPT_INSTRUCTIONS,
        input_text=canonical_json_bytes(input_payload).decode("utf-8"),
        output_schema=output_schema,
        prompt_template_id=CLAIM_SEMANTICS_PROMPT_TEMPLATE_ID,
        prompt_template_version=CLAIM_SEMANTICS_PROMPT_TEMPLATE_VERSION,
        prompt_template_hash=sha256_bytes(
            CLAIM_SEMANTICS_PROMPT_INSTRUCTIONS.encode("utf-8")
        ),
        governing_rule=CLAIM_SEMANTICS_GOVERNING_RULE,
    )


def _require_scientific_claim_semantics_judgment(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    proposal_artifact_hash: str,
    reference_support_semantic_judgment_artifact_hash: str | None,
    semantic_authority_artifact_hash: str,
    expected_run_id: str,
    expected_outcome: str | None = None,
) -> tuple[ClaimSemanticsProposal, Any]:
    request = build_claim_semantics_judgment_request(
        registry,
        ledger,
        proposal_artifact_hash=proposal_artifact_hash,
        expected_run_id=expected_run_id,
        reference_support_semantic_judgment_artifact_hash=(
            reference_support_semantic_judgment_artifact_hash
        ),
    )
    resolved_outcome = (
        request.accepted_outcome if expected_outcome is None else expected_outcome
    )
    if resolved_outcome not in {
        request.accepted_outcome,
        "CLAIM_SEMANTICS_REJECTED",
    }:
        raise ValidationError(
            "claim-semantics expected outcome is outside the frozen schema"
        )
    try:
        from .gates import (
            JudgmentSubjectKind,
            SemanticJudgmentReceipt,
            require_scientific_semantic_judgment_receipt,
        )

        judgment = require_scientific_semantic_judgment_receipt(
            registry,
            ledger,
            run_id=expected_run_id,
            receipt_artifact_hash=semantic_authority_artifact_hash,
            subject_kind=JudgmentSubjectKind.CLAIM_SEMANTICS,
            subject_id=request.subject_id,
            outcome=resolved_outcome,
            evidence_hashes=request.evidence_hashes,
            context_hashes=request.context_hashes,
        )
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific claim semantics failed live provider-custody resolution"
        ) from exc
    try:
        instructions = registry.get_bytes(judgment.instructions_artifact_hash)
        judged_input = registry.get_bytes(judgment.input_artifact_hash)
        output_schema = registry.get_bytes(judgment.output_schema_artifact_hash)
    except ArtifactError as exc:
        raise ValidationError(
            "scientific claim-semantics retained provider inputs are absent"
        ) from exc
    if (
        judgment.prompt_template_id != request.prompt_template_id
        or judgment.prompt_template_version != request.prompt_template_version
        or judgment.prompt_template_hash != request.prompt_template_hash
        or judgment.governing_rule != request.governing_rule
        or instructions != request.instructions_bytes
        or judged_input != request.input_bytes
        or output_schema != request.output_schema_bytes
    ):
        raise ValidationError(
            "scientific claim-semantics prompt, input, schema, or rule was substituted"
        )
    matching_judgments: list[str] = []
    for artifact in registry.list_records():
        if (
            artifact.logical_type != "scientific_semantic_judgment_receipt"
            or artifact.creator_role is not Role.SCIENTIFIC_REVIEWER
        ):
            continue
        try:
            payload = safe_json_loads(
                registry.get_bytes(artifact.sha256),
                max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
            )
            if not isinstance(payload, Mapping):
                continue
            candidate = SemanticJudgmentReceipt.from_dict(payload)
        except (ArtifactError, ValidationError):
            continue
        # Outcome is deliberately excluded from the branch key.  A favorable
        # and unfavorable audited review of the same frozen request is an
        # ambiguous branch, not permission to select the favorable hash.
        if (
            candidate.subject_kind is not JudgmentSubjectKind.CLAIM_SEMANTICS
            or candidate.subject_id != request.subject_id
            or candidate.evidence_hashes != request.evidence_hashes
            or candidate.context_hashes != request.context_hashes
            or candidate.prompt_template_id != request.prompt_template_id
            or candidate.prompt_template_version != request.prompt_template_version
            or candidate.prompt_template_hash != request.prompt_template_hash
            or candidate.governing_rule != request.governing_rule
        ):
            continue
        try:
            resolved_candidate = require_scientific_semantic_judgment_receipt(
                registry,
                ledger,
                run_id=expected_run_id,
                receipt_artifact_hash=artifact.sha256,
                subject_kind=JudgmentSubjectKind.CLAIM_SEMANTICS,
                subject_id=request.subject_id,
                outcome=candidate.outcome,
                evidence_hashes=request.evidence_hashes,
                context_hashes=request.context_hashes,
            )
            candidate_instructions = registry.get_bytes(
                resolved_candidate.instructions_artifact_hash
            )
            candidate_input = registry.get_bytes(resolved_candidate.input_artifact_hash)
            candidate_schema = registry.get_bytes(
                resolved_candidate.output_schema_artifact_hash
            )
        except (ArtifactError, ValidationError):
            continue
        if (
            candidate_instructions == request.instructions_bytes
            and candidate_input == request.input_bytes
            and candidate_schema == request.output_schema_bytes
        ):
            matching_judgments.append(artifact.sha256)
    if matching_judgments != [semantic_authority_artifact_hash]:
        raise ValidationError("scientific claim-semantics judgment branch is ambiguous")
    proposal = require_claim_semantics_proposal(
        registry,
        ledger,
        proposal_artifact_hash=proposal_artifact_hash,
        expected_run_id=expected_run_id,
        expected_claim_id=request.subject_id,
    )
    return proposal, judgment


def _require_scientific_claim_semantics_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    proposal_artifact_hash: str,
    reference_support_semantic_judgment_artifact_hash: str,
    semantic_authority_artifact_hash: str,
    expected_run_id: str,
) -> ClaimSemanticsProposal:
    """Preserve the existing positive semantic-authority API."""

    proposal, _judgment = _require_scientific_claim_semantics_judgment(
        registry,
        ledger,
        proposal_artifact_hash=proposal_artifact_hash,
        reference_support_semantic_judgment_artifact_hash=(
            reference_support_semantic_judgment_artifact_hash
        ),
        semantic_authority_artifact_hash=semantic_authority_artifact_hash,
        expected_run_id=expected_run_id,
    )
    return proposal


def register_claim_semantics_receipt(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    receipt_id: str,
    run_id: str,
    claim_graph_artifact_hash: str,
    claim_id: str,
    claim_type: ClaimType,
    scope: str,
    confidence: float,
    expressed_strength: ClaimStrength,
    permitted_strength: ClaimStrength,
    verification_method: str,
    dependency_claim_state_artifact_hashes: tuple[str, ...] = (),
    evidence_scope: ClaimSemanticsEvidenceScope,
    semantic_proposal_artifact_hash: str | None = None,
    reference_support_semantic_judgment_artifact_hash: str | None = None,
    semantic_authority_artifact_hash: str | None = None,
) -> ArtifactRecord:
    """Attest exact fixture or independently reviewed scientific semantics.

    A caller-selected enum or CLAIM_VERIFIER role never grants scientific
    authority.  The positive path requires a retained proposal plus the exact
    claim-specific audited-live semantic judgment constructed by
    :func:`build_claim_semantics_judgment_request`.
    """

    if not isinstance(registry, ArtifactRegistry) or not isinstance(
        ledger, EventLedger
    ):
        raise ValidationError(
            "claim-semantics registration requires registry and ledger"
        )
    if registry.policy.root != ledger.policy.root:
        raise ValidationError("claim-semantics registry and ledger roots differ")
    validate_identifier(receipt_id, "claim-semantics receipt ID")
    validate_identifier(run_id, "claim-semantics run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    evidence_scope = _enum_value(
        evidence_scope,
        ClaimSemanticsEvidenceScope,
        "claim-semantics evidence scope",
    )
    claim_type = _enum_value(
        claim_type,
        ClaimType,
        "claim-semantics claim type",
    )
    expressed_strength = _enum_value(
        expressed_strength,
        ClaimStrength,
        "claim-semantics expressed strength",
    )
    permitted_strength = _enum_value(
        permitted_strength,
        ClaimStrength,
        "claim-semantics permitted strength",
    )
    if evidence_scope is ClaimSemanticsEvidenceScope.NON_EVIDENTIARY_FIXTURE:
        if (
            semantic_proposal_artifact_hash is not None
            or reference_support_semantic_judgment_artifact_hash is not None
            or semantic_authority_artifact_hash is not None
        ):
            raise ValidationError(
                "non-evidentiary claim semantics cannot borrow semantic authority"
            )
    elif (
        semantic_proposal_artifact_hash is None
        or reference_support_semantic_judgment_artifact_hash is None
        or semantic_authority_artifact_hash is None
    ):
        raise ValidationError(
            "scientific claim semantics require a proposal, reference-support "
            "judgment, and audited authority"
        )
    graph_record, graph_claim = _resolve_claim_semantics_graph(
        registry,
        claim_graph_artifact_hash,
        claim_id,
    )
    dependency_hashes = _hash_tuple(
        dependency_claim_state_artifact_hashes,
        "claim-semantics dependency state artifact hashes",
    )
    dependencies = tuple(
        sorted(
            (
                _resolve_claim_semantics_dependency(
                    registry,
                    ledger,
                    run_id=run_id,
                    state_artifact_hash=digest,
                )
                for digest in dependency_hashes
            ),
            key=lambda item: item.claim_id,
        )
    )
    if evidence_scope is ClaimSemanticsEvidenceScope.SCIENTIFIC_EVIDENCE:
        assert semantic_proposal_artifact_hash is not None
        assert reference_support_semantic_judgment_artifact_hash is not None
        assert semantic_authority_artifact_hash is not None
        proposal = _require_scientific_claim_semantics_authority(
            registry,
            ledger,
            proposal_artifact_hash=semantic_proposal_artifact_hash,
            reference_support_semantic_judgment_artifact_hash=(
                reference_support_semantic_judgment_artifact_hash
            ),
            semantic_authority_artifact_hash=semantic_authority_artifact_hash,
            expected_run_id=run_id,
        )
        if (
            proposal.claim_graph_artifact_hash != graph_record.sha256
            or proposal.claim_id != graph_claim.claim_id
            or proposal.claim_type is not claim_type
            or proposal.scope != scope
            or proposal.confidence != float(confidence)
            or proposal.expressed_strength is not expressed_strength
            or proposal.permitted_strength is not permitted_strength
            or proposal.verification_method != verification_method
            or proposal.dependency_bindings != dependencies
        ):
            raise ValidationError(
                "scientific claim-semantics arguments differ from the reviewed proposal"
            )
    receipt = ClaimSemanticsReceipt(
        receipt_id=receipt_id,
        run_id=run_id,
        claim_graph_artifact_hash=graph_record.sha256,
        claim_graph_artifact_record_hash=str(graph_record.record_hash),
        claim_id=graph_claim.claim_id,
        claim_text=graph_claim.text,
        claim_producer_role=graph_claim.producer_role,
        claim_evidence_use=graph_claim.evidence_use,
        claim_type=claim_type,
        scope=scope,
        confidence=confidence,
        expressed_strength=expressed_strength,
        permitted_strength=permitted_strength,
        verification_method=verification_method,
        dependency_bindings=dependencies,
        evidence_scope=evidence_scope,
        semantic_proposal_artifact_hash=semantic_proposal_artifact_hash,
        reference_support_semantic_judgment_artifact_hash=(
            reference_support_semantic_judgment_artifact_hash
        ),
        semantic_authority_artifact_hash=semantic_authority_artifact_hash,
    )
    receipt_origin = (
        "claim-verifier-attested non-evidentiary canonical claim semantics"
        if evidence_scope is ClaimSemanticsEvidenceScope.NON_EVIDENTIARY_FIXTURE
        else "claim-verifier-attested audited-live scientific claim semantics"
    )
    artifact = registry.put_json(
        receipt.to_dict(),
        logical_type=CLAIM_SEMANTICS_RECEIPT_LOGICAL_TYPE,
        origin=receipt_origin,
        creator_role=Role.CLAIM_VERIFIER,
        creation_command=("scientist-one", "record-claim-semantics"),
        parent_artifacts=(
            graph_record.sha256,
            *(item.state_artifact_hash for item in dependencies),
            *(
                (
                    semantic_proposal_artifact_hash,
                    reference_support_semantic_judgment_artifact_hash,
                    semantic_authority_artifact_hash,
                )
                if semantic_proposal_artifact_hash is not None
                and reference_support_semantic_judgment_artifact_hash is not None
                and semantic_authority_artifact_hash is not None
                else ()
            ),
        ),
        schema_version=CLAIM_SEMANTICS_RECEIPT_SCHEMA_VERSION,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
    )
    require_claim_semantics_receipt(
        registry,
        ledger,
        receipt_artifact_hash=artifact.sha256,
        expected_run_id=run_id,
        expected_claim_graph_artifact_hash=graph_record.sha256,
        expected_claim_id=claim_id,
    )
    return artifact


def require_claim_semantics_receipt(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    receipt_artifact_hash: str,
    expected_run_id: str,
    expected_claim_graph_artifact_hash: str | None = None,
    expected_claim_id: str | None = None,
) -> ClaimSemanticsReceipt:
    """Freshly replay one exact non-evidentiary claim-semantics receipt."""

    if not isinstance(registry, ArtifactRegistry) or not isinstance(
        ledger, EventLedger
    ):
        raise ValidationError("claim-semantics replay requires registry and ledger")
    if registry.policy.root != ledger.policy.root:
        raise ValidationError("claim-semantics registry and ledger roots differ")
    validate_sha256(receipt_artifact_hash, "claim-semantics receipt SHA-256")
    validate_identifier(expected_run_id, "expected claim-semantics run ID")
    _require_run_scoped_authority_paths(
        registry,
        ledger,
        run_id=expected_run_id,
    )
    if expected_claim_graph_artifact_hash is not None:
        validate_sha256(
            expected_claim_graph_artifact_hash,
            "expected claim-semantics graph SHA-256",
        )
    if expected_claim_id is not None:
        validate_identifier(expected_claim_id, "expected claim-semantics claim ID")
    try:
        if registry.verify(receipt_artifact_hash, raise_on_error=True) is not True:
            raise ValidationError("claim-semantics receipt is absent or corrupt")
        artifact = registry.get_metadata(receipt_artifact_hash)
        raw = registry.get_bytes(receipt_artifact_hash)
        payload = safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        receipt = ClaimSemanticsReceipt.from_dict(payload)
    except (ArtifactError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "claim-semantics receipt cannot be safely rehydrated"
        ) from exc
    expected_origin = (
        "claim-verifier-attested non-evidentiary canonical claim semantics"
        if receipt.evidence_scope is ClaimSemanticsEvidenceScope.NON_EVIDENTIARY_FIXTURE
        else "claim-verifier-attested audited-live scientific claim semantics"
    )
    if (
        artifact.logical_type != CLAIM_SEMANTICS_RECEIPT_LOGICAL_TYPE
        or artifact.creator_role is not Role.CLAIM_VERIFIER
        or artifact.schema_version != CLAIM_SEMANTICS_RECEIPT_SCHEMA_VERSION
        or artifact.mime_type != "application/json"
        or artifact.origin != expected_origin
        or artifact.creation_command != ("scientist-one", "record-claim-semantics")
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or raw != canonical_json_bytes(receipt.to_dict()) + b"\n"
    ):
        raise ValidationError("claim-semantics receipt metadata grants no authority")
    if (
        receipt.run_id != expected_run_id
        or (
            expected_claim_graph_artifact_hash is not None
            and receipt.claim_graph_artifact_hash != expected_claim_graph_artifact_hash
        )
        or (expected_claim_id is not None and receipt.claim_id != expected_claim_id)
    ):
        raise ValidationError("claim-semantics receipt identity was substituted")
    proposal: ClaimSemanticsProposal | None = None
    if receipt.evidence_scope is ClaimSemanticsEvidenceScope.NON_EVIDENTIARY_FIXTURE:
        if (
            receipt.semantic_proposal_artifact_hash is not None
            or receipt.reference_support_semantic_judgment_artifact_hash is not None
            or receipt.semantic_authority_artifact_hash is not None
            or receipt.scientific_writer_eligible is not False
        ):
            raise ValidationError(
                "non-evidentiary claim semantics borrowed scientific authority"
            )
    else:
        if (
            receipt.semantic_proposal_artifact_hash is None
            or receipt.reference_support_semantic_judgment_artifact_hash is None
            or receipt.semantic_authority_artifact_hash is None
            or receipt.scientific_writer_eligible is not True
        ):
            raise ValidationError(
                "scientific claim semantics lack explicit live authority"
            )
        proposal = _require_scientific_claim_semantics_authority(
            registry,
            ledger,
            proposal_artifact_hash=receipt.semantic_proposal_artifact_hash,
            reference_support_semantic_judgment_artifact_hash=(
                receipt.reference_support_semantic_judgment_artifact_hash
            ),
            semantic_authority_artifact_hash=(receipt.semantic_authority_artifact_hash),
            expected_run_id=expected_run_id,
        )
    graph_record, graph_claim = _resolve_claim_semantics_graph(
        registry,
        receipt.claim_graph_artifact_hash,
        receipt.claim_id,
    )
    dependencies = tuple(
        sorted(
            (
                _resolve_claim_semantics_dependency(
                    registry,
                    ledger,
                    run_id=expected_run_id,
                    state_artifact_hash=item.state_artifact_hash,
                )
                for item in receipt.dependency_bindings
            ),
            key=lambda item: item.claim_id,
        )
    )
    fresh = ClaimSemanticsReceipt(
        receipt_id=receipt.receipt_id,
        run_id=receipt.run_id,
        claim_graph_artifact_hash=graph_record.sha256,
        claim_graph_artifact_record_hash=str(graph_record.record_hash),
        claim_id=graph_claim.claim_id,
        claim_text=graph_claim.text,
        claim_producer_role=graph_claim.producer_role,
        claim_evidence_use=graph_claim.evidence_use,
        claim_type=receipt.claim_type,
        scope=receipt.scope,
        confidence=receipt.confidence,
        expressed_strength=receipt.expressed_strength,
        permitted_strength=receipt.permitted_strength,
        verification_method=receipt.verification_method,
        dependency_bindings=dependencies,
        evidence_scope=receipt.evidence_scope,
        semantic_proposal_artifact_hash=(receipt.semantic_proposal_artifact_hash),
        reference_support_semantic_judgment_artifact_hash=(
            receipt.reference_support_semantic_judgment_artifact_hash
        ),
        semantic_authority_artifact_hash=(receipt.semantic_authority_artifact_hash),
    )
    if proposal is not None and (
        proposal.claim_graph_artifact_hash != fresh.claim_graph_artifact_hash
        or proposal.claim_graph_artifact_record_hash
        != fresh.claim_graph_artifact_record_hash
        or proposal.claim_id != fresh.claim_id
        or proposal.claim_text != fresh.claim_text
        or proposal.claim_producer_role is not fresh.claim_producer_role
        or proposal.claim_evidence_use is not fresh.claim_evidence_use
        or proposal.claim_type is not fresh.claim_type
        or proposal.scope != fresh.scope
        or proposal.confidence != fresh.confidence
        or proposal.expressed_strength is not fresh.expressed_strength
        or proposal.permitted_strength is not fresh.permitted_strength
        or proposal.verification_method != fresh.verification_method
        or proposal.dependency_bindings != fresh.dependency_bindings
    ):
        raise ValidationError(
            "scientific claim semantics differ from the reviewed proposal"
        )
    expected_parents = (
        graph_record.sha256,
        *(item.state_artifact_hash for item in dependencies),
        *(
            (
                receipt.semantic_proposal_artifact_hash,
                receipt.reference_support_semantic_judgment_artifact_hash,
                receipt.semantic_authority_artifact_hash,
            )
            if receipt.semantic_proposal_artifact_hash is not None
            and receipt.reference_support_semantic_judgment_artifact_hash is not None
            and receipt.semantic_authority_artifact_hash is not None
            else ()
        ),
    )
    if (
        fresh.to_dict() != receipt.to_dict()
        or artifact.parent_artifacts != expected_parents
    ):
        raise ValidationError(
            "claim-semantics receipt differs from its exact graph or dependencies"
        )
    return fresh


@dataclass(frozen=True)
class _ResolvedObjectAuthority:
    records: tuple[ArtifactRecord, ...]
    scientific_evidence_eligible: bool = False
    claim_semantics: ClaimSemanticsReceipt | None = None


@dataclass(frozen=True, slots=True)
class _ReplayedCanonicalReview:
    """An exact earlier projection, after its complete static-round owner.

    This is ephemeral reuse within one readback, never an issued authority.
    Canonical custody, currentness and ancestry must still be replayed.
    """

    research_object: CanonicalResearchObject
    artifact: ArtifactRecord
    authority_records: tuple[ArtifactRecord, ...]
    materialization_event_index: int


@dataclass(frozen=True, slots=True)
class _SameRoundReviewReplay:
    """Private, immutable cache of completed earlier semantic projections.

    Only the chronological audit owner may assemble this after full source
    replay.  The paired snapshot binds its lifetime; there is no public flag
    accepting this context and no scientific-eligibility override.
    """

    run_id: str
    code_version: str
    configuration_hash: str
    before_event_index: int
    registry_snapshot: RegistryValidationResult
    ledger_snapshot: LedgerValidationResult
    reviews: tuple[_ReplayedCanonicalReview, ...]

    def __post_init__(self) -> None:
        validate_identifier(self.run_id, "same-round review run ID")
        _bounded_text(self.code_version, "same-round review code version", maximum=512)
        validate_sha256(self.configuration_hash, "same-round review configuration")
        if (
            type(self.registry_snapshot) is not RegistryValidationResult
            or type(self.ledger_snapshot) is not LedgerValidationResult
            or not self.registry_snapshot.valid
            or not self.ledger_snapshot.valid
            or type(self.before_event_index) is not int
            or not 0 < self.before_event_index <= self.ledger_snapshot.event_count
            or type(self.reviews) is not tuple
            or len(self.reviews) > MAX_SEQUENCE_ITEMS
        ):
            raise ValidationError("same-round review replay context is malformed")
        hashes: set[str] = set()
        for review in self.reviews:
            if (
                type(review) is not _ReplayedCanonicalReview
                or type(review.research_object) not in {Challenge, Critique, Decision, VenueAssessment}
                or type(review.artifact) is not ArtifactRecord
                or review.research_object.revision != 1
                or review.research_object.supersedes_content_hash is not None
                or type(review.authority_records) is not tuple
                or not review.authority_records
                or any(type(item) is not ArtifactRecord for item in review.authority_records)
                or tuple(item.sha256 for item in review.authority_records)
                != review.research_object.authority_artifact_hashes
                or type(review.materialization_event_index) is not int
                or not 0 <= review.materialization_event_index < self.before_event_index
                or review.artifact.sha256 in hashes
            ):
                raise ValidationError("same-round review reuse is not an exact earlier review")
            hashes.add(review.artifact.sha256)


def _require_same_round_review_snapshot(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    replay: _SameRoundReviewReplay,
    run_id: str,
) -> None:
    if type(replay) is not _SameRoundReviewReplay or replay.run_id != run_id:
        raise ValidationError("same-round review replay run was substituted")
    current = _locked_research_state_source_snapshot(registry, ledger, run_id=run_id)
    if current != (replay.registry_snapshot, replay.ledger_snapshot):
        raise ValidationError("same-round review sources changed during replay")


def _resolve_object_with_replayed_review(
    repository: ResearchStateRepository,
    item: _StoredObject,
    by_content: Mapping[str, _StoredObject],
    *,
    replay: _SameRoundReviewReplay | None,
) -> _ResolvedObjectAuthority:
    """Reuse only an exact completed review; every other object keeps its owner."""

    review = next(
        (entry for entry in replay.reviews if entry.artifact.sha256 == item.artifact.sha256),
        None,
    ) if replay is not None else None
    if review is None:
        return repository._resolve_object_authority(item.research_object, by_content)
    record = item.research_object
    if (
        repository.run_id != replay.run_id
        or repository.code_version != replay.code_version
        or repository.configuration_hash != replay.configuration_hash
        or record != review.research_object
        or item.artifact != review.artifact
    ):
        raise ValidationError("replayed canonical review identity changed")
    repository._validate_canonical_ancestry_budget(record, by_content)
    authority_records = repository._authority_records(record)
    if authority_records != review.authority_records:
        raise ValidationError("replayed canonical review authority records changed")
    matches = _matching_scoped_materialization_events(
        repository, item, replay.ledger_snapshot.events,
    )
    if (
        len(matches) != 1
        or matches[0] != replay.ledger_snapshot.events[review.materialization_event_index]
    ):
        raise ValidationError("replayed canonical review chronology changed")
    # Every admitted review owner returns the default mechanical scope.
    return _ResolvedObjectAuthority(authority_records)


