@dataclass(frozen=True)
class _StoredObject:
    research_object: CanonicalResearchObject
    artifact: ArtifactRecord


class ResearchStateRepository:
    """Materialize and validate research state using existing authorities only."""

    def __init__(
        self,
        registry: ArtifactRegistry,
        ledger: EventLedger,
        *,
        run_id: str,
        code_version: str,
        configuration_hash: str,
        state: State = MacroState.GROUND,
        creation_command: tuple[str, ...] = (
            "scientist-one",
            "research-state",
            "materialize",
        ),
    ) -> None:
        if not isinstance(registry, ArtifactRegistry) or not isinstance(
            ledger, EventLedger
        ):
            raise ValidationError(
                "research-state repository requires the existing registry and ledger"
            )
        if registry.policy.root != ledger.policy.root:
            raise ValidationError(
                "research-state registry and ledger must share a project root"
            )
        validate_identifier(run_id, "research-state run ID")
        _bounded_text(code_version, "repository code version", maximum=512)
        validate_sha256(configuration_hash, "repository configuration SHA-256")
        if not isinstance(creation_command, tuple) or not creation_command:
            raise ValidationError(
                "research-state creation command must be a non-empty argv tuple"
            )
        for item in creation_command:
            _bounded_text(item, "research-state creation argv", maximum=512)
            if "\n" in item or "\r" in item:
                raise ValidationError("research-state creation argv must be inert")
        self.registry = registry
        self.ledger = ledger
        self.run_id = run_id
        self.code_version = code_version
        self.configuration_hash = configuration_hash
        self.state = parse_state(state)
        self.creation_command = creation_command

    def load_artifact(self, artifact_hash: str) -> CanonicalResearchObject:
        validate_sha256(artifact_hash, "research-state artifact SHA-256")
        artifact = self.registry.get_metadata(artifact_hash)
        if not artifact.logical_type.startswith("research_state."):
            raise ValidationError("artifact is not canonical research state")
        if artifact.validation_result != "PASS" or artifact.frozen is not True:
            raise ValidationError("canonical research state must be frozen PASS data")
        if artifact.mime_type != "application/json":
            raise ValidationError("research-state artifact must be JSON")
        raw = self.registry.get_bytes(artifact_hash)
        if len(raw) > MAX_CANONICAL_OBJECT_BYTES + 1:
            raise ValidationError("research-state artifact exceeds byte limit")
        value = safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        record = CanonicalResearchObject.from_dict(value)
        if record.logical_type != artifact.logical_type:
            raise ValidationError(
                "research-state logical type does not match artifact metadata"
            )
        if record.schema_version != artifact.schema_version:
            raise ValidationError(
                "research-state schema version does not match artifact metadata"
            )
        if record.schema_version != RESEARCH_STATE_SCHEMA_VERSION:
            raise ValidationError("unsupported canonical research-state schema version")
        if record.producer is not artifact.creator_role:
            raise ValidationError(
                "research-state producer does not match artifact metadata"
            )
        if record.created_at != artifact.created_at:
            raise ValidationError(
                "research-state timestamp does not match artifact metadata"
            )
        if record.canonical_bytes() != raw:
            raise ValidationError("research-state artifact is not canonical")
        return record

    def _stored_objects(self) -> tuple[_StoredObject, ...]:
        result: list[_StoredObject] = []
        for artifact in self.registry.list_records():
            if not artifact.logical_type.startswith("research_state."):
                continue
            result.append(_StoredObject(self.load_artifact(artifact.sha256), artifact))
        return tuple(
            sorted(
                result,
                key=lambda item: (
                    item.research_object.object_type,
                    item.research_object.object_id,
                    item.research_object.revision,
                    item.research_object.content_hash,
                ),
            )
        )

    def _preflight_repository_identity(
        self,
        *,
        stored: tuple[_StoredObject, ...] | None = None,
        ledger_result: LedgerValidationResult | None = None,
    ) -> tuple[_StoredObject, ...]:
        """Reject a mixed canonical-state writer before its first write.

        An interrupted append may leave the exact immutable artifact without
        its deterministic ledger event.  Such an orphan remains retryable, but
        every retained artifact and every event that is present must agree with
        this repository's writer identity.
        """

        _require_run_scoped_authority_paths(
            self.registry,
            self.ledger,
            run_id=self.run_id,
        )
        validated_ledger = (
            self.ledger.validate(raise_on_error=True)
            if ledger_result is None
            else ledger_result
        )
        if validated_ledger.events:
            current_event = validated_ledger.events[-1]
            if (
                current_event.run_id != self.run_id
                or current_event.configuration_hash != self.configuration_hash
                or current_event.requested_state_after != self.state
            ):
                raise ValidationError(
                    "canonical state belongs to another repository identity"
                )

        current = self._stored_objects() if stored is None else stored
        _current_by_content, current_by_identity = self._indexes(current)
        event_indices = {
            event.event_id: index for index, event in enumerate(validated_ledger.events)
        }
        for item in current:
            record = item.research_object
            artifact = item.artifact
            if artifact.creation_command != self.creation_command:
                raise ValidationError(
                    "canonical state belongs to another repository creation command"
                )
            if (
                record.code_version is not None
                and record.code_version != self.code_version
            ):
                raise ValidationError(
                    "canonical state belongs to another repository code version"
                )
            try:
                materialization_event = self._materialization_event(
                    artifact.sha256,
                    record,
                    events=validated_ledger.events,
                )
            except LedgerError as exc:
                raise ValidationError(
                    "canonical state belongs to another repository identity"
                ) from exc
            if materialization_event is not None:
                materialization_index = event_indices[materialization_event.event_id]
                successor = next(
                    (
                        candidate
                        for candidate in current_by_identity[
                            (record.object_type, record.object_id)
                        ]
                        if candidate.research_object.revision == record.revision + 1
                    ),
                    None,
                )
                allowed_correction_id = (
                    f"rs-{successor.artifact.sha256[:48]}"
                    if successor is not None
                    else None
                )
                if any(
                    event.event_type == "CORRECTION"
                    and event.supersedes_event_id == materialization_event.event_id
                    and event.event_id != allowed_correction_id
                    for event in validated_ledger.events[materialization_index + 1 :]
                ):
                    raise ValidationError(
                        "canonical state contains a non-lineage correction"
                    )
        return current

    def _ensure_ledger_file_for_atomic_commit(
        self,
        expected: LedgerValidationResult,
    ) -> None:
        """Create an empty ledger file before taking the registry parent lock.

        The registry namespace guard pins the shared run-directory metadata.
        Creating the ledger data file while that guard is held would correctly
        look like an out-of-band namespace change.  Establishing an empty,
        private ledger under its own lock first avoids that false conflict;
        the later dual-lock recheck still requires the exact expected bytes.
        """

        if expected.events:
            return
        guard = self.ledger._open_lock()
        descriptor: int | None = None
        try:
            descriptor = self.ledger._open_ledger_fd(
                guard,
                writable=True,
                create=True,
            )
            if descriptor is None:  # pragma: no cover - create=True is exhaustive
                raise LedgerError("research-state ledger cannot be initialized")
            current = self.ledger._validate_bytes(
                self.ledger._read_ledger_fd(descriptor)
            )
            if not current.valid or current != expected:
                raise ValidationError(
                    "canonical-state ledger changed before initialization"
                )
            os.fsync(descriptor)
            os.fsync(self.ledger._ledger_parent_fd(guard))
            self.ledger._verify_ledger_fd(guard, descriptor)
        finally:
            if descriptor is not None:
                os.close(descriptor)
            self.ledger._unlock(guard)

    @staticmethod
    def _indexes(
        stored: tuple[_StoredObject, ...],
    ) -> tuple[
        dict[str, _StoredObject],
        dict[tuple[str, str], list[_StoredObject]],
    ]:
        by_content: dict[str, _StoredObject] = {}
        by_identity: dict[tuple[str, str], list[_StoredObject]] = {}
        for item in stored:
            content_hash = item.research_object.content_hash
            if content_hash in by_content:
                raise ValidationError("duplicate research object content hash")
            by_content[content_hash] = item
            by_identity.setdefault(
                (item.research_object.object_type, item.research_object.object_id), []
            ).append(item)
        return by_content, by_identity

    @staticmethod
    def _embedded_artifact_hashes(record: CanonicalResearchObject) -> tuple[str, ...]:
        result: set[str] = set()
        for item in fields(record):
            name = item.name
            value = getattr(record, name)
            if name.endswith("_artifact_hash") and value:
                validate_sha256(value, f"{name} SHA-256")
                result.add(value)
            elif name.endswith("_artifact_hashes") or name == "source_artifact_ids":
                for digest in value:
                    validate_sha256(digest, f"{name} SHA-256")
                    result.add(digest)
        if isinstance(record, Critique):
            result.update(record.reviewer_input_hashes)
        if isinstance(record, Claim):
            for review in record.review_history:
                result.update(review.source_artifact_ids)
        return tuple(sorted(result))

    def _require_frozen_pass_artifact(
        self,
        digest: str,
        *,
        logical_type: str | None = None,
        creator_role: Role | None = None,
    ) -> ArtifactRecord:
        """Resolve exact registry metadata rather than trusting a SHA-shaped value."""

        if self.registry.verify(digest, raise_on_error=True) is not True:
            raise ValidationError("registry did not verify a claimed source artifact")
        artifact = self.registry.get_metadata(digest)
        if artifact.validation_result != "PASS" or artifact.frozen is not True:
            raise ValidationError(
                "verified research state requires frozen PASS sources"
            )
        if logical_type is not None and artifact.logical_type != logical_type:
            raise ValidationError("registry source has the wrong logical type")
        if creator_role is not None and artifact.creator_role is not creator_role:
            raise AuthorizationError("registry source has the wrong producer authority")
        return artifact

    def _read_authority_json(
        self,
        artifact: ArtifactRecord,
        *,
        require_canonical: bool = True,
    ) -> Mapping[str, Any]:
        """Read one already-resolved structured authority without trusting labels."""

        if artifact.mime_type != "application/json":
            raise ValidationError("structured research-state authority must be JSON")
        raw = self.registry.get_bytes(artifact.sha256)
        try:
            value = safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        except Exception as exc:
            raise ValidationError(
                "research-state authority payload is invalid JSON"
            ) from exc
        if not isinstance(value, Mapping):
            raise ValidationError("research-state authority payload must be an object")
        if require_canonical and raw != canonical_json_bytes(value) + b"\n":
            raise ValidationError(
                "research-state authority payload is not canonical JSON"
            )
        return value

    def _replay_execution_input_binding(
        self,
        artifact: ArtifactRecord,
        *,
        spec_artifact_sha256: str,
        spec_sha256: str,
        spec_value: Mapping[str, Any],
    ) -> None:
        """Replay the exact source-owned bytes staged for local execution."""

        value = self._read_authority_json(artifact)
        if (
            artifact.logical_type != "execution_input_binding"
            or artifact.origin != "exact local execution input-byte binding"
            or artifact.creator_role is not Role.EXPERIMENT_RUNNER
            or artifact.creation_command
            != (
                "scientist-one",
                "research-os-fixture",
                "capture-execution-input-binding",
            )
            or artifact.parent_artifacts != (spec_artifact_sha256,)
            or artifact.schema_version != "1.0"
            or artifact.mime_type != "application/json"
            or artifact.validation_result != "PASS"
            or artifact.frozen is not True
            or set(value)
            != {
                "schema_version",
                "spec_sha256",
                "inputs",
                "consumption",
                "scientific_evidence",
            }
            or value.get("schema_version")
            != "SCIENTIST_ONE_LOCAL_MAC_EXECUTION_INPUT_BINDING_V1"
            or value.get("spec_sha256") != spec_sha256
            or value.get("consumption") != "PARENT_HELD_READ_DESCRIPTORS"
            or value.get("scientific_evidence") is not False
            or not isinstance(value.get("inputs"), list)
        ):
            raise ValidationError("run execution input binding custody is not exact")
        expected_inputs = (
            ("code", spec_value.get("code_sha256"), ".py"),
            ("data", spec_value.get("data_sha256"), ".bin"),
            (
                "configuration",
                spec_value.get("configuration_sha256"),
                ".bin",
            ),
            ("evaluator", spec_value.get("evaluator_sha256"), ".bin"),
        )
        observed_inputs = value["inputs"]
        if len(observed_inputs) != len(expected_inputs):
            raise ValidationError("run execution input binding count is not exact")
        for observed, (kind, digest, suffix) in zip(observed_inputs, expected_inputs):
            if not isinstance(digest, str):
                raise ValidationError(
                    "run frozen spec omits an execution input identity"
                )
            try:
                frozen_bytes = self.registry.get_bytes(digest)
            except Exception as exc:
                raise ValidationError(
                    "run execution input binding cannot reopen its frozen input"
                ) from exc
            if (
                not isinstance(observed, Mapping)
                or set(observed) != {"kind", "sha256", "size", "staged_name"}
                or observed.get("kind") != kind
                or observed.get("sha256") != digest
                or isinstance(observed.get("size"), bool)
                or observed.get("size") != len(frozen_bytes)
                or observed.get("staged_name") != f"frozen-input-{kind}{suffix}"
            ):
                raise ValidationError(
                    "run execution input binding differs from the frozen run spec"
                )

    def _replay_adaptive_execution_plan_binding(
        self,
        artifact: ArtifactRecord,
        value: Mapping[str, Any],
        *,
        run_id: str,
        spec_artifact_sha256: str,
        spec_sha256: str,
        execution_plan_artifact_sha256: str,
        execution_plan_sha256: str,
        execution_input_binding_sha256: str,
        manifest_artifact_sha256: str,
        returned_artifact_sha256s: tuple[str, ...],
    ) -> None:
        """Recompute the exact local execution-plan custody assertion."""

        run_token = sha256_bytes(self.run_id.encode("utf-8"))[:20]
        expected_idempotency_key = {
            f"autonomous-{run_token}": f"autonomous-{run_token}",
            f"exp-{run_token}": f"submit-{run_token}",
            f"repro-{run_token}": f"reproduce-{run_token}",
        }.get(run_id)
        if expected_idempotency_key is None:
            raise ValidationError(
                "run adaptive execution plan custody identity is unsupported"
            )
        expected = {
            "agreement": True,
            "backend_id": "local-mac",
            "collected_backend_id": "local-mac",
            "collected_execution_plan_sha256": execution_plan_sha256,
            "collected_execution_input_binding_sha256": (
                execution_input_binding_sha256
            ),
            "collected_manifest_sha256": manifest_artifact_sha256,
            "collected_network_isolation_attested": False,
            "collected_network_used": False,
            "collected_returned_artifact_sha256s": list(returned_artifact_sha256s),
            "collected_scientific_evidence": False,
            "collected_spec_sha256": spec_sha256,
            "collected_validation_status": "VALIDATED_LOCAL",
            "execution_plan_artifact_sha256": execution_plan_artifact_sha256,
            "execution_plan_sha256": execution_plan_sha256,
            "execution_input_binding_artifact_sha256": (execution_input_binding_sha256),
            "execution_input_binding_sha256": execution_input_binding_sha256,
            "job_id": f"local-{spec_sha256[:20]}",
            "run_id": run_id,
            "spec_artifact_sha256": spec_artifact_sha256,
            "spec_sha256": spec_sha256,
            "submission_backend_id": "local-mac",
            "submission_execution_plan_sha256": execution_plan_sha256,
            "submission_execution_input_binding_sha256": (
                execution_input_binding_sha256
            ),
            "submission_idempotency_key": expected_idempotency_key,
            "submission_network_isolation_attested": False,
            "submission_network_used": False,
            "submission_scientific_evidence": False,
            "submission_spec_sha256": spec_sha256,
            "submission_state": "SUCCEEDED",
            "submission_validation_status": "VALIDATED_LOCAL",
        }
        if (
            artifact.logical_type != "adaptive_execution_plan_binding"
            or artifact.origin
            != f"exact backend execution-plan custody binding for {run_id}"
            or artifact.creator_role is not Role.EXPERIMENT_RUNNER
            or artifact.creation_command
            != (
                "scientist-one",
                "research-os-fixture",
                "bind-adaptive-execution-plan",
            )
            or artifact.parent_artifacts
            != (
                execution_plan_artifact_sha256,
                execution_input_binding_sha256,
                spec_artifact_sha256,
            )
            or artifact.schema_version != "1.0"
            or artifact.mime_type != "application/json"
            or artifact.validation_result != "PASS"
            or artifact.frozen is not True
            or dict(value) != expected
        ):
            raise ValidationError(
                "run adaptive execution plan custody binding is not exact"
            )
        try:
            validate_identifier(value["job_id"], "backend job ID")
            validate_identifier(
                value["submission_idempotency_key"],
                "submission idempotency key",
            )
        except ValidationError as exc:
            raise ValidationError(
                "run adaptive execution plan custody identity is invalid"
            ) from exc

    @staticmethod
    def _nested_mapping(value: Mapping[str, Any], *path: str) -> Mapping[str, Any]:
        current: Any = value
        for key in path:
            if not isinstance(current, Mapping) or not isinstance(
                current.get(key), Mapping
            ):
                raise ValidationError(
                    "research-state authority payload lacks the expected typed object"
                )
            current = current[key]
        return current

    @staticmethod
    def _nested_sequence(value: Mapping[str, Any], *path: str) -> tuple[Any, ...]:
        current: Any = value
        for key in path:
            if not isinstance(current, Mapping):
                raise ValidationError(
                    "research-state authority payload lacks the expected sequence"
                )
            current = current.get(key)
        if not isinstance(current, (list, tuple)):
            raise ValidationError(
                "research-state authority payload lacks the expected sequence"
            )
        return tuple(current)

    @staticmethod
    def _one_record(
        records: tuple[ArtifactRecord, ...],
        logical_type: str,
    ) -> ArtifactRecord:
        matches = tuple(item for item in records if item.logical_type == logical_type)
        if len(matches) != 1:
            raise ValidationError(
                f"canonical state requires one exact {logical_type} authority"
            )
        return matches[0]

    @staticmethod
    def _records_of_types(
        records: tuple[ArtifactRecord, ...],
        logical_types: frozenset[str],
    ) -> tuple[ArtifactRecord, ...]:
        return tuple(item for item in records if item.logical_type in logical_types)

    @staticmethod
    def _resolved_parent_objects(
        record: CanonicalResearchObject,
        by_content: Mapping[str, _StoredObject],
        object_type: str,
    ) -> tuple[CanonicalResearchObject, ...]:
        """Resolve exact canonical parents before the generic graph pass runs."""

        resolved: list[CanonicalResearchObject] = []
        for reference in record.parents:
            if reference.object_type != object_type:
                continue
            stored = by_content.get(reference.content_hash)
            if (
                stored is None
                or stored.research_object.object_type != reference.object_type
                or stored.research_object.object_id != reference.object_id
            ):
                raise ValidationError(
                    f"canonical {record.object_type} has a missing or substituted "
                    f"{object_type} parent"
                )
            if reference.evaluated is not True:
                raise ValidationError(
                    f"canonical {record.object_type} requires evaluated "
                    f"{object_type} authority"
                )
            resolved.append(stored.research_object)
        return tuple(resolved)

    @staticmethod
    def _validate_canonical_ancestry_budget(
        record: CanonicalResearchObject,
        by_content: Mapping[str, _StoredObject],
    ) -> None:
        """Reject unbounded, cyclic, missing, or substituted parent graphs.

        This iterative preflight runs before any type-specific resolver can
        recurse through canonical parents.  The depth limit is deliberately
        far below Python's interpreter recursion limit; node and edge limits
        bound wide adversarial DAGs independently of depth.
        """

        stack: list[tuple[CanonicalResearchObject, int, bool]] = [(record, 0, False)]
        active: set[str] = set()
        visited: set[str] = set()
        edge_count = 0
        while stack:
            current, depth, exiting = stack.pop()
            digest = current.content_hash
            if exiting:
                active.remove(digest)
                visited.add(digest)
                continue
            if digest in visited:
                continue
            if digest in active:
                raise ValidationError("canonical parent graph contains a cycle")
            if depth > MAX_CANONICAL_ANCESTRY_DEPTH:
                raise ValidationError(
                    "canonical parent graph exceeds the ancestry depth limit"
                )
            if len(visited) + len(active) >= MAX_CANONICAL_ANCESTRY_NODES:
                raise ValidationError(
                    "canonical parent graph exceeds the ancestry node limit"
                )
            edge_count += len(current.parents)
            if edge_count > MAX_CANONICAL_ANCESTRY_EDGES:
                raise ValidationError(
                    "canonical parent graph exceeds the ancestry edge limit"
                )
            active.add(digest)
            stack.append((current, depth, True))
            for reference in reversed(current.parents):
                parent = by_content.get(reference.content_hash)
                if (
                    parent is None
                    or parent.research_object.object_type != reference.object_type
                    or parent.research_object.object_id != reference.object_id
                ):
                    raise ValidationError(
                        "canonical parent graph contains a missing or substituted parent"
                    )
                stack.append((parent.research_object, depth + 1, False))

    @staticmethod
    def _claim_authority_allowlist() -> Mapping[str, frozenset[Role]]:
        """Closed set of graph/receipt authorities understood by this schema."""

        allowed: dict[str, frozenset[Role]] = {
            "claim_evidence_graph": frozenset({Role.CLAIM_VERIFIER}),
            "confirmatory_claim_authority": frozenset({Role.CLAIM_VERIFIER}),
            CLAIM_SEMANTICS_RECEIPT_LOGICAL_TYPE: frozenset({Role.CLAIM_VERIFIER}),
            "scientific_semantic_judgment_receipt": frozenset(
                {Role.SCIENTIFIC_REVIEWER}
            ),
        }
        for kind in GraphEvidenceKind:
            allowed[f"claim_support_receipt.{kind.value}"] = frozenset(
                {Role.CLAIM_VERIFIER}
            )
            allowed[f"claim_evidence_verification_receipt.{kind.value}"] = frozenset(
                {Role.CLAIM_VERIFIER}
            )
        return allowed

    @staticmethod
    def _declared_native_authority_hashes(
        record: CanonicalResearchObject,
    ) -> tuple[str, ...] | None:
        """Return exact source fields that cannot be supplemented by another digest."""

        values: tuple[str, ...] | None = None
        if isinstance(record, Dataset):
            values = record.artifact_hashes
        elif isinstance(record, Implementation):
            values = record.code_artifact_hashes + record.configuration_artifact_hashes
        elif isinstance(record, Experiment):
            values = record.configuration_artifact_hashes
        elif isinstance(record, Run):
            values = (
                record.configuration_artifact_hash,
            ) + record.output_artifact_hashes
            metadata = thaw_json(record.metadata)
            if (
                metadata.get("schema_version")
                == "scientific-execution-canonical-run/v1"
            ):
                authority_hash = metadata.get(
                    "scientific_execution_authority_artifact_sha256"
                )
                validate_sha256(
                    authority_hash,
                    "canonical Run scientific execution authority SHA-256",
                )
                values = (*values, authority_hash)
        elif isinstance(record, Result):
            values = record.source_artifact_hashes + record.evaluation_artifact_hashes
        elif isinstance(record, StatisticalTest):
            values = record.source_artifact_hashes
        elif isinstance(record, Evidence):
            values = record.source_artifact_hashes
        elif isinstance(record, Claim):
            values = record.source_artifact_ids + tuple(
                digest
                for review in record.review_history
                for digest in review.source_artifact_ids
            )
        elif isinstance(record, Critique):
            values = record.reviewer_input_hashes
        elif isinstance(record, Decision):
            values = record.source_artifact_hashes
        if values is None:
            return None
        return tuple(sorted(set(values)))

    @staticmethod
    def _semantic_authority_required(record: CanonicalResearchObject) -> bool:
        if record.status is RecordStatus.SUPERSEDED:
            raise ValidationError(
                "SUPERSEDED is not a materializable lifecycle status; use revisions"
            )
        if record.status in _AUTHORITY_REQUIRED_STATUSES:
            return True
        if isinstance(record, ResearchQuestion):
            return record.gate_outcome is not None
        if isinstance(record, Hypothesis):
            return record.hypothesis_status is not HypothesisStatus.UNTESTED
        if isinstance(record, Run):
            return record.completed_at is not None
        if isinstance(record, Claim):
            return record.verification_status in {
                VerificationStatus.VERIFIED,
                VerificationStatus.REJECTED,
            }
        if isinstance(record, Evidence):
            return record.verification_status in {
                VerificationStatus.VERIFIED,
                VerificationStatus.REJECTED,
            }
        if isinstance(record, Challenge):
            return record.resolution_status is ChallengeResolution.RESOLVED
        if isinstance(record, VenueAssessment):
            return record.classification is not VenueFit.NOT_READY
        if isinstance(record, ReproducibilityPackage):
            return record.reproduction_status not in {
                ReproductionStatus.NOT_RUN,
                ReproductionStatus.BLOCKED_EXTERNAL,
            }
        return False

    def _validate_producer_authority(self, record: CanonicalResearchObject) -> None:
        allowed = _PRODUCER_ROLE_ALLOWLIST.get(record.object_type)
        if allowed is None or record.producer not in allowed:
            raise AuthorizationError(
                f"{record.object_type} producer role is not authorized"
            )
        if (
            isinstance(record, Hypothesis)
            and record.hypothesis_status is HypothesisStatus.UNTESTED
            and record.producer is not Role.HYPOTHESIS_DESIGNER
        ):
            raise AuthorizationError(
                "untested hypothesis preregistration requires HYPOTHESIS_DESIGNER"
            )

    def _authority_records(
        self,
        record: CanonicalResearchObject,
    ) -> tuple[ArtifactRecord, ...]:
        self._validate_producer_authority(record)
        required = self._semantic_authority_required(record)
        if required and not record.authority_artifact_hashes:
            raise ValidationError(
                "promotional or terminal canonical state requires explicit authority artifacts"
            )
        native = self._declared_native_authority_hashes(record)
        if native and tuple(sorted(record.authority_artifact_hashes)) != native:
            raise ValidationError(
                "canonical authority hashes differ from the exact substantive source fields"
            )
        if isinstance(record, ReproducibilityPackage):
            base = tuple(
                sorted(
                    set(
                        record.manifest_artifact_hashes
                        + record.environment_artifact_hashes
                    )
                )
            )
            declared = tuple(sorted(record.authority_artifact_hashes))
            if record.reproduction_status in {
                ReproductionStatus.NOT_RUN,
                ReproductionStatus.BLOCKED_EXTERNAL,
            }:
                if declared != base:
                    raise ValidationError(
                        "non-run reproduction authority differs from exact package sources"
                    )
            elif not set(base).issubset(declared):
                raise ValidationError(
                    "completed reproduction authority omits package sources"
                )
        records = tuple(
            self._require_frozen_pass_artifact(digest)
            for digest in record.authority_artifact_hashes
        )
        if len({item.sha256 for item in records}) != len(records):
            raise ValidationError("canonical authority artifacts must be unique")
        return records

    @staticmethod
    def _require_exact_authority_roles(
        records: tuple[ArtifactRecord, ...],
        allowed: Mapping[str, frozenset[Role]],
    ) -> None:
        for artifact in records:
            roles = allowed.get(artifact.logical_type)
            if roles is None:
                raise ValidationError(
                    f"unsupported canonical authority type {artifact.logical_type!r}"
                )
            if artifact.creator_role not in roles:
                raise AuthorizationError(
                    f"{artifact.logical_type} has the wrong authority role"
                )

    @staticmethod
    def _float_matches(left: Any, right: Any) -> bool:
        if isinstance(left, bool) or isinstance(right, bool):
            return False
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            return False
        return float(left) == float(right)

    @staticmethod
    def _timestamp_strictly_after(later: str, earlier: str) -> bool:
        try:
            later_value = datetime.fromisoformat(later.replace("Z", "+00:00"))
            earlier_value = datetime.fromisoformat(earlier.replace("Z", "+00:00"))
        except (AttributeError, ValueError):
            return False
        return later_value > earlier_value

    def _resolve_scientific_result_promotion(
        self,
        records: tuple[ArtifactRecord, ...],
        *,
        expected_result_id: str,
        expected_execution_run_id: str,
    ) -> tuple[Any, Any, ArtifactRecord, LedgerEvent]:
        """Freshly replay one exact cycle-free v2 result-promotion receipt."""

        try:
            from .scientific_design import (
                SCIENTIFIC_RESULT_PROMOTION_RECEIPT_LOGICAL_TYPE,
                ScientificResultPromotionReceipt,
                require_scientific_result_promotion_authority,
            )

            promotion_record = self._one_record(
                records,
                SCIENTIFIC_RESULT_PROMOTION_RECEIPT_LOGICAL_TYPE,
            )
            if promotion_record.creator_role is not Role.CLAIM_VERIFIER:
                raise AuthorizationError(
                    "scientific result promotion has the wrong authority role"
                )
            receipt = ScientificResultPromotionReceipt.from_dict(
                self._read_authority_json(promotion_record)
            )
            resolution = require_scientific_result_promotion_authority(
                self.registry,
                self.ledger,
                expected_ledger_run_id=self.run_id,
                expected_execution_run_id=expected_execution_run_id,
                expected_canonical_state_code_version=self.code_version,
                expected_result_id=expected_result_id,
                promotion_receipt_artifact_sha256=promotion_record.sha256,
                scientific_timeline_receipt_artifact_sha256=(
                    receipt.scientific_timeline_receipt_artifact_sha256
                ),
                domain_validity_receipt_artifact_sha256=(
                    receipt.domain_validity_receipt_artifact_sha256
                ),
                backend_execution_authority_artifact_sha256=(
                    receipt.backend_execution_authority_artifact_sha256
                ),
                confirmation_authority_artifact_sha256=(
                    receipt.confirmation_authority_artifact_sha256
                ),
            )
        except (AuthorizationError, ValidationError):
            raise
        except Exception as exc:
            raise ValidationError(
                "scientific result promotion failed fresh source-owned replay"
            ) from exc
        projection = resolution.statistical_projection
        if projection is None:
            raise ValidationError(
                "scientific result promotion lacks exact state projections"
            )
        events = self.ledger.events()
        if projection.projection_event_index >= len(events):
            raise ValidationError(
                "scientific result projection event is absent from the ledger"
            )
        projection_event = events[projection.projection_event_index]
        if (
            receipt.ledger_run_id != self.run_id
            or receipt.execution_run_id != expected_execution_run_id
            or receipt.result_id != expected_result_id
            or resolution.ledger_run_id != self.run_id
            or resolution.execution_run_id != expected_execution_run_id
            or resolution.canonical_state_code_version != self.code_version
            or resolution.result_id != expected_result_id
            or resolution.receipt_artifact_sha256 != promotion_record.sha256
            or projection.ledger_run_id != self.run_id
            or projection.run_id != expected_execution_run_id
            or projection.result_id != expected_result_id
            or projection.canonical_state_code_version != self.code_version
            or projection.result_state_projection_artifact_sha256
            != receipt.result_state_projection_artifact_sha256
            or projection.statistical_state_projection_artifact_sha256
            != receipt.statistical_state_projection_artifact_sha256
            or projection_event.event_id != projection.projection_event_id
            or projection_event.event_hash != projection.projection_event_hash
            or projection_event.run_id != self.run_id
        ):
            raise ValidationError(
                "scientific result promotion differs from its canonical-state context"
            )
        return resolution, projection, promotion_record, projection_event

    def _resolve_scientific_result_promotion_v3(
        self,
        records: tuple[ArtifactRecord, ...],
        *,
        expected_result_id: str,
        expected_execution_run_id: str,
    ) -> tuple[Any, Any, ArtifactRecord]:
        """Freshly replay one exact outcome-neutral v3 result authority."""

        try:
            from .scientific_design import (
                SCIENTIFIC_RESULT_PROMOTION_RECEIPT_LOGICAL_TYPE_V3,
                require_scientific_result_canonical_projection_v3,
                require_scientific_result_promotion_authority_v3,
            )

            promotion_record = self._one_record(
                records,
                SCIENTIFIC_RESULT_PROMOTION_RECEIPT_LOGICAL_TYPE_V3,
            )
            if promotion_record.creator_role is not Role.CLAIM_VERIFIER:
                raise AuthorizationError(
                    "scientific result promotion v3 has the wrong authority role"
                )
            resolution = require_scientific_result_promotion_authority_v3(
                self.registry,
                self.ledger,
                promotion_receipt_artifact_sha256=promotion_record.sha256,
                expected_ledger_run_id=self.run_id,
                expected_execution_run_id=expected_execution_run_id,
                expected_result_id=expected_result_id,
            )
            projection = require_scientific_result_canonical_projection_v3(
                self.registry,
                self.ledger,
                promotion_receipt_artifact_sha256=promotion_record.sha256,
                expected_ledger_run_id=self.run_id,
                expected_execution_run_id=expected_execution_run_id,
                expected_result_id=expected_result_id,
                canonical_state_code_version=self.code_version,
            )
        except (AuthorizationError, ValidationError):
            raise
        except Exception as exc:
            raise ValidationError(
                "scientific result promotion v3 failed fresh source-owned replay"
            ) from exc
        if (
            resolution.ledger_run_id != self.run_id
            or resolution.execution_run_id != expected_execution_run_id
            or resolution.result_id != expected_result_id
            or resolution.receipt_artifact_sha256 != promotion_record.sha256
            or not resolution.scientific_evidence_eligible
            or projection.ledger_run_id != self.run_id
            or projection.execution_run_id != expected_execution_run_id
            or projection.result_id != expected_result_id
            or projection.promotion_receipt_artifact_sha256 != promotion_record.sha256
            or projection.canonical_state_code_version != self.code_version
            or projection.outcome is not resolution.outcome
        ):
            raise ValidationError(
                "scientific result promotion v3 differs from canonical-state context"
            )
        return resolution, projection, promotion_record

    def _resolve_scientific_execution_canonical_run(
        self,
        record: Run,
        records: tuple[ArtifactRecord, ...],
        by_content: Mapping[str, _StoredObject],
    ) -> _ResolvedObjectAuthority | None:
        """Freshly replay one execution-owned canonical Run projection."""

        metadata = thaw_json(record.metadata)
        if metadata.get("schema_version") != ("scientific-execution-canonical-run/v1"):
            return None
        try:
            from .experiments import (
                SCIENTIFIC_EXECUTION_AUTHORITY_LOGICAL_TYPE,
                ScientificExecutionOutcome,
                require_scientific_execution_authority,
                require_scientific_execution_run_spec,
            )

            authority_record = self._one_record(
                records,
                SCIENTIFIC_EXECUTION_AUTHORITY_LOGICAL_TYPE,
            )
            authority = require_scientific_execution_authority(
                self.registry,
                self.ledger,
                authority_artifact_sha256=authority_record.sha256,
                expected_ledger_run_id=self.run_id,
                expected_execution_run_id=record.object_id,
            )
            spec = require_scientific_execution_run_spec(
                self.registry,
                frozen_run_spec_artifact_sha256=(
                    authority.frozen_run_spec_artifact_sha256
                ),
            )
        except (AuthorizationError, ValidationError):
            raise
        except Exception as exc:
            raise ValidationError(
                "canonical Run failed fresh scientific execution replay"
            ) from exc

        experiment_parents = self._resolved_parent_objects(
            record,
            by_content,
            "Experiment",
        )
        if len(experiment_parents) != 1:
            raise ValidationError(
                "scientific execution Run lacks one exact Experiment parent"
            )
        experiment = experiment_parents[0]
        evaluator_record = self._require_frozen_pass_artifact(
            spec.evaluator_sha256,
            logical_type="evaluator_implementation",
            creator_role=Role.PROTOCOL_DESIGNER,
        )
        evaluator = self._read_authority_json(evaluator_record)
        evaluator_version = evaluator.get("evaluator_version")
        if not isinstance(evaluator_version, str) or not evaluator_version:
            raise ValidationError(
                "scientific execution Run evaluator version is absent"
            )
        expected_outputs = (
            authority.frozen_run_spec_artifact_sha256,
            authority.output_manifest_artifact_sha256,
            *authority.output_artifact_sha256s,
        )
        expected_authorities = tuple(
            sorted(
                {
                    spec.configuration_sha256,
                    *expected_outputs,
                    authority_record.sha256,
                }
            )
        )
        allowed: dict[str, frozenset[Role]] = {
            "experiment_configuration": frozenset({Role.PROTOCOL_DESIGNER}),
            "frozen_run_spec": frozenset({Role.EXPERIMENT_RUNNER}),
            "experiment_output_manifest": frozenset({Role.EXPERIMENT_RUNNER}),
            SCIENTIFIC_EXECUTION_AUTHORITY_LOGICAL_TYPE: frozenset(
                {Role.CLAIM_VERIFIER}
            ),
        }
        for source in records:
            if source.logical_type.startswith("experiment_output."):
                allowed[source.logical_type] = frozenset({Role.EXPERIMENT_RUNNER})
        self._require_exact_authority_roles(records, allowed)
        try:
            expected_compute_profile = ComputeProfile(spec.compute_profile.mode.value)
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                "scientific execution Run compute profile is unsupported"
            ) from exc
        expected_metadata = {
            "schema_version": "scientific-execution-canonical-run/v1",
            "authority_scope": "SCIENTIFIC_EXECUTION_ATTESTATION",
            "outcome": ScientificExecutionOutcome.COMPLETED.value,
            "scientific_execution_authority_artifact_sha256": (authority_record.sha256),
        }
        if (
            authority.outcome is not ScientificExecutionOutcome.COMPLETED
            or authority.scientific_evidence_eligible is not True
            or authority.frozen_run_spec_artifact_sha256
            not in authority.source_artifact_hashes
            or authority.output_manifest_artifact_sha256
            not in authority.source_artifact_hashes
            or set(authority.output_artifact_sha256s)
            - set(authority.source_artifact_hashes)
            or {item.sha256 for item in records} != set(expected_authorities)
            or len(records) != len(expected_authorities)
            or authority_record.sha256
            != metadata.get("scientific_execution_authority_artifact_sha256")
            or metadata != expected_metadata
            or record.parents
            != (
                ObjectReference(
                    "Experiment",
                    experiment.object_id,
                    experiment.content_hash,
                    "executes",
                    True,
                ),
            )
            or record.relationships
            or record.revision != 1
            or record.supersedes_content_hash is not None
            or record.producer is not Role.EXPERIMENT_RUNNER
            or record.status is not RecordStatus.COMPLETE
            or record.code_version != self.code_version
            or record.object_id != spec.run_id
            or record.experiment_id != spec.experiment_id
            or experiment.object_id != spec.experiment_id
            or experiment.status is not RecordStatus.FROZEN
            or record.code_revision != f"sha256:{spec.code_sha256}"
            or record.dataset_ids != experiment.dataset_ids
            or record.configuration_artifact_hash != spec.configuration_sha256
            or record.compute_profile is not expected_compute_profile
            or record.random_seeds != spec.seeds
            or record.output_artifact_hashes != expected_outputs
            or record.evaluator_version != evaluator_version
            or record.started_at != authority.attested_started_at
            or record.completed_at != authority.attested_completed_at
            or record.authority_artifact_hashes != expected_authorities
            or not self._timestamp_strictly_after(
                record.created_at,
                authority_record.created_at,
            )
        ):
            raise ValidationError(
                "canonical Run differs from its exact scientific execution authority"
            )
        return _ResolvedObjectAuthority(
            records,
            scientific_evidence_eligible=True,
        )

    def _validate_scientific_result_parent_join(
        self,
        *,
        record: Result,
        run: Run,
        metric: Metric,
        result_projection: Any,
        by_content: Mapping[str, _StoredObject],
        require_materialized_lineage: bool = True,
    ) -> bool:
        """Bind projected result bytes to one exact canonical protocol graph."""

        eligible, contract = self._validate_scientific_protocol_parent_join(
            run=run,
            protocol_source=result_projection,
            by_content=by_content,
            require_materialized_lineage=require_materialized_lineage,
        )
        experiment = self._resolved_parent_objects(run, by_content, "Experiment")[0]
        experiment_metrics = self._resolved_parent_objects(
            experiment, by_content, "Metric"
        )
        baselines = self._resolved_parent_objects(experiment, by_content, "Baseline")
        contract_metric = contract.primary_metric
        contract_baseline_ids = {
            item.baseline_id for item in contract.baseline_registry.entries
        }
        expected_direction = {
            "HIGHER_IS_BETTER": MetricDirection.HIGHER_IS_BETTER,
            "LOWER_IS_BETTER": MetricDirection.LOWER_IS_BETTER,
            "TARGET_IS_BEST": MetricDirection.TARGET_IS_BETTER,
        }.get(result_projection.metric_direction.value)
        if (
            expected_direction is None
            or metric.object_id not in {item.object_id for item in experiment_metrics}
            or result_projection.baseline_id not in contract_baseline_ids
            or result_projection.baseline_id
            not in {item.object_id for item in baselines}
            or metric.authority_artifact_hashes
            != (result_projection.contract_artifact_sha256,)
            or metric.object_id != result_projection.metric_id
            or metric.name != contract_metric.name
            or metric.unit != result_projection.metric_unit.value
            or metric.direction is not expected_direction
            or metric.evidence_level.value != result_projection.metric_scope.value
            or record.code_revision != result_projection.canonical_state_code_version
        ):
            raise ValidationError(
                "scientific Result projection is spliced from another canonical "
                "Run, Experiment, Method, implementation, hypothesis, or Metric"
            )
        if require_materialized_lineage:
            self._validate_source_bound_parent_lineage(metric, by_content)
        return eligible

    def _validate_scientific_protocol_parent_join(
        self,
        *,
        run: Run,
        protocol_source: Any,
        by_content: Mapping[str, _StoredObject],
        require_materialized_lineage: bool = True,
    ) -> tuple[bool, Any]:
        """Check the same exact protocol graph for execution and Result owners.

        The private source contains identities already replayed by the calling
        execution or Result owner.  This helper is not an authority issuer and
        never discovers Results that happen to contain a protocol ancestor.
        Dataset/Split/Method sources retain their ordinary full owner replay;
        the returned boolean concerns Dataset/Split eligibility, not execution.
        Result-specific primary-metric and selected-baseline assertions remain
        in the Result wrapper rather than becoming pre-Result Run requirements.
        """

        result_projection = protocol_source
        experiments = self._resolved_parent_objects(run, by_content, "Experiment")
        if len(experiments) != 1 or not isinstance(experiments[0], Experiment):
            raise ValidationError(
                "scientific Result Run lacks one exact canonical Experiment"
            )
        experiment = experiments[0]
        implementations = self._resolved_parent_objects(
            experiment,
            by_content,
            "Implementation",
        )
        hypotheses = self._resolved_parent_objects(
            experiment,
            by_content,
            "Hypothesis",
        )
        datasets = self._resolved_parent_objects(
            experiment,
            by_content,
            "Dataset",
        )
        splits = self._resolved_parent_objects(
            experiment,
            by_content,
            "Split",
        )
        experiment_metrics = self._resolved_parent_objects(
            experiment,
            by_content,
            "Metric",
        )
        baselines = self._resolved_parent_objects(
            experiment,
            by_content,
            "Baseline",
        )
        if len(implementations) != 1 or not isinstance(
            implementations[0], Implementation
        ):
            raise ValidationError(
                "scientific Result Experiment lacks one exact Implementation"
            )
        implementation = implementations[0]
        methods = self._resolved_parent_objects(
            implementation,
            by_content,
            "Method",
        )
        try:
            from .scientific_design import (
                require_frozen_evaluation_contract,
                scientific_ablation_component_id,
            )

            contract = require_frozen_evaluation_contract(
                self.registry,
                contract_artifact_sha256=(result_projection.contract_artifact_sha256),
            )
        except Exception as exc:
            raise ValidationError(
                "scientific Result contract failed fresh typed replay"
            ) from exc
        spec_record = self._require_frozen_pass_artifact(
            result_projection.frozen_run_spec_artifact_sha256,
            logical_type="frozen_run_spec",
            creator_role=Role.EXPERIMENT_RUNNER,
        )
        try:
            from .experiments import (
                require_scientific_execution_run_spec,
                resolve_scientific_method_definition_binding,
            )

            typed_spec = require_scientific_execution_run_spec(
                self.registry,
                frozen_run_spec_artifact_sha256=spec_record.sha256,
            )
            method_binding = resolve_scientific_method_definition_binding(
                self.registry,
                spec=typed_spec,
            )
        except Exception as exc:
            raise ValidationError(
                "scientific Result run spec or Method intention failed fresh replay"
            ) from exc
        spec = typed_spec.to_dict()
        code_hash = spec.get("code_sha256")
        data_hash = spec.get("data_sha256")
        configuration_hash = spec.get("configuration_sha256")
        evaluator_hash = spec.get("evaluator_sha256")
        for label, digest in (
            ("projected execution code", code_hash),
            ("projected Dataset", data_hash),
            ("projected configuration", configuration_hash),
            ("projected evaluator", evaluator_hash),
        ):
            validate_sha256(digest, f"{label} SHA-256")
        code_record = self._require_frozen_pass_artifact(
            code_hash,
            logical_type="experiment_code",
            creator_role=Role.IMPLEMENTER,
        )
        data_record = self._require_frozen_pass_artifact(
            data_hash,
            logical_type="experiment_dataset",
            creator_role=Role.EVIDENCE_CURATOR,
        )
        configuration_record = self._require_frozen_pass_artifact(
            configuration_hash,
            logical_type="experiment_configuration",
            creator_role=Role.PROTOCOL_DESIGNER,
        )
        evaluator_record = self._require_frozen_pass_artifact(
            evaluator_hash,
            logical_type="evaluator_implementation",
            creator_role=Role.PROTOCOL_DESIGNER,
        )
        evaluator_value = self._read_authority_json(evaluator_record)
        evaluator_version = evaluator_value.get("evaluator_version")
        if not isinstance(evaluator_version, str) or not evaluator_version:
            raise ValidationError(
                "scientific Result evaluator lacks a source-owned version"
            )
        primary_hypothesis = contract.hypothesis_register.primary
        expected_method_component_ids = tuple(
            scientific_ablation_component_id(
                item.ablation_id,
                item.component_changed,
            )
            for item in contract.ablations
        )
        contract_metric = contract.primary_metric
        contract_dataset = contract.dataset
        contract_split_roles = {
            contract_dataset.train_split_id: SplitRole.TRAIN,
            contract_dataset.development_split_id: SplitRole.EXPLORATORY,
            contract_dataset.validation_split_id: SplitRole.VALIDATION,
            contract_dataset.confirmatory_split_id: SplitRole.CONFIRMATORY,
        }
        contract_metric_ids = {
            contract_metric.metric_id,
            *(item.metric_id for item in contract.secondary_metrics),
        }
        contract_baseline_ids = {
            item.baseline_id for item in contract.baseline_registry.entries
        }
        hypothesis_by_id = {item.object_id: item for item in hypotheses}
        dataset_by_id = {item.object_id: item for item in datasets}
        split_by_id = {item.object_id: item for item in splits}
        metric_by_id = {item.object_id: item for item in experiment_metrics}
        baseline_by_id = {item.object_id: item for item in baselines}
        contract_split_ids = tuple(contract_split_roles)
        contract_metric_sequence = (
            contract.primary_metric,
            *contract.secondary_metrics,
        )
        contract_metric_id_sequence = tuple(
            item.metric_id for item in contract_metric_sequence
        )
        contract_baseline_sequence = contract.baseline_registry.entries
        contract_baseline_id_sequence = tuple(
            item.baseline_id for item in contract_baseline_sequence
        )
        expected_experiment_parent_shape = (
            (
                "Hypothesis",
                primary_hypothesis.hypothesis_id,
                (
                    hypothesis_by_id[primary_hypothesis.hypothesis_id].content_hash
                    if primary_hypothesis.hypothesis_id in hypothesis_by_id
                    else None
                ),
                "tests",
                True,
            ),
            (
                "Implementation",
                implementation.object_id,
                implementation.content_hash,
                "uses",
                True,
            ),
            (
                "Dataset",
                contract_dataset.dataset_id,
                (
                    dataset_by_id[contract_dataset.dataset_id].content_hash
                    if contract_dataset.dataset_id in dataset_by_id
                    else None
                ),
                "uses",
                True,
            ),
            *tuple(
                (
                    "Split",
                    split_id,
                    (
                        split_by_id[split_id].content_hash
                        if split_id in split_by_id
                        else None
                    ),
                    "binds_split",
                    True,
                )
                for split_id in contract_split_ids
            ),
            *tuple(
                (
                    "Metric",
                    metric_id,
                    (
                        metric_by_id[metric_id].content_hash
                        if metric_id in metric_by_id
                        else None
                    ),
                    "evaluates",
                    True,
                )
                for metric_id in contract_metric_id_sequence
            ),
            *tuple(
                (
                    "Baseline",
                    baseline_id,
                    (
                        baseline_by_id[baseline_id].content_hash
                        if baseline_id in baseline_by_id
                        else None
                    ),
                    "compares_with",
                    True,
                )
                for baseline_id in contract_baseline_id_sequence
            ),
        )
        execution_revision = result_projection.execution_code_revision
        execution_code_hash = (
            execution_revision.removeprefix("sha256:")
            if isinstance(execution_revision, str)
            and execution_revision.startswith("sha256:")
            else ""
        )
        if len(datasets) != 1:
            raise ValidationError(
                "scientific Result Experiment lacks one exact Dataset"
            )
        expected_method_id = (
            method_binding.method_id
            if method_binding is not None
            else f"method-{code_record.sha256}"
        )
        expected_method_producer = (
            Role.HYPOTHESIS_DESIGNER
            if method_binding is not None
            else Role.PROTOCOL_DESIGNER
        )
        expected_method_name = (
            method_binding.name if method_binding is not None else "UNAVAILABLE"
        )
        expected_method_description = (
            method_binding.description
            if method_binding is not None
            else "UNAVAILABLE"
        )
        expected_method_assumptions = (
            method_binding.assumptions if method_binding is not None else ()
        )
        expected_method_components = (
            method_binding.component_ids
            if method_binding is not None
            else expected_method_component_ids
        )
        expected_implementation_id = "implementation-" + sha256_bytes(
            canonical_json_bytes(
                {
                    "code_sha256": code_record.sha256,
                    "configuration_sha256": configuration_record.sha256,
                }
            )
        )
        metric_direction_map = {
            "HIGHER_IS_BETTER": MetricDirection.HIGHER_IS_BETTER,
            "LOWER_IS_BETTER": MetricDirection.LOWER_IS_BETTER,
            "TARGET_IS_BEST": MetricDirection.TARGET_IS_BETTER,
        }
        expected_metric_values = {
            item.metric_id: (
                item.name,
                metric_direction_map[item.direction.value],
                item.unit.value,
                MetricLevel(item.scope.value),
            )
            for item in contract_metric_sequence
        }
        expected_baseline_values = {
            item.baseline_id: item for item in contract_baseline_sequence
        }
        expected_budget = {
            "max_cpu_workers": contract.compute_budget.max_cpu_workers,
            "max_gpu_jobs": contract.compute_budget.max_gpu_jobs,
            "max_runs": contract.compute_budget.max_runs,
            "max_tuning_trials": contract.compute_budget.max_tuning_trials,
            "max_wall_seconds": contract.compute_budget.max_wall_seconds,
        }
        expected_seed_policy = {
            "best_of_n": contract.seed_reporting.best_of_n,
            "preserve_all_runs": contract.seed_reporting.preserve_all_runs,
            "regime": contract.seed_reporting.regime.value,
            "run_seed_policy": spec.get("seed_policy"),
            "seeds": list(contract.seed_reporting.seeds),
            "selection_defined_before_results": (
                contract.seed_reporting.selection_defined_before_results
            ),
            "selection_policy": contract.seed_reporting.selection_policy,
            "technical_retry_rule": (contract.seed_reporting.technical_retry_rule),
        }
        expected_termination = {
            "failure": list(contract.failure_criteria),
            "run": list(spec.get("termination_conditions", ())),
            "stopping": list(contract.stopping_criteria),
            "success": list(contract.success_criteria),
        }
        try:
            expected_compute_profile = ComputeProfile(
                self._nested_mapping(spec, "compute_profile").get("mode")
            )
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                "scientific Result compute profile is unsupported"
            ) from exc
        expected_outputs = tuple(spec.get("expected_outputs", ()))
        expected_run_outputs = (
            result_projection.frozen_run_spec_artifact_sha256,
            result_projection.output_manifest_artifact_sha256,
            *result_projection.raw_source_artifact_hashes,
        )
        expected_run_started_at = getattr(
            result_projection,
            "run_started_at",
            spec_record.created_at,
        )
        expected_run_completed_at = getattr(
            result_projection,
            "run_completed_at",
            None,
        )
        manifest_record = self._require_frozen_pass_artifact(
            result_projection.output_manifest_artifact_sha256,
            logical_type="experiment_output_manifest",
            creator_role=Role.EXPERIMENT_RUNNER,
        )

        dataset_authority_records = self._authority_records(datasets[0])
        dataset_scientific_eligible = False
        if (
            len(dataset_authority_records) == 1
            and dataset_authority_records[0].logical_type
            == SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE
        ):
            dataset_authority = require_scientific_dataset_authority(
                self.registry,
                self.ledger,
                run_id=self.run_id,
                authority_artifact_hash=dataset_authority_records[0].sha256,
                expected_dataset_id=contract_dataset.dataset_id,
                expected_version=datasets[0].version,
            )
            require_scientific_experiment_dataset_projection(
                self.registry,
                self.ledger,
                run_id=self.run_id,
                projection_artifact_hash=data_record.sha256,
                expected_dataset_authority_artifact_hash=(
                    dataset_authority.authority_artifact_hash
                ),
                expected_evaluation_contract_artifact_hash=(
                    result_projection.contract_artifact_sha256
                ),
            )
            if (
                dataset_authority.evaluation_contract_artifact_hash
                != result_projection.contract_artifact_sha256
            ):
                raise ValidationError(
                    "scientific Result Dataset projection differs from its "
                    "audited acquisition"
                )
            dataset_scientific_eligible = True
            expected_dataset_values = (
                dataset_authority.name,
                dataset_authority.version,
                (dataset_authority.authority_artifact_hash,),
                "AVAILABLE",
                dataset_authority.license_identifier,
            )
        else:
            expected_dataset_values = (
                "UNAVAILABLE",
                f"sha256:{data_record.sha256}",
                (data_record.sha256,),
                "UNSPECIFIED",
                "UNSPECIFIED",
            )

        split_scientific_eligible = True
        for item in splits:
            item_records = self._authority_records(item)
            if (
                len(item_records) == 1
                and item_records[0].logical_type
                == SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE
            ):
                split_authority = require_scientific_dataset_split_authority(
                    self.registry,
                    self.ledger,
                    run_id=self.run_id,
                    split_authority_artifact_hash=item_records[0].sha256,
                    expected_split_id=item.object_id,
                    expected_split_role=item.split_role,
                    expected_unit_type=item.unit_type,
                )
                if (
                    not dataset_scientific_eligible
                    or split_authority.dataset_authority_artifact_hash
                    != dataset_authority_records[0].sha256
                    or item.definition_artifact_hashes
                    != (split_authority.artifact_hash,)
                ):
                    raise ValidationError(
                        "scientific Result split differs from its Dataset authority"
                    )
            else:
                split_scientific_eligible = False
                if item.unit_type != "UNSPECIFIED" or item.definition_artifact_hashes:
                    raise ValidationError(
                        "non-evidentiary Result split differs from its neutral projection"
                    )

        def baseline_matches(item: Baseline) -> bool:
            expected = expected_baseline_values.get(item.object_id)
            if expected is None:
                return False
            metric_id = expected.conditions.metric_id
            implementation_id = "baseline-implementation-" + sha256_bytes(
                canonical_json_bytes(
                    {
                        "implementation": expected.implementation,
                        "implementation_version": expected.implementation_version,
                    }
                )
            )
            paper_id = "baseline-paper-" + sha256_bytes(
                canonical_json_bytes({"paper_locator": expected.paper_locator})
            )

            def optional_metric(value: Any) -> dict[str, Any]:
                return {} if value is None else {metric_id: value}

            return (
                item.producer is Role.PROTOCOL_DESIGNER
                and item.status is RecordStatus.FROZEN
                and item.authority_artifact_hashes
                == (result_projection.contract_artifact_sha256,)
                and not item.parents
                and item.name == expected.name
                and item.method_id == f"baseline-method-{expected.baseline_id}"
                and item.implementation_id == implementation_id
                and item.paper_id == paper_id
                and item.metric_ids == (metric_id,)
                and item.baseline_status.value == expected.status.value
                and thaw_json(item.reported_metrics)
                == optional_metric(expected.reported_metric)
                and thaw_json(item.expected_metrics)
                == optional_metric(expected.expected_metric)
                and thaw_json(item.observed_metrics)
                == optional_metric(expected.observed_metric)
                and thaw_json(item.tuning_budget)
                == {
                    "hyperparameter_search": (
                        expected.conditions.hyperparameter_search
                    ),
                    "trials": expected.conditions.tuning_trials,
                }
                and thaw_json(item.compute_budget)
                == {
                    "budget": expected.conditions.compute_budget,
                    "hardware_class": expected.conditions.hardware_class,
                }
                and self._float_matches(
                    item.implementation_confidence,
                    expected.implementation_confidence,
                )
                and item.fairness_assessment == expected.fairness_assessment
            )

        if (
            len(methods) != 1
            or not isinstance(methods[0], Method)
            or len(hypotheses) != 1
            or len(datasets) != 1
            or experiment.status is not RecordStatus.FROZEN
            or implementation.status is not RecordStatus.FROZEN
            or methods[0].status is not RecordStatus.FROZEN
            or methods[0].producer is not expected_method_producer
            or methods[0].object_id != expected_method_id
            or methods[0].name != expected_method_name
            or methods[0].description != expected_method_description
            or methods[0].assumptions != expected_method_assumptions
            or methods[0].component_ids != expected_method_components
            or implementation.producer is not Role.IMPLEMENTER
            or implementation.object_id != expected_implementation_id
            or implementation.code_artifact_hashes != (code_record.sha256,)
            or implementation.configuration_artifact_hashes
            != (configuration_record.sha256,)
            or implementation.code_revision != self.code_version
            or datasets[0].producer is not Role.EVIDENCE_CURATOR
            or (
                datasets[0].name,
                datasets[0].version,
                datasets[0].artifact_hashes,
                datasets[0].access_status,
                datasets[0].license,
            )
            != expected_dataset_values
            or any(
                not isinstance(item, Hypothesis)
                or item.status is not RecordStatus.FROZEN
                or item.hypothesis_status is not HypothesisStatus.UNTESTED
                or item.producer is not Role.HYPOTHESIS_DESIGNER
                for item in hypotheses
            )
            or hypotheses[0].object_id != primary_hypothesis.hypothesis_id
            or hypotheses[0].statement != primary_hypothesis.statement
            or hypotheses[0].motivation != primary_hypothesis.motivation
            or hypotheses[0].prior_evidence_ids != primary_hypothesis.prior_evidence_ids
            or hypotheses[0].prediction != primary_hypothesis.prediction
            or hypotheses[0].falsification_condition
            != primary_hypothesis.falsification_condition
            or hypotheses[0].planned_experiment_ids
            != (primary_hypothesis.planned_experiment,)
            or run.object_id != result_projection.run_id
            or run.experiment_id != result_projection.experiment_id
            or experiment.object_id != result_projection.experiment_id
            or result_projection.hypothesis_id != hypotheses[0].object_id
            or experiment.hypothesis_ids != (hypotheses[0].object_id,)
            or tuple(
                (
                    parent.object_type,
                    parent.object_id,
                    parent.content_hash,
                    parent.relation,
                    parent.evaluated,
                )
                for parent in experiment.parents
            )
            != expected_experiment_parent_shape
            or run.parents
            != (
                ObjectReference(
                    "Experiment",
                    experiment.object_id,
                    experiment.content_hash,
                    "executes",
                    True,
                ),
            )
            or implementation.object_id != experiment.implementation_id
            or methods[0].object_id != implementation.method_id
            or implementation.parents
            != (
                ObjectReference(
                    "Method",
                    methods[0].object_id,
                    methods[0].content_hash,
                    "implements",
                    True,
                ),
            )
            or not execution_code_hash
            or execution_code_hash not in implementation.code_artifact_hashes
            or run.code_revision != execution_revision
            or spec.get("run_id") != run.object_id
            or spec.get("experiment_id") != experiment.object_id
            or spec.get("hypothesis_id") != hypotheses[0].object_id
            or spec.get("code_sha256") != execution_code_hash
            or spec.get("configuration_sha256") != run.configuration_artifact_hash
            or tuple(spec.get("seeds", ())) != tuple(run.random_seeds)
            or experiment.dataset_ids != (contract_dataset.dataset_id,)
            or datasets[0].object_id != contract_dataset.dataset_id
            or run.dataset_ids != experiment.dataset_ids
            or experiment.split_ids != contract_split_ids
            or {item.object_id for item in splits} != set(contract_split_roles)
            or any(
                item.producer is not Role.PROTOCOL_DESIGNER
                or item.dataset_id != datasets[0].object_id
                or item.split_role is not contract_split_roles[item.object_id]
                or item.status is not RecordStatus.FROZEN
                or item.parents
                != (
                    ObjectReference(
                        "Dataset",
                        datasets[0].object_id,
                        datasets[0].content_hash,
                        "partitions",
                        True,
                    ),
                )
                for item in splits
            )
            or experiment.metric_ids != contract_metric_id_sequence
            or {item.object_id for item in experiment_metrics} != contract_metric_ids
            or any(
                item.producer is not Role.PROTOCOL_DESIGNER
                or item.status is not RecordStatus.FROZEN
                or item.authority_artifact_hashes
                != (result_projection.contract_artifact_sha256,)
                or item.parents
                or (
                    item.name,
                    item.direction,
                    item.unit,
                    item.evidence_level,
                )
                != expected_metric_values[item.object_id]
                for item in experiment_metrics
            )
            or experiment.baseline_ids != contract_baseline_id_sequence
            or {item.object_id for item in baselines} != contract_baseline_ids
            or any(not baseline_matches(item) for item in baselines)
            or thaw_json(experiment.seed_policy) != expected_seed_policy
            or experiment.evaluator != contract.candidate_conditions.evaluator
            or experiment.producer is not Role.PROTOCOL_DESIGNER
            or experiment.scientific_purpose != spec.get("scientific_purpose")
            or experiment.compute_profile is not expected_compute_profile
            or experiment.expected_output_types != expected_outputs
            or thaw_json(experiment.budget) != expected_budget
            or thaw_json(experiment.termination_conditions) != expected_termination
            or experiment.configuration_artifact_hashes
            != tuple(
                sorted(
                    (
                        run.configuration_artifact_hash,
                        result_projection.contract_artifact_sha256,
                    )
                )
            )
            or result_projection.contract_artifact_sha256
            not in experiment.authority_artifact_hashes
            or result_projection.frozen_run_spec_artifact_sha256
            not in run.output_artifact_hashes
            or result_projection.output_manifest_artifact_sha256
            not in run.output_artifact_hashes
            or run.producer is not Role.EXPERIMENT_RUNNER
            or run.compute_profile is not expected_compute_profile
            or run.output_artifact_hashes != expected_run_outputs
            or run.evaluator_version != evaluator_version
            or run.started_at != expected_run_started_at
            or run.completed_at
            != (expected_run_completed_at or manifest_record.created_at)
        ):
            raise ValidationError(
                "scientific Result projection is spliced from another canonical "
                "Run, Experiment, Method, implementation, hypothesis, or Metric"
            )
        if require_materialized_lineage:
            self._validate_source_bound_parent_lineage(run, by_content)
        return dataset_scientific_eligible and split_scientific_eligible, contract

    def _source_bound_hypothesis_evaluation_successor(
        self,
        current: CanonicalResearchObject,
        revisions: tuple[CanonicalResearchObject, ...],
        by_content: Mapping[str, _StoredObject],
        events: tuple[LedgerEvent, ...],
    ) -> _StoredObject | None:
        """Recognize the sole post-Result revision allowed in frozen ancestry.

        Result replay must continue to bind the preregistered r1 Hypothesis
        even after a later evaluation appends r2.  This check intentionally
        validates only that historical exception.  Full evaluation semantics
        are replayed when r2 itself is resolved, avoiding recursive Result ->
        Hypothesis authority -> Result resolution.
        """

        if not isinstance(current, Hypothesis) or len(revisions) != 2:
            return None
        ordered = tuple(sorted(revisions, key=lambda item: item.revision))
        prior, successor = ordered
        if prior != current or not isinstance(successor, Hypothesis):
            return None
        successor_stored = by_content.get(successor.content_hash)
        prior_stored = by_content.get(prior.content_hash)
        if successor_stored is None or prior_stored is None:
            return None
        expected_unchanged = (
            successor.object_id == prior.object_id
            and successor.schema_version == prior.schema_version
            and successor.code_version == prior.code_version
            and successor.relationships == prior.relationships
            and thaw_json(successor.metadata) == thaw_json(prior.metadata)
            and successor.statement == prior.statement
            and successor.motivation == prior.motivation
            and successor.prior_evidence_ids == prior.prior_evidence_ids
            and successor.prediction == prior.prediction
            and successor.falsification_condition == prior.falsification_condition
            and successor.planned_experiment_ids == prior.planned_experiment_ids
        )
        if (
            prior.revision != 1
            or prior.supersedes_content_hash is not None
            or prior.hypothesis_status is not HypothesisStatus.UNTESTED
            or prior.producer is not Role.HYPOTHESIS_DESIGNER
            or successor.revision != 2
            or successor.supersedes_content_hash != prior.content_hash
            or successor.hypothesis_status
            in {HypothesisStatus.UNTESTED, HypothesisStatus.POST_HOC}
            or successor.producer is not Role.SCIENTIFIC_REVIEWER
            or successor.status is not RecordStatus.COMPLETE
            or len(successor.parents) != 2
            or {item.object_type for item in successor.parents}
            != {"Result", "StatisticalTest"}
            or any(
                item.relation != "evaluated_by" or item.evaluated is not True
                for item in successor.parents
            )
            or len(successor.authority_artifact_hashes) != 1
            or not expected_unchanged
        ):
            return None
        authority_hash = successor.authority_artifact_hashes[0]
        try:
            authority_record = self._require_frozen_pass_artifact(
                authority_hash,
                logical_type=HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE,
                creator_role=Role.SCIENTIFIC_REVIEWER,
            )
            authority = HypothesisEvaluationAuthority.from_dict(
                safe_json_loads(
                    self.registry.get_bytes(authority_hash),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
            )
        except Exception:
            return None
        parent_by_type = {item.object_type: item for item in successor.parents}
        result_reference = parent_by_type["Result"]
        statistical_reference = parent_by_type["StatisticalTest"]
        result_stored = by_content.get(result_reference.content_hash)
        statistical_stored = by_content.get(statistical_reference.content_hash)
        if (
            authority.run_id != self.run_id
            or authority.hypothesis_id != prior.object_id
            or authority.prior_hypothesis_content_hash != prior.content_hash
            or authority.prior_hypothesis_state_artifact_hash
            != prior_stored.artifact.sha256
            or authority.result_id != result_reference.object_id
            or authority.result_content_hash != result_reference.content_hash
            or authority.statistical_test_id != statistical_reference.object_id
            or authority.statistical_test_content_hash
            != statistical_reference.content_hash
            or authority.outcome is not successor.hypothesis_status
            or result_stored is None
            or statistical_stored is None
            or authority.result_state_artifact_hash != result_stored.artifact.sha256
            or authority.statistical_test_state_artifact_hash
            != statistical_stored.artifact.sha256
            or authority_record.parent_artifacts != authority.source_artifact_hashes
            or not self._timestamp_strictly_after(
                successor.created_at,
                authority_record.created_at,
            )
        ):
            return None
        if authority.is_bounded_mean:
            try:
                if (
                    authority_record.schema_version != authority.artifact_schema_version
                    or self.registry.get_bytes(authority_hash) != canonical_json_bytes(authority.to_dict()) + b"\n"
                    or authority_record.origin != "source-owned prospective hypothesis evaluation authority"
                    or authority_record.creation_command != ("scientist-one", "evaluate-hypothesis")
                    or successor.parents != (
                        ObjectReference("Result", authority.result_id, authority.result_content_hash, "evaluated_by", True),
                        ObjectReference("StatisticalTest", authority.statistical_test_id, authority.statistical_test_content_hash, "evaluated_by", True),
                    )
                ):
                    return None
                _require_bounded_hypothesis_successor_bindings(
                    self, authority, prior_stored, result_stored, statistical_stored,
                )
            except Exception:
                return None
        event_indexes = {event.event_id: index for index, event in enumerate(events)}
        evaluation_event = next(
            (
                event
                for event in events
                if event.event_id == authority.evaluation_event_id
            ),
            None,
        )
        successor_event = self._materialization_event(
            successor_stored.artifact.sha256,
            successor,
            events=events,
        )
        evaluation_binding = (
            evaluation_event.metadata.get("hypothesis_evaluation")
            if evaluation_event is not None
            else None
        )
        if (
            evaluation_event is None
            or successor_event is None
            or evaluation_event.event_hash != authority.evaluation_event_hash
            or event_indexes.get(evaluation_event.event_id)
            != authority.evaluation_event_index
            or evaluation_event.actor_role is not Role.SCIENTIFIC_REVIEWER
            or evaluation_event.run_id != self.run_id
            or evaluation_event.artifact_hashes != authority.source_artifact_hashes
            or not isinstance(evaluation_binding, Mapping)
            or evaluation_binding.get("kind") != "HYPOTHESIS_EVALUATED"
            or evaluation_binding.get("authority_id") != authority.authority_id
            or evaluation_binding.get("hypothesis_id") != prior.object_id
            or evaluation_binding.get("outcome") != successor.hypothesis_status.value
            or event_indexes[evaluation_event.event_id]
            >= event_indexes[successor_event.event_id]
            or successor_event.supersedes_event_id
            != f"rs-{prior_stored.artifact.sha256[:48]}"
        ):
            return None
        if authority.is_bounded_mean and (
            thaw_json(evaluation_event.metadata) != {"hypothesis_evaluation": authority.evaluation_binding}
            or evaluation_event.event_id != "hyp-eval-" + sha256_bytes(canonical_json_bytes(authority.evaluation_binding))[:40]
            or evaluation_event.event_type != "CHECKPOINT"
            or evaluation_event.state_before != evaluation_event.requested_state_after
            or evaluation_event.code_version != self.code_version
            or evaluation_event.configuration_hash != self.configuration_hash
            or evaluation_event.timestamp != authority_record.created_at
            or evaluation_event.reason != "evaluated one preregistered hypothesis under its frozen policy"
            or evaluation_event.dataset_identifiers or evaluation_event.random_seeds
            or evaluation_event.evaluator_outputs or evaluation_event.supersedes_event_id is not None
        ):
            return None
        if authority.is_bounded_mean:
            try:
                candidates = _matching_hypothesis_evaluation_events(
                    events, authority.evaluation_binding,
                )
                index = authority.evaluation_event_index
                if (
                    candidates != ((index, evaluation_event),)
                    or index == 0
                    or evaluation_event.state_before != events[index - 1].requested_state_after
                    or any(later.event_type == "CORRECTION"
                           and later.supersedes_event_id == evaluation_event.event_id
                           for later in events[index + 1:])
                    or _matching_hypothesis_evaluation_authority_slots(
                        self.registry, self.registry.list_records(), authority,
                    ) != (authority_record,)
                ):
                    return None
                _require_bounded_hypothesis_evaluation_chronology(
                    {"repository": self, "result": result_stored.research_object,
                     "result_record": result_stored.artifact,
                     "statistical_test": statistical_stored.research_object,
                     "statistical_record": statistical_stored.artifact,
                     "source_hashes": authority.source_artifact_hashes},
                    evaluation_event, index, events,
                )
            except (ArtifactError, LedgerError, ValidationError):
                return None
        return successor_stored

    def _validate_source_bound_parent_lineage(
        self,
        record: CanonicalResearchObject,
        by_content: Mapping[str, _StoredObject],
    ) -> int:
        """Verify current, prior-visible storage for source-bound ancestors.

        The v2 promotion resolver already replays the authoritative contract,
        run specification, manifest, raw outputs, and statistics.  This helper
        proves that the canonical objects joined to those source facts were
        genuinely materialized before the Result; it does not reinterpret
        caller-authored ancestor authority labels.
        """

        events = self.ledger.events()
        event_indexes = {event.event_id: index for index, event in enumerate(events)}
        stored_values = tuple(by_content.values())
        visiting: set[str] = set()
        validated: dict[str, int] = {}
        contexts: dict[str, tuple[_StoredObject, LedgerEvent, int]] = {}
        stack: list[tuple[CanonicalResearchObject, int, bool]] = [(record, 0, False)]
        node_count = 0
        edge_count = 0
        while stack:
            current, depth, exiting = stack.pop()
            digest = current.content_hash
            if exiting:
                stored, event, event_index = contexts[digest]
                expected_parents = set(self._embedded_artifact_hashes(current))
                for reference in current.parents:
                    parent = by_content.get(reference.content_hash)
                    if parent is None:  # pragma: no cover - checked on entry
                        raise ValidationError("source-bound canonical parent is absent")
                    parent_index = validated.get(reference.content_hash)
                    if parent_index is None or parent_index >= event_index:
                        raise ValidationError(
                            "source-bound canonical parent predates none of its inputs"
                        )
                    expected_parents.add(parent.artifact.sha256)
                if (
                    stored.artifact.parent_artifacts != tuple(sorted(expected_parents))
                    or stored.artifact.origin
                    != (f"research-state:{current.object_type}:{current.object_id}:r1")
                    or stored.artifact.creation_command != self.creation_command
                ):
                    raise ValidationError(
                        "source-bound canonical parent provenance differs"
                    )
                visiting.remove(digest)
                validated[digest] = event_index
                continue
            if digest in validated:
                continue
            if digest in visiting:
                raise ValidationError(
                    "source-bound canonical parent graph contains a cycle"
                )
            if depth > MAX_CANONICAL_ANCESTRY_DEPTH:
                raise ValidationError(
                    "source-bound canonical parent graph exceeds the ancestry depth limit"
                )
            node_count += 1
            if node_count > MAX_CANONICAL_ANCESTRY_NODES:
                raise ValidationError(
                    "source-bound canonical parent graph exceeds the ancestry node limit"
                )
            edge_count += len(current.parents)
            if edge_count > MAX_CANONICAL_ANCESTRY_EDGES:
                raise ValidationError(
                    "source-bound canonical parent graph exceeds the ancestry edge limit"
                )
            stored = by_content.get(digest)
            if stored is None or stored.research_object != current:
                raise ValidationError(
                    "source-bound canonical parent is absent or substituted"
                )
            revisions = tuple(
                item.research_object
                for item in stored_values
                if item.research_object.object_type == current.object_type
                and item.research_object.object_id == current.object_id
            )
            evaluation_successor = self._source_bound_hypothesis_evaluation_successor(
                current,
                revisions,
                by_content,
                events,
            )
            if (
                (len(revisions) != 1 and evaluation_successor is None)
                or current.revision != 1
                or current.supersedes_content_hash is not None
                or current.code_version != self.code_version
            ):
                raise ValidationError(
                    "source-bound canonical parent is stale or revised"
                )
            self._validate_producer_authority(current)
            event = self._materialization_event(stored.artifact.sha256, current)
            event_index = (
                event_indexes.get(event.event_id) if event is not None else None
            )
            if event is None or event_index is None or event.event_hash is None:
                raise ValidationError(
                    "source-bound canonical parent lacks exact materialization"
                )
            corrections = tuple(
                candidate
                for candidate in events[event_index + 1 :]
                if candidate.event_type == "CORRECTION"
                and candidate.supersedes_event_id == event.event_id
            )
            allowed_correction_id = (
                f"rs-{evaluation_successor.artifact.sha256[:48]}"
                if evaluation_successor is not None
                else None
            )
            if corrections and (
                len(corrections) != 1
                or corrections[0].event_id != allowed_correction_id
            ):
                raise ValidationError(
                    "source-bound canonical parent materialization was corrected"
                )
            for reference in current.parents:
                parent = by_content.get(reference.content_hash)
                if (
                    parent is None
                    or parent.research_object.object_type != reference.object_type
                    or parent.research_object.object_id != reference.object_id
                ):
                    raise ValidationError(
                        "source-bound canonical parent identity is substituted"
                    )
            contexts[digest] = (stored, event, event_index)
            visiting.add(digest)
            stack.append((current, depth, True))
            for reference in reversed(current.parents):
                parent = by_content[reference.content_hash]
                stack.append((parent.research_object, depth + 1, False))

        result = validated.get(record.content_hash)
        if result is None:  # pragma: no cover - non-empty traversal proves this
            raise ValidationError("source-bound canonical parent was not validated")
        return result

    def _expected_scientific_result_ancestor_authority(
        self,
        record: CanonicalResearchObject,
        result_projection: Any,
    ) -> tuple[str, ...]:
        """Return the exact source-owned hashes for one v2 protocol ancestor."""

        spec_record = self._require_frozen_pass_artifact(
            result_projection.frozen_run_spec_artifact_sha256,
            logical_type="frozen_run_spec",
            creator_role=Role.EXPERIMENT_RUNNER,
        )
        try:
            from .experiments import (
                require_scientific_execution_run_spec,
                resolve_scientific_method_definition_binding,
            )

            typed_spec = require_scientific_execution_run_spec(
                self.registry,
                frozen_run_spec_artifact_sha256=spec_record.sha256,
            )
            method_binding = resolve_scientific_method_definition_binding(
                self.registry,
                spec=typed_spec,
            )
        except Exception as exc:
            raise ValidationError(
                "scientific Result Method/input projection failed fresh replay"
            ) from exc
        spec = typed_spec.to_dict()
        configuration_hash = spec.get("configuration_sha256")
        data_hash = spec.get("data_sha256")
        validate_sha256(configuration_hash, "projected configuration SHA-256")
        validate_sha256(data_hash, "projected Dataset SHA-256")
        dataset_authority = (
            tuple(record.authority_artifact_hashes)
            if isinstance(record, Dataset)
            and len(record.authority_artifact_hashes) == 1
            and self.registry.get_metadata(
                record.authority_artifact_hashes[0]
            ).logical_type
            == SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE
            else (data_hash,)
        )
        split_authority = (
            tuple(record.authority_artifact_hashes)
            if isinstance(record, Split)
            and len(record.authority_artifact_hashes) == 1
            and self.registry.get_metadata(
                record.authority_artifact_hashes[0]
            ).logical_type
            == SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE
            else (
                result_projection.contract_artifact_sha256,
                data_hash,
            )
        )
        source_by_type: dict[type[CanonicalResearchObject], tuple[str, ...]] = {
            Method: (
                method_binding.method_definition_artifact_sha256
                if method_binding is not None
                else result_projection.execution_code_revision.removeprefix(
                    "sha256:"
                ),
            ),
            Implementation: (
                result_projection.execution_code_revision.removeprefix("sha256:"),
                configuration_hash,
            ),
            Hypothesis: (result_projection.contract_artifact_sha256,),
            Dataset: dataset_authority,
            Split: split_authority,
            Metric: (result_projection.contract_artifact_sha256,),
            Baseline: (result_projection.contract_artifact_sha256,),
            Experiment: (
                result_projection.contract_artifact_sha256,
                configuration_hash,
            ),
            Run: (
                configuration_hash,
                result_projection.frozen_run_spec_artifact_sha256,
                result_projection.output_manifest_artifact_sha256,
                *result_projection.raw_source_artifact_hashes,
                *(
                    (result_projection.scientific_execution_authority_artifact_sha256,)
                    if hasattr(
                        result_projection,
                        "scientific_execution_authority_artifact_sha256",
                    )
                    else ()
                ),
            ),
        }
        expected = source_by_type.get(type(record))
        if expected is None:
            raise ValidationError(
                "unsupported scientific Result source-bound ancestor type"
            )
        return tuple(sorted(expected))

    def _resolve_scientific_result_ancestor_authority(
        self,
        record: CanonicalResearchObject,
        records: tuple[ArtifactRecord, ...],
        by_content: Mapping[str, _StoredObject],
    ) -> _ResolvedObjectAuthority | None:
        """Reopen a versioned Result before treating exact ancestors as current."""

        supported = (
            Method,
            Implementation,
            Hypothesis,
            Dataset,
            Split,
            Metric,
            Baseline,
            Experiment,
            Run,
        )
        if not isinstance(record, supported):
            return None

        def contains_target(candidate: Result) -> bool:
            pending = [(reference, 1) for reference in candidate.parents]
            visited: set[str] = set()
            edge_count = len(candidate.parents)
            while pending:
                reference, depth = pending.pop()
                if reference.content_hash in visited:
                    continue
                if depth > MAX_CANONICAL_ANCESTRY_DEPTH:
                    raise ValidationError(
                        "scientific Result ancestry exceeds the depth limit"
                    )
                if len(visited) >= MAX_CANONICAL_ANCESTRY_NODES:
                    raise ValidationError(
                        "scientific Result ancestry exceeds the node limit"
                    )
                visited.add(reference.content_hash)
                if reference.content_hash == record.content_hash:
                    return True
                stored = by_content.get(reference.content_hash)
                if stored is not None:
                    parents = stored.research_object.parents
                    edge_count += len(parents)
                    if edge_count > MAX_CANONICAL_ANCESTRY_EDGES:
                        raise ValidationError(
                            "scientific Result ancestry exceeds the edge limit"
                        )
                    pending.extend((parent, depth + 1) for parent in parents)
            return False

        candidates: list[Result] = []
        for stored in by_content.values():
            candidate = stored.research_object
            if not isinstance(candidate, Result) or not contains_target(candidate):
                continue
            try:
                logical_types = {
                    self.registry.get_metadata(digest).logical_type
                    for digest in candidate.evaluation_artifact_hashes
                }
            except Exception as exc:
                raise ValidationError(
                    "source-bound ancestor names unreadable Result authority"
                ) from exc
            if logical_types.intersection(
                {
                    "scientific_result_promotion_authority",
                    "scientific_result_promotion_authority_v3",
                }
            ):
                candidates.append(candidate)
        if not candidates:
            return None
        expected_authorities: set[tuple[str, ...]] = set()
        for candidate in sorted(candidates, key=lambda item: item.content_hash):
            candidate_records = self._authority_records(candidate)
            logical_types = {item.logical_type for item in candidate_records}
            if "scientific_result_promotion_authority_v3" in logical_types:
                _resolution, result_projection, _promotion = (
                    self._resolve_scientific_result_promotion_v3(
                        candidate_records,
                        expected_result_id=candidate.object_id,
                        expected_execution_run_id=candidate.run_ids[0],
                    )
                )
            else:
                _resolution, projection, _promotion, _event = (
                    self._resolve_scientific_result_promotion(
                        candidate_records,
                        expected_result_id=candidate.object_id,
                        expected_execution_run_id=candidate.run_ids[0],
                    )
                )
                result_projection = projection.result_state_projection
            expected = self._expected_scientific_result_ancestor_authority(
                record,
                result_projection,
            )
            expected_authorities.add(expected)
            if tuple(sorted(record.authority_artifact_hashes)) != expected:
                raise ValidationError(
                    "source-bound canonical ancestor authority differs from an "
                    "exact containing scientific Result projection"
                )
            # Every containing Result is freshly replayed.  No candidate hash is
            # selected as the authority branch; a malformed sibling invalidates
            # the shared ancestor instead of allowing a favorable choice.
            self._resolve_object_authority(candidate, by_content)
        if len(expected_authorities) != 1:
            raise ValidationError(
                "containing scientific Results project different ancestor authority"
            )
        source_scientific = (
            isinstance(record, Dataset)
            and len(records) == 1
            and records[0].logical_type == SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE
        ) or (
            isinstance(record, Split)
            and len(records) == 1
            and records[0].logical_type
            == SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE
        )
        # Dataset and Split state carry their own independently replayed
        # acquisition/partition authority.  Other ancestors are immutable
        # graph bindings, never independent Result-promotion authority.
        return _ResolvedObjectAuthority(
            records,
            source_scientific,
        )

    def _scientific_result_bundle_objects(
        self,
        result: Result,
        by_content: Mapping[str, _StoredObject],
    ) -> tuple[_StoredObject, ...]:
        """Return the exact current topological closure for one v2 Result."""

        supported = {
            "Method",
            "Implementation",
            "Hypothesis",
            "Dataset",
            "Split",
            "Metric",
            "Baseline",
            "Experiment",
            "Run",
        }
        pending = [(reference, 1) for reference in result.parents]
        ancestors: dict[str, _StoredObject] = {}
        edge_count = len(result.parents)
        while pending:
            reference, depth = pending.pop()
            if depth > MAX_CANONICAL_ANCESTRY_DEPTH:
                raise ValidationError(
                    "scientific Result bundle exceeds the ancestry depth limit"
                )
            stored = by_content.get(reference.content_hash)
            if (
                stored is None
                or stored.research_object.object_type != reference.object_type
                or stored.research_object.object_id != reference.object_id
                or stored.research_object.object_type not in supported
            ):
                raise ValidationError(
                    "scientific Result bundle has an absent or unsupported ancestor"
                )
            if stored.artifact.sha256 in ancestors:
                continue
            if len(ancestors) >= MAX_CANONICAL_ANCESTRY_NODES:
                raise ValidationError(
                    "scientific Result bundle exceeds the ancestry node limit"
                )
            ancestors[stored.artifact.sha256] = stored
            parents = stored.research_object.parents
            edge_count += len(parents)
            if edge_count > MAX_CANONICAL_ANCESTRY_EDGES:
                raise ValidationError(
                    "scientific Result bundle exceeds the ancestry edge limit"
                )
            pending.extend((parent, depth + 1) for parent in parents)

        result_stored = by_content.get(result.content_hash)
        if result_stored is None or result_stored.research_object != result:
            raise ValidationError(
                "scientific Result bundle completion requires stored Result bytes"
            )
        statistical_children = tuple(
            stored
            for stored in by_content.values()
            if isinstance(stored.research_object, StatisticalTest)
            and stored.research_object.parents
            == (
                ObjectReference(
                    "Result",
                    result.object_id,
                    result.content_hash,
                    "tests",
                    True,
                ),
            )
        )
        if len(statistical_children) > 1:
            raise ValidationError(
                "scientific Result bundle has ambiguous StatisticalTest children"
            )
        ordered = tuple(
            sorted(
                (
                    *ancestors.values(),
                    result_stored,
                    *statistical_children,
                ),
                key=lambda item: (
                    datetime.fromisoformat(
                        item.research_object.created_at.replace("Z", "+00:00")
                    ),
                    item.research_object.object_type,
                    item.research_object.object_id,
                ),
            )
        )
        if len({item.research_object.created_at for item in ordered}) != len(ordered):
            raise ValidationError(
                "scientific Result bundle timestamps must be strictly ordered"
            )
        return ordered

    def _require_scientific_result_bundle_completion(
        self,
        result: Result,
        by_content: Mapping[str, _StoredObject],
        *,
        promotion_record: ArtifactRecord,
        expected_scientific_evidence_eligible: bool,
    ) -> ArtifactRecord:
        """Require the final receipt/event that makes a persisted bundle visible."""

        ordered = self._scientific_result_bundle_objects(result, by_content)
        statistical_id = next(
            (
                item.research_object.object_id
                for item in ordered
                if isinstance(item.research_object, StatisticalTest)
            ),
            None,
        )
        object_bindings = [
            {
                "object_type": item.research_object.object_type,
                "object_id": item.research_object.object_id,
                "content_hash": item.research_object.content_hash,
                "artifact_sha256": item.artifact.sha256,
                "artifact_record_hash": str(item.artifact.record_hash),
                "created_at": item.research_object.created_at,
            }
            for item in ordered
        ]
        expected_payload = {
            "schema_version": SCIENTIFIC_RESULT_STATE_BUNDLE_PAYLOAD_SCHEMA,
            "ledger_run_id": self.run_id,
            "execution_run_id": result.run_ids[0],
            "canonical_state_code_version": self.code_version,
            "result_id": result.object_id,
            "statistical_test_id": statistical_id,
            "promotion_receipt_artifact_sha256": promotion_record.sha256,
            "objects": object_bindings,
            "scientific_evidence_eligible": (expected_scientific_evidence_eligible),
        }
        expected_parents = (
            promotion_record.sha256,
            *(item.artifact.sha256 for item in ordered),
        )
        # Completion is a checkpoint *at* the final canonical object state.
        # Ledger order, not an invented later wall-clock instant, proves that
        # the checkpoint follows every materialization.  Sharing this timestamp
        # also leaves the next representable instant available to a valid
        # Result-only -> StatisticalTest continuation.
        expected_created_at = ordered[-1].research_object.created_at
        candidates: list[ArtifactRecord] = []
        for artifact in self.registry.list_records():
            if artifact.logical_type != SCIENTIFIC_RESULT_STATE_BUNDLE_LOGICAL_TYPE:
                continue
            value = self._read_authority_json(artifact)
            if (
                value.get("ledger_run_id") == self.run_id
                and value.get("result_id") == result.object_id
                and value.get("statistical_test_id") == statistical_id
            ):
                candidates.append(artifact)
        if len(candidates) != 1:
            raise ValidationError(
                "scientific Result state lacks one exact bundle-completion receipt"
            )
        receipt = candidates[0]
        if (
            receipt.creator_role is not Role.CLAIM_VERIFIER
            or receipt.schema_version != SCIENTIFIC_RESULT_STATE_BUNDLE_SCHEMA_VERSION
            or receipt.mime_type != "application/json"
            or receipt.origin
            != ("deterministic scientific Result canonical-state bundle completion")
            or receipt.creation_command
            != (
                "scientist-one",
                "research-state",
                "complete-scientific-result-bundle",
            )
            or receipt.validation_result != "PASS"
            or receipt.frozen is not True
            or receipt.created_at != expected_created_at
            or receipt.parent_artifacts != expected_parents
            or self._read_authority_json(receipt) != expected_payload
        ):
            raise ValidationError(
                "scientific Result bundle-completion receipt was substituted"
            )
        expected_metadata = {
            "research_state_operation": "BUNDLE_COMPLETE",
            "result_id": result.object_id,
            "statistical_test_id": statistical_id,
            "bundle_receipt_artifact_sha256": receipt.sha256,
            "object_artifact_hashes": [item.artifact.sha256 for item in ordered],
        }
        events = self.ledger.events()
        expected_event_id = f"rsb-{receipt.sha256[:48]}"
        matching_events = tuple(
            (index, event)
            for index, event in enumerate(events)
            if event.event_id == expected_event_id
            and event.run_id == self.run_id
            and event.actor_role is Role.CLAIM_VERIFIER
            and event.timestamp == receipt.created_at
            and event.state_before == self.state
            and event.requested_state_after == self.state
            and event.artifact_hashes == (receipt.sha256,)
            and event.code_version == self.code_version
            and event.configuration_hash == self.configuration_hash
            and event.event_type == "CHECKPOINT"
            and thaw_json(event.metadata) == expected_metadata
        )
        materialization_indexes: list[int] = []
        for item in ordered:
            materialization = self._materialization_event(
                item.artifact.sha256,
                item.research_object,
            )
            if materialization is None:
                raise ValidationError(
                    "scientific Result bundle completion predates materialization"
                )
            materialization_indexes.append(
                next(
                    index
                    for index, event in enumerate(events)
                    if event.event_id == materialization.event_id
                )
            )
        if (
            len(matching_events) != 1
            or matching_events[0][1].event_hash is None
            or matching_events[0][0] <= max(materialization_indexes)
        ):
            raise ValidationError(
                "scientific Result bundle completion lacks one exact ledger event"
            )
        completion_index, completion_event = matching_events[0]
        if any(
            event.event_type == "CORRECTION"
            and event.supersedes_event_id == completion_event.event_id
            for event in events[completion_index + 1 :]
        ):
            raise ValidationError(
                "scientific Result bundle completion event was corrected"
            )
        return receipt

    def _require_final_venue_projection(
        self,
        record: VenueAssessment,
        by_content: Mapping[str, _StoredObject],
        *,
        assessment_record: ArtifactRecord,
        authority: Any,
    ) -> None:
        """Compare the complete canonical view after full final-Venue ownership."""

        from .paper_pipeline import VenueFit as PaperVenueFit

        assessment = authority.assessment
        try:
            classification = VenueFit(assessment.classification.value)
        except ValueError as exc:
            raise ValidationError(
                "paper and canonical venue classifications diverged"
            ) from exc
        if not isinstance(assessment.classification, PaperVenueFit):
            raise ValidationError(
                "final venue assessment classification is not typed"
            )
        expected_status = {
            VenueFit.NOT_READY: RecordStatus.REJECTED,
            VenueFit.UNCERTAIN: RecordStatus.INCONCLUSIVE,
            VenueFit.WORKSHOP_FIT: RecordStatus.COMPLETE,
            VenueFit.SPECIALIZED_CONFERENCE_FIT: RecordStatus.COMPLETE,
            VenueFit.SOLID_CONFERENCE_FIT: RecordStatus.COMPLETE,
            VenueFit.STRONG_CONFERENCE_CANDIDATE: RecordStatus.COMPLETE,
        }[classification]
        expected_metadata = {
            "authoritative_bundle_artifact_hash": (
                assessment.bundle_artifact_hash
            ),
            "paper_candidate_artifact_hash": (
                assessment.candidate_artifact_hash
            ),
            "paper_verification_artifact_hash": (
                authority.paper_verification_artifact_hash
            ),
            "profile_artifact_hash": assessment.profile_artifact_hash,
            "readiness_manifest_hash": (assessment.readiness_manifest_hash),
            "venue_assessment_artifact_hash": assessment_record.sha256,
        }
        claim_references = tuple(
            item for item in record.parents if item.object_type == "Claim"
        )
        claim_parents = self._resolved_parent_objects(
            record,
            by_content,
            "Claim",
        )
        if (
            len(record.parents) != len(authority.evidence_ids)
            or len(claim_references) != len(authority.evidence_ids)
            or tuple(item.object_id for item in claim_references)
            != authority.evidence_ids
            or any(
                item.relation != "assesses" or item.evaluated is not True
                for item in claim_references
            )
            or tuple(item.object_id for item in claim_parents)
            != authority.evidence_ids
            or any(
                item.status is not RecordStatus.VERIFIED
                or item.verification_status is not VerificationStatus.VERIFIED
                for item in claim_parents
            )
            or record.object_id != authority.assessment_id
            or record.status is not expected_status
            or record.created_at != authority.assessed_at
            or record.revision != 1
            or record.supersedes_content_hash is not None
            or record.relationships
            or record.authority_artifact_hashes != (assessment_record.sha256,)
            or record.code_version != self.code_version
            or thaw_json(record.metadata) != expected_metadata
            or record.venue != authority.venue_family.value
            or record.profile != assessment.profile_id
            or record.classification is not classification
            or record.evidence_ids != authority.evidence_ids
            or record.blockers
            != tuple(item.value for item in assessment.hard_blockers)
            or record.assessed_at != authority.assessed_at
        ):
            raise ValidationError(
                "canonical VenueAssessment differs from final typed authority"
            )

    def _resolve_object_authority(
        self,
        record: CanonicalResearchObject,
        by_content: Mapping[str, _StoredObject],
        *,
        allow_unmaterialized_source_bound: bool = False,
    ) -> _ResolvedObjectAuthority:
        """Resolve the exact typed authority for a canonical semantic assertion.

        This deliberately has no generic ``logical_type`` fallback.  New source
        schemas must add a bounded resolver here before they can promote state.
        """

        self._validate_canonical_ancestry_budget(record, by_content)

        records = self._authority_records(record)
        if not records:
            return _ResolvedObjectAuthority(())

        if isinstance(record, Run):
            scientific_run = self._resolve_scientific_execution_canonical_run(
                record,
                records,
                by_content,
            )
            if scientific_run is not None:
                return scientific_run

        source_bound = self._resolve_scientific_result_ancestor_authority(
            record,
            records,
            by_content,
        )
        if source_bound is not None:
            return source_bound

        if isinstance(record, ResearchQuestion):
            if record.gate_outcome is ResearchQuestionOutcome.PROCEED:
                self._require_exact_authority_roles(
                    records,
                    {
                        "research_question_gate_receipt": frozenset(
                            {Role.CLAIM_VERIFIER}
                        ),
                    },
                )
                if len(records) != 1:
                    raise ValidationError(
                        "positive research question requires one exact gate receipt"
                    )
                try:
                    from .scientific_design import (
                        ResearchQuestionGateReceipt,
                        require_research_question_gate_receipt,
                    )

                    receipt_value = self._read_authority_json(records[0])
                    stated_receipt = ResearchQuestionGateReceipt.from_dict(
                        receipt_value
                    )
                    if stated_receipt.semantic_judgment_artifact_sha256 is None:
                        raise ValidationError(
                            "positive canonical research question requires a "
                            "proposal-bound semantic judgment"
                        )
                    receipt = require_research_question_gate_receipt(
                        self.registry,
                        self.ledger,
                        receipt_artifact_sha256=records[0].sha256,
                        expected_run_id=self.run_id,
                        expected_object_id=stated_receipt.object_id,
                        expected_question_object_id=record.object_id,
                    )
                except Exception as exc:
                    raise ValidationError(
                        "positive research-question gate authority is invalid"
                    ) from exc
                if (
                    receipt.question_object_id != record.object_id
                    or receipt.research_goal != record.research_goal
                    or receipt.question != record.question
                    or receipt.falsification_condition != record.falsification_condition
                    or receipt.outcome.value != record.gate_outcome.value
                ):
                    raise ValidationError(
                        "canonical research question differs from its freshly "
                        "replayed gate receipt"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    scientific_evidence_eligible=receipt.scientific_gate_passed,
                )
            self._require_exact_authority_roles(
                records,
                {
                    "research_brief": frozenset({Role.PROBLEM_INVESTIGATOR}),
                    "problem_investigation_state": frozenset(
                        {Role.PROBLEM_INVESTIGATOR}
                    ),
                },
            )
            if len(records) != 2:
                raise ValidationError(
                    "research question authority requires a brief and investigation state"
                )
            brief_record = self._one_record(records, "research_brief")
            state_record = self._one_record(records, "problem_investigation_state")
            brief_payload = self._read_authority_json(brief_record)
            state_payload = self._read_authority_json(state_record)
            try:
                from .scientific_design import ProblemInvestigationState

                investigation = ProblemInvestigationState.from_dict(state_payload)
            except Exception as exc:
                raise ValidationError(
                    "research question investigation authority is invalid"
                ) from exc
            if (
                investigation.status.value != "READY_FOR_BRIEF"
                or brief_record.parent_artifacts != (state_record.sha256,)
            ):
                raise ValidationError(
                    "research brief is not bound to one brief-ready investigation state"
                )
            brief = self._nested_mapping(brief_payload, "research_brief")
            goal = self._nested_mapping(brief, "goal")
            directions = brief.get("directions")
            selected_id = brief.get("selected_direction_id")
            if not isinstance(directions, list) or not isinstance(selected_id, str):
                raise ValidationError("research brief direction authority is malformed")
            selected = tuple(
                item
                for item in directions
                if isinstance(item, Mapping) and item.get("direction_id") == selected_id
            )
            assessment = self._nested_mapping(brief, "assessment")
            if (
                len(selected) != 1
                or selected[0].get("question") != record.question
                or goal.get("question") != record.research_goal
                or brief.get("investigation_state_artifact_hash") != state_record.sha256
                or brief.get("investigation_state_sha256") != investigation.sha256
                or (
                    record.gate_outcome is not None
                    and assessment.get("outcome") != record.gate_outcome.value
                )
            ):
                raise ValidationError(
                    "canonical research question differs from its checked brief"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, PriorWork):
            self._require_exact_authority_roles(
                records,
                {
                    "investigation_literature_record": frozenset(
                        {Role.EVIDENCE_CURATOR}
                    ),
                    "reference_verification": frozenset({Role.CLAIM_VERIFIER}),
                },
            )
            if len(records) != 1:
                raise ValidationError("prior work requires one exact source authority")
            source = records[0]
            payload = self._read_authority_json(source)
            evidence_parents = self._resolved_parent_objects(
                record,
                by_content,
                "Evidence",
            )
            if (
                tuple(item.object_id for item in evidence_parents)
                != record.evidence_ids
            ):
                raise ValidationError(
                    "canonical prior-work evidence IDs differ from evaluated Evidence parents"
                )
            if source.logical_type == "investigation_literature_record":
                if evidence_parents or record.evidence_ids:
                    raise ValidationError(
                        "non-evidentiary investigation prior work cannot claim "
                        "canonical Evidence parents"
                    )
                try:
                    from .literature import CitationGraphNode
                    from .scientific_design import (
                        LiteratureRecord,
                        _resolve_registry_investigation_record,
                        _resolve_registry_scholarly_record,
                    )

                    literature_value = self._nested_mapping(
                        payload,
                        "literature_record",
                    )
                    literature = LiteratureRecord(
                        source_id=literature_value["source_id"],
                        title=literature_value["title"],
                        stable_locator=literature_value["stable_locator"],
                        full_text_sha256=literature_value["full_text_sha256"],
                        methodology_relevance=literature_value["methodology_relevance"],
                        problem_alignment=literature_value["problem_alignment"],
                        structured_notes=tuple(literature_value["structured_notes"]),
                        full_text_reviewed=literature_value["full_text_reviewed"],
                        destroys_gap=literature_value["destroys_gap"],
                    )
                    scholarly_hashes = tuple(
                        digest
                        for digest in source.parent_artifacts
                        if self.registry.get_metadata(digest).logical_type
                        == "normalized_scholarly_record"
                    )
                    if len(scholarly_hashes) != 1:
                        raise ValidationError(
                            "investigation prior work lacks one scholarly-record root"
                        )
                    scholarly = _resolve_registry_scholarly_record(
                        self.registry,
                        scholarly_hashes[0],
                    )
                    resolved_literature = _resolve_registry_investigation_record(
                        self.registry,
                        literature_record=literature,
                        literature_record_artifact_hash=source.sha256,
                        expected_node=CitationGraphNode.from_record(
                            scholarly.scholarly_record
                        ),
                        require_full_text_review=True,
                    ).literature_record
                except Exception as exc:
                    raise ValidationError(
                        "canonical prior-work investigation authority is invalid"
                    ) from exc
                expected_dimensions = {
                    "destroys_gap": resolved_literature.destroys_gap,
                    "full_text_sha256": resolved_literature.full_text_sha256,
                    "methodology_relevance": (
                        resolved_literature.methodology_relevance
                    ),
                    "problem_alignment": resolved_literature.problem_alignment,
                    "structured_notes": list(resolved_literature.structured_notes),
                    "tier": resolved_literature.tier.value,
                }
                if (
                    record.status is not RecordStatus.DRAFT
                    or record.title != resolved_literature.title
                    or record.source_identifier != resolved_literature.stable_locator
                    or record.verification_depth
                    is not ReferenceVerificationDepth.LEVEL_3
                    or thaw_json(record.comparison_dimensions) != expected_dimensions
                    or payload.get("scientific_evidence") is not False
                ):
                    raise ValidationError(
                        "canonical prior work differs from its non-evidentiary "
                        "investigation projection"
                    )
            else:
                try:
                    from .literature import CitationGraphNode
                    from .scientific_design import (
                        _resolve_registry_reference_verification,
                        _resolve_registry_scholarly_record,
                    )

                    scholarly_hash = payload.get("scholarly_record_artifact_hash")
                    if not isinstance(scholarly_hash, str):
                        raise ValidationError(
                            "reference prior work lacks a scholarly-record root"
                        )
                    scholarly = _resolve_registry_scholarly_record(
                        self.registry,
                        scholarly_hash,
                    )
                    resolved_reference = _resolve_registry_reference_verification(
                        self.registry,
                        source.sha256,
                        expected_target_sha256=payload["ranking_target_sha256"],
                        expected_node=CitationGraphNode.from_record(
                            scholarly.scholarly_record
                        ),
                        expected_citation_id=payload["citation_id"],
                        expected_claim_text=payload["claim_text"],
                        expected_claim_target_sha256=payload["claim_target_sha256"],
                    )
                except Exception as exc:
                    raise ValidationError(
                        "canonical prior-work reference authority is invalid"
                    ) from exc
                reference = resolved_reference.reference
                verification = resolved_reference.verification
                if reference.identifier is not None:
                    source_identifier = (
                        f"{reference.identifier.kind.value}:"
                        f"{reference.identifier.value}"
                    )
                else:
                    source_identifier = reference.reference_text
                effective_depth = ReferenceVerificationDepth[
                    f"LEVEL_{int(verification.level)}"
                ]
                fixture_source = "fixture_notice" in payload
                if fixture_source and effective_depth in {
                    ReferenceVerificationDepth.LEVEL_4,
                    ReferenceVerificationDepth.LEVEL_5,
                }:
                    effective_depth = ReferenceVerificationDepth.LEVEL_3
                expected_status = (
                    RecordStatus.VERIFIED
                    if not fixture_source
                    and effective_depth
                    in {
                        ReferenceVerificationDepth.LEVEL_4,
                        ReferenceVerificationDepth.LEVEL_5,
                    }
                    else RecordStatus.DRAFT
                )
                if expected_status is RecordStatus.DRAFT:
                    if evidence_parents or record.evidence_ids:
                        raise ValidationError(
                            "non-evidentiary reference prior work cannot claim "
                            "canonical Evidence parents"
                        )
                else:
                    for evidence in evidence_parents:
                        if not isinstance(evidence, Evidence):
                            raise ValidationError(
                                "verified prior-work Evidence parent is malformed"
                            )
                        resolved_evidence = self._resolve_object_authority(
                            evidence,
                            by_content,
                        )
                        if (
                            evidence.status is not RecordStatus.VERIFIED
                            or evidence.verification_status
                            is not VerificationStatus.VERIFIED
                            or evidence.source_artifact_hashes != (source.sha256,)
                            or evidence.authority_artifact_hashes != (source.sha256,)
                            or tuple(item.sha256 for item in resolved_evidence.records)
                            != (source.sha256,)
                            or evidence.verification_depth is not effective_depth
                            or evidence.locator != f"artifact:{source.sha256}"
                            or evidence.supports_claim_ids
                            or evidence.contradicts_claim_ids
                        ):
                            raise ValidationError(
                                "verified prior-work Evidence parent differs from "
                                "its exact reference authority"
                            )
                if (
                    reference.title != record.title
                    or record.source_identifier != source_identifier
                    or record.verification_depth is not effective_depth
                    or record.status is not expected_status
                    or thaw_json(record.comparison_dimensions) != {}
                ):
                    raise ValidationError(
                        "canonical prior work differs from reference verification"
                    )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Dataset):
            self._require_exact_authority_roles(
                records,
                {
                    "dataset_fixture": frozenset({Role.EVIDENCE_CURATOR}),
                    SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE: frozenset(
                        {Role.EVIDENCE_CURATOR}
                    ),
                    "autonomous_implementation.fixture_data": frozenset(
                        {Role.EVIDENCE_CURATOR}
                    ),
                    "autonomous_implementation.fixture_data_derivation": frozenset(
                        {Role.EVIDENCE_CURATOR}
                    ),
                },
            )
            types = {item.logical_type for item in records}
            if types == {"dataset_fixture"} and len(records) == 1:
                payload = self._read_authority_json(records[0], require_canonical=False)
                if payload.get("schema_version") != record.version:
                    raise ValidationError(
                        "canonical dataset version differs from frozen data"
                    )
            elif (
                types == {SCIENTIFIC_DATASET_AUTHORITY_LOGICAL_TYPE}
                and len(records) == 1
            ):
                authority = require_scientific_dataset_authority(
                    self.registry,
                    self.ledger,
                    run_id=self.run_id,
                    authority_artifact_hash=records[0].sha256,
                    expected_dataset_id=record.object_id,
                    expected_version=record.version,
                )
                if (
                    record.status is not RecordStatus.FROZEN
                    or record.name != authority.name
                    or record.artifact_hashes != (authority.authority_artifact_hash,)
                    or record.access_status != "AVAILABLE"
                    or record.license != authority.license_identifier
                ):
                    raise ValidationError(
                        "canonical scientific Dataset differs from audited acquisition"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    scientific_evidence_eligible=True,
                )
            elif (
                types
                == {
                    "autonomous_implementation.fixture_data",
                    "autonomous_implementation.fixture_data_derivation",
                }
                and len(records) == 2
            ):
                data = self._one_record(
                    records, "autonomous_implementation.fixture_data"
                )
                derivation = self._one_record(
                    records, "autonomous_implementation.fixture_data_derivation"
                )
                data_payload = self._read_authority_json(data)
                derivation_payload = self._read_authority_json(derivation)
                if (
                    data.parent_artifacts != (derivation.sha256,)
                    or data_payload.get("values") != derivation_payload.get("values")
                    or derivation_payload.get("scientific_evidence") is not False
                    or derivation_payload.get("schema_version")
                    != "AUTONOMOUS_IMPLEMENTATION_FIXTURE_DATA_DERIVATION_V1"
                    or record.version != derivation_payload.get("schema_version")
                ):
                    raise ValidationError(
                        "autonomous dataset derivation is not exact and non-evidentiary"
                    )
            else:
                raise ValidationError("unsupported canonical dataset authority bundle")
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Split):
            dataset_parents = self._resolved_parent_objects(
                record,
                by_content,
                "Dataset",
            )
            if (
                len(dataset_parents) != 1
                or dataset_parents[0].object_id != record.dataset_id
            ):
                raise ValidationError(
                    "canonical split lacks one exact evaluated Dataset parent"
                )
            self._require_exact_authority_roles(
                records,
                {
                    "dataset_fixture": frozenset({Role.EVIDENCE_CURATOR}),
                    SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE: frozenset(
                        {Role.PROTOCOL_DESIGNER}
                    ),
                    "evaluation_contract": frozenset({Role.PROTOCOL_DESIGNER}),
                },
            )
            scientific_split_records = self._records_of_types(
                records,
                frozenset({SCIENTIFIC_DATASET_SPLIT_AUTHORITY_LOGICAL_TYPE}),
            )
            if scientific_split_records:
                if (
                    len(scientific_split_records) != 1
                    or len(records) != 1
                    or record.definition_artifact_hashes
                    != (scientific_split_records[0].sha256,)
                ):
                    raise ValidationError(
                        "scientific split requires one exact role authority"
                    )
                split_authority = require_scientific_dataset_split_authority(
                    self.registry,
                    self.ledger,
                    run_id=self.run_id,
                    split_authority_artifact_hash=(scientific_split_records[0].sha256),
                    expected_split_id=record.object_id,
                    expected_split_role=record.split_role,
                    expected_unit_type=record.unit_type,
                )
                resolved_dataset = self._resolve_object_authority(
                    dataset_parents[0],
                    by_content,
                )
                if (
                    resolved_dataset.scientific_evidence_eligible is not True
                    or tuple(item.sha256 for item in resolved_dataset.records)
                    != (split_authority.dataset_authority_artifact_hash,)
                    or record.status is not RecordStatus.FROZEN
                ):
                    raise ValidationError(
                        "scientific split differs from its eligible Dataset"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    scientific_evidence_eligible=True,
                )
            if len(records) != 2:
                raise ValidationError(
                    "split authority requires one dataset and one frozen contract"
                )
            dataset_records = tuple(
                item
                for item in records
                if item.logical_type
                in {
                    "dataset_fixture",
                }
            )
            if len(dataset_records) != 1:
                raise ValidationError("split Dataset authority is ambiguous")
            dataset_record = dataset_records[0]
            if record.definition_artifact_hashes != (dataset_record.sha256,):
                raise ValidationError("split authority omits its exact definition")
            resolved_dataset = self._resolve_object_authority(
                dataset_parents[0],
                by_content,
            )
            if tuple(item.sha256 for item in resolved_dataset.records) != (
                dataset_record.sha256,
            ):
                raise ValidationError(
                    "split definition differs from its canonical Dataset authority"
                )
            contract_record = self._one_record(records, "evaluation_contract")
            contract = self._nested_mapping(
                self._read_authority_json(contract_record),
                "evaluation_contract",
            )
            dataset = self._nested_mapping(contract, "dataset")
            split_key = {
                SplitRole.TRAIN: "train_split_id",
                SplitRole.EXPLORATORY: "development_split_id",
                SplitRole.VALIDATION: "validation_split_id",
                SplitRole.CONFIRMATORY: "confirmatory_split_id",
            }.get(record.split_role)
            configuration_parents = tuple(
                self._require_frozen_pass_artifact(
                    digest,
                    logical_type="experiment_configuration",
                    creator_role=Role.PROTOCOL_DESIGNER,
                )
                for digest in contract_record.parent_artifacts
                if self.registry.get_metadata(digest).logical_type
                == "experiment_configuration"
            )
            if (
                split_key is None
                or dataset.get("dataset_id") != record.dataset_id
                or dataset.get(split_key) != record.object_id
                or len(configuration_parents) != 1
                or dataset_record.sha256
                not in configuration_parents[0].parent_artifacts
            ):
                raise ValidationError(
                    "canonical split is absent from the frozen evaluation contract"
                )
            return _ResolvedObjectAuthority(
                records,
                scientific_evidence_eligible=False,
            )

        if isinstance(record, Metric):
            self._require_exact_authority_roles(
                records,
                {
                    "metric_evaluator": frozenset({Role.PROTOCOL_DESIGNER}),
                    "autonomous_implementation.fixture_evaluator": frozenset(
                        {Role.PROTOCOL_DESIGNER}
                    ),
                    "evaluation_contract": frozenset({Role.PROTOCOL_DESIGNER}),
                },
            )
            evaluators = self._records_of_types(
                records,
                frozenset(
                    {
                        "metric_evaluator",
                        "autonomous_implementation.fixture_evaluator",
                    }
                ),
            )
            if len(evaluators) != 1:
                raise ValidationError("metric requires one exact evaluator authority")
            evaluator_record = evaluators[0]
            evaluator = self._read_authority_json(evaluator_record)
            if evaluator.get("metric_id") != record.object_id:
                raise ValidationError("canonical metric differs from its evaluator")
            contracts = self._records_of_types(
                records, frozenset({"evaluation_contract"})
            )
            if evaluator_record.logical_type == "metric_evaluator":
                if len(contracts) != 1:
                    raise ValidationError(
                        "scientific metric requires one exact contract authority"
                    )
                if evaluator.get("unit") != record.unit:
                    raise ValidationError(
                        "canonical metric unit differs from evaluator"
                    )
                contract = self._nested_mapping(
                    self._read_authority_json(contracts[0]), "evaluation_contract"
                )
                if evaluator_record.sha256 not in contracts[0].parent_artifacts:
                    raise ValidationError(
                        "metric evaluator is not a parent of the frozen contract"
                    )
                metric_values = (contract.get("primary_metric"),) + tuple(
                    contract.get("secondary_metrics", ())
                    if isinstance(contract.get("secondary_metrics", ()), list)
                    else ()
                )
                matches = tuple(
                    item
                    for item in metric_values
                    if isinstance(item, Mapping)
                    and item.get("metric_id") == record.object_id
                )
                if len(matches) != 1:
                    raise ValidationError(
                        "canonical metric is absent from the evaluation contract"
                    )
                metric = matches[0]
                expected_direction = {
                    "HIGHER_IS_BETTER": MetricDirection.HIGHER_IS_BETTER,
                    "LOWER_IS_BETTER": MetricDirection.LOWER_IS_BETTER,
                    "TARGET_IS_BEST": MetricDirection.TARGET_IS_BETTER,
                }.get(metric.get("direction"))
                if (
                    metric.get("name") != record.name
                    or expected_direction is not record.direction
                    or not isinstance(metric.get("unit"), str)
                    or metric["unit"].casefold() != record.unit.casefold()
                    or metric.get("scope") != record.evidence_level.value
                ):
                    raise ValidationError(
                        "canonical metric differs from its frozen contract specification"
                    )
            else:
                if contracts:
                    raise ValidationError(
                        "autonomous component metric cannot borrow a scientific contract"
                    )
                if (
                    evaluator.get("metric") != "template_defined_scalar"
                    or evaluator.get("direction")
                    != MetricDirection.HIGHER_IS_BETTER.value
                    or record.name != "Closed-template scalar component metric"
                    or record.direction is not MetricDirection.HIGHER_IS_BETTER
                    or record.unit != "dimensionless"
                    or record.evidence_level is not MetricLevel.PROXY
                ):
                    raise ValidationError(
                        "canonical autonomous metric differs from its closed evaluator"
                    )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Baseline):
            method_parents = self._resolved_parent_objects(record, by_content, "Method")
            implementation_parents = self._resolved_parent_objects(
                record, by_content, "Implementation"
            )
            metric_parents = self._resolved_parent_objects(record, by_content, "Metric")
            if (
                {item.object_id for item in method_parents} != {record.method_id}
                or (
                    {item.object_id for item in implementation_parents}
                    != (
                        {record.implementation_id}
                        if record.implementation_id is not None
                        else set()
                    )
                )
                or {item.object_id for item in metric_parents} != set(record.metric_ids)
            ):
                raise ValidationError(
                    "canonical baseline fields differ from its evaluated parents"
                )
            self._require_exact_authority_roles(
                records,
                {
                    "evaluation_contract": frozenset({Role.PROTOCOL_DESIGNER}),
                    "aggregate_experiment_result": frozenset({Role.STATISTICIAN}),
                },
            )
            if len(records) != 2:
                raise ValidationError(
                    "completed baseline requires contract and aggregate authority"
                )
            contract = self._nested_mapping(
                self._read_authority_json(
                    self._one_record(records, "evaluation_contract")
                ),
                "evaluation_contract",
            )
            baseline_registry = self._nested_mapping(contract, "baseline_registry")
            entries = baseline_registry.get("entries")
            if not isinstance(entries, list):
                raise ValidationError("baseline registry entries are malformed")
            matches = tuple(
                item
                for item in entries
                if isinstance(item, Mapping)
                and item.get("baseline_id") == record.object_id
            )
            aggregate = self._read_authority_json(
                self._one_record(records, "aggregate_experiment_result")
            )
            if len(matches) != 1 or len(record.metric_ids) != 1:
                raise ValidationError(
                    "canonical baseline is absent from its frozen registry"
                )
            entry = matches[0]
            metric_id = record.metric_ids[0]
            observed = record.observed_metrics.get(metric_id)
            conditions = self._nested_mapping(entry, "conditions")
            expected_metrics = (
                {}
                if entry.get("expected_metric") is None
                else {metric_id: entry.get("expected_metric")}
            )
            reported_metrics = (
                {}
                if entry.get("reported_metric") is None
                else {metric_id: entry.get("reported_metric")}
            )
            observed_metrics = (
                {}
                if entry.get("observed_metric") is None
                else {metric_id: entry.get("observed_metric")}
            )
            if (
                entry.get("name") != record.name
                or entry.get("status") != record.baseline_status.value
                or thaw_json(record.expected_metrics) != expected_metrics
                or thaw_json(record.reported_metrics) != reported_metrics
                or thaw_json(record.observed_metrics) != observed_metrics
                or thaw_json(record.tuning_budget)
                != {"trials": conditions.get("tuning_trials")}
                or not self._float_matches(
                    entry.get("implementation_confidence"),
                    record.implementation_confidence,
                )
                or entry.get("fairness_assessment") != record.fairness_assessment
                or entry.get("evaluation_compatible") is not True
                or entry.get("exclusion") is not None
                or aggregate.get("metric_id") != metric_id
                or not self._float_matches(aggregate.get("baseline_accuracy"), observed)
            ):
                raise ValidationError(
                    "canonical baseline differs from its contract or observed result"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Hypothesis):
            if record.hypothesis_status is not HypothesisStatus.UNTESTED:
                self._require_exact_authority_roles(
                    records,
                    {
                        HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE: frozenset(
                            {Role.SCIENTIFIC_REVIEWER}
                        )
                    },
                )
                if len(records) != 1:
                    raise ValidationError(
                        "tested Hypothesis requires one exact evaluation authority"
                    )
                authority = require_hypothesis_evaluation_authority(
                    self.registry,
                    self.ledger,
                    authority_artifact_hash=records[0].sha256,
                    expected_run_id=self.run_id,
                    expected_hypothesis_id=record.object_id,
                )
                predecessor = by_content.get(record.supersedes_content_hash or "")
                if predecessor is None or not isinstance(
                    predecessor.research_object, Hypothesis
                ):
                    raise ValidationError(
                        "tested Hypothesis lacks its exact preregistered predecessor"
                    )
                prior = predecessor.research_object
                expected_parents = (
                    ObjectReference(
                        "Result",
                        authority.result_id,
                        authority.result_content_hash,
                        "evaluated_by",
                        True,
                    ),
                    ObjectReference(
                        "StatisticalTest",
                        authority.statistical_test_id,
                        authority.statistical_test_content_hash,
                        "evaluated_by",
                        True,
                    ),
                )
                unchanged = (
                    record.object_id == prior.object_id
                    and record.schema_version == prior.schema_version
                    and record.code_version == prior.code_version
                    and record.relationships == prior.relationships
                    and thaw_json(record.metadata) == thaw_json(prior.metadata)
                    and record.statement == prior.statement
                    and record.motivation == prior.motivation
                    and record.prior_evidence_ids == prior.prior_evidence_ids
                    and record.prediction == prior.prediction
                    and record.falsification_condition == prior.falsification_condition
                    and record.planned_experiment_ids == prior.planned_experiment_ids
                )
                if (
                    record.revision != 2
                    or record.supersedes_content_hash
                    != authority.prior_hypothesis_content_hash
                    or prior.content_hash != authority.prior_hypothesis_content_hash
                    or prior.revision != 1
                    or prior.hypothesis_status is not HypothesisStatus.UNTESTED
                    or prior.producer is not Role.HYPOTHESIS_DESIGNER
                    or record.producer is not Role.SCIENTIFIC_REVIEWER
                    or record.status is not RecordStatus.COMPLETE
                    or record.parents != expected_parents
                    or record.authority_artifact_hashes != (records[0].sha256,)
                    or record.hypothesis_status is not authority.outcome
                    or not unchanged
                    or not self._timestamp_strictly_after(
                        record.created_at,
                        records[0].created_at,
                    )
                ):
                    raise ValidationError(
                        "tested Hypothesis differs from its source-owned evaluation"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    scientific_evidence_eligible=(
                        authority.scientific_evidence_eligible
                    ),
                )
            self._require_exact_authority_roles(
                records,
                {"hypothesis_register": frozenset({Role.HYPOTHESIS_DESIGNER})},
            )
            if (
                len(records) != 1
                or record.hypothesis_status is not HypothesisStatus.UNTESTED
            ):
                raise ValidationError(
                    "tested hypothesis status lacks a supported independent resolver"
                )
            register = self._nested_mapping(
                self._read_authority_json(records[0]), "hypothesis_register"
            )
            hypotheses = register.get("hypotheses")
            if not isinstance(hypotheses, list):
                raise ValidationError("hypothesis register is malformed")
            matches = tuple(
                item
                for item in hypotheses
                if isinstance(item, Mapping)
                and item.get("hypothesis_id") == record.object_id
            )
            if (
                len(matches) != 1
                or matches[0].get("statement") != record.statement
                or matches[0].get("motivation") != record.motivation
                or tuple(matches[0].get("prior_evidence_ids", ()))
                != tuple(record.prior_evidence_ids)
                or matches[0].get("prediction") != record.prediction
                or matches[0].get("falsification_condition")
                != record.falsification_condition
                or (matches[0].get("planned_experiment"),)
                != tuple(record.planned_experiment_ids)
                or matches[0].get("status") != HypothesisStatus.UNTESTED.value
            ):
                raise ValidationError(
                    "canonical hypothesis differs from its preregistered entry"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Method):
            self._require_exact_authority_roles(
                records,
                {
                    "method_definition": frozenset({Role.HYPOTHESIS_DESIGNER}),
                    "baseline_method_definition": frozenset({Role.PROTOCOL_DESIGNER}),
                    "autonomous_implementation.validation_receipt": frozenset(
                        {Role.ORCHESTRATOR}
                    ),
                    "autonomous_implementation.admitted_descriptor": frozenset(
                        {Role.IMPLEMENTER}
                    ),
                },
            )
            definition_types = {
                "method_definition",
                "baseline_method_definition",
            }
            definitions = self._records_of_types(records, frozenset(definition_types))
            if len(definitions) == 1 and len(records) == 1:
                definition = self._read_authority_json(definitions[0])
                if (
                    definition.get("method_id") != record.object_id
                    or definition.get("name") != record.name
                    or definition.get("description") != record.description
                    or tuple(definition.get("assumptions", ()))
                    != tuple(record.assumptions)
                    or tuple(definition.get("component_ids", ()))
                    != tuple(record.component_ids)
                    or len(definitions[0].parent_artifacts) != 1
                ):
                    raise ValidationError(
                        "canonical method differs from its frozen definition"
                    )
                definition_parent = self._require_frozen_pass_artifact(
                    definitions[0].parent_artifacts[0],
                    logical_type="experiment_configuration",
                    creator_role=Role.PROTOCOL_DESIGNER,
                )
                if (
                    definition_parent.sha256 == definitions[0].sha256
                ):  # pragma: no cover
                    raise ValidationError("method definition self-parented")
            else:
                if len(records) != 2:
                    raise ValidationError(
                        "unsupported canonical method authority bundle"
                    )
                descriptor = self._read_authority_json(
                    self._one_record(
                        records,
                        "autonomous_implementation.admitted_descriptor",
                    )
                )
                receipt = self._read_authority_json(
                    self._one_record(
                        records,
                        "autonomous_implementation.validation_receipt",
                    )
                )
                template_id = descriptor.get("template_id")
                expected_description = (
                    "A provider-selected declarative template from the pinned reviewed "
                    "catalog; the provider supplied no executable source."
                )
                if (
                    not isinstance(template_id, str)
                    or record.object_id != f"method-autonomous-{template_id}"
                    or record.name != f"Reviewed closed template {template_id}"
                    or record.description != expected_description
                    or tuple(record.assumptions)
                    != (
                        "Only exact development-fixture scalar values are consumed.",
                        "The output is a non-evidentiary component metric.",
                    )
                    or tuple(record.component_ids) != (f"component-{template_id}",)
                    or receipt.get("status") != "ADMITTED"
                    or receipt.get("template_id") != template_id
                    or descriptor.get("validation_receipt_sha256")
                    != self._one_record(
                        records,
                        "autonomous_implementation.validation_receipt",
                    ).sha256
                ):
                    raise ValidationError(
                        "canonical autonomous method differs from admission authority"
                    )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Implementation):
            self._require_exact_authority_roles(
                records,
                {
                    "experiment_code": frozenset({Role.IMPLEMENTER}),
                    "experiment_configuration": frozenset({Role.PROTOCOL_DESIGNER}),
                    "autonomous_implementation.reviewed_worker_code": frozenset(
                        {Role.IMPLEMENTER}
                    ),
                    "autonomous_implementation.worker_configuration": frozenset(
                        {Role.IMPLEMENTER}
                    ),
                    "autonomous_implementation.validation_receipt": frozenset(
                        {Role.ORCHESTRATOR}
                    ),
                    "autonomous_implementation.admitted_descriptor": frozenset(
                        {Role.IMPLEMENTER}
                    ),
                },
            )
            if not records:
                raise ValidationError("implementation lacks exact code authority")
            autonomous = any(
                item.logical_type == "autonomous_implementation.admitted_descriptor"
                for item in records
            )
            if autonomous:
                descriptor_record = self._one_record(
                    records, "autonomous_implementation.admitted_descriptor"
                )
                receipt_record = self._one_record(
                    records, "autonomous_implementation.validation_receipt"
                )
                descriptor = self._read_authority_json(descriptor_record)
                receipt = self._read_authority_json(receipt_record)
                expected_hashes = {
                    descriptor.get("worker_code_sha256"),
                    descriptor.get("configuration_sha256"),
                    descriptor.get("validation_receipt_sha256"),
                    descriptor_record.sha256,
                }
                if (
                    descriptor.get("implementation_id") != record.object_id
                    or receipt.get("status") != "ADMITTED"
                    or receipt.get("worker_code_sha256")
                    not in record.code_artifact_hashes
                    or receipt.get("configuration_sha256")
                    not in record.configuration_artifact_hashes
                    or not expected_hashes.issubset(
                        set(record.authority_artifact_hashes)
                    )
                ):
                    raise ValidationError(
                        "canonical implementation differs from admission authority"
                    )
            else:
                codes = tuple(
                    item for item in records if item.logical_type == "experiment_code"
                )
                configs = tuple(
                    item
                    for item in records
                    if item.logical_type == "experiment_configuration"
                )
                if len(codes) != 1 or (
                    not configs and record.status not in _CONSERVATIVE_STATUSES
                ):
                    raise ValidationError(
                        "canonical implementation lacks exact code/configuration authority"
                    )
                if configs and codes[0].sha256 not in set(configs[0].parent_artifacts):
                    raise ValidationError(
                        "implementation configuration is not bound to its exact code"
                    )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Experiment):
            hypothesis_parents = self._resolved_parent_objects(
                record, by_content, "Hypothesis"
            )
            implementation_parents = self._resolved_parent_objects(
                record, by_content, "Implementation"
            )
            dataset_parents = self._resolved_parent_objects(
                record, by_content, "Dataset"
            )
            split_parents = self._resolved_parent_objects(record, by_content, "Split")
            metric_parents = self._resolved_parent_objects(record, by_content, "Metric")
            baseline_parents = self._resolved_parent_objects(
                record, by_content, "Baseline"
            )
            if (
                {item.object_id for item in hypothesis_parents}
                != set(record.hypothesis_ids)
                or len(implementation_parents) != 1
                or implementation_parents[0].object_id != record.implementation_id
                or {item.object_id for item in dataset_parents}
                != set(record.dataset_ids)
                or {item.object_id for item in split_parents} != set(record.split_ids)
                or {item.object_id for item in metric_parents} != set(record.metric_ids)
                or {item.object_id for item in baseline_parents}
                != set(record.baseline_ids)
            ):
                raise ValidationError(
                    "canonical experiment fields differ from evaluated parents"
                )
            self._require_exact_authority_roles(
                records,
                {
                    "experiment_configuration": frozenset({Role.PROTOCOL_DESIGNER}),
                    "evaluation_contract": frozenset({Role.PROTOCOL_DESIGNER}),
                    "autonomous_implementation.worker_configuration": frozenset(
                        {Role.IMPLEMENTER}
                    ),
                    "autonomous_implementation.admitted_descriptor": frozenset(
                        {Role.IMPLEMENTER}
                    ),
                    "autonomous_implementation.fixture_evaluator": frozenset(
                        {Role.PROTOCOL_DESIGNER}
                    ),
                },
            )
            contracts = self._records_of_types(
                records, frozenset({"evaluation_contract"})
            )
            descriptors = self._records_of_types(
                records,
                frozenset({"autonomous_implementation.admitted_descriptor"}),
            )
            if contracts:
                if len(contracts) != 1 or len(records) != 2:
                    raise ValidationError("experiment contract authority is ambiguous")
                configuration_record = self._one_record(
                    records, "experiment_configuration"
                )
                if configuration_record.sha256 not in contracts[0].parent_artifacts:
                    raise ValidationError(
                        "experiment configuration is not bound by its frozen contract"
                    )
                contract = self._nested_mapping(
                    self._read_authority_json(contracts[0]), "evaluation_contract"
                )
                registered_hypotheses = self._nested_mapping(
                    contract, "hypothesis_register"
                ).get("hypotheses")
                dataset = self._nested_mapping(contract, "dataset")
                split_values = tuple(
                    dataset.get(name)
                    for name in (
                        "train_split_id",
                        "development_split_id",
                        "validation_split_id",
                        "confirmatory_split_id",
                    )
                )
                metric_values = (contract.get("primary_metric"),) + tuple(
                    contract.get("secondary_metrics", ())
                    if isinstance(contract.get("secondary_metrics", ()), list)
                    else ()
                )
                baseline_registry = self._nested_mapping(contract, "baseline_registry")
                baseline_values = baseline_registry.get("entries")
                planned_hypotheses = (
                    tuple(
                        item
                        for item in registered_hypotheses
                        if isinstance(item, Mapping)
                        and item.get("planned_experiment") == record.object_id
                    )
                    if isinstance(registered_hypotheses, list)
                    else ()
                )
                if (
                    not isinstance(registered_hypotheses, list)
                    or {item.get("hypothesis_id") for item in planned_hypotheses}
                    != set(record.hypothesis_ids)
                    or {
                        item.get("metric_id")
                        for item in metric_values
                        if isinstance(item, Mapping)
                    }
                    != set(record.metric_ids)
                    or record.dataset_ids != (dataset.get("dataset_id"),)
                    or len(split_values) != len(record.split_ids)
                    or set(split_values) != set(record.split_ids)
                    or not isinstance(baseline_values, list)
                    or {
                        item.get("baseline_id")
                        for item in baseline_values
                        if isinstance(item, Mapping)
                    }
                    != set(record.baseline_ids)
                    or record.evaluator
                    != self._nested_mapping(contract, "candidate_conditions").get(
                        "evaluator"
                    )
                    or thaw_json(record.seed_policy)
                    != {
                        "regime": self._nested_mapping(contract, "seed_reporting").get(
                            "regime"
                        ),
                        "seeds": self._nested_mapping(contract, "seed_reporting").get(
                            "seeds"
                        ),
                    }
                    or configuration_record.sha256
                    not in record.configuration_artifact_hashes
                    or contracts[0].sha256 not in record.configuration_artifact_hashes
                    or set(record.configuration_artifact_hashes)
                    != {configuration_record.sha256, contracts[0].sha256}
                ):
                    raise ValidationError(
                        "canonical experiment differs from its frozen contract"
                    )
            elif descriptors:
                if len(descriptors) != 1 or len(records) != 3:
                    raise ValidationError(
                        "autonomous experiment descriptor authority is ambiguous"
                    )
                descriptor = self._read_authority_json(descriptors[0])
                configuration_record = self._one_record(
                    records,
                    "autonomous_implementation.worker_configuration",
                )
                evaluator_record = self._one_record(
                    records,
                    "autonomous_implementation.fixture_evaluator",
                )
                descriptor_evidence = descriptor.get("parent_evidence_sha256s")
                if (
                    descriptor.get("experiment_id") != record.object_id
                    or record.hypothesis_ids != (descriptor.get("hypothesis_id"),)
                    or descriptor.get("implementation_id") != record.implementation_id
                    or descriptor.get("configuration_sha256")
                    != configuration_record.sha256
                    or len(record.configuration_artifact_hashes) != 3
                    or set(record.configuration_artifact_hashes)
                    != {
                        configuration_record.sha256,
                        descriptors[0].sha256,
                        evaluator_record.sha256,
                    }
                    or not isinstance(descriptor_evidence, list)
                    or evaluator_record.sha256 not in descriptor_evidence
                    or len(dataset_parents) != 1
                    or not set(descriptor_evidence).intersection(
                        dataset_parents[0].artifact_hashes
                    )
                    or len(metric_parents) != 1
                    or evaluator_record.sha256
                    not in metric_parents[0].authority_artifact_hashes
                    or descriptor.get("phase") != "EXPLORATORY"
                    or descriptor.get("scientific_evidence") is not False
                ):
                    raise ValidationError(
                        "canonical autonomous experiment differs from its descriptor"
                    )
            else:
                raise ValidationError(
                    "experiment lacks a supported frozen contract authority"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Run):
            experiment_parents = self._resolved_parent_objects(
                record, by_content, "Experiment"
            )
            if (
                len(experiment_parents) != 1
                or experiment_parents[0].object_id != record.experiment_id
                or experiment_parents[0].status is not RecordStatus.FROZEN
                or set(record.dataset_ids) != set(experiment_parents[0].dataset_ids)
            ):
                raise ValidationError(
                    "canonical run fields differ from its evaluated Experiment"
                )
            manifest_record = self._one_record(records, "experiment_output_manifest")
            manifest_value = self._read_authority_json(
                manifest_record, require_canonical=False
            )
            try:
                from .experiments import OutputManifest

                manifest = OutputManifest.from_mapping(manifest_value)
            except Exception as exc:
                raise ValidationError("run output manifest is invalid") from exc
            allowed: dict[str, frozenset[Role]] = {
                "experiment_configuration": frozenset({Role.PROTOCOL_DESIGNER}),
                "autonomous_implementation.worker_configuration": frozenset(
                    {Role.IMPLEMENTER}
                ),
                "frozen_run_spec": frozenset({Role.EXPERIMENT_RUNNER}),
                "frozen_experiment_plan": frozenset({Role.PROTOCOL_DESIGNER}),
                "autonomous_implementation.frozen_run_spec": frozenset(
                    {Role.EXPERIMENT_RUNNER}
                ),
                "adaptive_execution_plan": frozenset({Role.EXPERIMENT_RUNNER}),
                "adaptive_execution_plan_binding": frozenset({Role.EXPERIMENT_RUNNER}),
                "execution_input_binding": frozenset({Role.EXPERIMENT_RUNNER}),
                "experiment_output_manifest": frozenset({Role.EXPERIMENT_RUNNER}),
                "experiment_log_descriptor": frozenset({Role.EXPERIMENT_RUNNER}),
                "autonomous_implementation.execution_receipt": frozenset(
                    {Role.EXPERIMENT_RUNNER}
                ),
                "scientific_timeline_receipt": frozenset({Role.CLAIM_VERIFIER}),
            }
            manifest_output_hashes: set[str] = set()
            manifest_output_sequence: list[str] = []
            for output in manifest.artifacts:
                allowed[f"experiment_output.{output.logical_type}"] = frozenset(
                    {Role.EXPERIMENT_RUNNER}
                )
                manifest_output_hashes.add(output.sha256)
                manifest_output_sequence.append(output.sha256)
            self._require_exact_authority_roles(records, allowed)
            output_records = tuple(
                item
                for item in records
                if item.logical_type.startswith("experiment_output.")
            )
            if (
                len(output_records) != len(manifest.artifacts)
                or {item.sha256 for item in output_records} != manifest_output_hashes
            ):
                raise ValidationError(
                    "run authority differs from the exact manifest outputs"
                )
            timeline_records = self._records_of_types(
                records, frozenset({"scientific_timeline_receipt"})
            )
            experiment_authority = experiment_parents[0].authority_artifact_hashes
            autonomous_specs = self._records_of_types(
                records,
                frozenset({"autonomous_implementation.frozen_run_spec"}),
            )
            scientific_specs = self._records_of_types(
                records, frozenset({"frozen_run_spec"})
            )
            scientific_plans = self._records_of_types(
                records, frozenset({"frozen_experiment_plan"})
            )
            plan_record = self._one_record(records, "adaptive_execution_plan")
            binding_record = self._one_record(
                records, "adaptive_execution_plan_binding"
            )
            input_binding_record = self._one_record(records, "execution_input_binding")
            try:
                from .experiments import AdaptiveExecutionPlan

                plan = AdaptiveExecutionPlan.from_mapping(
                    self._read_authority_json(plan_record)
                )
            except Exception as exc:
                raise ValidationError("run adaptive execution plan is invalid") from exc
            binding = self._read_authority_json(binding_record)
            spec_record = (
                autonomous_specs[0]
                if len(autonomous_specs) == 1
                else scientific_specs[0]
                if len(scientific_specs) == 1
                else None
            )
            if spec_record is None:
                raise ValidationError("run lacks one exact frozen run spec")
            spec_value = self._read_authority_json(spec_record)
            self._replay_execution_input_binding(
                input_binding_record,
                spec_artifact_sha256=spec_record.sha256,
                spec_sha256=manifest.spec_sha256,
                spec_value=spec_value,
            )
            self._replay_adaptive_execution_plan_binding(
                binding_record,
                binding,
                run_id=record.object_id,
                spec_artifact_sha256=spec_record.sha256,
                spec_sha256=manifest.spec_sha256,
                execution_plan_artifact_sha256=plan_record.sha256,
                execution_plan_sha256=plan.sha256,
                execution_input_binding_sha256=input_binding_record.sha256,
                manifest_artifact_sha256=manifest_record.sha256,
                returned_artifact_sha256s=tuple(manifest_output_sequence),
            )
            compute_profile = self._nested_mapping(spec_value, "compute_profile")
            if (
                plan_record.parent_artifacts
                or spec_value.get("run_id") != record.object_id
                or spec_value.get("experiment_id") != record.experiment_id
                or spec_value.get("configuration_sha256")
                != record.configuration_artifact_hash
                or tuple(spec_value.get("seeds", ())) != tuple(record.random_seeds)
                or compute_profile.get("mode") != record.compute_profile.value
                or manifest.code_sha256 != spec_value.get("code_sha256")
                or manifest.data_sha256 != spec_value.get("data_sha256")
                or manifest.evaluator_sha256 != spec_value.get("evaluator_sha256")
                or manifest_record.parent_artifacts != (spec_record.sha256,)
            ):
                raise ValidationError(
                    "canonical run differs from its exact spec, plan, and custody binding"
                )
            for output_record in output_records:
                if output_record.parent_artifacts != (
                    manifest_record.sha256,
                    spec_record.sha256,
                ):
                    raise ValidationError(
                        "run output has substituted manifest or spec custody"
                    )
            log_records = self._records_of_types(
                records, frozenset({"experiment_log_descriptor"})
            )
            if len(log_records) != 2:
                raise ValidationError("run requires exact stdout/stderr descriptors")
            observed_streams: set[str] = set()
            for log_record in log_records:
                log = self._read_authority_json(log_record)
                raw_hash = log.get("raw_artifact_hash")
                if not isinstance(raw_hash, str):
                    raise ValidationError("run log descriptor omits raw bytes")
                raw_record = self._require_frozen_pass_artifact(
                    raw_hash,
                    logical_type="raw_experiment_log_bytes",
                    creator_role=Role.EXPERIMENT_RUNNER,
                )
                stream = log.get("stream")
                if (
                    stream not in {"stdout", "stderr"}
                    or log.get("run_id") != record.object_id
                    or log_record.parent_artifacts
                    != (raw_record.sha256, spec_record.sha256)
                    or raw_record.parent_artifacts
                ):
                    raise ValidationError(
                        "run log descriptor has substituted bytes or spec custody"
                    )
                observed_streams.add(stream)
            if observed_streams != {"stdout", "stderr"}:
                raise ValidationError("run log descriptor streams are incomplete")
            if autonomous_specs:
                if (
                    len(autonomous_specs) != 1
                    or scientific_specs
                    or scientific_plans
                    or timeline_records
                ):
                    raise ValidationError(
                        "autonomous run mixed scientific timeline authority"
                    )
                spec_record = autonomous_specs[0]
                spec = self._read_authority_json(spec_record)
                configuration_record = self._one_record(
                    records,
                    "autonomous_implementation.worker_configuration",
                )
                execution_record = self._one_record(
                    records, "autonomous_implementation.execution_receipt"
                )
                execution = self._read_authority_json(execution_record)
                spec_parents = tuple(
                    self._require_frozen_pass_artifact(digest)
                    for digest in spec_record.parent_artifacts
                )
                self._require_exact_authority_roles(
                    spec_parents,
                    {
                        "autonomous_implementation.admitted_descriptor": frozenset(
                            {Role.IMPLEMENTER}
                        ),
                        "autonomous_implementation.validation_receipt": frozenset(
                            {Role.ORCHESTRATOR}
                        ),
                        "autonomous_implementation.reviewed_worker_code": frozenset(
                            {Role.IMPLEMENTER}
                        ),
                        "autonomous_implementation.worker_configuration": frozenset(
                            {Role.IMPLEMENTER}
                        ),
                        "autonomous_implementation.fixture_data": frozenset(
                            {Role.EVIDENCE_CURATOR}
                        ),
                        "autonomous_implementation.fixture_evaluator": frozenset(
                            {Role.PROTOCOL_DESIGNER}
                        ),
                    },
                )
                if len(spec_parents) != 6:
                    raise ValidationError(
                        "autonomous run spec has substituted admission parents"
                    )
                descriptor_record = self._one_record(
                    spec_parents,
                    "autonomous_implementation.admitted_descriptor",
                )
                validation_record = self._one_record(
                    spec_parents,
                    "autonomous_implementation.validation_receipt",
                )
                configuration_record = self._one_record(
                    spec_parents,
                    "autonomous_implementation.worker_configuration",
                )
                descriptor = self._read_authority_json(descriptor_record)
                validation = self._read_authority_json(validation_record)
                if (
                    spec.get("run_id") != record.object_id
                    or spec.get("experiment_id") != record.experiment_id
                    or spec.get("configuration_sha256")
                    != record.configuration_artifact_hash
                    or configuration_record.sha256 != record.configuration_artifact_hash
                    or tuple(spec.get("seeds", ())) != tuple(record.random_seeds)
                    or spec.get("phase") != "EXPLORATORY"
                    or spec.get("evidence_class") != "NON_EVIDENTIARY"
                    or descriptor.get("experiment_id") != record.experiment_id
                    or descriptor.get("configuration_sha256")
                    != configuration_record.sha256
                    or descriptor.get("validation_receipt_sha256")
                    != validation_record.sha256
                    or validation.get("status") != "ADMITTED"
                    or execution.get("frozen_run_spec_artifact_sha256")
                    != spec_record.sha256
                    or execution.get("implementation_descriptor_sha256")
                    != descriptor_record.sha256
                    or execution.get("state") != "SUCCEEDED"
                    or execution.get("validation_status") != "VALIDATED_LOCAL"
                    or execution.get("scientific_evidence") is not False
                    or record.evaluator_version
                    != f"artifact:{manifest.evaluator_sha256}"
                    or execution_record.parent_artifacts
                    != (
                        spec_record.sha256,
                        descriptor_record.sha256,
                        validation_record.sha256,
                    )
                    or descriptor_record.sha256 not in experiment_authority
                ):
                    raise ValidationError(
                        "autonomous run differs from exact admission and execution custody"
                    )
            else:
                if len(scientific_specs) != 1 or len(timeline_records) != 1:
                    raise ValidationError(
                        "scientific run requires one spec and timeline receipt"
                    )
                configuration_record = self._one_record(
                    records, "experiment_configuration"
                )
                if (
                    configuration_record.sha256 != record.configuration_artifact_hash
                    or record.evaluator_version != experiment_parents[0].evaluator
                ):
                    raise ValidationError(
                        "scientific run configuration or evaluator differs from its Experiment"
                    )
                try:
                    from .scientific_design import (
                        ScientificTimelineReceipt,
                        require_scientific_timeline_receipt,
                    )

                    timeline = ScientificTimelineReceipt.from_dict(
                        self._read_authority_json(timeline_records[0])
                    )
                    require_scientific_timeline_receipt(
                        self.registry,
                        self.ledger,
                        receipt_artifact_sha256=timeline_records[0].sha256,
                        run_id=self.run_id,
                        contract_artifact_sha256=(timeline.contract_artifact_sha256),
                        experiment_plan_artifact_sha256s=(
                            timeline.experiment_plan_artifact_sha256s
                        ),
                        frozen_run_spec_artifact_sha256=(
                            timeline.frozen_run_spec_artifact_sha256
                        ),
                        output_manifest_artifact_sha256=(
                            timeline.output_manifest_artifact_sha256
                        ),
                    )
                except Exception as exc:
                    raise ValidationError(
                        "run scientific timeline failed fresh ledger resolution"
                    ) from exc
                timeline_run_inputs = {
                    *timeline.experiment_plan_artifact_sha256s,
                    timeline.frozen_run_spec_artifact_sha256,
                    timeline.output_manifest_artifact_sha256,
                }
                if (
                    timeline.run_id != self.run_id
                    or timeline.experiment_id != record.experiment_id
                    or timeline.output_manifest_artifact_sha256
                    != manifest_record.sha256
                    or timeline.contract_artifact_sha256 not in experiment_authority
                    or len(scientific_plans)
                    != len(timeline.experiment_plan_artifact_sha256s)
                    or {item.sha256 for item in scientific_plans}
                    != set(timeline.experiment_plan_artifact_sha256s)
                    or not timeline_run_inputs.issubset(
                        set(record.authority_artifact_hashes)
                    )
                ):
                    raise ValidationError(
                        "scientific run differs from its timeline authority"
                    )
            if (
                manifest.run_id != record.object_id
                or manifest.configuration_sha256 != record.configuration_artifact_hash
                or tuple(manifest.planned_seeds) != tuple(record.random_seeds)
                or not manifest_output_hashes.issubset(
                    set(record.output_artifact_hashes)
                )
            ):
                raise ValidationError("canonical run differs from its frozen manifest")
            expected_promotion_hashes = tuple(
                digest
                for digest in record.output_artifact_hashes
                if self.registry.get_metadata(digest).logical_type
                != "autonomous_implementation.execution_receipt"
            )
            expected_execution_code = record.code_revision.removeprefix(
                "research-os-vnext:"
            )
            promotion_events = tuple(
                event
                for event in self.ledger.events()
                if event.run_id == self.run_id
                and event.actor_role is Role.EXPERIMENT_RUNNER
                and event.metadata.get("promotion") == "EXPERIMENT_OUTPUTS_REGISTERED"
                and event.metadata.get("experiment_run_id") == record.object_id
                and tuple(event.artifact_hashes) == expected_promotion_hashes
                and event.code_version == expected_execution_code
                and event.configuration_hash == self.configuration_hash
                and tuple(event.random_seeds) == tuple(record.random_seeds)
                and event.state_before == self.state
                and event.requested_state_after == self.state
                and event.event_type == "CHECKPOINT"
                and event.metadata.get("scientific_evidence_eligible") is False
            )
            if len(promotion_events) != 1:
                raise ValidationError(
                    "completed run lacks one exact same-run ledger promotion"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Result):
            run_parents = self._resolved_parent_objects(record, by_content, "Run")
            metric_parents = self._resolved_parent_objects(record, by_content, "Metric")
            promotion_records = self._records_of_types(
                records,
                frozenset({"scientific_result_promotion_authority"}),
            )
            promotion_v3_records = self._records_of_types(
                records,
                frozenset({"scientific_result_promotion_authority_v3"}),
            )
            if (
                not run_parents
                or {item.object_id for item in run_parents} != set(record.run_ids)
                or any(
                    item.status is not RecordStatus.COMPLETE
                    or item.completed_at is None
                    for item in run_parents
                )
                or len(metric_parents) != 1
                or metric_parents[0].object_id != record.metric_id
                or metric_parents[0].status is not RecordStatus.FROZEN
                or metric_parents[0].unit.casefold() != record.unit.casefold()
                or metric_parents[0].direction is not record.direction
                or (
                    not promotion_records
                    and not promotion_v3_records
                    and any(
                        item.code_revision != record.code_revision
                        for item in run_parents
                    )
                )
            ):
                raise ValidationError(
                    "canonical result fields differ from evaluated Run/Metric parents"
                )
            if promotion_v3_records:
                if promotion_records:
                    raise ValidationError(
                        "scientific Result mixes legacy and outcome-neutral promotion"
                    )
                if (
                    len(promotion_v3_records) != 1
                    or len(run_parents) != 1
                    or record.run_ids != (run_parents[0].object_id,)
                    or len(record.parents) != 2
                    or record.parents[0]
                    != ObjectReference(
                        "Run",
                        run_parents[0].object_id,
                        run_parents[0].content_hash,
                        "aggregates",
                        True,
                    )
                    or record.parents[1]
                    != ObjectReference(
                        "Metric",
                        metric_parents[0].object_id,
                        metric_parents[0].content_hash,
                        "reports",
                        True,
                    )
                    or record.relationships
                    or record.revision != 1
                    or record.supersedes_content_hash is not None
                ):
                    raise ValidationError(
                        "outcome-neutral Result requires exact Run and Metric parents"
                    )
                resolution, projection, promotion_record = (
                    self._resolve_scientific_result_promotion_v3(
                        records,
                        expected_result_id=record.object_id,
                        expected_execution_run_id=run_parents[0].object_id,
                    )
                )
                expected_direction = {
                    "HIGHER_IS_BETTER": MetricDirection.HIGHER_IS_BETTER,
                    "LOWER_IS_BETTER": MetricDirection.LOWER_IS_BETTER,
                    "TARGET_IS_BEST": MetricDirection.TARGET_IS_BETTER,
                }.get(projection.metric_direction.value)
                expected_sources = projection.state_source_artifact_hashes
                expected_evaluations = projection.state_evaluation_artifact_hashes
                expected_authorities = projection.state_authority_artifact_hashes
                allowed = {
                    "scientific_result_promotion_authority_v3": frozenset(
                        {Role.CLAIM_VERIFIER}
                    ),
                    "aggregate_experiment_result": frozenset({Role.STATISTICIAN}),
                    "experiment_output_manifest": frozenset({Role.EXPERIMENT_RUNNER}),
                }
                for source in records:
                    if source.logical_type.startswith("experiment_output."):
                        allowed[source.logical_type] = frozenset(
                            {Role.EXPERIMENT_RUNNER}
                        )
                self._require_exact_authority_roles(records, allowed)
                if (
                    expected_direction is None
                    or {item.sha256 for item in records} != set(expected_authorities)
                    or len(records) != len(expected_authorities)
                    or record.object_id != projection.result_id
                    or record.metric_id != projection.metric_id
                    or record.producer is not Role.STATISTICIAN
                    or record.status is not RecordStatus.COMPLETE
                    or record.code_version != projection.canonical_state_code_version
                    or record.code_revision != projection.canonical_state_code_version
                    or thaw_json(record.value) != projection.state_value
                    or record.unit != projection.metric_unit.value
                    or record.direction is not expected_direction
                    or thaw_json(record.uncertainty) != projection.state_uncertainty
                    or record.source_artifact_hashes != expected_sources
                    or record.evaluation_artifact_hashes != expected_evaluations
                    or record.authority_artifact_hashes != expected_authorities
                    or thaw_json(record.metadata) != projection.state_metadata
                    or record.observed_at != projection.observed_at
                    or not self._timestamp_strictly_after(
                        record.created_at,
                        promotion_record.created_at,
                    )
                ):
                    raise ValidationError(
                        "canonical Result differs from its exact outcome-neutral projection"
                    )
                run_resolution = self._resolve_object_authority(
                    run_parents[0],
                    by_content,
                    allow_unmaterialized_source_bound=(
                        allow_unmaterialized_source_bound
                    ),
                )
                source_graph_eligible = self._validate_scientific_result_parent_join(
                    record=record,
                    run=run_parents[0],
                    metric=metric_parents[0],
                    result_projection=projection,
                    by_content=by_content,
                    require_materialized_lineage=(
                        not allow_unmaterialized_source_bound
                    ),
                )
                effective_eligible = bool(
                    resolution.scientific_evidence_eligible
                    and run_resolution.scientific_evidence_eligible
                    and source_graph_eligible
                )
                if not allow_unmaterialized_source_bound:
                    self._require_scientific_result_bundle_completion(
                        record,
                        by_content,
                        promotion_record=promotion_record,
                        expected_scientific_evidence_eligible=(effective_eligible),
                    )
                return _ResolvedObjectAuthority(records, effective_eligible)
            if promotion_records:
                if (
                    len(run_parents) != 1
                    or record.run_ids != (run_parents[0].object_id,)
                    or len(record.parents) != 2
                    or record.parents[0]
                    != ObjectReference(
                        "Run",
                        run_parents[0].object_id,
                        run_parents[0].content_hash,
                        "aggregates",
                        True,
                    )
                    or record.parents[1]
                    != ObjectReference(
                        "Metric",
                        metric_parents[0].object_id,
                        metric_parents[0].content_hash,
                        "reports",
                        True,
                    )
                    or record.relationships
                    or thaw_json(record.metadata) != {}
                    or record.revision != 1
                    or record.supersedes_content_hash is not None
                ):
                    raise ValidationError(
                        "scientific Result requires exact Run and Metric parents"
                    )
                resolution, projection, promotion_record, projection_event = (
                    self._resolve_scientific_result_promotion(
                        records,
                        expected_result_id=record.object_id,
                        expected_execution_run_id=run_parents[0].object_id,
                    )
                )
                result_projection = projection.result_state_projection
                expected_direction = {
                    "HIGHER_IS_BETTER": MetricDirection.HIGHER_IS_BETTER,
                    "LOWER_IS_BETTER": MetricDirection.LOWER_IS_BETTER,
                    "TARGET_IS_BEST": MetricDirection.TARGET_IS_BETTER,
                }.get(result_projection.metric_direction.value)
                expected_sources = result_projection.state_source_artifact_hashes
                expected_evaluations = (promotion_record.sha256,)
                expected_authorities = tuple(
                    sorted((*expected_sources, *expected_evaluations))
                )
                allowed = {
                    "scientific_result_promotion_authority": frozenset(
                        {Role.CLAIM_VERIFIER}
                    ),
                    "aggregate_experiment_result": frozenset({Role.STATISTICIAN}),
                    "experiment_output_manifest": frozenset({Role.EXPERIMENT_RUNNER}),
                    "experiment_output.paired_experiment_output": frozenset(
                        {Role.EXPERIMENT_RUNNER}
                    ),
                    "experiment_output.ablation_output": frozenset(
                        {Role.EXPERIMENT_RUNNER}
                    ),
                }
                self._require_exact_authority_roles(records, allowed)
                if (
                    expected_direction is None
                    or {item.sha256 for item in records} != set(expected_authorities)
                    or len(records) != len(expected_authorities)
                    or result_projection.result_id != record.object_id
                    or result_projection.run_id != run_parents[0].object_id
                    or result_projection.metric_id != record.metric_id
                    or record.producer is not Role.STATISTICIAN
                    or record.status is not RecordStatus.COMPLETE
                    or record.code_version
                    != result_projection.canonical_state_code_version
                    or record.code_revision
                    != result_projection.canonical_state_code_version
                    or thaw_json(record.value) != result_projection.state_value
                    or record.unit != result_projection.metric_unit.value
                    or record.direction is not expected_direction
                    or thaw_json(record.uncertainty)
                    != result_projection.state_uncertainty
                    or record.source_artifact_hashes != expected_sources
                    or record.evaluation_artifact_hashes != expected_evaluations
                    or record.authority_artifact_hashes != expected_authorities
                    or record.observed_at != result_projection.observed_at
                    or not self._timestamp_strictly_after(
                        record.created_at,
                        projection_event.timestamp,
                    )
                ):
                    raise ValidationError(
                        "canonical Result differs from its exact scientific "
                        "state projection"
                    )
                source_graph_eligible = self._validate_scientific_result_parent_join(
                    record=record,
                    run=run_parents[0],
                    metric=metric_parents[0],
                    result_projection=result_projection,
                    by_content=by_content,
                    require_materialized_lineage=(
                        not allow_unmaterialized_source_bound
                    ),
                )
                effective_eligible = bool(
                    resolution.scientific_evidence_eligible and source_graph_eligible
                )
                if not allow_unmaterialized_source_bound:
                    self._require_scientific_result_bundle_completion(
                        record,
                        by_content,
                        promotion_record=promotion_record,
                        expected_scientific_evidence_eligible=(effective_eligible),
                    )
                return _ResolvedObjectAuthority(
                    records,
                    effective_eligible,
                )
            # These are the only domain receipt namespaces whose complete
            # source/manifest/adapter replay is implemented by ``domains``.
            # Keep this map closed: a prefix or substring match here would let
            # an unimplemented domain label masquerade as semantic authority.
            domain_receipt_types = {
                "domain_validity.generic_ml": "GENERIC_ML",
                "domain_validity.medical_imaging": "MEDICAL_IMAGING",
                "domain_validity.time_series": "TIME_SERIES",
                "domain_validity.recommender_systems": "RECOMMENDER_SYSTEMS",
                "domain_validity.operations_research": "OPERATIONS_RESEARCH",
                "domain_validity.systems": "SYSTEMS",
            }
            allowed: dict[str, frozenset[Role]] = {
                "aggregate_experiment_result": frozenset({Role.STATISTICIAN}),
                "all_seed_report": frozenset({Role.STATISTICIAN}),
                "evaluator_integrity_assessment": frozenset({Role.SCIENTIFIC_REVIEWER}),
                "statistical_analysis": frozenset({Role.STATISTICIAN}),
                "experiment_output_manifest": frozenset({Role.EXPERIMENT_RUNNER}),
                "autonomous_implementation.semantic_validation": frozenset(
                    {Role.SCIENTIFIC_REVIEWER}
                ),
                "autonomous_implementation.fixture_evaluator": frozenset(
                    {Role.PROTOCOL_DESIGNER}
                ),
                "autonomous_implementation.execution_receipt": frozenset(
                    {Role.EXPERIMENT_RUNNER}
                ),
            }
            allowed.update(
                {
                    logical_type: frozenset({Role.SCIENTIFIC_REVIEWER})
                    for logical_type in domain_receipt_types
                }
            )
            manifests = self._records_of_types(
                records, frozenset({"experiment_output_manifest"})
            )
            manifest_sources: dict[str, str] = {}
            for manifest_record in manifests:
                manifest_value = self._read_authority_json(
                    manifest_record, require_canonical=False
                )
                try:
                    from .experiments import OutputManifest

                    manifest = OutputManifest.from_mapping(manifest_value)
                except Exception as exc:
                    raise ValidationError("result output manifest is invalid") from exc
                if manifest.run_id not in record.run_ids:
                    raise ValidationError("result manifest belongs to another run")
                for output in manifest.artifacts:
                    expected_type = f"experiment_output.{output.logical_type}"
                    allowed[expected_type] = frozenset({Role.EXPERIMENT_RUNNER})
                    manifest_sources[output.sha256] = expected_type
            self._require_exact_authority_roles(records, allowed)
            aggregates = self._records_of_types(
                records, frozenset({"aggregate_experiment_result"})
            )
            semantics = self._records_of_types(
                records,
                frozenset({"autonomous_implementation.semantic_validation"}),
            )
            domain_receipts = tuple(
                item for item in records if item.logical_type in domain_receipt_types
            )
            if aggregates:
                if len(aggregates) != 1 or not isinstance(record.value, Mapping):
                    raise ValidationError("aggregate result authority is ambiguous")
                if len(domain_receipts) != 1:
                    raise ValidationError(
                        "aggregate result requires one exact domain-validity receipt"
                    )
                seed_record = self._one_record(records, "all_seed_report")
                evaluator_record = self._one_record(
                    records, "evaluator_integrity_assessment"
                )
                statistics_record = self._one_record(records, "statistical_analysis")
                aggregate = self._read_authority_json(aggregates[0])
                seed_payload = self._read_authority_json(seed_record)
                seed_report = self._nested_mapping(seed_payload, "report")
                seed_runs = seed_payload.get("runs")
                evaluator_payload = self._read_authority_json(evaluator_record)
                evaluator = self._nested_mapping(evaluator_payload, "assessment")
                statistics = self._read_authority_json(statistics_record)
                interval = self._nested_mapping(statistics, "bootstrap")
                aggregate_distribution = aggregate.get("seed_distribution")
                if not isinstance(seed_runs, list) or not isinstance(
                    aggregate_distribution, list
                ):
                    raise ValidationError(
                        "aggregate result seed authorities are malformed"
                    )
                aggregate_seed_artifacts = tuple(aggregates[0].parent_artifacts)
                if not aggregate_seed_artifacts:
                    raise ValidationError(
                        "aggregate result requires non-empty seed authority"
                    )
                for seed_artifact_hash in aggregate_seed_artifacts:
                    seed_artifact = self._require_frozen_pass_artifact(
                        seed_artifact_hash,
                        logical_type="experiment_output.seed_result",
                        creator_role=Role.EXPERIMENT_RUNNER,
                    )
                    seed_payload = self._read_authority_json(
                        seed_artifact,
                        require_canonical=False,
                    )
                    matching_runs = tuple(
                        run
                        for run in run_parents
                        if run.object_id == seed_payload.get("run_id")
                        and seed_artifact_hash in run.output_artifact_hashes
                    )
                    if len(matching_runs) != 1:
                        raise ValidationError(
                            "aggregate seed authority does not belong to one "
                            "evaluated canonical Run"
                        )
                reported_seed_artifacts = tuple(
                    item.get("artifact_sha256")
                    for item in seed_runs
                    if isinstance(item, Mapping)
                )
                expected_uncertainty = {
                    "confidence_interval": interval.get("interval"),
                    "p_value": statistics.get("adjusted_p_value"),
                }
                if (
                    aggregate.get("metric_id") != record.metric_id
                    or set(thaw_json(record.value))
                    != {"baseline", "candidate", "improvement"}
                    or not self._float_matches(
                        aggregate.get("baseline_accuracy"),
                        record.value.get("baseline"),
                    )
                    or not self._float_matches(
                        aggregate.get("candidate_accuracy"),
                        record.value.get("candidate"),
                    )
                    or not self._float_matches(
                        aggregate.get("effect"), record.value.get("improvement")
                    )
                    or record.source_artifact_hashes != (aggregates[0].sha256,)
                    or set(record.evaluation_artifact_hashes)
                    != {
                        seed_record.sha256,
                        evaluator_record.sha256,
                        statistics_record.sha256,
                        domain_receipts[0].sha256,
                    }
                    or statistics_record.parent_artifacts != (aggregates[0].sha256,)
                    or thaw_json(record.uncertainty) != expected_uncertainty
                    or seed_record.parent_artifacts != aggregate_seed_artifacts
                    or reported_seed_artifacts != aggregate_seed_artifacts
                    or seed_report.get("regime") != "ALL_SEEDS"
                    or seed_report.get("selected_run_id") is not None
                    or seed_report.get("total_runs") != len(aggregate_distribution)
                    or seed_report.get("successful_runs") != len(aggregate_distribution)
                    or seed_report.get("failed_runs") != 0
                    or seed_report.get("invalid_runs") != 0
                    or seed_report.get("successful_distribution")
                    != [item.get("metric") for item in aggregate_distribution]
                    or evaluator.get("passed") is not True
                    or evaluator.get("signals") != []
                    or evaluator_record.parent_artifacts[-1:] != (seed_record.sha256,)
                ):
                    raise ValidationError(
                        "canonical result differs from aggregate authority"
                    )
                domain_record = domain_receipts[0]
                domain_payload = self._read_authority_json(domain_record)
                try:
                    from .domains import (
                        DomainEvidenceScope,
                        DomainKind,
                        DomainValidityStatus,
                        resolve_domain_validity,
                    )

                    domain = DomainKind(domain_payload.get("domain"))
                    task_id = domain_payload.get("task_id")
                    if (
                        domain.value != domain_receipt_types[domain_record.logical_type]
                        or domain_payload.get("run_id") != self.run_id
                        or domain_payload.get("object_id") != record.object_id
                        or not isinstance(task_id, str)
                    ):
                        raise ValidationError(
                            "domain receipt identity differs from canonical result"
                        )
                    resolved_domain = resolve_domain_validity(
                        self.registry,
                        domain_record.sha256,
                        expected_run_id=self.run_id,
                        expected_domain=domain,
                        expected_object_id=record.object_id,
                        expected_task_id=task_id,
                        ledger=self.ledger,
                    )
                except ValidationError:
                    raise
                except Exception as exc:
                    raise ValidationError(
                        "result domain-validity authority failed fresh resolution"
                    ) from exc
                domain_eligible = (
                    resolved_domain.scope is DomainEvidenceScope.SCIENTIFIC_EVIDENCE
                    and resolved_domain.outcome.status is DomainValidityStatus.PASS
                )
                if not isinstance(aggregate.get("scientific_evidence_eligible"), bool):
                    raise ValidationError(
                        "aggregate scientific eligibility label must be boolean"
                    )
                # Aggregate and domain replay establish exact result bytes and
                # domain validity, but neither is execution/promotion authority.
                # In particular, the aggregate's serialized boolean is caller
                # data.  Keep state ineligible until a source-owned checked
                # result-promotion resolver binds the Run, scientific timeline,
                # backend isolation, contract, aggregate, statistics, and domain
                # authority.  No such positive resolver is currently available.
                _ = domain_eligible
                eligible = False
            elif semantics:
                if len(semantics) != 1:
                    raise ValidationError("semantic result authority is ambiguous")
                if domain_receipts:
                    raise ValidationError(
                        "autonomous component result cannot borrow domain authority"
                    )
                semantic = self._read_authority_json(semantics[0])
                manifest_records = self._records_of_types(
                    records, frozenset({"experiment_output_manifest"})
                )
                evaluator_records = self._records_of_types(
                    records,
                    frozenset({"autonomous_implementation.fixture_evaluator"}),
                )
                execution_records = self._records_of_types(
                    records,
                    frozenset({"autonomous_implementation.execution_receipt"}),
                )
                if (
                    len(manifest_records) != 1
                    or len(evaluator_records) != 1
                    or len(execution_records) != 1
                    or semantic.get("status") != "PASS"
                    or semantic.get("run_id") not in record.run_ids
                    or not self._float_matches(
                        semantic.get("recomputed_metric"), thaw_json(record.value)
                    )
                    or semantic.get("scientific_evidence") is not False
                    or set(record.source_artifact_hashes) != set(manifest_sources)
                    or any(
                        self.registry.get_metadata(digest).logical_type
                        != manifest_sources[digest]
                        for digest in record.source_artifact_hashes
                    )
                    or set(record.evaluation_artifact_hashes)
                    != {
                        manifest_records[0].sha256,
                        semantics[0].sha256,
                        evaluator_records[0].sha256,
                        execution_records[0].sha256,
                    }
                    or evaluator_records[0].sha256
                    not in metric_parents[0].authority_artifact_hashes
                    or execution_records[0].sha256
                    not in run_parents[0].authority_artifact_hashes
                    or thaw_json(record.uncertainty)
                    != {
                        "classification": "SYSTEM_COMPONENT_FIXTURE_ONLY",
                        "scientific_inference": False,
                    }
                ):
                    raise ValidationError(
                        "canonical autonomous result differs from semantic recomputation"
                    )
                eligible = False
            else:
                raise ValidationError(
                    "result lacks aggregate or semantic-validation authority"
                )
            return _ResolvedObjectAuthority(records, eligible)

        if isinstance(record, StatisticalTest):
            result_parents = self._resolved_parent_objects(record, by_content, "Result")
            if {item.object_id for item in result_parents} != set(
                record.result_ids
            ) or any(
                item.status is not RecordStatus.COMPLETE for item in result_parents
            ):
                raise ValidationError(
                    "statistical test result IDs differ from evaluated parents"
                )
            promotion_records = self._records_of_types(
                records,
                frozenset({"scientific_result_promotion_authority"}),
            )
            promotion_v3_records = self._records_of_types(
                records,
                frozenset({"scientific_result_promotion_authority_v3"}),
            )
            if promotion_v3_records:
                if promotion_records:
                    raise ValidationError(
                        "StatisticalTest mixes legacy and outcome-neutral promotion"
                    )
                if (
                    len(promotion_v3_records) != 1
                    or len(result_parents) != 1
                    or record.result_ids != (result_parents[0].object_id,)
                    or len(result_parents[0].run_ids) != 1
                    or record.parents
                    != (
                        ObjectReference(
                            "Result",
                            result_parents[0].object_id,
                            result_parents[0].content_hash,
                            "tests",
                            True,
                        ),
                    )
                    or record.relationships
                    or record.revision != 1
                    or record.supersedes_content_hash is not None
                    or not self._timestamp_strictly_after(
                        record.created_at,
                        result_parents[0].created_at,
                    )
                ):
                    raise ValidationError(
                        "outcome-neutral StatisticalTest requires one exact later Result"
                    )
                parent_resolution = self._resolve_object_authority(
                    result_parents[0],
                    by_content,
                    allow_unmaterialized_source_bound=(
                        allow_unmaterialized_source_bound
                    ),
                )
                resolution, projection, promotion_record = (
                    self._resolve_scientific_result_promotion_v3(
                        records,
                        expected_result_id=result_parents[0].object_id,
                        expected_execution_run_id=result_parents[0].run_ids[0],
                    )
                )
                expected_sources = projection.statistical_state_source_artifact_hashes
                expected_authorities = tuple(sorted(expected_sources))
                allowed = {
                    "scientific_result_promotion_authority_v3": frozenset(
                        {Role.CLAIM_VERIFIER}
                    ),
                    "statistical_analysis": frozenset({Role.STATISTICIAN}),
                    "aggregate_experiment_result": frozenset({Role.STATISTICIAN}),
                }
                for source in records:
                    if source.logical_type.startswith("experiment_output."):
                        allowed[source.logical_type] = frozenset(
                            {Role.EXPERIMENT_RUNNER}
                        )
                self._require_exact_authority_roles(records, allowed)
                if (
                    {item.sha256 for item in records} != set(expected_authorities)
                    or len(records) != len(expected_authorities)
                    or record.producer is not Role.STATISTICIAN
                    or record.status is not RecordStatus.COMPLETE
                    or record.code_version != projection.canonical_state_code_version
                    or record.test_name != projection.contract_primary_test
                    or record.null_hypothesis != projection.null_hypothesis
                    or record.alternative != projection.alternative
                    or thaw_json(record.method_configuration)
                    != projection.statistical_state_method_configuration
                    or thaw_json(record.outcome) != projection.statistical_state_outcome
                    or record.source_artifact_hashes != expected_sources
                    or record.authority_artifact_hashes != expected_authorities
                    or thaw_json(record.metadata)
                    != projection.statistical_state_metadata
                    or result_parents[0].evaluation_artifact_hashes
                    != (promotion_record.sha256,)
                    or (
                        parent_resolution.scientific_evidence_eligible
                        and not resolution.scientific_evidence_eligible
                    )
                ):
                    raise ValidationError(
                        "canonical StatisticalTest differs from its exact "
                        "outcome-neutral projection"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    parent_resolution.scientific_evidence_eligible,
                )
            if promotion_records:
                if (
                    len(result_parents) != 1
                    or record.result_ids != (result_parents[0].object_id,)
                    or len(result_parents[0].run_ids) != 1
                    or len(record.parents) != 1
                    or record.parents[0]
                    != ObjectReference(
                        "Result",
                        result_parents[0].object_id,
                        result_parents[0].content_hash,
                        "tests",
                        True,
                    )
                    or record.relationships
                    or thaw_json(record.metadata) != {}
                    or record.revision != 1
                    or record.supersedes_content_hash is not None
                    or not self._timestamp_strictly_after(
                        record.created_at,
                        result_parents[0].created_at,
                    )
                ):
                    raise ValidationError(
                        "scientific StatisticalTest requires one exact later "
                        "Result parent"
                    )
                parent_resolution = self._resolve_object_authority(
                    result_parents[0],
                    by_content,
                    allow_unmaterialized_source_bound=(
                        allow_unmaterialized_source_bound
                    ),
                )
                resolution, projection, promotion_record, _projection_event = (
                    self._resolve_scientific_result_promotion(
                        records,
                        expected_result_id=result_parents[0].object_id,
                        expected_execution_run_id=result_parents[0].run_ids[0],
                    )
                )
                statistical_projection = projection.statistical_state_projection
                expected_sources = (
                    *statistical_projection.state_source_artifact_hashes,
                    promotion_record.sha256,
                )
                expected_authorities = tuple(sorted(expected_sources))
                allowed = {
                    "scientific_result_promotion_authority": frozenset(
                        {Role.CLAIM_VERIFIER}
                    ),
                    "statistical_analysis": frozenset({Role.STATISTICIAN}),
                    "aggregate_experiment_result": frozenset({Role.STATISTICIAN}),
                    "experiment_output.paired_experiment_output": frozenset(
                        {Role.EXPERIMENT_RUNNER}
                    ),
                    "experiment_output.ablation_output": frozenset(
                        {Role.EXPERIMENT_RUNNER}
                    ),
                }
                self._require_exact_authority_roles(records, allowed)
                if (
                    {item.sha256 for item in records} != set(expected_authorities)
                    or len(records) != len(expected_authorities)
                    or statistical_projection.statistical_test_id != record.object_id
                    or statistical_projection.result_id != result_parents[0].object_id
                    or statistical_projection.run_id != result_parents[0].run_ids[0]
                    or record.producer is not Role.STATISTICIAN
                    or record.status is not RecordStatus.COMPLETE
                    or record.code_version
                    != statistical_projection.canonical_state_code_version
                    or record.test_name != statistical_projection.contract_primary_test
                    or record.null_hypothesis != statistical_projection.null_hypothesis
                    or record.alternative != statistical_projection.alternative
                    or thaw_json(record.method_configuration)
                    != statistical_projection.state_method_configuration
                    or thaw_json(record.outcome) != statistical_projection.state_outcome
                    or record.source_artifact_hashes != expected_sources
                    or record.authority_artifact_hashes != expected_authorities
                    or result_parents[0].evaluation_artifact_hashes
                    != (promotion_record.sha256,)
                    or (
                        parent_resolution.scientific_evidence_eligible
                        and not resolution.scientific_evidence_eligible
                    )
                ):
                    raise ValidationError(
                        "canonical StatisticalTest differs from its exact "
                        "scientific state projection"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    parent_resolution.scientific_evidence_eligible,
                )
            self._require_exact_authority_roles(
                records,
                {"statistical_analysis": frozenset({Role.STATISTICIAN})},
            )
            if len(records) != 1:
                raise ValidationError(
                    "statistical test requires one exact analysis authority"
                )
            analysis = self._read_authority_json(records[0])
            interval = analysis.get("bootstrap")
            expected_interval = record.outcome.get("confidence_interval")
            if (
                analysis.get("test") != record.test_name
                or analysis.get("null_hypothesis") != record.null_hypothesis
                or analysis.get("alternative") != record.alternative
                or not isinstance(interval, Mapping)
                or record.method_configuration.get("ties") != "removed"
                or record.method_configuration.get("bootstrap_resamples")
                != interval.get("resamples")
                or record.method_configuration.get("bootstrap_seed")
                != interval.get("fixed_seed")
                or record.method_configuration.get("resampling_unit")
                != interval.get("resampling_unit")
                or not self._float_matches(
                    analysis.get("effect"), record.outcome.get("effect")
                )
                or not self._float_matches(
                    analysis.get("adjusted_p_value"),
                    record.outcome.get("p_value"),
                )
                or analysis.get("independent_unit_count")
                != record.outcome.get("sample_size")
                or interval.get("interval") != thaw_json(expected_interval)
            ):
                raise ValidationError(
                    "canonical statistical test differs from analysis authority"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Ablation):
            from .scientific_numeric_ablation_canonical import (
                is_numeric_ablation_metadata,
                require_numeric_ablation_canonical,
            )

            if is_numeric_ablation_metadata(record.metadata):
                require_numeric_ablation_canonical(self, record, records, by_content)
                # This does not inherit the parent Result's claim eligibility.
                # Complete-cohort coverage must explicitly reopen the native
                # descriptive owner; old claim/Soundness consumers stay closed.
                return _ResolvedObjectAuthority(records, scientific_evidence_eligible=False)
            experiment_parents = self._resolved_parent_objects(
                record, by_content, "Experiment"
            )
            result_parents = self._resolved_parent_objects(record, by_content, "Result")
            authority_types = {item.logical_type for item in records}
            result_relation = (
                "evaluates"
                if authority_types == {"scientific_ablation_authority"}
                else "contextualizes"
            )
            if (
                len(experiment_parents) != 1
                or len(result_parents) != 1
                or record.experiment_ids != (experiment_parents[0].object_id,)
                or record.result_ids != (result_parents[0].object_id,)
                or experiment_parents[0].status is not RecordStatus.FROZEN
                or result_parents[0].status is not RecordStatus.COMPLETE
                or record.hypothesis_id not in experiment_parents[0].hypothesis_ids
                or record.parents
                != (
                    ObjectReference(
                        "Experiment",
                        experiment_parents[0].object_id,
                        experiment_parents[0].content_hash,
                        "ablates",
                        True,
                    ),
                    ObjectReference(
                        "Result",
                        result_parents[0].object_id,
                        result_parents[0].content_hash,
                        result_relation,
                        True,
                    ),
                )
            ):
                raise ValidationError(
                    "canonical ablation fields differ from evaluated parents"
                )
            experiment = experiment_parents[0]
            result = result_parents[0]
            implementations = self._resolved_parent_objects(
                experiment,
                by_content,
                "Implementation",
            )
            if len(implementations) != 1 or not isinstance(
                implementations[0], Implementation
            ):
                raise ValidationError(
                    "canonical ablation lacks one exact Implementation"
                )
            methods = self._resolved_parent_objects(
                implementations[0],
                by_content,
                "Method",
            )
            runs = self._resolved_parent_objects(result, by_content, "Run")
            if len(methods) != 1 or not isinstance(methods[0], Method):
                raise ValidationError("canonical ablation lacks one exact Method")
            method = methods[0]
            if authority_types == {"scientific_ablation_authority"}:
                if (
                    len(runs) != 1
                    or not isinstance(runs[0], Run)
                    or result.run_ids != (runs[0].object_id,)
                    or runs[0].experiment_id != experiment.object_id
                ):
                    raise ValidationError(
                        "scientific ablation lacks one exact evaluated Run"
                    )
                run = runs[0]
                if (
                    record.status is not RecordStatus.COMPLETE
                    or record.producer is not Role.STATISTICIAN
                    or len(record.removed_component_ids) != 1
                    or record.removed_component_ids[0] not in method.component_ids
                ):
                    raise ValidationError(
                        "scientific ablation lifecycle or component projection differs"
                    )
                self._require_exact_authority_roles(
                    records,
                    {
                        "scientific_ablation_authority": frozenset(
                            {Role.SCIENTIFIC_REVIEWER}
                        )
                    },
                )
                if len(records) != 1:
                    raise ValidationError(
                        "scientific ablation requires one exact source authority"
                    )
                try:
                    from .scientific_design import (
                        require_scientific_ablation_authority,
                    )

                    authority = require_scientific_ablation_authority(
                        self.registry,
                        self.ledger,
                        expected_ledger_run_id=self.run_id,
                        expected_execution_run_id=run.object_id,
                        expected_ablation_id=record.object_id,
                        authority_artifact_sha256=records[0].sha256,
                    )
                except (AuthorizationError, ValidationError):
                    raise
                except Exception as exc:
                    raise ValidationError(
                        "scientific ablation failed fresh source-owned replay"
                    ) from exc

                stored_by_object = {
                    item.object_type: by_content.get(item.content_hash)
                    for item in (result, run, method, experiment)
                }
                events = self.ledger.events()
                event_index = {
                    event.event_id: index for index, event in enumerate(events)
                }

                def binding_matches(binding: Any, expected: Any) -> bool:
                    stored = stored_by_object.get(expected.object_type)
                    if (
                        stored is None
                        or stored.research_object != expected
                        or stored.artifact.sha256 != binding.artifact_sha256
                        or str(stored.artifact.record_hash)
                        != binding.artifact_record_hash
                    ):
                        return False
                    materialization = self._materialization_event(
                        stored.artifact.sha256,
                        expected,
                    )
                    return bool(
                        materialization is not None
                        and materialization.event_hash is not None
                        and binding.object_type == expected.object_type
                        and binding.object_id == expected.object_id
                        and binding.revision == expected.revision
                        and binding.content_hash == expected.content_hash
                        and binding.materialization_event_id == materialization.event_id
                        and binding.materialization_event_hash
                        == materialization.event_hash
                        and binding.materialization_event_index
                        == event_index.get(materialization.event_id)
                    )

                result_resolution = self._resolve_object_authority(
                    result,
                    by_content,
                )
                if (
                    authority.ablation_id != record.object_id
                    or authority.hypothesis_id != record.hypothesis_id
                    or authority.component_id not in method.component_ids
                    or record.removed_component_ids != (authority.component_id,)
                    or authority.authoritative is not True
                    or authority.executed is not True
                    or authority.status != "PASS"
                    or authority.scientific_evidence_eligible
                    is not result_resolution.scientific_evidence_eligible
                    or not binding_matches(
                        authority.result_state_binding,
                        result,
                    )
                    or not binding_matches(authority.run_state_binding, run)
                    or not binding_matches(
                        authority.method_state_binding,
                        method,
                    )
                    or not binding_matches(
                        authority.experiment_state_binding,
                        experiment,
                    )
                ):
                    raise ValidationError(
                        "canonical scientific ablation differs from its exact "
                        "contract, output, or canonical state authority"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    scientific_evidence_eligible=(
                        authority.scientific_evidence_eligible
                    ),
                )

            if authority_types != {"ablation_validation"} or len(records) != 1:
                raise ValidationError(
                    "ablation authority is mixed, absent, or unsupported"
                )
            if (
                not runs
                or {item.object_id for item in runs} != set(result.run_ids)
                or any(
                    not isinstance(item, Run)
                    or item.experiment_id != experiment.object_id
                    for item in runs
                )
            ):
                raise ValidationError(
                    "legacy ablation differs from its evaluated Run parents"
                )
            self._require_exact_authority_roles(
                records,
                {"ablation_validation": frozenset({Role.SCIENTIFIC_REVIEWER})},
            )
            # The retained validator below is a legacy system-fixture boundary.
            # It is deliberately incompatible with v2 Result promotion and can
            # never confer scientific evidence eligibility.
            result_resolution = self._resolve_object_authority(result, by_content)
            if any(
                item.logical_type == "scientific_result_promotion_authority"
                for item in result_resolution.records
            ):
                raise ValidationError(
                    "legacy ablation validation cannot bind a v2 scientific Result"
                )
            removed_candidates = set(method.component_ids)
            if set(record.removed_component_ids) != removed_candidates:
                raise ValidationError(
                    "legacy ablation component IDs lack exact Method authority"
                )
            payload = self._read_authority_json(records[0])
            legacy_result = self._nested_mapping(payload, "result")
            if len(records[0].parent_artifacts) != 2:
                raise ValidationError(
                    "legacy ablation validation requires raw output and aggregate parents"
                )
            output_record = self._require_frozen_pass_artifact(
                records[0].parent_artifacts[0],
                logical_type="experiment_output.ablation_result",
                creator_role=Role.EXPERIMENT_RUNNER,
            )
            aggregate_record = self._require_frozen_pass_artifact(
                records[0].parent_artifacts[1],
                logical_type="aggregate_experiment_result",
                creator_role=Role.STATISTICIAN,
            )
            output = self._read_authority_json(output_record)
            matching_result_runs = tuple(
                run_id
                for parent in result_parents
                for run_id in parent.run_ids
                if run_id == output.get("run_id")
            )
            if (
                payload.get("validation") != "PASS"
                or legacy_result.get("ablation_id") != record.object_id
                or legacy_result.get("executed") is not True
                or legacy_result.get("artifact_sha256") != output_record.sha256
                or output.get("ablation_id") != record.object_id
                or len(matching_result_runs) != 1
                or aggregate_record.sha256
                not in {
                    digest
                    for parent in result_parents
                    for digest in parent.source_artifact_hashes
                }
                or output_record.sha256
                not in {
                    digest
                    for parent in result_parents
                    for run_reference in parent.parents
                    if run_reference.object_type == "Run"
                    for stored_run in (by_content.get(run_reference.content_hash),)
                    if stored_run is not None
                    and isinstance(stored_run.research_object, Run)
                    for digest in stored_run.research_object.output_artifact_hashes
                }
            ):
                raise ValidationError(
                    "canonical legacy ablation differs from its validation authority"
                )
            return _ResolvedObjectAuthority(
                records,
                scientific_evidence_eligible=False,
            )

        if isinstance(record, Evidence):
            if record.verification_status is VerificationStatus.VERIFIED:
                allowed = dict(self._claim_authority_allowlist())
                allowed["reference_verification"] = frozenset({Role.CLAIM_VERIFIER})
                self._require_exact_authority_roles(records, allowed)
                self._validate_verified_evidence_boundary(record)
            elif record.verification_status is VerificationStatus.REJECTED:
                self._validate_rejected_evidence_boundary(record)
            return _ResolvedObjectAuthority(records, False)

        if isinstance(record, Claim):
            if record.verification_status is VerificationStatus.VERIFIED:
                self._require_exact_authority_roles(
                    records,
                    self._claim_authority_allowlist(),
                )
                eligible, claim_semantics = self._validate_verified_claim_boundary(
                    record,
                    by_content,
                )
            elif record.verification_status is VerificationStatus.REJECTED:
                self._validate_rejected_claim_boundary(record, by_content)
                eligible = False
                claim_semantics = None
            else:
                eligible = False
                claim_semantics = None
            return _ResolvedObjectAuthority(records, eligible, claim_semantics)

        if isinstance(record, Critique):
            claim_parents = self._resolved_parent_objects(record, by_content, "Claim")
            if {item.object_id for item in claim_parents} != set(
                record.target_ids
            ) or any(
                item.status is not RecordStatus.VERIFIED
                or item.verification_status is not VerificationStatus.VERIFIED
                for item in claim_parents
            ):
                raise ValidationError(
                    "critique targets differ from evaluated verified Claim parents"
                )
            self._require_exact_authority_roles(
                records,
                {
                    "challenger_finding": frozenset({Role.ADVERSARIAL_REVIEWER}),
                    "scientific_soundness_assessment": frozenset(
                        {Role.SCIENTIFIC_REVIEWER}
                    ),
                },
            )
            findings = self._records_of_types(
                records, frozenset({"challenger_finding"})
            )
            soundness = self._records_of_types(
                records, frozenset({"scientific_soundness_assessment"})
            )
            if not findings or len(soundness) != 1:
                raise ValidationError(
                    "critique requires Challenger findings and one soundness assessment"
                )
            soundness_payload = self._nested_mapping(
                self._read_authority_json(soundness[0]), "assessment"
            )
            soundness_run_id = soundness_payload.get("run_id")
            if soundness_run_id is not None:
                validate_identifier(soundness_run_id, "soundness run ID")
                if soundness_run_id != self.run_id:
                    raise ValidationError(
                        "critique soundness authority belongs to another run"
                    )
            try:
                from .gates import require_scientific_soundness_assessment

                assessment = require_scientific_soundness_assessment(
                    self.registry,
                    assessment_artifact_hash=soundness[0].sha256,
                    ledger=self.ledger,
                    expected_run_id=soundness_run_id,
                )
            except Exception as exc:
                raise ValidationError(
                    "critique soundness authority failed fresh resolution"
                ) from exc
            if {item.sha256 for item in findings} != set(
                assessment.finding_artifact_hashes
            ):
                raise ValidationError(
                    "critique finding artifacts differ from resolved soundness"
                )
            expected_findings = tuple(
                {
                    "category": item.category.value,
                    "severity": item.severity.value,
                    "status": item.status.value,
                }
                for item in assessment.findings
            )
            if (
                tuple(record.target_ids) != tuple(assessment.central_claim_ids)
                or any(
                    assessment.claim_graph_artifact_hash not in item.source_artifact_ids
                    for item in claim_parents
                )
                or tuple(thaw_json(item) for item in record.findings)
                != expected_findings
                or assessment.verdict.value != record.verdict
            ):
                raise ValidationError(
                    "canonical critique differs from freshly resolved soundness"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Decision):
            allowed = {
                "scientific_soundness_assessment": frozenset(
                    {Role.SCIENTIFIC_REVIEWER}
                ),
                "research_terminal_outcome": frozenset({Role.SCIENTIFIC_REVIEWER}),
                "terminal_soundness_source_receipt": frozenset(
                    {Role.SCIENTIFIC_REVIEWER}
                ),
            }
            self._require_exact_authority_roles(records, allowed)
            terminal_records = self._records_of_types(
                records, frozenset({"research_terminal_outcome"})
            )
            soundness_records = self._records_of_types(
                records, frozenset({"scientific_soundness_assessment"})
            )
            if terminal_records:
                if len(terminal_records) != 1:
                    raise ValidationError("terminal Decision authority is ambiguous")
                try:
                    from .terminal_outcomes import (
                        TERMINAL_OUTCOME_SCHEMA_VERSION,
                        _load_terminal_record_from_registry,
                        _resolve_authoritative_derivation,
                        _terminal_decision,
                    )

                    terminal = _load_terminal_record_from_registry(
                        self.registry, terminal_records[0].sha256
                    )
                    resolved = _resolve_authoritative_derivation(
                        self, terminal.derivation
                    )
                    expected_decision = _terminal_decision(
                        terminal, self, terminal_records[0].sha256
                    )
                except Exception as exc:
                    raise ValidationError(
                        "terminal Decision derivation failed live authority resolution"
                    ) from exc
                if (
                    terminal.run_id != self.run_id
                    or terminal_records[0].origin
                    != f"research-terminal:{terminal.run_id}:{terminal.record_id}"
                    or terminal_records[0].creation_command != self.creation_command
                    or (
                        terminal.schema_version == TERMINAL_OUTCOME_SCHEMA_VERSION
                        and terminal.authority_scope is not resolved.authority_scope
                    )
                    or record != expected_decision
                ):
                    raise ValidationError(
                        "canonical terminal Decision differs from terminal record"
                    )
            elif soundness_records:
                if len(soundness_records) != 1:
                    raise ValidationError("soundness Decision authority is ambiguous")
                soundness_payload = self._nested_mapping(
                    self._read_authority_json(soundness_records[0]),
                    "assessment",
                )
                soundness_run_id = soundness_payload.get("run_id")
                if soundness_run_id is not None:
                    validate_identifier(soundness_run_id, "soundness run ID")
                    if soundness_run_id != self.run_id:
                        raise ValidationError(
                            "Decision soundness authority belongs to another run"
                        )
                try:
                    from .gates import require_scientific_soundness_assessment

                    assessment = require_scientific_soundness_assessment(
                        self.registry,
                        assessment_artifact_hash=soundness_records[0].sha256,
                        ledger=self.ledger,
                        expected_run_id=soundness_run_id,
                    )
                except Exception as exc:
                    raise ValidationError(
                        "Decision soundness authority failed fresh resolution"
                    ) from exc
                expected_evidence_ids = {
                    *assessment.central_claim_ids,
                    *(item.challenge_id for item in assessment.findings),
                }
                claim_parents = self._resolved_parent_objects(
                    record, by_content, "Claim"
                )
                challenge_parents = self._resolved_parent_objects(
                    record, by_content, "Challenge"
                )
                if (
                    record.decision_type != "SOUNDNESS_PROMOTION"
                    or assessment.verdict.value != record.outcome
                    or set(record.evidence_ids) != expected_evidence_ids
                    or {item.object_id for item in (*claim_parents, *challenge_parents)}
                    != expected_evidence_ids
                    or {item.object_id for item in claim_parents}
                    != set(assessment.central_claim_ids)
                    or {item.object_id for item in challenge_parents}
                    != {item.challenge_id for item in assessment.findings}
                    or any(
                        item.status is not RecordStatus.VERIFIED
                        or item.verification_status is not VerificationStatus.VERIFIED
                        or assessment.claim_graph_artifact_hash
                        not in item.source_artifact_ids
                        for item in claim_parents
                    )
                    or record.reason != assessment.reason
                ):
                    raise ValidationError(
                        "canonical Decision differs from soundness assessment"
                    )
            else:
                raise ValidationError("Decision lacks supported semantic authority")
            return _ResolvedObjectAuthority(records)

        if isinstance(record, Challenge):
            claim_parents = self._resolved_parent_objects(record, by_content, "Claim")
            if {item.object_id for item in claim_parents} != set(
                record.target_claim_ids
            ) or any(
                item.status is not RecordStatus.VERIFIED
                or item.verification_status is not VerificationStatus.VERIFIED
                for item in claim_parents
            ):
                raise ValidationError(
                    "challenge targets differ from evaluated verified Claim parents"
                )
            self._require_exact_authority_roles(
                records,
                {
                    "challenger_finding": frozenset({Role.ADVERSARIAL_REVIEWER}),
                    "challenger_finding_resolution_receipt": frozenset(
                        {Role.CLAIM_VERIFIER}
                    ),
                },
            )
            if len(records) not in {1, 2}:
                raise ValidationError("challenge authority bundle is ambiguous")
            finding_record = self._one_record(records, "challenger_finding")
            try:
                from .gates import _load_challenge_finding

                finding = _load_challenge_finding(
                    self.registry,
                    finding_record.sha256,
                    ledger=self.ledger,
                )
            except Exception as exc:
                raise ValidationError("canonical Challenge finding is invalid") from exc
            if (
                finding.challenge_id != record.object_id
                or finding.attack != record.finding
                or tuple(finding.target_claim_ids) != tuple(record.target_claim_ids)
                or any(
                    finding.claim_graph_artifact_hash not in item.source_artifact_ids
                    for item in claim_parents
                )
                or finding.severity.value != record.severity.value
                or finding.status.value != record.resolution_status.value
            ):
                raise ValidationError(
                    "canonical Challenge differs from the typed finding"
                )
            if record.resolution_status is ChallengeResolution.RESOLVED:
                receipt = self._one_record(
                    records, "challenger_finding_resolution_receipt"
                )
                if finding.resolution_receipt_hash != receipt.sha256:
                    raise ValidationError(
                        "resolved Challenge lacks its exact independent receipt"
                    )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, VenueAssessment):
            self._require_exact_authority_roles(
                records,
                {"venue_readiness_assessment": frozenset({Role.SCIENTIFIC_REVIEWER})},
            )
            if len(records) != 1:
                raise ValidationError(
                    "venue state requires one exact readiness assessment"
                )
            assessment_record = records[0]
            if assessment_record.origin == (
                "fresh deterministic venue assessment over exact paper authority"
            ):
                try:
                    from .paper_pipeline import (
                        require_venue_assessment,
                    )

                    authority = require_venue_assessment(
                        self.registry,
                        self.ledger,
                        run_id=self.run_id,
                        assessment_artifact_hash=assessment_record.sha256,
                    )
                except ValidationError:
                    raise
                except Exception as exc:
                    raise ValidationError(
                        "canonical VenueAssessment authority failed fresh replay"
                    ) from exc
                self._require_final_venue_projection(
                    record, by_content, assessment_record=assessment_record,
                    authority=authority,
                )
                return _ResolvedObjectAuthority(records)

            # Compatibility is intentionally confined to the existing
            # source-free Research OS fixture.  It can represent only a
            # conservative NOT_READY view and can never promote venue fit.
            if (
                assessment_record.origin
                != "conservative venue-profile readiness assessment"
                or assessment_record.creation_command
                != ("scientist-one", "research-os-fixture")
                or len(assessment_record.parent_artifacts) != 1
            ):
                raise ValidationError(
                    "source-free venue authority is not the supported fixture boundary"
                )
            payload = self._read_authority_json(assessment_record)
            if set(payload) != {"assessment", "fixture_notice"}:
                raise ValidationError(
                    "source-free venue fixture authority has an invalid schema"
                )
            try:
                from .paper_pipeline import _venue_assessment_from_json

                assessment = _venue_assessment_from_json(
                    self._nested_mapping(payload, "assessment")
                )
            except ValidationError:
                raise
            except Exception as exc:
                raise ValidationError(
                    "source-free venue fixture assessment is malformed"
                ) from exc
            verification_parent = self._require_frozen_pass_artifact(
                assessment_record.parent_artifacts[0],
                logical_type="paper_verification",
                creator_role=Role.SCIENTIFIC_REVIEWER,
            )
            if (
                not isinstance(payload["fixture_notice"], str)
                or not payload["fixture_notice"].strip()
                or verification_parent.sha256 != assessment_record.parent_artifacts[0]
                or assessment.classification.value != VenueFit.NOT_READY.value
                or assessment.profile_id != record.profile
                or tuple(item.value for item in assessment.hard_blockers)
                != tuple(record.blockers)
                or assessment.run_id is not None
                or record.classification is not VenueFit.NOT_READY
            ):
                raise ValidationError(
                    "canonical venue assessment differs from source-free fixture authority"
                )
            return _ResolvedObjectAuthority(records)

        if isinstance(record, ReproducibilityPackage):
            run_references = tuple(
                item for item in record.parents if item.object_type == "Run"
            )
            result_references = tuple(
                item for item in record.parents if item.object_type == "Result"
            )
            if (
                len(run_references) != len(record.run_ids)
                or {item.object_id for item in run_references} != set(record.run_ids)
                or any(
                    item.relation != "packages" or item.evaluated is not True
                    for item in run_references
                )
                or len(result_references) > 1
                or any(
                    item.relation != "reproduces" or item.evaluated is not True
                    for item in result_references
                )
                or len(record.parents) != len(run_references) + len(result_references)
            ):
                raise ValidationError(
                    "reproduction package has an invalid canonical parent shape"
                )
            run_parents = self._resolved_parent_objects(record, by_content, "Run")
            if (
                {item.object_id for item in run_parents} != set(record.run_ids)
                or any(
                    item.status is not RecordStatus.COMPLETE
                    or item.completed_at is None
                    for item in run_parents
                )
                or {item.code_revision for item in run_parents}
                != {record.source_revision}
                or {item.evaluator_version for item in run_parents}
                != {record.evaluator_version}
                or len({item.experiment_id for item in run_parents}) != 1
            ):
                raise ValidationError(
                    "reproduction package differs from evaluated Run parents"
                )
            result_parents = self._resolved_parent_objects(
                record,
                by_content,
                "Result",
            )
            if result_parents and (
                result_parents[0].status is not RecordStatus.COMPLETE
                or not result_parents[0].run_ids
                or not set(result_parents[0].run_ids).issubset(record.run_ids)
            ):
                raise ValidationError(
                    "reproduction package differs from its evaluated Result parent"
                )
            scientific_clean_records = self._records_of_types(
                records,
                frozenset({"scientific_clean_rerun_authority"}),
            )
            if scientific_clean_records:
                if (
                    len(scientific_clean_records) != 1
                    or len(run_parents) != 2
                    or len(result_parents) != 1
                ):
                    raise ValidationError(
                        "scientific reproduction requires one Result and two Runs"
                    )
                clean_record = scientific_clean_records[0]
                try:
                    from .reproduction import (
                        ScientificCleanRerunOutcome,
                        require_scientific_clean_rerun_authority,
                    )

                    clean = require_scientific_clean_rerun_authority(
                        self.registry,
                        self.ledger,
                        authority_artifact_sha256=clean_record.sha256,
                        expected_ledger_run_id=self.run_id,
                        expected_original_execution_run_id=record.run_ids[0],
                        expected_rerun_execution_run_id=record.run_ids[1],
                    )
                except (AuthorizationError, ValidationError):
                    raise
                except Exception as exc:
                    raise ValidationError(
                        "scientific reproduction failed clean-rerun owner replay"
                    ) from exc
                run_by_id = {item.object_id: item for item in run_parents}
                original_run = run_by_id.get(clean.original_execution_run_id)
                rerun_run = run_by_id.get(clean.rerun_execution_run_id)
                original_result = result_parents[0]
                if original_run is None or rerun_run is None:
                    raise ValidationError(
                        "scientific reproduction Run identities are substituted"
                    )
                original_run_resolution = self._resolve_object_authority(
                    original_run,
                    by_content,
                )
                rerun_run_resolution = self._resolve_object_authority(
                    rerun_run,
                    by_content,
                )
                result_resolution = self._resolve_object_authority(
                    original_result,
                    by_content,
                )
                verification_events = self.ledger.events()
                if clean.verification_event_index >= len(verification_events):
                    raise ValidationError(
                        "scientific reproduction verification event is absent"
                    )
                verification_event = verification_events[clean.verification_event_index]
                expected_status = ReproductionStatus(clean.outcome.value)
                expected_manifests = (
                    clean.original_output_manifest_artifact_sha256,
                    clean.rerun_output_manifest_artifact_sha256,
                )
                expected_environments = (
                    clean.original_environment_artifact_sha256,
                    clean.rerun_environment_artifact_sha256,
                )
                expected_authorities = tuple(
                    sorted(
                        {
                            clean_record.sha256,
                            *expected_manifests,
                            *expected_environments,
                        }
                    )
                )
                expected_metadata = {
                    "schema_version": (
                        SCIENTIFIC_REPRODUCIBILITY_PACKAGE_METADATA_SCHEMA
                    ),
                    "authority_scope": clean.authority_scope,
                    "scientific_evidence": True,
                    "clean_rerun_authority_artifact_sha256": (clean_record.sha256),
                    "original_result_id": clean.original_result_id,
                    "original_result_promotion_artifact_sha256": (
                        clean.original_result_promotion_artifact_sha256
                    ),
                    "cross_host_replication_claimed": False,
                }
                self._require_exact_authority_roles(
                    records,
                    {
                        "scientific_clean_rerun_authority": frozenset(
                            {Role.REPRODUCTION_VERIFIER}
                        ),
                        "experiment_output_manifest": frozenset(
                            {Role.EXPERIMENT_RUNNER}
                        ),
                        "scientific_execution_environment": frozenset(
                            {Role.EXPERIMENT_RUNNER}
                        ),
                    },
                )
                if (
                    clean.outcome
                    not in {
                        ScientificCleanRerunOutcome.PASS,
                        ScientificCleanRerunOutcome.FAIL,
                        ScientificCleanRerunOutcome.OUTSIDE_TOLERANCE,
                    }
                    or record.parents
                    != (
                        ObjectReference(
                            "Result",
                            original_result.object_id,
                            original_result.content_hash,
                            "reproduces",
                            True,
                        ),
                        ObjectReference(
                            "Run",
                            original_run.object_id,
                            original_run.content_hash,
                            "packages",
                            True,
                        ),
                        ObjectReference(
                            "Run",
                            rerun_run.object_id,
                            rerun_run.content_hash,
                            "packages",
                            True,
                        ),
                    )
                    or record.run_ids
                    != (
                        clean.original_execution_run_id,
                        clean.rerun_execution_run_id,
                    )
                    or original_result.object_id != clean.original_result_id
                    or original_result.run_ids != (clean.original_execution_run_id,)
                    or original_result.evaluation_artifact_hashes
                    != (clean.original_result_promotion_artifact_sha256,)
                    or original_run.output_artifact_hashes[1:2]
                    != (clean.original_output_manifest_artifact_sha256,)
                    or rerun_run.output_artifact_hashes[1:2]
                    != (clean.rerun_output_manifest_artifact_sha256,)
                    or original_run.code_revision != rerun_run.code_revision
                    or original_run.evaluator_version != rerun_run.evaluator_version
                    or record.manifest_artifact_hashes != expected_manifests
                    or record.environment_artifact_hashes != expected_environments
                    or record.source_revision != original_run.code_revision
                    or record.evaluator_version != original_run.evaluator_version
                    or record.reproduction_status is not expected_status
                    or record.reproduced_at != verification_event.timestamp
                    or verification_event.event_id != clean.verification_event_id
                    or verification_event.event_hash != clean.verification_event_hash
                    or record.producer is not Role.REPRODUCTION_VERIFIER
                    or record.status is not RecordStatus.COMPLETE
                    or record.revision != 1
                    or record.supersedes_content_hash is not None
                    or record.relationships
                    or record.code_version != self.code_version
                    or thaw_json(record.metadata) != expected_metadata
                    or record.authority_artifact_hashes != expected_authorities
                    or {item.sha256 for item in records} != set(expected_authorities)
                    or len(records) != len(expected_authorities)
                    or original_run_resolution.scientific_evidence_eligible is not True
                    or rerun_run_resolution.scientific_evidence_eligible is not True
                    or result_resolution.scientific_evidence_eligible is not True
                    or not all(
                        self._timestamp_strictly_after(
                            record.created_at,
                            item.created_at,
                        )
                        for item in (
                            clean_record,
                            original_result,
                            original_run,
                            rerun_run,
                        )
                    )
                ):
                    raise ValidationError(
                        "canonical reproduction differs from its clean-rerun authority"
                    )
                return _ResolvedObjectAuthority(
                    records,
                    scientific_evidence_eligible=True,
                )
            allowed = {
                "experiment_output_manifest": frozenset({Role.EXPERIMENT_RUNNER}),
                "clean_reproduction_comparison": frozenset(
                    {Role.REPRODUCTION_VERIFIER}
                ),
                "execution_environment": frozenset({Role.EXPERIMENT_RUNNER}),
                "reproduction_report": frozenset({Role.REPRODUCTION_VERIFIER}),
            }
            self._require_exact_authority_roles(records, allowed)
            manifest_records = self._records_of_types(
                records, frozenset({"experiment_output_manifest"})
            )
            comparison_records = self._records_of_types(
                records, frozenset({"clean_reproduction_comparison"})
            )
            environment_records = self._records_of_types(
                records, frozenset({"execution_environment"})
            )
            if (
                len(manifest_records) != len(record.run_ids)
                or len(comparison_records) != 1
                or len(environment_records) != 1
                or set(record.manifest_artifact_hashes)
                != {
                    *(item.sha256 for item in manifest_records),
                    comparison_records[0].sha256,
                }
                or record.environment_artifact_hashes
                != (environment_records[0].sha256,)
            ):
                raise ValidationError(
                    "reproduction package source bundle is incomplete or substituted"
                )
            try:
                from .experiments import OutputManifest

                manifests = tuple(
                    OutputManifest.from_mapping(
                        self._read_authority_json(item, require_canonical=False)
                    )
                    for item in manifest_records
                )
            except Exception as exc:
                raise ValidationError(
                    "reproduction package manifest authority is invalid"
                ) from exc
            comparison = self._read_authority_json(comparison_records[0])
            environment = self._read_authority_json(environment_records[0])
            expected_comparison_parents = tuple(
                digest for run in run_parents for digest in run.output_artifact_hashes
            )
            if (
                {item.run_id for item in manifests} != set(record.run_ids)
                or set(comparison_records[0].parent_artifacts)
                != set(expected_comparison_parents)
                or len(comparison_records[0].parent_artifacts)
                != len(set(expected_comparison_parents))
                or comparison.get("scientific_evidence_eligible") is not False
                or environment.get("run_id") != self.run_id
                or environment.get("scientific_evidence_eligible") is not False
            ):
                raise ValidationError(
                    "reproduction package differs from exact run/environment custody"
                )
            if record.reproduction_status in {
                ReproductionStatus.PASS,
                ReproductionStatus.FAIL,
                ReproductionStatus.OUTSIDE_TOLERANCE,
            }:
                report_record = self._one_record(records, "reproduction_report")
                report = self._read_authority_json(report_record)
                if report.get("status") != record.reproduction_status.value:
                    raise ValidationError(
                        "canonical reproduction status differs from frozen replay"
                    )
                try:
                    from .reproduction import verify_frozen_reproduction

                    verified = verify_frozen_reproduction(
                        self.registry.policy.root,
                        self.run_id,
                        report,
                    )
                except Exception as exc:
                    raise ValidationError(
                        "reproduction status failed live frozen replay"
                    ) from exc
                if verified.status != record.reproduction_status.value:
                    raise ValidationError(
                        "reproduction replay differs from canonical status"
                    )
                # The only currently supported replay is the local synthetic
                # confirmatory fixture.  Its comparison and environment are
                # deliberately marked non-evidentiary above, and it does not
                # bind a distinct execution rerun to this package's exact Run
                # state.  A PASS is therefore useful as an architecture-control
                # result, but it must never become scientific ROBUSTNESS
                # authority.  A future positive path requires a separately
                # typed, source-owned rerun authority rather than promoting
                # this legacy replay label.
                eligible = False
            else:
                if any(item.logical_type == "reproduction_report" for item in records):
                    raise ValidationError(
                        "non-run reproduction package cannot bind a completed report"
                    )
                eligible = False
            return _ResolvedObjectAuthority(records, eligible)

        raise ValidationError(
            f"no semantic authority resolver exists for {record.object_type}"
        )

    def _resolve_confirmatory_authority(
        self,
        records: tuple[ArtifactRecord, ...],
        graph_artifact: ArtifactRecord,
        *,
        expected_claim_ids: tuple[str, ...],
    ) -> bool:
        authority_records = tuple(
            item
            for item in records
            if item.logical_type == "confirmatory_claim_authority"
        )
        graph_wrapper = self._read_authority_json(graph_artifact)
        graph = self._nested_mapping(graph_wrapper, "graph")
        serialized_claims = graph.get("claims")
        if not isinstance(serialized_claims, list):
            raise ValidationError("confirmatory claim graph claims are malformed")
        graph_claims = tuple(
            item
            for item in serialized_claims
            if isinstance(item, Mapping) and item.get("claim_id") in expected_claim_ids
        )
        if len(graph_claims) != len(expected_claim_ids) or {
            item.get("claim_id") for item in graph_claims
        } != set(expected_claim_ids):
            raise ValidationError(
                "confirmatory authority targets differ from exact graph claims"
            )
        confirmatory_claim_ids = tuple(
            sorted(
                item["claim_id"]
                for item in graph_claims
                if item.get("confirmatory") is True
            )
        )
        if not confirmatory_claim_ids:
            if authority_records:
                raise ValidationError(
                    "non-confirmatory state cannot borrow claim authority"
                )
            return False
        if len(authority_records) != len(confirmatory_claim_ids):
            raise ValidationError(
                "each confirmatory claim requires one exact claim-scoped authority"
            )
        try:
            from .paper_pipeline import (
                ConfirmatoryAuthorityScope,
                require_confirmatory_claim_authority,
            )

            unused = {item.sha256 for item in authority_records}
            for claim_id in confirmatory_claim_ids:
                matches: list[tuple[str, Any]] = []
                for authority_hash in sorted(unused):
                    try:
                        authority = require_confirmatory_claim_authority(
                            self.registry,
                            self.ledger,
                            authority_artifact_hash=authority_hash,
                            expected_run_id=self.run_id,
                            expected_claim_id=claim_id,
                            expected_claim_graph_artifact_hash=(graph_artifact.sha256),
                        )
                    except ValidationError:
                        continue
                    matches.append((authority_hash, authority))
                if len(matches) != 1:
                    raise ValidationError(
                        "confirmatory claim authority is missing, ambiguous, or substituted"
                    )
                authority_hash, authority = matches[0]
                if (
                    authority.scope
                    is not ConfirmatoryAuthorityScope.SCIENTIFIC_EVIDENCE
                    or authority.scientific_gate_passed is not True
                ):
                    raise ValidationError(
                        "confirmatory claim authority is not scientific evidence"
                    )
                unused.remove(authority_hash)
            if unused:
                raise ValidationError(
                    "confirmatory state includes unrelated claim authority"
                )
        except ValidationError:
            raise
        except Exception as exc:
            raise ValidationError(
                "confirmatory claim authority failed fresh custody-and-ledger resolution"
            ) from exc
        return True

    def _resolve_claim_graph_decision(
        self,
        digest: str,
        *,
        expected_claim_id: str,
        expected_decisions: frozenset[GraphClaimDecision],
        expected_claim_text: str | None = None,
        expected_claim_producer: Role | None = None,
        expected_confirmatory: bool | None = None,
        expected_evidence_use: ClaimEvidenceUse | None = None,
        confirmatory_evidence_valid: bool = False,
    ) -> tuple[ArtifactRecord, VerifierDecision, ClaimEvidenceGraph]:
        """Rehydrate and independently re-check one exact graph decision."""

        if (
            not isinstance(expected_decisions, frozenset)
            or not expected_decisions
            or not all(
                isinstance(item, GraphClaimDecision) for item in expected_decisions
            )
        ):
            raise ValidationError(
                "claim-evidence graph expected decisions must be a non-empty typed set"
            )

        artifact = self._require_frozen_pass_artifact(
            digest,
            logical_type="claim_evidence_graph",
            creator_role=Role.CLAIM_VERIFIER,
        )
        if not artifact.parent_artifacts:
            raise ValidationError(
                "claim-evidence graph lacks registry provenance parents"
            )
        raw = self.registry.get_bytes(digest)
        try:
            payload = safe_json_loads(raw)
        except Exception as exc:
            raise ValidationError("claim-evidence graph payload is invalid") from exc
        if not isinstance(payload, Mapping):
            raise ValidationError("claim-evidence graph payload must be an object")
        if raw != canonical_json_bytes(payload) + b"\n":
            raise ValidationError("claim-evidence graph payload is not canonical JSON")
        graph_value = payload.get("graph", payload)
        if not isinstance(graph_value, Mapping):
            raise ValidationError("claim-evidence graph wrapper lacks a typed graph")
        try:
            graph = ClaimEvidenceGraph.from_dict(
                graph_value,
                evidence_resolver=artifact_registry_resolver(
                    self.registry,
                    resolver_id=CLAIM_GRAPH_RESOLVER_ID,
                ),
            )
        except Exception as exc:
            raise ValidationError(
                "claim-evidence graph cannot be safely rehydrated"
            ) from exc
        graph_claim = next(
            (item for item in graph.claims if item.claim_id == expected_claim_id),
            None,
        )
        if graph_claim is None:
            raise ValidationError(
                "claim-evidence graph does not contain the canonical claim"
            )
        if expected_claim_text is not None and graph_claim.text != expected_claim_text:
            raise ValidationError(
                "canonical claim text differs from the checked graph claim"
            )
        if (
            expected_claim_producer is not None
            and graph_claim.producer_role is not expected_claim_producer
        ):
            raise AuthorizationError(
                "canonical claim producer differs from the checked graph producer"
            )
        if (
            expected_confirmatory is not None
            and graph_claim.confirmatory is not expected_confirmatory
        ):
            raise ValidationError(
                "canonical claim confirmatory scope differs from the checked graph"
            )
        if (
            expected_evidence_use is not None
            and graph_claim.evidence_use is not expected_evidence_use
        ):
            raise ValidationError(
                "canonical claim evidence use differs from the checked graph"
            )

        decisions = graph_value.get("decisions")
        if not isinstance(decisions, list):
            raise ValidationError(
                "claim-evidence graph lacks serialized verifier decisions"
            )
        serialized_matches = [
            item
            for item in decisions
            if isinstance(item, Mapping)
            and item.get("claim_id") == expected_claim_id
            and item.get("verifier_role") == Role.CLAIM_VERIFIER.value
        ]
        if len(serialized_matches) != 1:
            raise ValidationError(
                "claim-evidence graph lacks one authoritative current decision"
            )
        serialized = serialized_matches[0]
        verifier_id = serialized.get("verifier_id")
        validate_identifier(verifier_id, "claim graph verifier ID")
        try:
            decision_from_graph = VerifierDecision(
                claim_id=serialized["claim_id"],
                decision=GraphClaimDecision(serialized["decision"]),
                verifier_id=serialized["verifier_id"],
                verifier_role=Role(serialized["verifier_role"]),
                reason=serialized["reason"],
                checked_evidence_hashes=tuple(serialized["checked_evidence_hashes"]),
                evidence_receipt_hashes=tuple(serialized["evidence_receipt_hashes"]),
                missing_kinds=tuple(
                    GraphEvidenceKind(item) for item in serialized["missing_kinds"]
                ),
                contradictions=tuple(serialized["contradictions"]),
            )
            if decision_from_graph.sha256 != serialized["sha256"]:
                raise ValidationError(
                    "claim-evidence graph decision hash is inconsistent"
                )
            decision = graph.verify_claim(
                expected_claim_id,
                verifier_id=verifier_id,
                verifier_role=Role.CLAIM_VERIFIER,
                confirmatory_evidence_valid=confirmatory_evidence_valid,
                raise_on_rejection=False,
            )
        except Exception as exc:
            raise ValidationError(
                "claim-evidence graph failed fresh registry-resolved verification"
            ) from exc
        if decision != decision_from_graph:
            raise ValidationError(
                "fresh verifier decision differs from its exact serialized reason, "
                "contradiction, evidence, or receipt closure"
            )
        if decision.decision not in expected_decisions:
            raise ValidationError(
                "claim-evidence graph decision is outside the required authority branch"
            )
        graph_parents = set(artifact.parent_artifacts)
        support_receipt_hashes = {
            node.verification_receipt_hash
            for node in graph.evidence
            if node.verification_receipt_hash is not None
        }
        serialized_verification_hashes = {
            digest
            for serialized in decisions
            if isinstance(serialized, Mapping)
            for digest in serialized.get("evidence_receipt_hashes", ())
            if isinstance(digest, str)
        }
        expected_graph_parents = {
            *(node.artifact_hash for node in graph.evidence),
            *support_receipt_hashes,
            *serialized_verification_hashes,
        }
        if graph_parents != expected_graph_parents:
            raise ValidationError(
                "claim-evidence graph parents differ from its exact evidence closure"
            )
        for receipt_hash in decision.evidence_receipt_hashes:
            receipt_artifact = self._require_frozen_pass_artifact(
                receipt_hash,
                creator_role=Role.CLAIM_VERIFIER,
            )
            raw_receipt = self.registry.get_bytes(receipt_hash)
            try:
                receipt = EvidenceVerificationReceipt.from_dict(
                    safe_json_loads(raw_receipt)
                )
            except Exception as exc:
                raise ValidationError(
                    "claim evidence verification receipt payload is invalid"
                ) from exc
            expected_logical_type = (
                f"claim_evidence_verification_receipt.{receipt.evidence_kind.value}"
            )
            if receipt_artifact.logical_type != expected_logical_type:
                raise ValidationError(
                    "claim evidence verification receipt has the wrong logical type"
                )
            if raw_receipt != receipt.canonical_bytes or receipt.sha256 != receipt_hash:
                raise ValidationError(
                    "claim evidence verification receipt is not canonical or hash-bound"
                )
            if receipt.resolver_id != CLAIM_GRAPH_RESOLVER_ID:
                raise ValidationError(
                    "claim evidence verification receipt uses an unstable resolver identity"
                )
            if decision.decision is GraphClaimDecision.ELIGIBLE and (
                receipt.validation_result != "PASS"
                or receipt.frozen is not True
                or receipt.supports_claim is not True
                or receipt.contradicts_claim is not False
                or receipt.locally_verifiable is not True
            ):
                raise ValidationError(
                    "eligible claim evidence receipt is not supportive and passing"
                )
            if receipt_artifact.parent_artifacts != (
                receipt.artifact_hash,
                receipt.support_receipt_hash,
            ):
                raise ValidationError(
                    "claim evidence verification receipt registry parents are invalid"
                )
            if receipt_hash not in graph_parents:
                raise ValidationError(
                    "claim-evidence graph omits a materialized verification receipt"
                )
        return artifact, decision, graph

    def _resolve_claim_graph_artifact(
        self,
        digest: str,
        *,
        expected_claim_id: str,
        expected_claim_text: str | None = None,
        expected_claim_producer: Role | None = None,
        expected_confirmatory: bool | None = None,
        expected_evidence_use: ClaimEvidenceUse | None = None,
        confirmatory_evidence_valid: bool = False,
    ) -> ArtifactRecord:
        """Resolve the existing positive, writer-eligible graph branch."""

        artifact, _decision, _graph = self._resolve_claim_graph_decision(
            digest,
            expected_claim_id=expected_claim_id,
            expected_decisions=frozenset({GraphClaimDecision.ELIGIBLE}),
            expected_claim_text=expected_claim_text,
            expected_claim_producer=expected_claim_producer,
            expected_confirmatory=expected_confirmatory,
            expected_evidence_use=expected_evidence_use,
            confirmatory_evidence_valid=confirmatory_evidence_valid,
        )
        return artifact

    def _claim_graph_receipt_closure(
        self,
        graph_artifact: ArtifactRecord,
    ) -> tuple[str, ...]:
        receipt_prefixes = (
            "claim_support_receipt.",
            "claim_evidence_verification_receipt.",
        )
        return tuple(
            sorted(
                digest
                for digest in graph_artifact.parent_artifacts
                if self.registry.get_metadata(digest).logical_type.startswith(
                    receipt_prefixes
                )
            )
        )

    def _validate_rejected_evidence_boundary(self, record: Evidence) -> None:
        """Resolve one conservative Evidence rejection from a negative graph."""

        if (
            record.verification_status is not VerificationStatus.REJECTED
            or record.status is not RecordStatus.REJECTED
            or record.producer is not Role.CLAIM_VERIFIER
            or record.revision != 1
            or record.supersedes_content_hash is not None
            or record.parents
            or record.relationships
            or thaw_json(record.metadata)
        ):
            raise ValidationError(
                "rejected Evidence must be one neutral claim-verifier-owned revision"
            )
        records = self._authority_records(record)
        allowed = {
            "claim_evidence_graph": frozenset({Role.CLAIM_VERIFIER}),
            **{
                f"claim_support_receipt.{kind.value}": frozenset({Role.CLAIM_VERIFIER})
                for kind in GraphEvidenceKind
            },
            **{
                f"claim_evidence_verification_receipt.{kind.value}": frozenset(
                    {Role.CLAIM_VERIFIER}
                )
                for kind in GraphEvidenceKind
            },
        }
        self._require_exact_authority_roles(records, allowed)
        graph_records = tuple(
            item for item in records if item.logical_type == "claim_evidence_graph"
        )
        if len(graph_records) != 1:
            raise ValidationError(
                "rejected Evidence requires one exact claim-evidence graph"
            )
        graph_artifact = graph_records[0]
        try:
            graph_value = self._nested_mapping(
                self._read_authority_json(graph_artifact),
                "graph",
            )
            graph = ClaimEvidenceGraph.from_dict(
                graph_value,
                evidence_resolver=artifact_registry_resolver(
                    self.registry,
                    resolver_id=CLAIM_GRAPH_RESOLVER_ID,
                ),
            )
        except Exception as exc:
            raise ValidationError(
                "rejected Evidence graph cannot be safely rehydrated"
            ) from exc
        nodes = tuple(
            item for item in graph.evidence if item.evidence_id == record.object_id
        )
        linked_claims = tuple(
            claim
            for claim in graph.claims
            if any(
                link.evidence_id == record.object_id for link in claim.evidence_links
            )
        )
        if len(nodes) != 1 or len(linked_claims) != 1:
            raise ValidationError(
                "rejected Evidence identity or claim basis is ambiguous"
            )
        node = nodes[0]
        graph_artifact, decision, graph = self._resolve_claim_graph_decision(
            graph_artifact.sha256,
            expected_claim_id=linked_claims[0].claim_id,
            expected_decisions=frozenset(
                {
                    GraphClaimDecision.UNSUPPORTED,
                    GraphClaimDecision.CONTRADICTED,
                    GraphClaimDecision.INVALIDATED,
                }
            ),
            expected_claim_text=linked_claims[0].text,
            expected_claim_producer=linked_claims[0].producer_role,
            expected_confirmatory=linked_claims[0].confirmatory,
            expected_evidence_use=linked_claims[0].evidence_use,
            confirmatory_evidence_valid=False,
        )
        verification_receipts: list[EvidenceVerificationReceipt] = []
        for digest in decision.evidence_receipt_hashes:
            try:
                receipt = EvidenceVerificationReceipt.from_dict(
                    safe_json_loads(
                        self.registry.get_bytes(digest),
                        max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                    )
                )
            except Exception as exc:
                raise ValidationError(
                    "rejected Evidence verification receipt is malformed"
                ) from exc
            if receipt.evidence_id == node.evidence_id:
                verification_receipts.append(receipt)
        if len(verification_receipts) > 1:
            raise ValidationError(
                "rejected Evidence has ambiguous verification receipts"
            )
        receipt = verification_receipts[0] if verification_receipts else None
        serialized_contradictions = graph_value.get("contradictions")
        if not isinstance(serialized_contradictions, list):
            raise ValidationError(
                "rejected Evidence graph contradictions are malformed"
            )
        contradiction = any(
            isinstance(item, Mapping)
            and item.get("claim_id") == linked_claims[0].claim_id
            and item.get("evidence_id") == node.evidence_id
            for item in serialized_contradictions
        )
        node_rejected = bool(
            contradiction
            or receipt is None
            or receipt.validation_result != "PASS"
            or receipt.frozen is not True
            or receipt.supports_claim is not True
            or receipt.contradicts_claim is True
            or receipt.locally_verifiable is not True
        )
        if not node_rejected:
            raise ValidationError(
                "claim rejection does not establish rejection of this Evidence node"
            )
        supports = bool(
            receipt is not None
            and receipt.supports_claim
            and not receipt.contradicts_claim
            and not contradiction
        )
        contradicts = bool(
            contradiction or receipt is not None and receipt.contradicts_claim
        )
        claim_id = linked_claims[0].claim_id
        expected_receipts = self._claim_graph_receipt_closure(graph_artifact)
        expected_sources = tuple(sorted((graph_artifact.sha256, *expected_receipts)))
        if (
            record.evidence_kind != node.kind.value
            or record.source_artifact_hashes != expected_sources
            or record.authority_artifact_hashes != expected_sources
            or record.supports_claim_ids != ((claim_id,) if supports else ())
            or record.contradicts_claim_ids != ((claim_id,) if contradicts else ())
            or record.verification_depth is not ReferenceVerificationDepth.LEVEL_0
            or record.locator
            != f"claim-graph:{graph_artifact.sha256}#{node.evidence_id}"
            or record.verified_at != graph_artifact.created_at
            or record.created_at != graph_artifact.created_at
        ):
            raise ValidationError(
                "rejected Evidence differs from its exact negative graph projection"
            )

    def _validate_rejected_claim_boundary(
        self,
        record: Claim,
        by_content: Mapping[str, _StoredObject],
    ) -> None:
        """Retain one graph-derived rejection without creating writer authority."""

        if (
            record.verification_status is not VerificationStatus.REJECTED
            or record.status is not RecordStatus.REJECTED
            or record.producer is Role.CLAIM_VERIFIER
            or record.revision != 1
            or record.supersedes_content_hash is not None
            or record.relationships
            or thaw_json(record.metadata)
        ):
            raise ValidationError(
                "rejected Claim must be one neutral independently reviewed revision"
            )
        records = self._authority_records(record)
        self._require_exact_authority_roles(
            records,
            self._claim_authority_allowlist(),
        )
        graph_records = tuple(
            item for item in records if item.logical_type == "claim_evidence_graph"
        )
        semantic_judgments = tuple(
            item
            for item in records
            if item.logical_type == "scientific_semantic_judgment_receipt"
        )
        semantics_receipts = tuple(
            item
            for item in records
            if item.logical_type == CLAIM_SEMANTICS_RECEIPT_LOGICAL_TYPE
        )
        if len(graph_records) != 1:
            raise ValidationError(
                "rejected Claim requires one exact claim-evidence graph"
            )
        graph_artifact = graph_records[0]
        graph_wrapper = self._read_authority_json(graph_artifact)
        graph_value = self._nested_mapping(graph_wrapper, "graph")
        serialized_decisions = graph_value.get("decisions")
        if not isinstance(serialized_decisions, list):
            raise ValidationError("rejected Claim graph decisions are malformed")
        current = tuple(
            item
            for item in serialized_decisions
            if isinstance(item, Mapping) and item.get("claim_id") == record.object_id
        )
        if len(current) != 1:
            raise ValidationError("rejected Claim graph decision is ambiguous")
        try:
            serialized_outcome = GraphClaimDecision(current[0]["decision"])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValidationError("rejected Claim graph decision is malformed") from exc
        negative_graph = serialized_outcome in {
            GraphClaimDecision.UNSUPPORTED,
            GraphClaimDecision.CONTRADICTED,
            GraphClaimDecision.INVALIDATED,
        }
        if negative_graph:
            if semantic_judgments or semantics_receipts:
                raise ValidationError(
                    "rejected Claim has ambiguous graph and semantic bases"
                )
            graph_artifact, decision, graph = self._resolve_claim_graph_decision(
                graph_artifact.sha256,
                expected_claim_id=record.object_id,
                expected_decisions=frozenset(
                    {
                        GraphClaimDecision.UNSUPPORTED,
                        GraphClaimDecision.CONTRADICTED,
                        GraphClaimDecision.INVALIDATED,
                    }
                ),
                expected_claim_text=record.claim_text,
                expected_claim_producer=record.producer,
                expected_confirmatory=record.confirmatory,
                expected_evidence_use=record.evidence_use,
                confirmatory_evidence_valid=False,
            )
            failure_reason = decision.reason
            basis_timestamp = graph_artifact.created_at
            if (
                record.claim_type is not ClaimType.QUALITATIVE
                or record.scope != "REJECTED"
                or record.verification_method != "ClaimEvidenceGraph.verify_claim/v1"
                or not self._float_matches(record.confidence, 0.0)
            ):
                raise ValidationError(
                    "graph-rejected Claim must use the conservative neutral semantics"
                )
            extra_basis_hashes: tuple[str, ...] = ()
        else:
            if serialized_outcome is not GraphClaimDecision.ELIGIBLE:
                raise ValidationError(
                    "rejected Claim graph has no terminal verification decision"
                )
            if len(semantic_judgments) != 1 or len(semantics_receipts) > 1:
                raise ValidationError(
                    "rejected Claim semantic basis is absent or ambiguous"
                )
            confirmatory_valid = self._resolve_confirmatory_authority(
                records,
                graph_artifact,
                expected_claim_ids=(record.object_id,),
            )
            graph_artifact, _decision, graph = self._resolve_claim_graph_decision(
                graph_artifact.sha256,
                expected_claim_id=record.object_id,
                expected_decisions=frozenset({GraphClaimDecision.ELIGIBLE}),
                expected_claim_text=record.claim_text,
                expected_claim_producer=record.producer,
                expected_confirmatory=record.confirmatory,
                expected_evidence_use=record.evidence_use,
                confirmatory_evidence_valid=confirmatory_valid,
            )
            proposal, judgment = self._resolve_rejected_claim_semantic_basis(
                record,
                semantic_judgments[0],
                semantics_receipts,
            )
            failure_reason = judgment.rationale
            basis_timestamp = semantic_judgments[0].created_at
            if proposal is not None and (
                proposal.claim_type is not record.claim_type
                or proposal.scope != record.scope
                or proposal.verification_method != record.verification_method
                or proposal.dependency_claim_ids != tuple(record.dependency_claim_ids)
            ):
                raise ValidationError(
                    "rejected Claim semantics differ from their reviewed proposal"
                )
            expected_dependency_bindings = (
                proposal.dependency_bindings if proposal is not None else ()
            )
            extra_basis_hashes = (
                semantic_judgments[0].sha256,
                *(item.sha256 for item in semantics_receipts),
            )
        if negative_graph:
            expected_dependency_bindings = ()
        graph_claim = next(
            item for item in graph.claims if item.claim_id == record.object_id
        )
        expected_evidence_ids = tuple(
            link.evidence_id for link in graph_claim.evidence_links
        )
        evidence_parents = tuple(
            item for item in record.parents if item.object_type == "Evidence"
        )
        dependency_parents = tuple(
            item for item in record.parents if item.object_type == "Claim"
        )
        if (
            len(evidence_parents) + len(dependency_parents) != len(record.parents)
            or record.evidence_ids != expected_evidence_ids
            or len({item.object_id for item in evidence_parents})
            != len(evidence_parents)
            or any(
                item.object_id not in expected_evidence_ids for item in evidence_parents
            )
            or any(
                item.relation != "reviewed_against" or item.evaluated is not True
                for item in evidence_parents
            )
            or record.dependency_claim_ids
            != tuple(item.claim_id for item in expected_dependency_bindings)
            or tuple(
                (item.object_id, item.content_hash, item.relation, item.evaluated)
                for item in dependency_parents
            )
            != tuple(
                (
                    item.claim_id,
                    item.content_hash,
                    "depends_on",
                    True,
                )
                for item in expected_dependency_bindings
            )
        ):
            raise ValidationError(
                "rejected Claim evidence parents differ from its graph links"
            )
        for parent in evidence_parents:
            stored = by_content.get(parent.content_hash)
            if stored is None or not isinstance(stored.research_object, Evidence):
                raise ValidationError("rejected Claim Evidence parent is absent")
            self._resolve_object_authority(stored.research_object, by_content)
        for parent, binding in zip(
            dependency_parents,
            expected_dependency_bindings,
            strict=True,
        ):
            stored = by_content.get(parent.content_hash)
            if (
                stored is None
                or not isinstance(stored.research_object, Claim)
                or stored.artifact.sha256 != binding.state_artifact_hash
                or str(stored.artifact.record_hash)
                != binding.state_artifact_record_hash
            ):
                raise ValidationError(
                    "rejected Claim dependency revision is substituted"
                )
        receipt_hashes = self._claim_graph_receipt_closure(graph_artifact)
        confirmatory_hashes = tuple(
            item.sha256
            for item in records
            if item.logical_type == "confirmatory_claim_authority"
        )
        expected_authorities = tuple(
            sorted(
                {
                    graph_artifact.sha256,
                    *receipt_hashes,
                    *confirmatory_hashes,
                    *extra_basis_hashes,
                }
            )
        )
        final_review = record.review_history[-1]
        if (
            len(record.review_history) != 1
            or final_review.reviewer is not Role.CLAIM_VERIFIER
            or final_review.reviewer is record.producer
            or final_review.verification_status is not VerificationStatus.REJECTED
            or final_review.reason != failure_reason
            or final_review.evidence_ids != expected_evidence_ids
            or final_review.source_artifact_ids != expected_authorities
            or record.failure_reason != failure_reason
            or record.source_artifact_ids != expected_authorities
            or record.authority_artifact_hashes != expected_authorities
            or record.expressed_strength is not ClaimStrength.UNSUPPORTED
            or record.permitted_strength is not ClaimStrength.UNSUPPORTED
            or not self._float_matches(record.confidence, 0.0)
            or record.evidence_use is not graph_claim.evidence_use
            or record.created_at != basis_timestamp
            or final_review.timestamp != basis_timestamp
        ):
            raise ValidationError(
                "rejected Claim differs from its exact independent review and closure"
            )

    def _resolve_rejected_claim_semantic_basis(
        self,
        record: Claim,
        judgment_record: ArtifactRecord,
        semantics_receipts: tuple[ArtifactRecord, ...],
    ) -> tuple[Any | None, Any]:
        """Dispatch an unfavorable semantic decision to its source owner."""

        try:
            from .gates import JudgmentSubjectKind, SemanticJudgmentReceipt

            judgment = SemanticJudgmentReceipt.from_dict(
                safe_json_loads(
                    self.registry.get_bytes(judgment_record.sha256),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
            )
        except Exception as exc:
            raise ValidationError(
                "rejected Claim semantic judgment is malformed"
            ) from exc
        if judgment.subject_id != record.object_id:
            raise ValidationError(
                "rejected Claim semantic judgment names another claim"
            )
        if judgment.subject_kind is JudgmentSubjectKind.CLAIM_SEMANTICS:
            if semantics_receipts:
                raise ValidationError(
                    "rejected Claim has ambiguous accepted and rejected semantics"
                )
            try:
                retained = safe_json_loads(
                    self.registry.get_bytes(judgment.input_artifact_hash),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
                proposal_hash = retained["proposal_artifact_hash"]
                reference_candidates = tuple(
                    digest
                    for digest in judgment.evidence_hashes
                    if self.registry.get_metadata(digest).logical_type
                    == "scientific_semantic_judgment_receipt"
                    and safe_json_loads(
                        self.registry.get_bytes(digest),
                        max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                    ).get("subject_kind")
                    == "REFERENCE_SUPPORT"
                )
                if len(reference_candidates) > 1:
                    raise ValidationError(
                        "claim-semantics reference-support basis is ambiguous"
                    )
                proposal, resolved = _require_scientific_claim_semantics_judgment(
                    self.registry,
                    self.ledger,
                    proposal_artifact_hash=proposal_hash,
                    reference_support_semantic_judgment_artifact_hash=(
                        reference_candidates[0] if reference_candidates else None
                    ),
                    semantic_authority_artifact_hash=judgment_record.sha256,
                    expected_run_id=self.run_id,
                    expected_outcome="CLAIM_SEMANTICS_REJECTED",
                )
            except ValidationError:
                raise
            except Exception as exc:
                raise ValidationError(
                    "rejected Claim semantics failed source-owned replay"
                ) from exc
            return proposal, resolved
        if judgment.subject_kind is JudgmentSubjectKind.CLAIM_QUALIFIER:
            if len(semantics_receipts) != 1:
                raise ValidationError(
                    "qualifier-rejected Claim requires one accepted semantics receipt"
                )
            semantics = require_claim_semantics_receipt(
                self.registry,
                self.ledger,
                receipt_artifact_hash=semantics_receipts[0].sha256,
                expected_run_id=self.run_id,
                expected_claim_graph_artifact_hash=(
                    semantics_receipts[0].parent_artifacts[0]
                ),
                expected_claim_id=record.object_id,
            )
            retained_input = self.registry.get_bytes(judgment.input_artifact_hash)
            request = _claim_qualifier_request_from_retained_input(
                self.registry,
                self.ledger,
                run_id=self.run_id,
                retained_input=retained_input,
            )
            resolved = _require_unique_scientific_claim_qualifier_judgment(
                self.registry,
                self.ledger,
                run_id=self.run_id,
                request=request,
                selected_artifact_hash=judgment_record.sha256,
                expected_outcome="CLAIM_QUALIFIER_REJECTED",
            )
            projection = safe_json_loads(retained_input)["qualifier_projection"]
            if (
                projection["claim_id"] != record.object_id
                or projection["claim_text"] != record.claim_text
                or projection["claim_producer_role"] != record.producer.value
                or projection["claim_confirmatory"] is not record.confirmatory
                or projection["claim_evidence_use"] != record.evidence_use.value
            ):
                raise ValidationError(
                    "qualifier rejection differs from the canonical Claim"
                )
            return semantics, resolved
        if judgment.subject_kind is JudgmentSubjectKind.REFERENCE_SUPPORT:
            if semantics_receipts:
                raise ValidationError(
                    "reference-rejected Claim has ambiguous accepted semantics"
                )
            try:
                from .scientific_design import (
                    require_rejected_claim_bound_reference_support,
                )

                rejected = require_rejected_claim_bound_reference_support(
                    self.registry,
                    self.ledger,
                    expected_run_id=self.run_id,
                    semantic_judgment_artifact_sha256=judgment_record.sha256,
                    expected_claim_id=record.object_id,
                )
            except Exception as exc:
                raise ValidationError(
                    "reference-support rejection failed source-owned replay"
                ) from exc
            return rejected.proposal, rejected
        raise ValidationError("rejected Claim semantic judgment subject is unsupported")

    def _validate_verified_evidence_boundary(self, record: Evidence) -> None:
        if record.verification_status is not VerificationStatus.VERIFIED:
            return
        source_records = tuple(
            self._require_frozen_pass_artifact(digest)
            for digest in record.source_artifact_hashes
        )
        if not record.supports_claim_ids:
            if len(source_records) != 1 or record.contradicts_claim_ids:
                raise ValidationError(
                    "standalone verified Evidence requires one exact non-claim source"
                )
            source = source_records[0]
            if source.logical_type != "reference_verification":
                raise ValidationError(
                    "standalone verified Evidence lacks a supported typed resolver"
                )
            try:
                from .literature import ReferenceVerification

                payload = self._read_authority_json(source)
                verification = ReferenceVerification.from_dict(
                    self._nested_mapping(payload, "verification")
                )
            except Exception as exc:
                raise ValidationError(
                    "reference Evidence authority is malformed"
                ) from exc
            expected_depth = f"LEVEL_{int(verification.level)}"
            if (
                tuple(verification.parent_artifact_hashes)
                != tuple(source.parent_artifacts)
                or record.verification_depth.value != expected_depth
                or record.locator != f"artifact:{source.sha256}"
                or record.verified_at != source.created_at
            ):
                raise ValidationError(
                    "canonical reference Evidence differs from its typed verification"
                )
            return
        if record.status is not RecordStatus.VERIFIED:
            raise ValidationError(
                "verified claim-supporting Evidence must have VERIFIED lifecycle status"
            )
        if record.producer is not Role.CLAIM_VERIFIER:
            raise AuthorizationError(
                "verified claim-supporting Evidence requires CLAIM_VERIFIER authority"
            )
        graph_sources = tuple(
            item
            for item in source_records
            if item.logical_type == "claim_evidence_graph"
        )
        if len(graph_sources) != 1:
            raise ValidationError(
                "verified claim-supporting Evidence must bind exactly one claim_evidence_graph"
            )
        source_records_by_hash = {item.sha256: item for item in source_records}
        confirmatory_valid = self._resolve_confirmatory_authority(
            tuple(source_records_by_hash.values()),
            graph_sources[0],
            expected_claim_ids=record.supports_claim_ids,
        )
        for claim_id in record.supports_claim_ids:
            self._resolve_claim_graph_artifact(
                graph_sources[0].sha256,
                expected_claim_id=claim_id,
                confirmatory_evidence_valid=confirmatory_valid,
            )

    def _validate_verified_claim_boundary(
        self,
        record: Claim,
        by_content: Mapping[str, _StoredObject],
    ) -> tuple[bool, ClaimSemanticsReceipt]:
        if record.verification_status is not VerificationStatus.VERIFIED:
            return False
        if record.status is not RecordStatus.VERIFIED:
            raise ValidationError("verified Claim must have VERIFIED lifecycle status")
        if record.producer is Role.CLAIM_VERIFIER:
            raise AuthorizationError("claim verifier cannot produce a verified Claim")
        final_review = record.review_history[-1]
        if (
            final_review.reviewer is not Role.CLAIM_VERIFIER
            or final_review.reviewer is record.producer
        ):
            raise AuthorizationError(
                "verified Claim requires a distinct final CLAIM_VERIFIER review"
            )
        graph_sources = tuple(
            self._require_frozen_pass_artifact(digest)
            for digest in record.source_artifact_ids
            if self.registry.get_metadata(digest).logical_type == "claim_evidence_graph"
        )
        if len(graph_sources) != 1:
            raise ValidationError(
                "verified Claim must bind exactly one claim_evidence_graph source"
            )
        claim_authority_records = tuple(
            self._require_frozen_pass_artifact(digest)
            for digest in record.authority_artifact_hashes
        )
        semantics_records = self._records_of_types(
            claim_authority_records,
            frozenset({CLAIM_SEMANTICS_RECEIPT_LOGICAL_TYPE}),
        )
        if len(semantics_records) != 1:
            raise ValidationError(
                "verified Claim requires one exact claim-semantics receipt"
            )
        semantics = require_claim_semantics_receipt(
            self.registry,
            self.ledger,
            receipt_artifact_hash=semantics_records[0].sha256,
            expected_run_id=self.run_id,
            expected_claim_graph_artifact_hash=graph_sources[0].sha256,
            expected_claim_id=record.object_id,
        )
        confirmatory_valid = self._resolve_confirmatory_authority(
            claim_authority_records,
            graph_sources[0],
            expected_claim_ids=(record.object_id,),
        )
        graph_artifact = self._resolve_claim_graph_artifact(
            graph_sources[0].sha256,
            expected_claim_id=record.object_id,
            expected_claim_text=record.claim_text,
            expected_claim_producer=record.producer,
            expected_confirmatory=record.confirmatory,
            expected_evidence_use=record.evidence_use,
            confirmatory_evidence_valid=confirmatory_valid,
        )
        graph_receipt_types = frozenset(
            {
                *(f"claim_support_receipt.{kind.value}" for kind in GraphEvidenceKind),
                *(
                    f"claim_evidence_verification_receipt.{kind.value}"
                    for kind in GraphEvidenceKind
                ),
            }
        )
        expected_authority_hashes = {
            graph_artifact.sha256,
            semantics_records[0].sha256,
            *(
                item.sha256
                for item in claim_authority_records
                if item.logical_type == "confirmatory_claim_authority"
            ),
            *(
                digest
                for digest in graph_artifact.parent_artifacts
                if self.registry.get_metadata(digest).logical_type
                in graph_receipt_types
            ),
        }
        if set(record.authority_artifact_hashes) != expected_authority_hashes:
            raise ValidationError(
                "verified Claim authority differs from its exact graph, "
                "semantics, and confirmatory closure"
            )
        if graph_artifact.sha256 not in final_review.source_artifact_ids:
            raise ValidationError(
                "final claim-verifier review does not bind the checked claim graph"
            )
        if set(record.evidence_ids) != set(final_review.evidence_ids):
            raise ValidationError(
                "final claim-verifier review differs from canonical Evidence identities"
            )
        if set(final_review.source_artifact_ids) != set(
            record.authority_artifact_hashes
        ):
            raise ValidationError(
                "final claim-verifier review differs from exact Claim authority"
            )

        dependency_parents = tuple(
            parent for parent in record.parents if parent.object_type == "Claim"
        )
        expected_dependencies = {
            (item.claim_id, item.content_hash): item
            for item in semantics.dependency_bindings
        }
        if {(item.object_id, item.content_hash) for item in dependency_parents} != set(
            expected_dependencies
        ):
            raise ValidationError(
                "canonical Claim dependencies differ from attested semantics"
            )
        for parent in dependency_parents:
            if parent.evaluated is not True:
                raise ValidationError("canonical Claim dependency must be evaluated")
            stored_dependency = by_content.get(parent.content_hash)
            binding = expected_dependencies[(parent.object_id, parent.content_hash)]
            if (
                stored_dependency is None
                or not isinstance(stored_dependency.research_object, Claim)
                or stored_dependency.artifact.sha256 != binding.state_artifact_hash
                or str(stored_dependency.artifact.record_hash)
                != binding.state_artifact_record_hash
            ):
                raise ValidationError(
                    "canonical Claim dependency revision was substituted"
                )
        if (
            semantics.claim_text != record.claim_text
            or semantics.claim_producer_role is not record.producer
            or semantics.claim_evidence_use is not record.evidence_use
            or semantics.claim_type is not record.claim_type
            or semantics.scope != record.scope
            or not self._float_matches(semantics.confidence, record.confidence)
            or semantics.expressed_strength is not record.expressed_strength
            or semantics.permitted_strength is not record.permitted_strength
            or semantics.verification_method != record.verification_method
            or semantics.dependency_claim_ids != tuple(record.dependency_claim_ids)
        ):
            raise ValidationError(
                "canonical Claim semantics differ from source-owned attestation"
            )

        evidence_parents = tuple(
            parent for parent in record.parents if parent.object_type == "Evidence"
        )
        if {item.object_id for item in evidence_parents} != set(record.evidence_ids):
            raise ValidationError(
                "verified Claim evidence IDs must exactly match bound Evidence parents"
            )
        for evidence_id in record.evidence_ids:
            matches = tuple(
                parent for parent in evidence_parents if parent.object_id == evidence_id
            )
            if len(matches) != 1 or matches[0].evaluated is not True:
                raise ValidationError(
                    "verified Claim requires one evaluated canonical Evidence parent per evidence ID"
                )
            stored = by_content.get(matches[0].content_hash)
            if stored is None or not isinstance(stored.research_object, Evidence):
                raise ValidationError("verified Claim Evidence parent is absent")
            evidence = stored.research_object
            if (
                evidence.verification_status is not VerificationStatus.VERIFIED
                or evidence.status is not RecordStatus.VERIFIED
                or evidence.producer is not Role.CLAIM_VERIFIER
                or record.object_id not in evidence.supports_claim_ids
            ):
                raise AuthorizationError(
                    "verified Claim parent is not an authoritative supporting Evidence view"
                )
            if evidence.producer is record.producer:
                raise AuthorizationError(
                    "claim producer and canonical Evidence verifier must be distinct"
                )
            if graph_artifact.sha256 not in evidence.source_artifact_hashes:
                raise ValidationError(
                    "canonical Evidence parent does not bind the checked claim graph"
                )
        eligible = bool(
            semantics.scientific_writer_eligible
            and record.evidence_use is ClaimEvidenceUse.SCIENTIFIC
            and (not record.confirmatory or confirmatory_valid)
        )
        return eligible, semantics

    def _materialization_event(
        self,
        artifact_hash: str,
        record: CanonicalResearchObject,
        *,
        events: tuple[LedgerEvent, ...] | None = None,
    ) -> LedgerEvent | None:
        event_id = f"rs-{artifact_hash[:48]}"
        for event in self.ledger.events() if events is None else events:
            if event.event_id != event_id:
                continue
            metadata = event.metadata
            expected_operation = (
                "MATERIALIZED" if record.revision == 1 else "SUPERSEDED"
            )
            expected_event_type = "CHECKPOINT" if record.revision == 1 else "CORRECTION"
            if (
                event.run_id != self.run_id
                or event.actor_role is not record.producer
                or event.timestamp != record.created_at
                or event.code_version != self.code_version
                or event.configuration_hash != self.configuration_hash
                or event.state_before != self.state
                or event.requested_state_after != self.state
                or event.event_type != expected_event_type
                or metadata.get("research_state_operation") != expected_operation
                or metadata.get("object_type") != record.object_type
                or metadata.get("object_id") != record.object_id
                or metadata.get("revision") != record.revision
                or metadata.get("content_hash") != record.content_hash
                or metadata.get("artifact_hash") != artifact_hash
                or metadata.get("schema_version") != record.schema_version
                or metadata.get("supersedes_content_hash")
                != record.supersedes_content_hash
                or tuple(event.artifact_hashes) != (artifact_hash,)
            ):
                raise LedgerError(
                    "research-state event ID collides with different materialization"
                )
            return event
        return None

    def _prospective_scientific_bundle_artifacts(
        self,
        ordered: tuple[CanonicalResearchObject, ...],
    ) -> dict[str, ArtifactRecord]:
        """Compute exact immutable registry metadata for a topological bundle."""

        prospective: dict[str, ArtifactRecord] = {}
        for record in ordered:
            data = record.canonical_bytes()
            digest = sha256_bytes(data)
            parent_artifacts = set(self._embedded_artifact_hashes(record))
            for authority_hash in parent_artifacts:
                self.registry.verify(authority_hash, raise_on_error=True)
            for parent in record.parents:
                parent_artifact = prospective.get(parent.content_hash)
                if parent_artifact is None:
                    raise ValidationError(
                        "scientific Result bundle prospective parent is absent"
                    )
                parent_artifacts.add(parent_artifact.sha256)
            object_path = self.registry.objects_path / digest[:2] / digest
            metadata_path = self.registry.metadata_path / digest[:2] / f"{digest}.json"
            prospective[record.content_hash] = ArtifactRecord(
                sha256=digest,
                path=object_path.as_posix(),
                relative_path=object_path.as_posix(),
                metadata_path=metadata_path.as_posix(),
                logical_type=record.logical_type,
                schema_version=record.schema_version,
                mime_type="application/json",
                size=len(data),
                origin=(
                    f"research-state:{record.object_type}:"
                    f"{record.object_id}:r{record.revision}"
                ),
                creator_role=record.producer,
                creation_command=self.creation_command,
                parent_artifacts=tuple(sorted(parent_artifacts)),
                validation_result="PASS",
                frozen=True,
                created_at=record.created_at,
            )
        return prospective

    def _persist_prevalidated_scientific_bundle_record(
        self,
        record: CanonicalResearchObject,
        *,
        registry_guard: Any,
        ledger_guard: Any,
        expected_artifact: ArtifactRecord,
        artifact_missing: bool,
        existing_event: LedgerEvent | None,
        event_to_append: LedgerEvent | None,
        expected_ledger: LedgerValidationResult,
    ) -> tuple[MaterializedResearchObject, LedgerValidationResult]:
        """Commit one fully preflighted bundle member while both locks are held."""

        if artifact_missing:
            artifact = self.registry._put_bytes_locked(
                registry_guard,
                record.canonical_bytes(),
                logical_type=expected_artifact.logical_type,
                origin=expected_artifact.origin,
                creator_role=expected_artifact.creator_role,
                creation_command=expected_artifact.creation_command,
                parent_artifacts=expected_artifact.parent_artifacts,
                schema_version=expected_artifact.schema_version,
                mime_type=expected_artifact.mime_type,
                validation_result=expected_artifact.validation_result,
                frozen=expected_artifact.frozen,
                created_at=expected_artifact.created_at,
            )
        else:
            artifact = self.registry._get_metadata_locked(
                registry_guard,
                expected_artifact.sha256,
            )
        if artifact != expected_artifact:
            raise ValidationError(
                "scientific Result bundle member changed during commit"
            )

        if event_to_append is not None:

            def build_event(current: LedgerValidationResult) -> LedgerEvent:
                if current != expected_ledger:
                    raise ValidationError(
                        "scientific Result bundle ledger changed during commit"
                    )
                return event_to_append

            event = self.ledger._append_locked(ledger_guard, build_event)
            if event != event_to_append:
                raise ValidationError(
                    "scientific Result bundle event changed during commit"
                )
            committed_ledger = self.ledger._validate_bytes(
                self.ledger._read_raw_locked(ledger_guard)
            )
            if (
                not committed_ledger.valid
                or committed_ledger.event_count != expected_ledger.event_count + 1
                or committed_ledger.events[-1] != event_to_append
            ):
                raise ValidationError(
                    "scientific Result bundle ledger append is incomplete"
                )
        else:
            if existing_event is None:
                raise ValidationError(
                    "scientific Result bundle member lacks its exact event"
                )
            event = existing_event
            committed_ledger = expected_ledger
        return MaterializedResearchObject(record, artifact, event), committed_ledger

    def materialize_scientific_result_bundle(
        self,
        *,
        ancestors: tuple[CanonicalResearchObject, ...],
        result: Result,
        statistical_test: StatisticalTest | None = None,
        reason: str | None = None,
    ) -> tuple[MaterializedResearchObject, ...]:
        """Preflight and commit one exact cycle-free scientific state bundle.

        All deterministic validation completes against an ephemeral closed
        graph before the first write.  Commit is append-only and resumable: an
        interruption may leave only an exact inert prefix, which a retry must
        continue without rewriting or deleting immutable evidence.  Result or
        StatisticalTest authority becomes visible only after the final typed
        bundle-completion receipt and ledger checkpoint.
        """

        if (
            not isinstance(ancestors, tuple)
            or not ancestors
            or len(ancestors) > MAX_SEQUENCE_ITEMS
            or not isinstance(result, Result)
            or (
                statistical_test is not None
                and not isinstance(statistical_test, StatisticalTest)
            )
        ):
            raise ValidationError(
                "scientific Result bundle inputs are malformed or unbounded"
            )
        if reason is not None and (
            not isinstance(reason, str) or not reason.strip() or len(reason) > 8192
        ):
            raise ValidationError(
                "scientific Result bundle reason must be non-empty bounded text"
            )
        _require_run_scoped_authority_paths(
            self.registry,
            self.ledger,
            run_id=self.run_id,
        )
        ledger_result = self.ledger.validate(raise_on_error=True)
        # Establish the empty ledger inode before taking a registry namespace
        # snapshot.  Creating it later would legitimately change a parent
        # directory while a concurrent registry guard is active.
        self._ensure_ledger_file_for_atomic_commit(ledger_result)
        registry_result = self.registry.verify_all(raise_on_error=True)
        initial_stored = self._preflight_repository_identity(
            ledger_result=ledger_result,
        )
        if (
            not ledger_result.events
            or ledger_result.events[-1].requested_state_after != self.state
        ):
            raise ValidationError(
                "scientific Result bundle ledger is absent or in another state"
            )

        existing_children = tuple(
            item.research_object
            for item in initial_stored
            if isinstance(item.research_object, StatisticalTest)
            and (
                result.object_id in item.research_object.result_ids
                or any(
                    parent.object_type == "Result"
                    and (
                        parent.object_id == result.object_id
                        or parent.content_hash == result.content_hash
                    )
                    for parent in item.research_object.parents
                )
            )
        )
        exact_child_parent = (
            ObjectReference(
                "Result",
                result.object_id,
                result.content_hash,
                "tests",
                True,
            ),
        )
        if (
            len(existing_children) > 1
            or existing_children
            and (
                existing_children[0].result_ids != (result.object_id,)
                or existing_children[0].parents != exact_child_parent
            )
        ):
            raise ValidationError(
                "scientific Result bundle has ambiguous StatisticalTest children"
            )
        if statistical_test is None:
            if existing_children:
                statistical_test = existing_children[0]
        elif existing_children and existing_children[0] != statistical_test:
            raise ValidationError(
                "scientific Result bundle StatisticalTest was substituted"
            )

        incoming = (*ancestors, result)
        if statistical_test is not None:
            incoming = (*incoming, statistical_test)
        orphaned = tuple(
            item
            for item in initial_stored
            if self._materialization_event(
                item.artifact.sha256,
                item.research_object,
                events=ledger_result.events,
            )
            is None
        )
        if (
            len(orphaned) > 1
            or orphaned
            and orphaned[0].research_object not in incoming
        ):
            raise ValidationError(
                "scientific Result bundle cannot consume an unrelated "
                "or ambiguous inert state artifact"
            )
        identities = tuple(
            (record.object_type, record.object_id) for record in incoming
        )
        content_hashes = tuple(record.content_hash for record in incoming)
        if len(set(identities)) != len(identities) or len(set(content_hashes)) != len(
            content_hashes
        ):
            raise ValidationError(
                "scientific Result bundle identities and contents must be unique"
            )
        allowed_ancestor_types = {
            Method,
            Implementation,
            Hypothesis,
            Dataset,
            Split,
            Metric,
            Baseline,
            Experiment,
            Run,
        }
        if any(type(record) not in allowed_ancestor_types for record in ancestors):
            raise ValidationError(
                "scientific Result bundle contains an extra ancestor type"
            )

        result_records = self._authority_records(result)
        result_authority_types = {item.logical_type for item in result_records}
        if "scientific_result_promotion_authority_v3" in result_authority_types:
            resolution, result_projection, promotion_record = (
                self._resolve_scientific_result_promotion_v3(
                    result_records,
                    expected_result_id=result.object_id,
                    expected_execution_run_id=result.run_ids[0],
                )
            )
            outcome_neutral_v3 = True
        else:
            resolution, projection, promotion_record, _projection_event = (
                self._resolve_scientific_result_promotion(
                    result_records,
                    expected_result_id=result.object_id,
                    expected_execution_run_id=result.run_ids[0],
                )
            )
            result_projection = projection.result_state_projection
            outcome_neutral_v3 = False
        try:
            from .scientific_design import require_frozen_evaluation_contract

            contract = require_frozen_evaluation_contract(
                self.registry,
                contract_artifact_sha256=(result_projection.contract_artifact_sha256),
            )
        except Exception as exc:
            raise ValidationError(
                "scientific Result bundle contract failed fresh replay"
            ) from exc
        try:
            from .experiments import (
                require_scientific_execution_run_spec,
                resolve_scientific_method_definition_binding,
            )

            bundle_spec = require_scientific_execution_run_spec(
                self.registry,
                frozen_run_spec_artifact_sha256=(
                    result_projection.frozen_run_spec_artifact_sha256
                ),
            )
            bundle_method_binding = resolve_scientific_method_definition_binding(
                self.registry,
                spec=bundle_spec,
            )
        except Exception as exc:
            raise ValidationError(
                "scientific Result bundle Method intention failed fresh replay"
            ) from exc
        expected_counts = {
            Method: 1,
            Implementation: 1,
            Hypothesis: 1,
            Dataset: 1,
            Split: 4,
            Metric: 1 + len(contract.secondary_metrics),
            Baseline: len(contract.baseline_registry.entries),
            Experiment: 1,
            Run: 1,
        }
        observed_counts = {
            record_type: sum(type(item) is record_type for item in ancestors)
            for record_type in expected_counts
        }
        if observed_counts != expected_counts:
            raise ValidationError(
                "scientific Result bundle omits or adds canonical graph nodes"
            )

        status_by_type = {
            Method: RecordStatus.FROZEN,
            Implementation: RecordStatus.FROZEN,
            Hypothesis: RecordStatus.FROZEN,
            Dataset: RecordStatus.FROZEN,
            Split: RecordStatus.FROZEN,
            Metric: RecordStatus.FROZEN,
            Baseline: RecordStatus.FROZEN,
            Experiment: RecordStatus.FROZEN,
            Run: RecordStatus.COMPLETE,
            Result: RecordStatus.COMPLETE,
            StatisticalTest: RecordStatus.COMPLETE,
        }
        producer_by_type = {
            Method: (
                Role.HYPOTHESIS_DESIGNER
                if bundle_method_binding is not None
                else Role.PROTOCOL_DESIGNER
            ),
            Implementation: Role.IMPLEMENTER,
            Hypothesis: Role.HYPOTHESIS_DESIGNER,
            Dataset: Role.EVIDENCE_CURATOR,
            Split: Role.PROTOCOL_DESIGNER,
            Metric: Role.PROTOCOL_DESIGNER,
            Baseline: Role.PROTOCOL_DESIGNER,
            Experiment: Role.PROTOCOL_DESIGNER,
            Run: Role.EXPERIMENT_RUNNER,
            Result: Role.STATISTICIAN,
            StatisticalTest: Role.STATISTICIAN,
        }
        root_types = (Method, Hypothesis, Dataset, Metric, Baseline)
        for record in incoming:
            expected_metadata: Mapping[str, Any] = {}
            if outcome_neutral_v3:
                if isinstance(record, Run):
                    expected_metadata = result_projection.run_metadata
                elif isinstance(record, Result):
                    expected_metadata = result_projection.state_metadata
                elif isinstance(record, StatisticalTest):
                    expected_metadata = result_projection.statistical_state_metadata
            if (
                record.revision != 1
                or record.supersedes_content_hash is not None
                or record.schema_version != RESEARCH_STATE_SCHEMA_VERSION
                or record.code_version != self.code_version
                or record.status is not status_by_type[type(record)]
                or record.producer is not producer_by_type[type(record)]
                or record.relationships
                or thaw_json(record.metadata) != expected_metadata
                or (isinstance(record, root_types) and record.parents)
            ):
                raise ValidationError(
                    "scientific Result bundle lifecycle or envelope differs"
                )
            self._validate_producer_authority(record)
        dataset_node = next(item for item in ancestors if isinstance(item, Dataset))
        for split in (item for item in ancestors if isinstance(item, Split)):
            if split.parents != (
                ObjectReference(
                    "Dataset",
                    dataset_node.object_id,
                    dataset_node.content_hash,
                    "partitions",
                    True,
                ),
            ):
                raise ValidationError(
                    "scientific Result bundle Split lacks its exact Dataset parent"
                )
        if statistical_test is not None and (
            statistical_test.result_ids != (result.object_id,)
            or statistical_test.parents
            != (
                ObjectReference(
                    "Result",
                    result.object_id,
                    result.content_hash,
                    "tests",
                    True,
                ),
            )
        ):
            raise ValidationError(
                "scientific Result bundle StatisticalTest parent differs"
            )

        ordered = tuple(
            sorted(
                incoming,
                key=lambda record: datetime.fromisoformat(
                    record.created_at.replace("Z", "+00:00")
                ),
            )
        )
        if len({record.created_at for record in ordered}) != len(ordered) or ordered[
            -1
        ] is not (statistical_test or result):
            raise ValidationError(
                "scientific Result bundle timestamps are not strictly topological"
            )
        position = {record.content_hash: index for index, record in enumerate(ordered)}
        for record in ordered:
            for parent in record.parents:
                if (
                    parent.content_hash not in position
                    or position[parent.content_hash] >= position[record.content_hash]
                ):
                    raise ValidationError(
                        "scientific Result bundle parent order is non-topological"
                    )

        prospective_artifacts = self._prospective_scientific_bundle_artifacts(ordered)
        registry_records = {
            artifact.sha256: artifact for artifact in self.registry.list_records()
        }
        stored = initial_stored
        stored_by_content, stored_by_identity = self._indexes(stored)
        first_incomplete_index: int | None = None
        complete_prefix: list[CanonicalResearchObject] = []
        placeholder_artifact = promotion_record
        ephemeral_by_content = dict(stored_by_content)
        for index, record in enumerate(ordered):
            expected_artifact = prospective_artifacts[record.content_hash]
            revisions = stored_by_identity.get(
                (record.object_type, record.object_id),
                (),
            )
            if any(item.research_object != record for item in revisions):
                raise ValidationError(
                    "scientific Result bundle collides with canonical state"
                )
            existing_metadata = registry_records.get(expected_artifact.sha256)
            existing = stored_by_content.get(record.content_hash)
            event = self._materialization_event(
                expected_artifact.sha256,
                record,
            )
            if existing_metadata is not None:
                if (
                    existing_metadata != expected_artifact
                    or self.registry.get_bytes(expected_artifact.sha256)
                    != record.canonical_bytes()
                    or existing is None
                    or existing.research_object != record
                    or existing.artifact != expected_artifact
                ):
                    raise ValidationError(
                        "scientific Result bundle registry prefix differs"
                    )
                if first_incomplete_index is not None:
                    raise ValidationError(
                        "scientific Result bundle artifact exists after an "
                        "incomplete prefix"
                    )
                ephemeral_by_content[record.content_hash] = existing
                if event is None:
                    first_incomplete_index = index
                else:
                    complete_prefix.append(record)
            else:
                if existing is not None or event is not None:
                    raise ValidationError(
                        "scientific Result bundle event/artifact prefix is incomplete"
                    )
                if first_incomplete_index is None:
                    first_incomplete_index = index
                ephemeral_by_content[record.content_hash] = _StoredObject(
                    record,
                    placeholder_artifact,
                )

        prefix_hashes = {record.content_hash for record in complete_prefix}
        for record in complete_prefix:
            for parent in record.parents:
                if parent.content_hash not in prefix_hashes:
                    raise ValidationError(
                        "scientific Result bundle stored prefix has a gap"
                    )
        if first_incomplete_index is not None:
            ledger_head_timestamp = ledger_result.events[-1].timestamp
            if not self._timestamp_strictly_after(
                ordered[first_incomplete_index].created_at,
                ledger_head_timestamp,
            ):
                raise ValidationError(
                    "scientific Result bundle continuation is backdated"
                )

        for record in ancestors:
            expected_authority = self._expected_scientific_result_ancestor_authority(
                record,
                result_projection,
            )
            if tuple(sorted(record.authority_artifact_hashes)) != expected_authority:
                raise ValidationError(
                    "scientific Result bundle ancestor source authority differs"
                )
            self._authority_records(record)

        result_resolution = self._resolve_object_authority(
            result,
            ephemeral_by_content,
            allow_unmaterialized_source_bound=True,
        )
        if (
            result_resolution.scientific_evidence_eligible
            and not resolution.scientific_evidence_eligible
        ):
            raise ValidationError(
                "scientific Result bundle graph eligibility exceeds promotion"
            )
        if statistical_test is not None:
            self._resolve_object_authority(
                statistical_test,
                ephemeral_by_content,
                allow_unmaterialized_source_bound=True,
            )

        statistical_id = (
            statistical_test.object_id if statistical_test is not None else None
        )
        prospective_bindings = [
            {
                "object_type": record.object_type,
                "object_id": record.object_id,
                "content_hash": record.content_hash,
                "artifact_sha256": prospective_artifacts[record.content_hash].sha256,
                "artifact_record_hash": str(
                    prospective_artifacts[record.content_hash].record_hash
                ),
                "created_at": record.created_at,
            }
            for record in ordered
        ]
        completion_payload = {
            "schema_version": SCIENTIFIC_RESULT_STATE_BUNDLE_PAYLOAD_SCHEMA,
            "ledger_run_id": self.run_id,
            "execution_run_id": result.run_ids[0],
            "canonical_state_code_version": self.code_version,
            "result_id": result.object_id,
            "statistical_test_id": statistical_id,
            "promotion_receipt_artifact_sha256": promotion_record.sha256,
            "objects": prospective_bindings,
            "scientific_evidence_eligible": (
                result_resolution.scientific_evidence_eligible
            ),
        }
        # The append index is the completion ordering authority.  Do not
        # consume a canonical-object timestamp solely for this checkpoint.
        completion_time = ordered[-1].created_at
        completion_bytes = canonical_json_bytes(completion_payload) + b"\n"
        completion_digest = sha256_bytes(completion_bytes)
        completion_object_path = (
            self.registry.objects_path / completion_digest[:2] / completion_digest
        )
        completion_metadata_path = (
            self.registry.metadata_path
            / completion_digest[:2]
            / f"{completion_digest}.json"
        )
        completion_parent_artifacts = (
            promotion_record.sha256,
            *(prospective_artifacts[record.content_hash].sha256 for record in ordered),
        )
        expected_completion_record = ArtifactRecord(
            sha256=completion_digest,
            path=completion_object_path.as_posix(),
            relative_path=completion_object_path.as_posix(),
            metadata_path=completion_metadata_path.as_posix(),
            logical_type=SCIENTIFIC_RESULT_STATE_BUNDLE_LOGICAL_TYPE,
            schema_version=SCIENTIFIC_RESULT_STATE_BUNDLE_SCHEMA_VERSION,
            mime_type="application/json",
            size=len(completion_bytes),
            origin=(
                "deterministic scientific Result canonical-state bundle completion"
            ),
            creator_role=Role.CLAIM_VERIFIER,
            creation_command=(
                "scientist-one",
                "research-state",
                "complete-scientific-result-bundle",
            ),
            parent_artifacts=completion_parent_artifacts,
            validation_result="PASS",
            frozen=True,
            created_at=completion_time,
        )
        completion_candidates: list[ArtifactRecord] = []
        for artifact in registry_records.values():
            if artifact.logical_type != SCIENTIFIC_RESULT_STATE_BUNDLE_LOGICAL_TYPE:
                continue
            value = self._read_authority_json(artifact)
            if (
                value.get("ledger_run_id") == self.run_id
                and value.get("result_id") == result.object_id
                and value.get("statistical_test_id") == statistical_id
            ):
                completion_candidates.append(artifact)
        digest_collision = registry_records.get(completion_digest)
        if (
            len(completion_candidates) > 1
            or completion_candidates
            and completion_candidates[0] != expected_completion_record
            or digest_collision is not None
            and digest_collision != expected_completion_record
            or completion_candidates
            and first_incomplete_index is not None
        ):
            raise ValidationError(
                "scientific Result bundle completion collides before commit"
            )
        expected_completion_metadata = {
            "research_state_operation": "BUNDLE_COMPLETE",
            "result_id": result.object_id,
            "statistical_test_id": statistical_id,
            "bundle_receipt_artifact_sha256": completion_digest,
            "object_artifact_hashes": [
                prospective_artifacts[record.content_hash].sha256 for record in ordered
            ],
        }
        completion_event_id = f"rsb-{completion_digest[:48]}"
        completion_events = tuple(
            event
            for event in self.ledger.events()
            if event.event_id == completion_event_id
        )
        if len(completion_events) > 1:
            raise ValidationError(
                "scientific Result bundle completion event is ambiguous"
            )
        if completion_events:
            event = completion_events[0]
            completion_event_index = ledger_result.events.index(event)
            if (
                not completion_candidates
                or first_incomplete_index is not None
                or event.run_id != self.run_id
                or event.actor_role is not Role.CLAIM_VERIFIER
                or event.timestamp != completion_time
                or event.state_before != self.state
                or event.requested_state_after != self.state
                or event.artifact_hashes != (completion_digest,)
                or event.code_version != self.code_version
                or event.configuration_hash != self.configuration_hash
                or event.event_type != "CHECKPOINT"
                or thaw_json(event.metadata) != expected_completion_metadata
                or event.event_hash is None
                or any(
                    later.event_type == "CORRECTION"
                    and later.supersedes_event_id == event.event_id
                    for later in ledger_result.events[completion_event_index + 1 :]
                )
            ):
                raise ValidationError(
                    "scientific Result bundle completion event collides before commit"
                )
        elif datetime.fromisoformat(
            completion_time.replace("Z", "+00:00")
        ) < datetime.fromisoformat(
            ledger_result.events[-1].timestamp.replace("Z", "+00:00")
        ):
            raise ValidationError(
                "scientific Result bundle completion would be backdated"
            )
        missing_artifacts = sum(
            prospective_artifacts[record.content_hash].sha256 not in registry_records
            for record in ordered
        ) + (0 if completion_candidates else 1)
        missing_events = sum(
            self._materialization_event(
                prospective_artifacts[record.content_hash].sha256,
                record,
            )
            is None
            for record in ordered
        ) + (0 if completion_events else 1)
        if len(registry_records) + missing_artifacts > MAX_REGISTRY_RECORDS:
            raise ValidationError("scientific Result bundle exceeds registry capacity")
        prospective_events: list[LedgerEvent] = []
        prospective_head = ledger_result.head_hash
        for record in ordered:
            artifact = prospective_artifacts[record.content_hash]
            if self._materialization_event(artifact.sha256, record) is not None:
                continue
            event = LedgerEvent.create(
                run_id=self.run_id,
                actor_role=record.producer,
                state_before=self.state,
                requested_state_after=self.state,
                artifact_hashes=(artifact.sha256,),
                code_version=self.code_version,
                configuration_hash=self.configuration_hash,
                reason=(
                    reason
                    or (
                        "materialized preflighted scientific Result bundle "
                        f"{record.object_type} {record.object_id}"
                    )
                ),
                prior_event_hash=prospective_head,
                event_id=f"rs-{artifact.sha256[:48]}",
                timestamp=record.created_at,
                event_type="CHECKPOINT",
                metadata={
                    "research_state_operation": "MATERIALIZED",
                    "object_type": record.object_type,
                    "object_id": record.object_id,
                    "revision": record.revision,
                    "content_hash": record.content_hash,
                    "artifact_hash": artifact.sha256,
                    "supersedes_content_hash": None,
                    "schema_version": record.schema_version,
                },
            )
            prospective_events.append(event)
            prospective_head = event.event_hash
        if not completion_events:
            completion_event = LedgerEvent.create(
                run_id=self.run_id,
                actor_role=Role.CLAIM_VERIFIER,
                state_before=self.state,
                requested_state_after=self.state,
                artifact_hashes=(completion_digest,),
                code_version=self.code_version,
                configuration_hash=self.configuration_hash,
                reason=(
                    reason or "completed exact scientific Result canonical-state bundle"
                ),
                prior_event_hash=prospective_head,
                event_id=completion_event_id,
                timestamp=completion_time,
                event_type="CHECKPOINT",
                metadata=expected_completion_metadata,
            )
            prospective_events.append(completion_event)
        if missing_events != len(prospective_events):
            raise ValidationError(
                "scientific Result bundle prospective event closure differs"
            )
        prospective_event_bytes = sum(
            len(canonical_json_bytes(event.to_dict()) + b"\n")
            for event in prospective_events
        )
        if len(ledger_result.events) + len(prospective_events) > MAX_LEDGER_EVENTS:
            raise ValidationError("scientific Result bundle exceeds ledger capacity")
        if (
            ledger_result.valid_prefix_bytes + prospective_event_bytes
            > MAX_LEDGER_BYTES
        ):
            raise ValidationError(
                "scientific Result bundle exceeds ledger byte capacity"
            )

        prospective_events_by_id = {
            event.event_id: event for event in prospective_events
        }

        # One registry->ledger critical section covers every object and the
        # completion receipt.  A cooperating materializer therefore cannot
        # change repository identity between preflight and any authoritative
        # publication.  Abrupt termination can leave only the exact next
        # registry artifact without its event; retry logic treats that single
        # inert artifact as the only permissible continuation point.
        committed: list[MaterializedResearchObject] = []
        registry_guard = self.registry._open_mutation_lock()
        try:
            ledger_guard = self.ledger._open_lock()
            try:
                locked_registry = self.registry._verify_all_locked(
                    registry_guard,
                    raise_on_error=True,
                )
                locked_ledger = self.ledger._validate_bytes(
                    self.ledger._read_raw_locked(ledger_guard)
                )
                if (
                    not locked_ledger.valid
                    or locked_registry != registry_result
                    or locked_ledger != ledger_result
                ):
                    raise ValidationError(
                        "scientific Result bundle repository changed before commit"
                    )

                running_ledger = locked_ledger
                for record in ordered:
                    expected_artifact = prospective_artifacts[record.content_hash]
                    existing_event = self._materialization_event(
                        expected_artifact.sha256,
                        record,
                        events=ledger_result.events,
                    )
                    event_to_append = (
                        prospective_events_by_id.get(
                            f"rs-{expected_artifact.sha256[:48]}"
                        )
                        if existing_event is None
                        else None
                    )
                    materialized, running_ledger = (
                        self._persist_prevalidated_scientific_bundle_record(
                            record,
                            registry_guard=registry_guard,
                            ledger_guard=ledger_guard,
                            expected_artifact=expected_artifact,
                            artifact_missing=(
                                expected_artifact.sha256 not in registry_records
                            ),
                            existing_event=existing_event,
                            event_to_append=event_to_append,
                            expected_ledger=running_ledger,
                        )
                    )
                    committed.append(materialized)

                if completion_candidates:
                    completion_record = self.registry._get_metadata_locked(
                        registry_guard,
                        completion_digest,
                    )
                else:
                    completion_record = self.registry._put_bytes_locked(
                        registry_guard,
                        completion_bytes,
                        logical_type=expected_completion_record.logical_type,
                        origin=expected_completion_record.origin,
                        creator_role=expected_completion_record.creator_role,
                        creation_command=(expected_completion_record.creation_command),
                        parent_artifacts=(expected_completion_record.parent_artifacts),
                        schema_version=(expected_completion_record.schema_version),
                        mime_type=expected_completion_record.mime_type,
                        validation_result=(
                            expected_completion_record.validation_result
                        ),
                        frozen=expected_completion_record.frozen,
                        created_at=expected_completion_record.created_at,
                    )
                if completion_record != expected_completion_record:
                    raise ValidationError(
                        "scientific Result bundle completion changed during commit"
                    )

                if not completion_events:
                    event_to_append = prospective_events_by_id.get(completion_event_id)
                    if event_to_append is None:
                        raise ValidationError(
                            "scientific Result bundle completion event is absent"
                        )

                    def build_completion_event(
                        current: LedgerValidationResult,
                    ) -> LedgerEvent:
                        if current != running_ledger:
                            raise ValidationError(
                                "scientific Result bundle ledger changed "
                                "during completion"
                            )
                        return event_to_append

                    appended = self.ledger._append_locked(
                        ledger_guard,
                        build_completion_event,
                    )
                    if appended != event_to_append:
                        raise ValidationError(
                            "scientific Result bundle completion event changed"
                        )
                    running_ledger = self.ledger._validate_bytes(
                        self.ledger._read_raw_locked(ledger_guard)
                    )
                    if (
                        not running_ledger.valid
                        or running_ledger.events[-1] != event_to_append
                    ):
                        raise ValidationError(
                            "scientific Result bundle completion append is incomplete"
                        )
                self.registry._verify_mutation_namespace(registry_guard)
            finally:
                self.ledger._unlock(ledger_guard)
        finally:
            self.registry._unlock_mutation(registry_guard)

        stored = self._stored_objects()
        by_content, _by_identity = self._indexes(stored)
        ordered_stored = self._scientific_result_bundle_objects(
            result,
            by_content,
        )
        if tuple(item.research_object for item in ordered_stored) != ordered or tuple(
            item.artifact for item in ordered_stored
        ) != tuple(prospective_artifacts[record.content_hash] for record in ordered):
            raise ValidationError(
                "scientific Result bundle changed during append-only commit"
            )
        self._require_scientific_result_bundle_completion(
            result,
            by_content,
            promotion_record=promotion_record,
            expected_scientific_evidence_eligible=(
                result_resolution.scientific_evidence_eligible
            ),
        )
        return tuple(committed)

    def materialize(
        self,
        record: CanonicalResearchObject,
        *,
        reason: str | None = None,
    ) -> MaterializedResearchObject:
        if not isinstance(record, CanonicalResearchObject):
            raise ValidationError(
                "only typed canonical research objects may be materialized"
            )
        if record.schema_version != RESEARCH_STATE_SCHEMA_VERSION:
            raise ValidationError("unsupported canonical research-state schema version")
        if record.code_version is not None and record.code_version != self.code_version:
            raise ValidationError(
                "research object was produced by a different code version"
            )
        if reason is not None and (
            not isinstance(reason, str) or not reason.strip() or len(reason) > 8192
        ):
            raise ValidationError(
                "canonical-state materialization reason must be non-empty bounded text"
            )
        ledger_result = self.ledger.validate(raise_on_error=True)
        # Establish the empty ledger inode before taking a registry namespace
        # snapshot.  Creating it later would legitimately change a parent
        # directory while a concurrent registry guard is active.
        self._ensure_ledger_file_for_atomic_commit(ledger_result)
        registry_result = self.registry.verify_all(raise_on_error=True)
        stored = self._preflight_repository_identity(
            ledger_result=ledger_result,
        )
        orphaned = tuple(
            item
            for item in stored
            if self._materialization_event(
                item.artifact.sha256,
                item.research_object,
                events=ledger_result.events,
            )
            is None
        )
        if len(orphaned) > 1 or orphaned and orphaned[0].research_object != record:
            raise ValidationError(
                "canonical-state materialization cannot consume an inert "
                "artifact from another operation"
            )
        by_content, by_identity = self._indexes(stored)
        identity = (record.object_type, record.object_id)
        existing_revisions = by_identity.get(identity, [])
        for item in existing_revisions:
            candidate = item.research_object
            if (
                candidate.revision == record.revision
                and candidate.content_hash != record.content_hash
            ):
                raise ValidationError(
                    "research object revision already has different canonical content"
                )

        existing = by_content.get(record.content_hash)
        predecessor: _StoredObject | None = None
        if record.revision == 1:
            if existing_revisions and existing is None:
                raise ValidationError(
                    "research object identity already exists; create a superseding revision"
                )
        else:
            if not existing_revisions:
                raise ValidationError("superseding research object has no predecessor")
            predecessor = next(
                (
                    item
                    for item in existing_revisions
                    if item.research_object.revision == record.revision - 1
                ),
                None,
            )
            if predecessor is None:
                raise ValidationError("research object revision is not contiguous")
            if (
                predecessor.research_object.content_hash
                != record.supersedes_content_hash
            ):
                raise ValidationError(
                    "research object supersession hash does not bind the latest revision"
                )
            latest_revision = max(
                item.research_object.revision for item in existing_revisions
            )
            expected_latest = (
                record.revision if existing is not None else record.revision - 1
            )
            if latest_revision != expected_latest:
                raise ValidationError(
                    "research object supersession does not extend the latest revision"
                )

        # Authority and semantic checks that require resolving registry bytes
        # belong at this boundary, not in SHA-shaped canonical fields.
        self._resolve_object_authority(record, by_content)
        if isinstance(record, StatisticalTest):
            result_parents = self._resolved_parent_objects(
                record,
                by_content,
                "Result",
            )
            if any(
                any(
                    authority.logical_type
                    in {
                        "scientific_result_promotion_authority",
                        "scientific_result_promotion_authority_v3",
                    }
                    for authority in self._resolve_object_authority(
                        parent,
                        by_content,
                    ).records
                )
                for parent in result_parents
            ):
                raise ValidationError(
                    "a source-bound Result StatisticalTest must be materialized "
                    "through materialize_scientific_result_bundle"
                )

        parent_artifacts: set[str] = set()
        for parent in record.parents:
            stored_parent = by_content.get(parent.content_hash)
            if stored_parent is None:
                raise ValidationError("research object parent is missing")
            parent_record = stored_parent.research_object
            if (
                parent_record.object_type != parent.object_type
                or parent_record.object_id != parent.object_id
            ):
                raise ValidationError(
                    "research object parent identity does not match its content hash"
                )
            latest_parent = max(
                by_identity[(parent.object_type, parent.object_id)],
                key=lambda item: item.research_object.revision,
            )
            if latest_parent.research_object.content_hash != parent.content_hash:
                raise ValidationError(
                    "new research object cannot derive from a stale parent"
                )
            parent_artifacts.add(stored_parent.artifact.sha256)
        if predecessor is not None:
            parent_artifacts.add(predecessor.artifact.sha256)
        for digest in self._embedded_artifact_hashes(record):
            self.registry.verify(digest, raise_on_error=True)
            parent_artifacts.add(digest)

        record_bytes = record.canonical_bytes()
        artifact_hash = sha256_bytes(record_bytes)
        origin = (
            f"research-state:{record.object_type}:{record.object_id}:r{record.revision}"
        )
        canonical_parents = tuple(sorted(parent_artifacts))
        prior_event: LedgerEvent | None = None
        if predecessor is not None:
            prior_event = self._materialization_event(
                predecessor.artifact.sha256,
                predecessor.research_object,
                events=ledger_result.events,
            )
            if prior_event is None:
                raise LedgerError(
                    "superseded research object has no materialization event"
                )
        event = self._materialization_event(
            artifact_hash,
            record,
            events=ledger_result.events,
        )
        if event is not None and existing is None:
            raise LedgerError(
                "research-state event cannot precede registry materialization"
            )
        operation = "SUPERSEDED" if predecessor is not None else "MATERIALIZED"
        event_to_append: LedgerEvent | None = None
        if event is None:
            event_to_append = LedgerEvent.create(
                run_id=self.run_id,
                actor_role=record.producer,
                state_before=self.state,
                requested_state_after=self.state,
                artifact_hashes=(artifact_hash,),
                code_version=self.code_version,
                configuration_hash=self.configuration_hash,
                reason=(
                    reason
                    if reason is not None
                    else (
                        f"{operation.lower()} canonical "
                        f"{record.object_type} {record.object_id} "
                        f"revision {record.revision}"
                    )
                ),
                prior_event_hash=ledger_result.head_hash,
                event_id=f"rs-{artifact_hash[:48]}",
                timestamp=record.created_at,
                event_type=("CORRECTION" if predecessor is not None else "CHECKPOINT"),
                supersedes_event_id=(
                    prior_event.event_id if prior_event is not None else None
                ),
                metadata={
                    "research_state_operation": operation,
                    "object_type": record.object_type,
                    "object_id": record.object_id,
                    "revision": record.revision,
                    "content_hash": record.content_hash,
                    "artifact_hash": artifact_hash,
                    "supersedes_content_hash": record.supersedes_content_hash,
                    "schema_version": record.schema_version,
                },
            )
            event_bytes = canonical_json_bytes(event_to_append.to_dict()) + b"\n"
            if ledger_result.event_count + 1 > MAX_LEDGER_EVENTS:
                raise ValidationError(
                    "canonical-state materialization exceeds ledger capacity"
                )
            if ledger_result.valid_prefix_bytes + len(event_bytes) > MAX_LEDGER_BYTES:
                raise ValidationError(
                    "canonical-state materialization exceeds ledger byte capacity"
                )

        # The registry lock is always acquired before the ledger lock.  Both
        # remain held from the exact preflight recheck through the
        # registry-first/ledger-second commit, so a competing repository
        # identity cannot interleave between validation and publication.
        registry_guard = self.registry._open_mutation_lock()
        try:
            ledger_guard = self.ledger._open_lock()
            try:
                locked_registry = self.registry._verify_all_locked(
                    registry_guard,
                    raise_on_error=True,
                )
                locked_ledger = self.ledger._validate_bytes(
                    self.ledger._read_raw_locked(ledger_guard)
                )
                if (
                    not locked_ledger.valid
                    or locked_registry != registry_result
                    or locked_ledger != ledger_result
                ):
                    raise ValidationError(
                        "canonical-state repository changed before materialization"
                    )

                if existing is None:
                    artifact = self.registry._put_bytes_locked(
                        registry_guard,
                        record_bytes,
                        logical_type=record.logical_type,
                        origin=origin,
                        creator_role=record.producer,
                        creation_command=self.creation_command,
                        parent_artifacts=canonical_parents,
                        schema_version=record.schema_version,
                        mime_type="application/json",
                        validation_result="PASS",
                        frozen=True,
                        created_at=record.created_at,
                    )
                else:
                    artifact = self.registry._get_metadata_locked(
                        registry_guard,
                        artifact_hash,
                    )
                    if artifact != existing.artifact:
                        raise ValidationError(
                            "existing research-state artifact changed"
                        )
                if (
                    artifact.sha256 != artifact_hash
                    or artifact.parent_artifacts != canonical_parents
                    or artifact.origin != origin
                    or artifact.creation_command != self.creation_command
                ):
                    raise ValidationError(
                        "existing research-state artifact provenance differs"
                    )

                if event is None:
                    if event_to_append is None:  # pragma: no cover - exhaustive
                        raise ValidationError(
                            "canonical-state prospective event is absent"
                        )

                    def build_event(
                        current: LedgerValidationResult,
                    ) -> LedgerEvent:
                        if current != locked_ledger:
                            raise ValidationError(
                                "canonical-state ledger changed during materialization"
                            )
                        return event_to_append

                    event = self.ledger._append_locked(
                        ledger_guard,
                        build_event,
                    )
                self.registry._verify_mutation_namespace(registry_guard)
            finally:
                self.ledger._unlock(ledger_guard)
        finally:
            self.registry._unlock_mutation(registry_guard)
        return MaterializedResearchObject(record, artifact, event)

    def objects(self) -> tuple[CanonicalResearchObject, ...]:
        return tuple(item.research_object for item in self._stored_objects())

    def latest(self, object_type: str, object_id: str) -> CanonicalResearchObject:
        if object_type not in _RECORD_TYPES:
            raise ValidationError("unknown research object type")
        validate_identifier(object_id, "research object ID")
        matches = [
            item.research_object
            for item in self._stored_objects()
            if item.research_object.object_type == object_type
            and item.research_object.object_id == object_id
        ]
        if not matches:
            raise ValidationError("research object does not exist")
        return max(matches, key=lambda item: item.revision)

    def validate_state(
        self, *, expected_code_version: str | None = None
    ) -> StateValidationReport:
        issues: list[StateIssue] = []
        try:
            self.registry.verify_all(raise_on_error=True)
        except ArtifactError as exc:
            return StateValidationReport(
                False,
                (
                    StateIssue(
                        StateIssueCode.ARTIFACT_REGISTRY_CORRUPT,
                        StateIssueSeverity.ERROR,
                        None,
                        None,
                        None,
                        str(exc),
                    ),
                ),
                0,
                (),
            )
        try:
            ledger_result = self.ledger.validate(raise_on_error=True)
        except LedgerError as exc:
            return StateValidationReport(
                False,
                (
                    StateIssue(
                        StateIssueCode.LEDGER_CORRUPT,
                        StateIssueSeverity.ERROR,
                        None,
                        None,
                        None,
                        str(exc),
                    ),
                ),
                0,
                (),
            )
        try:
            stored = self._stored_objects()
            by_content, by_identity = self._indexes(stored)
        except (ArtifactError, ValidationError) as exc:
            return StateValidationReport(
                False,
                (
                    StateIssue(
                        StateIssueCode.ARTIFACT_METADATA_MISMATCH,
                        StateIssueSeverity.ERROR,
                        None,
                        None,
                        None,
                        str(exc),
                    ),
                ),
                0,
                (),
            )

        latest_by_identity: dict[tuple[str, str], _StoredObject] = {}
        for identity, revisions in by_identity.items():
            ordered = sorted(revisions, key=lambda item: item.research_object.revision)
            seen_revisions: set[int] = set()
            previous: _StoredObject | None = None
            for item in ordered:
                record = item.research_object
                if record.revision in seen_revisions:
                    issues.append(
                        StateIssue(
                            StateIssueCode.DUPLICATE_REVISION,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            "multiple canonical objects use the same revision",
                        )
                    )
                seen_revisions.add(record.revision)
                if previous is None:
                    if (
                        record.revision != 1
                        or record.supersedes_content_hash is not None
                    ):
                        issues.append(
                            StateIssue(
                                StateIssueCode.SUPERSESSION_GAP,
                                StateIssueSeverity.ERROR,
                                record.object_type,
                                record.object_id,
                                record.content_hash,
                                "revision lineage does not start at revision one",
                            )
                        )
                elif (
                    record.revision != previous.research_object.revision + 1
                    or record.supersedes_content_hash
                    != previous.research_object.content_hash
                ):
                    issues.append(
                        StateIssue(
                            StateIssueCode.SUPERSESSION_GAP,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            "revision does not exactly supersede its predecessor",
                        )
                    )
                previous = item
            latest = ordered[-1]
            latest_by_identity[identity] = latest
            for stale in ordered[:-1]:
                record = stale.research_object
                issues.append(
                    StateIssue(
                        StateIssueCode.STALE_OBJECT,
                        StateIssueSeverity.INFO,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        "historical revision is superseded by a newer canonical revision",
                    )
                )

        events_by_artifact: dict[str, list[LedgerEvent]] = {}
        for event in ledger_result.events:
            if len(event.artifact_hashes) == 1 and event.metadata.get(
                "research_state_operation"
            ) in {"MATERIALIZED", "SUPERSEDED"}:
                events_by_artifact.setdefault(event.artifact_hashes[0], []).append(
                    event
                )
        event_indices = {
            event.event_id: index for index, event in enumerate(ledger_result.events)
        }
        expected_code = expected_code_version or self.code_version
        for item in stored:
            record = item.research_object
            expected_operation = (
                "MATERIALIZED" if record.revision == 1 else "SUPERSEDED"
            )
            expected_event_type = "CHECKPOINT" if record.revision == 1 else "CORRECTION"
            matching_events = [
                event
                for event in events_by_artifact.get(item.artifact.sha256, [])
                if event.run_id == self.run_id
                and event.actor_role is record.producer
                and event.timestamp == record.created_at
                and event.code_version == self.code_version
                and event.configuration_hash == self.configuration_hash
                and event.state_before == self.state
                and event.requested_state_after == self.state
                and event.event_type == expected_event_type
                and event.metadata.get("research_state_operation") == expected_operation
                and event.metadata.get("object_type") == record.object_type
                and event.metadata.get("object_id") == record.object_id
                and event.metadata.get("revision") == record.revision
                and event.metadata.get("content_hash") == record.content_hash
                and event.metadata.get("artifact_hash") == item.artifact.sha256
                and event.metadata.get("schema_version") == record.schema_version
                and event.metadata.get("supersedes_content_hash")
                == record.supersedes_content_hash
            ]
            if len(matching_events) != 1:
                issues.append(
                    StateIssue(
                        StateIssueCode.MISSING_MATERIALIZATION_EVENT,
                        StateIssueSeverity.ERROR,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        "canonical artifact has no matching materialization event",
                    )
                )
            else:
                materialization_event = matching_events[0]
                materialization_index = event_indices[materialization_event.event_id]
                successor = next(
                    (
                        candidate
                        for candidate in by_identity.get(
                            (record.object_type, record.object_id),
                            (),
                        )
                        if candidate.research_object.revision == record.revision + 1
                    ),
                    None,
                )
                allowed_correction_id = (
                    f"rs-{successor.artifact.sha256[:48]}"
                    if successor is not None
                    else None
                )
                if any(
                    event.event_type == "CORRECTION"
                    and event.supersedes_event_id == materialization_event.event_id
                    and event.event_id != allowed_correction_id
                    for event in ledger_result.events[materialization_index + 1 :]
                ):
                    issues.append(
                        StateIssue(
                            StateIssueCode.MISSING_MATERIALIZATION_EVENT,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            "canonical materialization event has a non-lineage correction",
                        )
                    )
                if record.revision > 1:
                    predecessor = by_content.get(record.supersedes_content_hash or "")
                    expected_superseded_event_id = (
                        f"rs-{predecessor.artifact.sha256[:48]}"
                        if predecessor is not None
                        else None
                    )
                    predecessor_index = (
                        event_indices.get(expected_superseded_event_id)
                        if expected_superseded_event_id is not None
                        else None
                    )
                    if (
                        materialization_event.supersedes_event_id
                        != expected_superseded_event_id
                        or predecessor_index is None
                        or predecessor_index >= materialization_index
                    ):
                        issues.append(
                            StateIssue(
                                StateIssueCode.MISSING_MATERIALIZATION_EVENT,
                                StateIssueSeverity.ERROR,
                                record.object_type,
                                record.object_id,
                                record.content_hash,
                                "canonical correction does not follow and supersede the exact predecessor event",
                            )
                        )
            if record.code_version is not None and record.code_version != expected_code:
                issues.append(
                    StateIssue(
                        StateIssueCode.WRONG_CODE,
                        StateIssueSeverity.ERROR,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        f"object code version {record.code_version!r} differs from expected {expected_code!r}",
                    )
                )

            try:
                self._validate_producer_authority(record)
            except (AuthorizationError, ValidationError) as exc:
                issues.append(
                    StateIssue(
                        StateIssueCode.UNAUTHORIZED_PRODUCER,
                        StateIssueSeverity.ERROR,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        str(exc),
                    )
                )
            try:
                self._resolve_object_authority(record, by_content)
            except (
                ArtifactError,
                AuthorizationError,
                LedgerError,
                ValidationError,
            ) as exc:
                issues.append(
                    StateIssue(
                        StateIssueCode.SEMANTIC_AUTHORITY_INVALID,
                        StateIssueSeverity.ERROR,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        str(exc),
                    )
                )

            expected_parent_artifacts = set(self._embedded_artifact_hashes(record))
            for parent in record.parents:
                stored_parent = by_content.get(parent.content_hash)
                if stored_parent is None:
                    issues.append(
                        StateIssue(
                            StateIssueCode.MISSING_PARENT,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            f"missing {parent.object_type}:{parent.object_id}@{parent.content_hash[:12]}",
                        )
                    )
                    continue
                expected_parent_artifacts.add(stored_parent.artifact.sha256)
                if (
                    stored_parent.research_object.object_type != parent.object_type
                    or stored_parent.research_object.object_id != parent.object_id
                ):
                    issues.append(
                        StateIssue(
                            StateIssueCode.MISSING_PARENT,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            "parent content hash resolves to a different identity",
                        )
                    )
                    continue
                parent_events = tuple(
                    event
                    for event in events_by_artifact.get(
                        stored_parent.artifact.sha256,
                        (),
                    )
                    if event.event_id == f"rs-{stored_parent.artifact.sha256[:48]}"
                )
                if (
                    len(matching_events) == 1
                    and len(parent_events) == 1
                    and event_indices[parent_events[0].event_id]
                    >= event_indices[matching_events[0].event_id]
                ):
                    issues.append(
                        StateIssue(
                            StateIssueCode.MISSING_PROVENANCE_EDGE,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            "canonical child became visible before its parent event",
                        )
                    )
                latest_parent = latest_by_identity.get(
                    (parent.object_type, parent.object_id)
                )
                if (
                    latest_parent is not None
                    and latest_parent.research_object.content_hash
                    != parent.content_hash
                ):
                    try:
                        evaluation_successor = (
                            self._source_bound_hypothesis_evaluation_successor(
                                stored_parent.research_object,
                                tuple(
                                    candidate.research_object
                                    for candidate in by_identity.get(
                                        (parent.object_type, parent.object_id),
                                        (),
                                    )
                                ),
                                by_content,
                                ledger_result.events,
                            )
                        )
                    except (ArtifactError, LedgerError, ValidationError):
                        evaluation_successor = None
                    if (
                        evaluation_successor is None
                        or evaluation_successor.artifact.sha256
                        != latest_parent.artifact.sha256
                    ):
                        code = (
                            StateIssueCode.CHANGED_AFTER_EVALUATION
                            if parent.evaluated
                            else StateIssueCode.OUTDATED_DERIVED_ARTIFACT
                        )
                        detail = (
                            "evaluated input has a newer canonical revision"
                            if parent.evaluated
                            else "derived object depends on a superseded input"
                        )
                        issues.append(
                            StateIssue(
                                code,
                                StateIssueSeverity.ERROR,
                                record.object_type,
                                record.object_id,
                                record.content_hash,
                                detail,
                            )
                        )
            if record.revision > 1 and record.supersedes_content_hash in by_content:
                expected_parent_artifacts.add(
                    by_content[record.supersedes_content_hash].artifact.sha256
                )
            if tuple(item.artifact.parent_artifacts) != tuple(
                sorted(expected_parent_artifacts)
            ):
                issues.append(
                    StateIssue(
                        StateIssueCode.MISSING_PROVENANCE_EDGE,
                        StateIssueSeverity.ERROR,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        "artifact registry parents differ from exact canonical dependencies",
                    )
                )
            if (
                item.artifact.origin
                != f"research-state:{record.object_type}:{record.object_id}:r{record.revision}"
                or item.artifact.creation_command != self.creation_command
            ):
                issues.append(
                    StateIssue(
                        StateIssueCode.ARTIFACT_METADATA_MISMATCH,
                        StateIssueSeverity.ERROR,
                        record.object_type,
                        record.object_id,
                        record.content_hash,
                        "canonical artifact origin or creation command differs from repository materialization",
                    )
                )

            for link in record.relationships:
                if (
                    link.required
                    and (link.object_type, link.object_id) not in latest_by_identity
                ):
                    issues.append(
                        StateIssue(
                            StateIssueCode.MISSING_RELATIONSHIP,
                            StateIssueSeverity.ERROR,
                            record.object_type,
                            record.object_id,
                            record.content_hash,
                            f"required relationship {link.relation} points to missing {link.object_type}:{link.object_id}",
                        )
                    )

        current_hashes = tuple(
            sorted(item.artifact.sha256 for item in latest_by_identity.values())
        )
        valid = not any(issue.severity is StateIssueSeverity.ERROR for issue in issues)
        return StateValidationReport(valid, tuple(issues), len(stored), current_hashes)


def _hypothesis_evaluation_repository(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    state_artifact_hash: str,
) -> tuple[
    ResearchStateRepository,
    tuple[_StoredObject, ...],
    dict[str, _StoredObject],
    dict[tuple[str, str], list[_StoredObject]],
]:
    """Reopen the exact repository identity that owns a state artifact."""

    validate_identifier(run_id, "hypothesis evaluation run ID")
    validate_sha256(
        state_artifact_hash,
        "hypothesis evaluation state artifact SHA-256",
    )
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    registry.verify(state_artifact_hash, raise_on_error=True)
    artifact = registry.get_metadata(state_artifact_hash)
    events = ledger.validate(raise_on_error=True).events
    matches = tuple(
        event
        for event in events
        if event.event_id == f"rs-{state_artifact_hash[:48]}"
        and event.run_id == run_id
        and event.artifact_hashes == (state_artifact_hash,)
        and event.metadata.get("artifact_hash") == state_artifact_hash
        and event.metadata.get("research_state_operation")
        in {"MATERIALIZED", "SUPERSEDED"}
    )
    if len(matches) != 1:
        raise ValidationError(
            "hypothesis evaluation source lacks one exact same-run materialization"
        )
    event = matches[0]
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=event.code_version,
        configuration_hash=event.configuration_hash,
        state=event.state_before,
        creation_command=artifact.creation_command,
    )
    stored = repository._preflight_repository_identity()
    by_content, by_identity = repository._indexes(stored)
    return repository, stored, by_content, by_identity


def _hypothesis_evaluation_facts(
    result: Result,
    statistical_test: StatisticalTest,
) -> Any:
    """Derive one typed fact projection from exact canonical state."""

    from .scientific_design import HypothesisEvaluationFacts

    if any(
        str(value.get("schema_version", "")).endswith("/v4")
        for value in (result.metadata, statistical_test.metadata)
    ):
        raise ValidationError("bounded hypothesis evaluation requires native source replay")
    result_value = thaw_json(result.value)
    result_uncertainty = thaw_json(result.uncertainty)
    statistical_outcome = thaw_json(statistical_test.outcome)
    if (
        not isinstance(result_value, Mapping)
        or not isinstance(result_uncertainty, Mapping)
        or not isinstance(statistical_outcome, Mapping)
    ):
        raise ValidationError(
            "hypothesis evaluation requires structured Result and StatisticalTest facts"
        )
    effect = statistical_outcome.get(
        "improvement_effect",
        statistical_outcome.get("effect"),
    )
    p_value = statistical_outcome.get(
        "adjusted_p_value",
        statistical_outcome.get("p_value"),
    )
    sample_size = statistical_outcome.get(
        "sample_size",
        statistical_outcome.get("independent_unit_count"),
    )
    if "confidence_low" in statistical_outcome:
        confidence_low = statistical_outcome.get("confidence_low")
        confidence_high = statistical_outcome.get("confidence_high")
    else:
        interval = statistical_outcome.get("confidence_interval")
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            raise ValidationError(
                "hypothesis evaluation StatisticalTest lacks a confidence interval"
            )
        confidence_low, confidence_high = interval
    result_effect = result_value.get("improvement")
    result_p = result_uncertainty.get(
        "adjusted_p_value",
        result_uncertainty.get("p_value"),
    )
    if "confidence_low" in result_uncertainty:
        result_low = result_uncertainty.get("confidence_low")
        result_high = result_uncertainty.get("confidence_high")
    else:
        result_interval = result_uncertainty.get("confidence_interval")
        if not isinstance(result_interval, (list, tuple)) or len(result_interval) != 2:
            raise ValidationError(
                "hypothesis evaluation Result lacks a confidence interval"
            )
        result_low, result_high = result_interval
    if not all(
        ResearchStateRepository._float_matches(left, right)
        for left, right in (
            (effect, result_effect),
            (confidence_low, result_low),
            (confidence_high, result_high),
        )
    ) or not (
        (p_value is None and result_p is None)
        or ResearchStateRepository._float_matches(p_value, result_p)
    ):
        raise ValidationError(
            "hypothesis evaluation Result and StatisticalTest facts disagree"
        )
    try:
        return HypothesisEvaluationFacts(
            improvement_effect=effect,
            confidence_low=confidence_low,
            confidence_high=confidence_high,
            adjusted_p_value=p_value,
            sample_size=sample_size,
        )
    except Exception as exc:
        raise ValidationError(
            "hypothesis evaluation facts fail the frozen typed contract"
        ) from exc


def _one_optional_authority(
    records: tuple[ArtifactRecord, ...],
    logical_types: frozenset[str],
    *,
    label: str,
) -> ArtifactRecord | None:
    matches = tuple(item for item in records if item.logical_type in logical_types)
    if len(matches) > 1:
        raise ValidationError(f"hypothesis evaluation {label} is ambiguous")
    return matches[0] if matches else None


def _require_bounded_hypothesis_successor_bindings(
    repository: ResearchStateRepository,
    authority: HypothesisEvaluationAuthority,
    prior: _StoredObject,
    result_stored: _StoredObject,
    test_stored: _StoredObject,
) -> None:
    """Static v2 exception joins, never downstream scientific owner replay.

    The contract reader is registry-only; native arithmetic is pure. In
    particular this must not call Result, Test, projection, execution or
    Hypothesis semantic owners, which would create a frozen-ancestry cycle.
    """

    from .bounded_mean_inference import (
        BOUNDED_MEAN_CONDITIONAL_SCOPE, BOUNDED_MEAN_DECISION_RULE_ID,
        BOUNDED_MEAN_INTERVAL_METHOD_ID, BOUNDED_MEAN_NUMERICAL_CONTRACT_ID,
        BOUNDED_MEAN_PROCEDURE_ID, BOUNDED_MEAN_ZERO_P_METHOD_ID,
        BoundedMeanInferencePlan, BoundedMeanInferenceResult, PairedRowCorrectnessCounts,
    )
    from .scientific_design import (
        CheckedResultAssessment, MetricDirection, MetricScope, MetricUnit,
        ScientificResultPromotionReceiptV3,
        _replay_bounded_mean_policy_result, derive_bounded_mean_result_assessment,
        require_frozen_evaluation_contract,
    )

    registry = repository.registry
    result, test = result_stored.research_object, test_stored.research_object
    if type(result) is not Result or type(test) is not StatisticalTest:
        raise ValidationError("bounded historical evaluation parents have wrong types")
    for record, expected_hash in (
        (prior.artifact, authority.prior_hypothesis_state_record_hash),
        (result_stored.artifact, authority.result_state_record_hash),
        (test_stored.artifact, authority.statistical_test_state_record_hash),
        (registry.get_metadata(authority.evaluation_contract_artifact_hash), authority.evaluation_contract_record_hash),
        (registry.get_metadata(authority.checked_result_assessment_artifact_hash), authority.checked_result_assessment_record_hash),
        (registry.get_metadata(authority.paired_metric_projection_authority_artifact_hash), authority.paired_metric_projection_authority_record_hash),
        (registry.get_metadata(authority.statistical_use_authority_artifact_hash), authority.statistical_use_authority_record_hash),
    ):
        if record.record_hash != expected_hash:
            raise ValidationError("bounded historical evaluation source record differs")
    for current, hashes, record_hashes in (
        (result, authority.result_authority_artifact_hashes, authority.result_authority_record_hashes),
        (test, authority.statistical_authority_artifact_hashes, authority.statistical_authority_record_hashes),
    ):
        records = repository._authority_records(current)
        if (tuple(item.sha256 for item in records) != hashes
                or tuple(item.record_hash for item in records) != record_hashes):
            raise ValidationError("bounded historical canonical authority records differ")
    contract = require_frozen_evaluation_contract(registry, contract_artifact_sha256=authority.evaluation_contract_artifact_hash)
    policy = contract.hypothesis_evaluation_policy(authority.hypothesis_id)
    assessment_record = repository._require_frozen_pass_artifact(
        authority.checked_result_assessment_artifact_hash,
        logical_type="checked_result_assessment", creator_role=Role.CLAIM_VERIFIER,
    )
    assessment = CheckedResultAssessment.from_dict(repository._read_authority_json(assessment_record))
    promotion_record = repository._require_frozen_pass_artifact(
        authority.scientific_result_promotion_authority_artifact_hash,
        logical_type="scientific_result_promotion_authority_v3", creator_role=Role.CLAIM_VERIFIER,
    )
    promotion = ScientificResultPromotionReceiptV3.from_dict(repository._read_authority_json(promotion_record))
    if (
        not authority.is_bounded_mean or not assessment.is_bounded_mean
        or assessment_record.schema_version != "3.0"
        or promotion_record.schema_version != "1.0"
        or registry.get_bytes(promotion_record.sha256) != canonical_json_bytes(promotion.to_dict()) + b"\n"
        or promotion_record.parent_artifacts != promotion.source_artifact_hashes
        or registry.get_bytes(assessment_record.sha256) != canonical_json_bytes(assessment.to_dict()) + b"\n"
        or contract.sha256 != authority.evaluation_contract_sha256
        or policy.policy_id != authority.evaluation_policy_id or policy.sha256 != authority.evaluation_policy_sha256
        or policy.rule_id != BOUNDED_MEAN_DECISION_RULE_ID
        or assessment.contract_artifact_sha256 != authority.evaluation_contract_artifact_hash
        or assessment.contract_record_hash != authority.evaluation_contract_record_hash
        or assessment.contract_sha256 != authority.evaluation_contract_sha256
        or assessment.hypothesis_id != authority.hypothesis_id or assessment.metric_id != authority.metric_id
        or assessment.ledger_run_id != authority.run_id
        or assessment.metric_unit is not MetricUnit.FRACTION
        or assessment.metric_scope is not MetricScope.END_TO_END
        or contract.primary_metric.metric_id != authority.metric_id
        or contract.primary_metric.unit is not assessment.metric_unit
        or contract.primary_metric.scope is not assessment.metric_scope
        or contract.primary_metric.direction is not MetricDirection.HIGHER_IS_BETTER
        or assessment.inference_profile_id != authority.inference_profile_id
        or assessment.statistical_use_authority_artifact_sha256 != authority.statistical_use_authority_artifact_hash
        or assessment.statistical_use_authority_record_hash != authority.statistical_use_authority_record_hash
        or assessment.generic_ml_paired_metric_projection_authority_artifact_sha256 != authority.paired_metric_projection_authority_artifact_hash
        or assessment.generic_ml_paired_metric_projection_authority_record_hash != authority.paired_metric_projection_authority_record_hash
        or assessment.statistical_analysis_sha256 != authority.statistical_analysis_authority_artifact_hash
        or assessment.scientific_execution_authority_artifact_sha256 != authority.backend_execution_authority_artifact_hash
        or promotion.checked_result_assessment_artifact_sha256 != assessment_record.sha256
        or promotion.contract_artifact_sha256 != authority.evaluation_contract_artifact_hash
        or promotion.result_id != result.object_id or promotion.ledger_run_id != authority.run_id
        or result.run_ids != (promotion.execution_run_id,) or result.metric_id != authority.metric_id
        or promotion.execution_run_id != assessment.execution_run_id
        or promotion.scientific_execution_authority_artifact_sha256 != authority.backend_execution_authority_artifact_hash
        or promotion.domain_validity_receipt_artifact_sha256 != authority.domain_validity_authority_artifact_hash
        or promotion.scientific_timeline_receipt_artifact_sha256 != authority.scientific_timeline_authority_artifact_hash
        or promotion.confirmation_authority_artifact_sha256 != authority.confirmation_authority_artifact_hash
        or result.evaluation_artifact_hashes != (promotion_record.sha256,)
        or test.result_ids != (result.object_id,)
    ):
        raise ValidationError("bounded historical evaluation differs from its prospective source identity")
    statistics_record = repository._require_frozen_pass_artifact(
        authority.statistical_analysis_authority_artifact_hash,
        logical_type="statistical_analysis", creator_role=Role.STATISTICIAN,
    )
    statistics = repository._read_authority_json(statistics_record)
    aggregate_record = repository._require_frozen_pass_artifact(
        assessment.aggregate_result_sha256,
        logical_type="aggregate_experiment_result", creator_role=Role.STATISTICIAN,
    )
    expected_statistics_keys = {
        "schema_version", "contract_artifact_sha256", "contract_record_hash",
        "aggregate_result_sha256", "aggregate_record_hash",
        "generic_ml_projection_artifact_sha256", "generic_ml_projection_record_hash",
        "statistical_use_authority_artifact_sha256", "statistical_use_authority_record_hash",
        "frozen_policy_sha256", "numeric_result", "inference_scope", "scientific_authority",
    }
    if (
        set(statistics) != expected_statistics_keys
        or statistics_record.record_hash != assessment.statistical_record_hash
        or aggregate_record.record_hash != assessment.aggregate_record_hash
        or aggregate_record.schema_version != "3.0"
        or statistics.get("aggregate_result_sha256") != aggregate_record.sha256
        or statistics.get("aggregate_record_hash") != aggregate_record.record_hash
        or registry.get_bytes(statistics_record.sha256) != canonical_json_bytes(statistics) + b"\n"
        or statistics_record.schema_version != "3.0"
        or statistics.get("schema_version") != "checked-result-statistics/v3"
        or statistics.get("scientific_authority") is not False
        or statistics.get("inference_scope") != BOUNDED_MEAN_CONDITIONAL_SCOPE
        or statistics.get("contract_artifact_sha256") != authority.evaluation_contract_artifact_hash
        or statistics.get("contract_record_hash") != authority.evaluation_contract_record_hash
        or statistics.get("generic_ml_projection_artifact_sha256") != authority.paired_metric_projection_authority_artifact_hash
        or statistics.get("generic_ml_projection_record_hash") != authority.paired_metric_projection_authority_record_hash
        or statistics.get("statistical_use_authority_artifact_sha256") != authority.statistical_use_authority_artifact_hash
        or statistics.get("statistical_use_authority_record_hash") != authority.statistical_use_authority_record_hash
        or statistics.get("frozen_policy_sha256") != authority.evaluation_policy_sha256
    ):
        raise ValidationError("bounded historical statistics source binding differs")
    native = statistics["numeric_result"]
    native_plan = native["plan"]
    if not isinstance(native["rows"], list) or not 1 <= len(native["rows"]) <= 4096:
        raise ValidationError("bounded historical numeric grid is invalid")
    plan = BoundedMeanInferencePlan(
        **{key: native_plan[key] for key in (
            "alpha", "benefit_margin", "harm_margin", "minimum_unit_count", "support_low", "support_high",
        )}, unit_ids=tuple(native_plan["unit_ids"]), seed_order=tuple(native_plan["seed_order"]),
    )
    numeric = _replay_bounded_mean_policy_result(policy, BoundedMeanInferenceResult(
        plan=plan, rows=tuple(PairedRowCorrectnessCounts(**row) for row in native["rows"]),
    ))
    if canonical_json_bytes(native) != canonical_json_bytes(numeric.to_dict()):
        raise ValidationError("bounded historical numeric facts fail pure replay")
    decision = derive_bounded_mean_result_assessment(policy, numeric)
    denominator = len(numeric.rows) * len(numeric.plan.seed_order)
    if (authority.outcome.value != decision.hypothesis_status.value
            or assessment.candidate_value != sum(row.candidate_correct_count for row in numeric.rows) / denominator
            or assessment.baseline_value != sum(row.reference_correct_count for row in numeric.rows) / denominator
            or authority.outcome.value != assessment.hypothesis_status.value
            or decision.outcome is not assessment.outcome
            or any(getattr(authority, field) != getattr(assessment, field) for field in (
                "improvement_effect", "confidence_low", "confidence_high", "mean_zero_p_upper", "sample_size",
            )) or any(getattr(authority, field) != value for field, value in (
                ("improvement_effect", numeric.mean_estimate), ("confidence_low", numeric.confidence_low),
                ("confidence_high", numeric.confidence_high), ("mean_zero_p_upper", numeric.mean_zero_p_upper),
                ("sample_size", len(numeric.rows)),
            ))):
        raise ValidationError("bounded historical hypothesis outcome differs from native facts")
    binding = {
        "inference_profile_id": authority.inference_profile_id,
        "statistical_use_authority_artifact_sha256": authority.statistical_use_authority_artifact_hash,
        "statistical_use_authority_record_hash": authority.statistical_use_authority_record_hash,
    }
    outcome_fields = {
        "hypothesis_id": authority.hypothesis_id, "hypothesis_status": authority.outcome.value,
        "scientific_result_outcome": assessment.outcome.value,
    }
    expected_configuration = {
        **binding, "checked_procedure_id": BOUNDED_MEAN_PROCEDURE_ID,
        "confidence_method": BOUNDED_MEAN_INTERVAL_METHOD_ID, "mean_zero_p_method": BOUNDED_MEAN_ZERO_P_METHOD_ID,
        "numerical_contract_id": BOUNDED_MEAN_NUMERICAL_CONTRACT_ID, "decision_rule_id": BOUNDED_MEAN_DECISION_RULE_ID,
        "conditional_scope": BOUNDED_MEAN_CONDITIONAL_SCOPE, "independent_unit": "PROSPECTIVELY_REVIEWED_DATASET_ROW",
        "mean_estimand": "E[D]", "alpha": plan.alpha, "confidence_level_lower": numeric.confidence_level_lower,
        "benefit_margin": plan.benefit_margin, "harm_margin": plan.harm_margin,
        "minimum_unit_count": plan.minimum_unit_count, "support": [plan.support_low, plan.support_high],
        "multiplicity_correction": "NOT_APPLICABLE_SINGLE_MEAN_FAMILY", "seed_order": list(plan.seed_order),
        "ordered_numeric_plan_sha256": sha256_bytes(canonical_json_bytes(plan.to_dict())),
    }
    expected_outcome = {
        "mean_zero_p_upper": numeric.mean_zero_p_upper, "confidence_interval": [numeric.confidence_low, numeric.confidence_high],
        "effect": numeric.mean_estimate, "hypothesis_status": authority.outcome.value,
        "mean_zero_log_p_upper": numeric.mean_zero_log_p_upper,
        "mean_zero_p_binary64_underflow_limited": numeric.mean_zero_p_binary64_underflow_limited,
        "auxiliary_sign": numeric.auxiliary_sign.to_dict(), "mean_decision": numeric.decision.value,
        "mean_decision_reason": numeric.decision_reason.value, "sample_size": len(numeric.rows),
        "scientific_result_outcome": assessment.outcome.value,
    }
    if (test.test_name != BOUNDED_MEAN_ZERO_P_METHOD_ID
            or test.null_hypothesis != "The conditional population mean row difference E[D] is zero."
            or test.alternative != "The conditional population mean row difference E[D] is non-zero."
            or any(canonical_json_bytes(thaw_json(actual)) != canonical_json_bytes(expected) for actual, expected in (
                (result.value, {"baseline": assessment.baseline_value, "candidate": assessment.candidate_value, "improvement": assessment.improvement_effect}),
                (result.uncertainty, {"mean_zero_p_upper": authority.mean_zero_p_upper, "confidence_low": authority.confidence_low, "confidence_high": authority.confidence_high}),
                (result.metadata, {"schema_version": "scientific-result-canonical-state/v4", **binding, **outcome_fields,
                                   "checked_result_assessment_artifact_sha256": assessment_record.sha256,
                                   "superiority_authority_artifact_sha256": promotion.checked_superiority_receipt_artifact_sha256}),
                (test.metadata, {"schema_version": "scientific-statistical-canonical-state/v4", **binding, **outcome_fields}),
                (test.method_configuration, expected_configuration), (test.outcome, expected_outcome),
            ))):
        raise ValidationError("bounded historical evaluation canonical views differ")


def _bounded_hypothesis_projection_outcome(
    projection: Any,
    policy: Any,
    result: Result,
    statistical_test: StatisticalTest,
) -> HypothesisStatus:
    """Check inert native views; this helper does not confer source authority."""

    from .scientific_design import (
        HypothesisEvaluationPolicy,
        HypothesisStatus as ScientificHypothesisStatus,
        MetricDirection, MetricScope, MetricUnit, ScientificResultOutcome,
        ScientificResultCanonicalProjectionV4,
        derive_bounded_mean_result_assessment,
    )
    from .bounded_mean_inference import (
        BoundedMeanDecision, BoundedMeanDecisionReason, BoundedMeanInferencePlan,
        BoundedMeanInferenceResult, ConditionalSignResult, ConditionalSignStatus,
        PairedRowCorrectnessCounts,
    )

    if (type(projection) is not ScientificResultCanonicalProjectionV4
            or type(policy) is not HypothesisEvaluationPolicy
            or type(result) is not Result or type(statistical_test) is not StatisticalTest):
        raise ValidationError("bounded hypothesis evaluation requires exact native view types")
    # Exact-type walk before any constructor, equality, serialization, or
    # arithmetic: frozen Python DTOs can be altered to carry coercion hooks.
    # This is a closed inert boundary, not a generic data/authority validator.
    dto_types = (
        ScientificResultCanonicalProjectionV4, HypothesisEvaluationPolicy,
        BoundedMeanInferencePlan, BoundedMeanInferenceResult,
        PairedRowCorrectnessCounts, ConditionalSignResult,
    )
    scalar_types = (
        str, int, bool, type(None), ScientificHypothesisStatus,
        MetricDirection, MetricScope, MetricUnit, ScientificResultOutcome,
        BoundedMeanDecision, BoundedMeanDecisionReason, ConditionalSignStatus,
    )

    def require_native(value: Any, depth: int = 0) -> None:
        if depth > 8:
            raise ValidationError("bounded hypothesis inert DTO nesting is invalid")
        value_type = type(value)
        if value_type is float:
            if not math.isfinite(value):
                raise ValidationError("bounded hypothesis inert facts must be finite")
        elif any(value_type is allowed for allowed in scalar_types):
            return
        elif value_type is tuple:
            for item in value:
                require_native(item, depth + 1)
        elif any(value_type is allowed for allowed in dto_types):
            for item in fields(value):
                require_native(getattr(value, item.name), depth + 1)
        else:
            raise ValidationError("bounded hypothesis inert DTO contains non-native values")

    require_native(projection)
    require_native(policy)
    # Reconstruct to detect altered frozen DTOs and recompute the native
    # interval decision. No generic p-value policy or auxiliary sign decision.
    projection = replace(projection)
    policy = replace(policy)
    if (
        projection.hypothesis_policy != policy
        or projection.result_id != result.object_id
        or projection.metric_id != result.metric_id
        or projection.hypothesis_id != policy.hypothesis_id
        or result.run_ids != (projection.execution_run_id,)
        or statistical_test.result_ids != (result.object_id,)
        or statistical_test.test_name != projection.contract_primary_test
        or statistical_test.null_hypothesis != projection.null_hypothesis
        or statistical_test.alternative != projection.alternative
        or any(
            canonical_json_bytes(thaw_json(actual)) != canonical_json_bytes(expected)
            for actual, expected in (
                (result.value, projection.state_value),
                (result.uncertainty, projection.state_uncertainty),
                (result.metadata, projection.state_metadata),
                (statistical_test.method_configuration, projection.statistical_state_method_configuration),
                (statistical_test.outcome, projection.statistical_state_outcome),
                (statistical_test.metadata, projection.statistical_state_metadata),
            )
        )
    ):
        raise ValidationError("bounded hypothesis evaluation differs from exact native canonical views")
    decision = derive_bounded_mean_result_assessment(policy, projection.numeric_result)
    if decision.hypothesis_status is not projection.hypothesis_status:
        raise ValidationError("bounded hypothesis evaluation outcome differs from interval decision")
    return HypothesisStatus(decision.hypothesis_status.value)


def _resolve_bounded_hypothesis_evaluation_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    repository: ResearchStateRepository,
    prior_stored: _StoredObject,
    result_stored: _StoredObject,
    statistical_stored: _StoredObject,
    contract: Any,
    contract_record: ArtifactRecord,
    policy: Any,
) -> dict[str, Any]:
    """Consume full current canonical owners, then the source-owned native mean.

    Never resolve historical r1 as a current Hypothesis here: Result ancestry
    owns its nonrecursive r1-to-r2 exception and complete frozen protocol.
    """

    from .scientific_design import (
        BOUNDED_MEAN_DECISION_RULE_ID,
        ScientificResultCanonicalProjectionV4,
        ScientificResultPromotionReceiptV3,
    )

    prior = prior_stored.research_object
    result = result_stored.research_object
    statistical_test = statistical_stored.research_object
    if policy.rule_id != BOUNDED_MEAN_DECISION_RULE_ID:
        raise ValidationError("bounded hypothesis evaluation requires its prospective interval policy")
    scoped = resolve_current_research_state_bindings(
        registry, ledger, run_id=repository.run_id,
        state_artifact_hashes=(result_stored.artifact.sha256, statistical_stored.artifact.sha256),
    )
    by_artifact = {item.artifact_sha256: item for item in scoped.entries}
    if set(by_artifact) != {result_stored.artifact.sha256, statistical_stored.artifact.sha256}:
        raise ValidationError("bounded hypothesis evaluation source selection differs")
    for stored in (result_stored, statistical_stored):
        binding = by_artifact[stored.artifact.sha256]
        if (binding.research_object != stored.research_object
                or binding.artifact_record_hash != stored.artifact.record_hash):
            raise ValidationError("bounded hypothesis evaluation current canonical identity differs")
    result_binding = by_artifact[result_stored.artifact.sha256]
    test_binding = by_artifact[statistical_stored.artifact.sha256]
    result_records = tuple(registry.get_metadata(digest)
                           for digest in result_binding.authority_artifact_hashes)
    statistical_records = tuple(registry.get_metadata(digest)
                                for digest in test_binding.authority_artifact_hashes)
    resolution, projection, promotion_record = repository._resolve_scientific_result_promotion_v3(
        result_records, expected_result_id=result.object_id,
        expected_execution_run_id=result.run_ids[0],
    )
    assessment = resolution.assessment
    if (
        type(projection) is not ScientificResultCanonicalProjectionV4
        or not assessment.is_bounded_mean
        or projection.contract_artifact_sha256 != contract_record.sha256
        or assessment.contract_artifact_sha256 != contract_record.sha256
        or assessment.contract_record_hash != contract_record.record_hash
        or assessment.contract_sha256 != contract.sha256
        or projection.hypothesis_policy.sha256 != policy.sha256
        or assessment.hypothesis_id != prior.object_id
        or projection.hypothesis_id != prior.object_id
    ):
        raise ValidationError("bounded hypothesis evaluation uses another native source closure")
    outcome = _bounded_hypothesis_projection_outcome(projection, policy, result, statistical_test)
    promotion = ScientificResultPromotionReceiptV3.from_dict(repository._read_authority_json(promotion_record))
    assessment_record = registry.get_metadata(promotion.checked_result_assessment_artifact_sha256)
    projection_record = registry.get_metadata(assessment.generic_ml_paired_metric_projection_authority_artifact_sha256)
    statistical_use_record = registry.get_metadata(projection.statistical_use_authority_artifact_sha256)
    if (
        projection.checked_result_assessment_artifact_sha256 != assessment_record.sha256
        or promotion.scientific_execution_authority_artifact_sha256
        != assessment.scientific_execution_authority_artifact_sha256
        or promotion.domain_validity_receipt_artifact_sha256 != assessment.domain_validity_receipt_artifact_sha256
        or projection_record.record_hash != assessment.generic_ml_paired_metric_projection_authority_record_hash
        or statistical_use_record.sha256 != assessment.statistical_use_authority_artifact_sha256
        or statistical_use_record.record_hash != assessment.statistical_use_authority_record_hash
        or statistical_use_record.record_hash != projection.statistical_use_authority_record_hash
    ):
        raise ValidationError("bounded hypothesis evaluation source record bindings differ")
    named = {
        "promotion_hash": promotion_record.sha256,
        "backend_hash": promotion.scientific_execution_authority_artifact_sha256,
        "timeline_hash": promotion.scientific_timeline_receipt_artifact_sha256,
        "confirmation_hash": promotion.confirmation_authority_artifact_sha256,
        "domain_hash": promotion.domain_validity_receipt_artifact_sha256,
        "statistics_hash": assessment.statistical_analysis_sha256,
    }
    bounded_fields = {
        "inference_profile_id": projection.inference_profile_id,
        "mean_zero_p_upper": projection.mean_zero_p_upper,
        "checked_result_assessment_artifact_hash": assessment_record.sha256,
        "checked_result_assessment_record_hash": assessment_record.record_hash,
        "paired_metric_projection_authority_artifact_hash": projection_record.sha256,
        "paired_metric_projection_authority_record_hash": projection_record.record_hash,
        "statistical_use_authority_artifact_hash": statistical_use_record.sha256,
        "statistical_use_authority_record_hash": statistical_use_record.record_hash,
    }
    blockers = tuple(name for name, eligible in (
        ("RESULT_NOT_SCIENTIFICALLY_ELIGIBLE", result_binding.scientific_evidence_eligible),
        ("STATISTICAL_TEST_NOT_SCIENTIFICALLY_ELIGIBLE", test_binding.scientific_evidence_eligible),
    ) if eligible is not True)
    source_hashes = tuple(sorted({
        prior_stored.artifact.sha256, result_stored.artifact.sha256,
        statistical_stored.artifact.sha256, contract_record.sha256,
        *(item.sha256 for item in result_records),
        *(item.sha256 for item in statistical_records),
        *named.values(), assessment_record.sha256, projection_record.sha256,
        statistical_use_record.sha256,
    }))
    for digest in source_hashes:
        registry.verify(digest, raise_on_error=True)
    return {
        "repository": repository, "prior": prior, "prior_record": prior_stored.artifact,
        "result": result, "result_record": result_stored.artifact,
        "statistical_test": statistical_test, "statistical_record": statistical_stored.artifact,
        "contract": contract, "contract_record": contract_record, "policy": policy,
        "facts": projection, "outcome": outcome, "bounded_fields": bounded_fields,
        "result_records": result_records, "statistical_records": statistical_records,
        **named, "evaluator_hash": None, "obligations_hash": None,
        "blockers": blockers, "scientific_evidence_eligible": not blockers,
        "evidence_scope": (HypothesisEvaluationEvidenceScope.SCIENTIFIC_EVIDENCE
                           if not blockers else HypothesisEvaluationEvidenceScope.NON_EVIDENTIARY_MECHANICAL),
        "source_hashes": source_hashes,
    }


def _resolve_hypothesis_evaluation_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    prior_hypothesis_state_artifact_hash: str,
    result_state_artifact_hash: str,
    statistical_test_state_artifact_hash: str,
    evaluation_contract_artifact_hash: str,
    authority_artifact_hash: str | None = None,
) -> dict[str, Any]:
    """Freshly resolve every state and scientific authority named by evaluation."""

    before = _locked_research_state_source_snapshot(registry, ledger, run_id=run_id)
    repository, stored, by_content, by_identity = _hypothesis_evaluation_repository(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hash=prior_hypothesis_state_artifact_hash,
    )
    by_artifact = {item.artifact.sha256: item for item in stored}
    if len(by_artifact) != len(stored):
        raise ValidationError("hypothesis evaluation state identity is ambiguous")
    try:
        prior_stored = by_artifact[prior_hypothesis_state_artifact_hash]
        result_stored = by_artifact[result_state_artifact_hash]
        statistical_stored = by_artifact[statistical_test_state_artifact_hash]
    except KeyError as exc:
        raise ValidationError(
            "hypothesis evaluation source state artifact is absent"
        ) from exc
    prior = prior_stored.research_object
    result = result_stored.research_object
    statistical_test = statistical_stored.research_object
    if (
        not isinstance(prior, Hypothesis)
        or not isinstance(result, Result)
        or not isinstance(statistical_test, StatisticalTest)
        or prior.revision != 1
        or prior.supersedes_content_hash is not None
        or prior.hypothesis_status is not HypothesisStatus.UNTESTED
        or prior.producer is not Role.HYPOTHESIS_DESIGNER
    ):
        raise ValidationError(
            "hypothesis evaluation requires the exact preregistered UNTESTED revision"
        )
    revisions = tuple(
        item.research_object for item in by_identity[("Hypothesis", prior.object_id)]
    )
    if len(revisions) == 1:
        if authority_artifact_hash is not None:
            # Replaying an authority before its canonical r2 is valid and
            # intentionally supports crash-safe resumption.
            pass
    elif len(revisions) == 2 and authority_artifact_hash is not None:
        latest = max(revisions, key=lambda item: item.revision)
        expected_parents = (
            ObjectReference(
                "Result",
                result.object_id,
                result.content_hash,
                "evaluated_by",
                True,
            ),
            ObjectReference(
                "StatisticalTest",
                statistical_test.object_id,
                statistical_test.content_hash,
                "evaluated_by",
                True,
            ),
        )
        if (
            not isinstance(latest, Hypothesis)
            or latest.revision != 2
            or latest.supersedes_content_hash != prior.content_hash
            or latest.parents != expected_parents
            or latest.authority_artifact_hashes != (authority_artifact_hash,)
        ):
            raise ValidationError(
                "hypothesis evaluation predecessor is stale or ambiguously revised"
            )
    else:
        raise ValidationError(
            "hypothesis evaluation predecessor is stale or ambiguously revised"
        )
    result_revisions = by_identity[("Result", result.object_id)]
    statistical_revisions = by_identity[("StatisticalTest", statistical_test.object_id)]
    if (
        len(result_revisions) != 1
        or len(statistical_revisions) != 1
        or statistical_test.result_ids != (result.object_id,)
        or statistical_test.parents
        != (
            ObjectReference(
                "Result",
                result.object_id,
                result.content_hash,
                "tests",
                True,
            ),
        )
    ):
        raise ValidationError(
            "hypothesis evaluation Result or StatisticalTest is stale or substituted"
        )
    run_parents = repository._resolved_parent_objects(result, by_content, "Run")
    if len(run_parents) != 1 or not isinstance(run_parents[0], Run):
        raise ValidationError("hypothesis evaluation Result lacks one exact Run")
    experiment_parents = repository._resolved_parent_objects(
        run_parents[0], by_content, "Experiment"
    )
    if len(experiment_parents) != 1 or not isinstance(
        experiment_parents[0], Experiment
    ):
        raise ValidationError("hypothesis evaluation Run lacks one exact Experiment")
    hypothesis_parents = repository._resolved_parent_objects(
        experiment_parents[0], by_content, "Hypothesis"
    )
    if hypothesis_parents != (prior,):
        raise ValidationError(
            "hypothesis evaluation Result was not produced for the preregistered Hypothesis"
        )

    contract_record = repository._require_frozen_pass_artifact(
        evaluation_contract_artifact_hash,
        logical_type="evaluation_contract",
        creator_role=Role.PROTOCOL_DESIGNER,
    )
    try:
        from .scientific_design import (
            CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2,
            CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3,
            HypothesisStatus as DesignHypothesisStatus,
            ScientificResultPromotionReceipt,
            evaluate_hypothesis_policy,
            require_frozen_evaluation_contract,
        )

        contract = require_frozen_evaluation_contract(
            registry,
            contract_artifact_sha256=contract_record.sha256,
        )
        wrapper = repository._read_authority_json(contract_record)
        if wrapper.get("schema_version") not in {
            CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2, CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3,
        }:
            raise ValidationError(
                "tested Hypothesis requires a prospective evaluation contract"
            )
        policy = contract.hypothesis_evaluation_policy(prior.object_id)
        design_hypothesis = contract.hypothesis_register.hypothesis(prior.object_id)
        if (
            design_hypothesis.status is not DesignHypothesisStatus.UNTESTED
            or design_hypothesis.timing.value != "PRE_SPECIFIED"
            or design_hypothesis.formed_after_observation
            or design_hypothesis.statement != prior.statement
            or design_hypothesis.motivation != prior.motivation
            or design_hypothesis.prior_evidence_ids != prior.prior_evidence_ids
            or design_hypothesis.prediction != prior.prediction
            or design_hypothesis.falsification_condition
            != prior.falsification_condition
            or (design_hypothesis.planned_experiment,) != prior.planned_experiment_ids
            or design_hypothesis.planned_experiment != experiment_parents[0].object_id
            or policy.metric_id != result.metric_id
        ):
            raise ValidationError(
                "canonical Hypothesis or Result differs from the prospective contract"
            )
        if wrapper.get("schema_version") == CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3:
            source = _resolve_bounded_hypothesis_evaluation_sources(
                registry, ledger, repository=repository, prior_stored=prior_stored,
                result_stored=result_stored, statistical_stored=statistical_stored,
                contract=contract, contract_record=contract_record, policy=policy,
            )
            if _locked_research_state_source_snapshot(registry, ledger, run_id=run_id) != before:
                raise ValidationError("bounded hypothesis evaluation sources changed during replay")
            source["source_snapshot"] = before
            return source
        facts = _hypothesis_evaluation_facts(result, statistical_test)
        design_outcome = evaluate_hypothesis_policy(policy, facts)
        outcome = HypothesisStatus(design_outcome.value)
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(
            "hypothesis evaluation contract or policy failed fresh replay"
        ) from exc

    result_resolution = repository._resolve_object_authority(result, by_content)
    statistical_resolution = repository._resolve_object_authority(
        statistical_test, by_content
    )
    result_records = result_resolution.records
    statistical_records = statistical_resolution.records
    if not result_records or not statistical_records:
        raise ValidationError(
            "hypothesis evaluation requires authoritative Result and StatisticalTest sources"
        )
    promotion_record = _one_optional_authority(
        result_records,
        frozenset({"scientific_result_promotion_authority"}),
        label="Result promotion authority",
    )
    timeline_hash: str | None = None
    backend_hash: str | None = None
    confirmation_hash: str | None = None
    domain_hash: str | None = None
    statistics_hash: str | None = None
    evaluator_hash: str | None = None
    obligations_hash: str | None = None
    if promotion_record is not None:
        try:
            promotion = ScientificResultPromotionReceipt.from_dict(
                repository._read_authority_json(promotion_record)
            )
        except Exception as exc:
            raise ValidationError(
                "hypothesis evaluation Result promotion receipt is malformed"
            ) from exc
        if promotion.contract_artifact_sha256 != contract_record.sha256:
            raise ValidationError(
                "hypothesis evaluation Result uses another evaluation contract"
            )
        timeline_hash = promotion.scientific_timeline_receipt_artifact_sha256
        backend_hash = promotion.backend_execution_authority_artifact_sha256
        confirmation_hash = promotion.confirmation_authority_artifact_sha256
        domain_hash = promotion.domain_validity_receipt_artifact_sha256
        statistics_hash = promotion.statistical_analysis_sha256
        evaluator_hash = promotion.evaluator_assessment_sha256
        obligations_hash = promotion.scientific_obligations_sha256
    else:
        statistics_record = _one_optional_authority(
            (*result_records, *statistical_records),
            frozenset({"statistical_analysis"}),
            label="statistical-analysis authority",
        )
        evaluator_record = _one_optional_authority(
            result_records,
            frozenset({"evaluator_integrity_assessment"}),
            label="evaluator authority",
        )
        domain_record = _one_optional_authority(
            result_records,
            frozenset(
                {
                    "domain_validity.generic_ml",
                    "domain_validity.medical_imaging",
                    "domain_validity.time_series",
                    "domain_validity.recommender_systems",
                    "domain_validity.operations_research",
                    "domain_validity.systems",
                }
            ),
            label="domain-validity authority",
        )
        statistics_hash = statistics_record.sha256 if statistics_record else None
        evaluator_hash = evaluator_record.sha256 if evaluator_record else None
        domain_hash = domain_record.sha256 if domain_record else None

    named = {
        "RESULT_PROMOTION_UNAVAILABLE": (
            promotion_record.sha256 if promotion_record else None
        ),
        "BACKEND_SCIENTIFIC_EXECUTION_UNAVAILABLE": backend_hash,
        "SCIENTIFIC_TIMELINE_UNAVAILABLE": timeline_hash,
        "CONFIRMATION_AUTHORITY_UNAVAILABLE": confirmation_hash,
        "DOMAIN_VALIDITY_UNAVAILABLE": domain_hash,
        "STATISTICAL_ANALYSIS_UNAVAILABLE": statistics_hash,
        "EVALUATOR_AUTHORITY_UNAVAILABLE": evaluator_hash,
        "SCIENTIFIC_OBLIGATIONS_UNAVAILABLE": obligations_hash,
    }
    blockers = tuple(name for name, value in named.items() if value is None)
    if not result_resolution.scientific_evidence_eligible:
        blockers = (*blockers, "RESULT_NOT_SCIENTIFICALLY_ELIGIBLE")
    blockers = tuple(sorted(set(blockers)))
    evidence_scope = (
        HypothesisEvaluationEvidenceScope.SCIENTIFIC_EVIDENCE
        if not blockers
        else HypothesisEvaluationEvidenceScope.NON_EVIDENTIARY_MECHANICAL
    )
    source_hashes = {
        prior_stored.artifact.sha256,
        result_stored.artifact.sha256,
        statistical_stored.artifact.sha256,
        contract_record.sha256,
        *(item.sha256 for item in result_records),
        *(item.sha256 for item in statistical_records),
        *(value for value in named.values() if value is not None),
    }
    for digest in source_hashes:
        registry.verify(digest, raise_on_error=True)
    if _locked_research_state_source_snapshot(registry, ledger, run_id=run_id) != before:
        raise ValidationError("hypothesis evaluation sources changed during replay")
    return {
        "repository": repository,
        "prior": prior,
        "prior_record": prior_stored.artifact,
        "result": result,
        "result_record": result_stored.artifact,
        "statistical_test": statistical_test,
        "statistical_record": statistical_stored.artifact,
        "contract": contract,
        "contract_record": contract_record,
        "policy": policy,
        "facts": facts,
        "outcome": outcome,
        "result_records": result_records,
        "statistical_records": statistical_records,
        "promotion_hash": promotion_record.sha256 if promotion_record else None,
        "backend_hash": backend_hash,
        "timeline_hash": timeline_hash,
        "confirmation_hash": confirmation_hash,
        "domain_hash": domain_hash,
        "statistics_hash": statistics_hash,
        "evaluator_hash": evaluator_hash,
        "obligations_hash": obligations_hash,
        "blockers": blockers,
        "evidence_scope": evidence_scope,
        "scientific_evidence_eligible": not blockers,
        "source_hashes": tuple(sorted(source_hashes)),
    }


def _hypothesis_evaluation_event_binding(
    source: Mapping[str, Any],
    *,
    authority_id: str,
) -> dict[str, Any]:
    facts = source["facts"]
    bounded = source.get("bounded_fields", {})
    return {
        "schema_version": (HYPOTHESIS_EVALUATION_EVENT_SCHEMA_V2 if bounded
                           else HYPOTHESIS_EVALUATION_EVENT_SCHEMA),
        "kind": "HYPOTHESIS_EVALUATED",
        "authority_id": authority_id,
        "hypothesis_id": source["prior"].object_id,
        "prior_hypothesis_content_hash": source["prior"].content_hash,
        "result_id": source["result"].object_id,
        "result_content_hash": source["result"].content_hash,
        "statistical_test_id": source["statistical_test"].object_id,
        "statistical_test_content_hash": source["statistical_test"].content_hash,
        "evaluation_contract_artifact_hash": source["contract_record"].sha256,
        "evaluation_policy_sha256": source["policy"].sha256,
        "outcome": source["outcome"].value,
        "evidence_scope": source["evidence_scope"].value,
        "scientific_evidence_eligible": source["scientific_evidence_eligible"],
        "facts": {
            "improvement_effect": facts.improvement_effect,
            "confidence_low": facts.confidence_low,
            "confidence_high": facts.confidence_high,
            **({"mean_zero_p_upper": facts.mean_zero_p_upper} if bounded
               else {"adjusted_p_value": facts.adjusted_p_value}),
            "sample_size": facts.sample_size,
        },
        "source_artifact_hashes": list(source["source_hashes"]),
        **{name: value for name, value in bounded.items() if name != "mean_zero_p_upper"},
    }


def _matching_hypothesis_evaluation_events(
    events: tuple[LedgerEvent, ...], binding: Mapping[str, Any],
) -> tuple[tuple[int, LedgerEvent], ...]:
    """Shared read-only v1/v2 event slot selection, with no semantic replay."""

    slot = (
        binding["hypothesis_id"],
        binding["prior_hypothesis_content_hash"],
        binding["result_content_hash"],
        binding["statistical_test_content_hash"],
        binding["evaluation_policy_sha256"],
    )
    candidates: list[tuple[int, LedgerEvent]] = []
    for index, event in enumerate(events):
        candidate = event.metadata.get("hypothesis_evaluation")
        if not isinstance(candidate, Mapping):
            continue
        candidate_slot = (
            candidate.get("hypothesis_id"),
            candidate.get("prior_hypothesis_content_hash"),
            candidate.get("result_content_hash"),
            candidate.get("statistical_test_content_hash"),
            candidate.get("evaluation_policy_sha256"),
        )
        if candidate_slot == slot or (
            binding["schema_version"] == HYPOTHESIS_EVALUATION_EVENT_SCHEMA_V2
            and candidate.get("authority_id") == binding["authority_id"]
        ):
            candidates.append((index, event))
    return tuple(candidates)


def _hypothesis_evaluation_event(
    ledger: EventLedger,
    *,
    run_id: str,
    repository: ResearchStateRepository,
    binding: Mapping[str, Any],
    source_hashes: tuple[str, ...],
    evaluated_at: str | None,
    prospective: bool = False,
) -> tuple[LedgerEvent, int]:
    events = ledger.validate(raise_on_error=True).events
    candidates = _matching_hypothesis_evaluation_events(events, binding)
    if len(candidates) > 1:
        raise ValidationError("hypothesis evaluation event branch is ambiguous")
    reason = "evaluated one preregistered hypothesis under its frozen policy"
    if candidates:
        index, event = candidates[0]
        if binding["schema_version"] == HYPOTHESIS_EVALUATION_EVENT_SCHEMA_V2 and (
            index == 0
            or event.event_id != "hyp-eval-" + sha256_bytes(canonical_json_bytes(dict(binding)))[:40]
            or event.dataset_identifiers or event.random_seeds or event.evaluator_outputs
            or event.supersedes_event_id is not None
            or (evaluated_at is not None and evaluated_at != event.timestamp)
            or event.state_before != events[index - 1].requested_state_after
        ):
            raise ValidationError("bounded hypothesis evaluation event prefix differs")
        if (
            thaw_json(event.metadata) != {"hypothesis_evaluation": dict(binding)}
            or event.run_id != run_id
            or event.actor_role is not Role.SCIENTIFIC_REVIEWER
            or event.state_before != event.requested_state_after
            or event.artifact_hashes != source_hashes
            or event.code_version != repository.code_version
            or event.configuration_hash != repository.configuration_hash
            or event.event_type != "CHECKPOINT"
            or event.reason != reason
            or event.event_hash is None
            or any(
                later.event_type == "CORRECTION"
                and later.supersedes_event_id == event.event_id
                for later in events[index + 1 :]
            )
        ):
            raise ValidationError(
                "hypothesis evaluation event is substituted or superseded"
            )
        return event, index
    if evaluated_at is None:
        raise ValidationError("hypothesis evaluation event is absent")
    _utc_timestamp(evaluated_at, "hypothesis evaluation timestamp")
    if not events or events[-1].run_id != run_id:
        raise ValidationError(
            "hypothesis evaluation requires an initialized same-run ledger"
        )
    event_id = "hyp-eval-" + sha256_bytes(canonical_json_bytes(dict(binding)))[:40]
    if prospective:
        return LedgerEvent.create(
            run_id=run_id, actor_role=Role.SCIENTIFIC_REVIEWER,
            state_before=events[-1].requested_state_after,
            requested_state_after=events[-1].requested_state_after,
            artifact_hashes=source_hashes, code_version=repository.code_version,
            configuration_hash=repository.configuration_hash, reason=reason,
            prior_event_hash=events[-1].event_hash, event_id=event_id,
            timestamp=evaluated_at, event_type="CHECKPOINT",
            metadata={"hypothesis_evaluation": dict(binding)},
        ), len(events)
    event = ledger.record(
        run_id=run_id,
        actor_role=Role.SCIENTIFIC_REVIEWER,
        state_before=events[-1].requested_state_after,
        requested_state_after=events[-1].requested_state_after,
        artifact_hashes=source_hashes,
        code_version=repository.code_version,
        configuration_hash=repository.configuration_hash,
        reason=reason,
        event_id=event_id,
        timestamp=evaluated_at,
        event_type="CHECKPOINT",
        metadata={"hypothesis_evaluation": dict(binding)},
    )
    if event.event_hash is None:  # pragma: no cover - ledger create guarantees
        raise ValidationError("hypothesis evaluation event hash is absent")
    return event, len(events)


def _hypothesis_evaluation_authority_from_source(
    source: Mapping[str, Any],
    *,
    authority_id: str,
    run_id: str,
    event: LedgerEvent,
    event_index: int,
) -> HypothesisEvaluationAuthority:
    facts = source["facts"]
    return HypothesisEvaluationAuthority(
        authority_id=authority_id,
        run_id=run_id,
        evidence_scope=source["evidence_scope"],
        hypothesis_id=source["prior"].object_id,
        prior_hypothesis_content_hash=source["prior"].content_hash,
        prior_hypothesis_state_artifact_hash=source["prior_record"].sha256,
        prior_hypothesis_state_record_hash=str(source["prior_record"].record_hash),
        result_id=source["result"].object_id,
        result_content_hash=source["result"].content_hash,
        result_state_artifact_hash=source["result_record"].sha256,
        result_state_record_hash=str(source["result_record"].record_hash),
        statistical_test_id=source["statistical_test"].object_id,
        statistical_test_content_hash=source["statistical_test"].content_hash,
        statistical_test_state_artifact_hash=source["statistical_record"].sha256,
        statistical_test_state_record_hash=str(
            source["statistical_record"].record_hash
        ),
        evaluation_contract_artifact_hash=source["contract_record"].sha256,
        evaluation_contract_record_hash=str(source["contract_record"].record_hash),
        evaluation_contract_sha256=source["contract"].sha256,
        evaluation_policy_id=source["policy"].policy_id,
        evaluation_policy_sha256=source["policy"].sha256,
        metric_id=source["policy"].metric_id,
        improvement_effect=facts.improvement_effect,
        confidence_low=facts.confidence_low,
        confidence_high=facts.confidence_high,
        adjusted_p_value=(None if source.get("bounded_fields") else facts.adjusted_p_value),
        sample_size=facts.sample_size,
        outcome=source["outcome"],
        result_authority_artifact_hashes=tuple(
            item.sha256 for item in source["result_records"]
        ),
        result_authority_record_hashes=tuple(
            str(item.record_hash) for item in source["result_records"]
        ),
        statistical_authority_artifact_hashes=tuple(
            item.sha256 for item in source["statistical_records"]
        ),
        statistical_authority_record_hashes=tuple(
            str(item.record_hash) for item in source["statistical_records"]
        ),
        scientific_result_promotion_authority_artifact_hash=source["promotion_hash"],
        backend_execution_authority_artifact_hash=source["backend_hash"],
        scientific_timeline_authority_artifact_hash=source["timeline_hash"],
        confirmation_authority_artifact_hash=source["confirmation_hash"],
        domain_validity_authority_artifact_hash=source["domain_hash"],
        statistical_analysis_authority_artifact_hash=source["statistics_hash"],
        evaluator_authority_artifact_hash=source["evaluator_hash"],
        scientific_obligations_authority_artifact_hash=source["obligations_hash"],
        blocker_codes=source["blockers"],
        scientific_evidence_eligible=source["scientific_evidence_eligible"],
        evaluation_event_id=event.event_id,
        evaluation_event_hash=str(event.event_hash),
        evaluation_event_index=event_index,
        ledger_prefix_head_hash=str(event.event_hash),
        **source.get("bounded_fields", {}),
    )


def _matching_hypothesis_evaluation_authority_slots(
    registry: ArtifactRegistry,
    records: tuple[ArtifactRecord, ...],
    authority: HypothesisEvaluationAuthority,
) -> tuple[ArtifactRecord, ...]:
    """Inventory the shared v1/v2 ID OR semantic slot before any publication."""

    slot_keys = (
        "hypothesis_id", "prior_hypothesis_content_hash", "result_content_hash",
        "statistical_test_content_hash", "evaluation_policy_sha256",
    )
    slot = tuple(getattr(authority, key) for key in slot_keys)
    matches = []
    for record in records:
        if record.logical_type != HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE:
            continue
        value = safe_json_loads(registry.get_bytes(record.sha256), max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        if not isinstance(value, Mapping) or value.get("run_id") != authority.run_id:
            continue
        if (value.get("authority_id") != authority.authority_id
                and tuple(value.get(key) for key in slot_keys) != slot):
            continue
        parsed = HypothesisEvaluationAuthority.from_dict(value)
        if (record.schema_version != parsed.artifact_schema_version
                or registry.get_bytes(record.sha256) != canonical_json_bytes(parsed.to_dict()) + b"\n"):
            raise ValidationError("hypothesis evaluation reserved slot has incompatible bytes or schema")
        matches.append(record)
    if len(matches) > 1:
        raise ValidationError("hypothesis evaluation shared authority slot is ambiguous")
    return tuple(matches)


def _require_bounded_hypothesis_evaluation_chronology(
    source: Mapping[str, Any], event: LedgerEvent, event_index: int,
    events: tuple[LedgerEvent, ...],
) -> None:
    """Require evaluation after both current canonical publications and sources."""

    repository = source["repository"]
    for object_key, record_key in (("result", "result_record"), ("statistical_test", "statistical_record")):
        stored = _StoredObject(source[object_key], source[record_key])
        matches = _matching_scoped_materialization_events(repository, stored, events)
        if len(matches) != 1 or events.index(matches[0]) >= event_index:
            raise ValidationError("bounded hypothesis evaluation precedes its exact canonical publications")
    evaluated = datetime.fromisoformat(event.timestamp.replace("Z", "+00:00"))
    for digest in source["source_hashes"]:
        created = datetime.fromisoformat(repository.registry.get_metadata(digest).created_at.replace("Z", "+00:00"))
        if created > evaluated:
            raise ValidationError("bounded hypothesis evaluation is backdated before a source")


def _preflight_bounded_hypothesis_evaluation_publication(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    source: Mapping[str, Any],
    authority_id: str,
    evaluated_at: str,
) -> tuple[HypothesisEvaluationAuthority, ArtifactRecord, LedgerEvent, bool, bool]:
    """Read-only candidate construction; no supplied DTO is scientific authority."""

    registry_snapshot, ledger_snapshot = source["source_snapshot"]
    repository = source["repository"]
    binding = _hypothesis_evaluation_event_binding(source, authority_id=authority_id)
    if binding["schema_version"] != HYPOTHESIS_EVALUATION_EVENT_SCHEMA_V2:
        raise ValidationError("bounded publication requires its distinct event schema")
    event, index = _hypothesis_evaluation_event(
        ledger, run_id=repository.run_id, repository=repository, binding=binding,
        source_hashes=source["source_hashes"], evaluated_at=evaluated_at, prospective=True,
    )
    event_missing = index == len(ledger_snapshot.events)
    _require_bounded_hypothesis_evaluation_chronology(source, event, index, ledger_snapshot.events)
    authority = _hypothesis_evaluation_authority_from_source(
        source, authority_id=authority_id, run_id=repository.run_id, event=event, event_index=index,
    )
    if authority.evaluation_binding != binding:
        raise ValidationError("bounded hypothesis evaluation event projection differs")
    content = canonical_json_bytes(authority.to_dict()) + b"\n"
    if len(content) > MAX_CANONICAL_OBJECT_BYTES or len(authority.source_artifact_hashes) > MAX_ARTIFACT_PARENTS:
        raise ValidationError("bounded hypothesis evaluation authority exceeds capacity")
    digest = sha256_bytes(content)
    object_path = registry.objects_path / digest[:2] / digest
    metadata_path = registry.metadata_path / digest[:2] / f"{digest}.json"
    expected = ArtifactRecord(
        sha256=digest, path=object_path.as_posix(), relative_path=object_path.as_posix(),
        metadata_path=metadata_path.as_posix(), logical_type=HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE,
        schema_version=authority.artifact_schema_version, mime_type="application/json", size=len(content),
        origin="source-owned prospective hypothesis evaluation authority", creator_role=Role.SCIENTIFIC_REVIEWER,
        creation_command=("scientist-one", "evaluate-hypothesis"), parent_artifacts=authority.source_artifact_hashes,
        validation_result="PASS", frozen=True, created_at=event.timestamp,
    )
    matches = _matching_hypothesis_evaluation_authority_slots(registry, registry_snapshot.records, authority)
    digest_matches = tuple(record for record in registry_snapshot.records if record.sha256 == digest)
    if matches != digest_matches or (matches and (matches[0] != expected or event_missing)):
        raise ValidationError("bounded hypothesis evaluation publication prefix conflicts")
    artifact_missing = not matches
    if registry_snapshot.count + int(artifact_missing) > MAX_REGISTRY_RECORDS:
        raise ValidationError("bounded hypothesis evaluation exceeds registry capacity")
    if event_missing:
        line = canonical_json_bytes(event.to_dict()) + b"\n"
        if (len(line) > 64 * 1024 or len(ledger_snapshot.events) + 1 > MAX_LEDGER_EVENTS
                or ledger_snapshot.valid_prefix_bytes + len(line) > MAX_LEDGER_BYTES):
            raise ValidationError("bounded hypothesis evaluation exceeds ledger capacity")
        prefix = b"".join(canonical_json_bytes(item.to_dict()) + b"\n" for item in ledger_snapshot.events)
        simulated = ledger._validate_bytes(prefix + line)
        if not simulated.valid or simulated.events != (*ledger_snapshot.events, event):
            raise ValidationError("bounded hypothesis evaluation prospective event is invalid")
    return authority, expected, event, event_missing, artifact_missing


def _register_bounded_hypothesis_evaluation_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    source: Mapping[str, Any],
    authority_id: str,
    evaluated_at: str,
) -> ArtifactRecord:
    authority, expected, event, event_missing, artifact_missing = _preflight_bounded_hypothesis_evaluation_publication(
        registry, ledger, source=source, authority_id=authority_id, evaluated_at=evaluated_at,
    )
    registry_guard = registry._open_mutation_lock()
    try:
        ledger_guard = ledger._open_lock()
        try:
            current_registry = registry._verify_all_locked(registry_guard, raise_on_error=True)
            current_ledger = ledger._validate_bytes(ledger._read_raw_locked(ledger_guard))
            if (current_registry, current_ledger) != source["source_snapshot"]:
                raise ValidationError("bounded hypothesis evaluation sources changed before commit")
            if event_missing:
                def build_event(prefix: LedgerValidationResult) -> LedgerEvent:
                    if prefix != current_ledger:
                        raise ValidationError("bounded hypothesis evaluation ledger changed during commit")
                    return event
                if ledger._append_locked(ledger_guard, build_event) != event:
                    raise ValidationError("bounded hypothesis evaluation event changed during commit")
            if artifact_missing:
                artifact = registry._put_bytes_locked(
                    registry_guard, canonical_json_bytes(authority.to_dict()) + b"\n",
                    logical_type=expected.logical_type, schema_version=expected.schema_version,
                    mime_type=expected.mime_type, origin=expected.origin, creator_role=expected.creator_role,
                    creation_command=expected.creation_command, parent_artifacts=expected.parent_artifacts,
                    validation_result=expected.validation_result, frozen=expected.frozen, created_at=expected.created_at,
                )
            else:
                artifact = registry._get_metadata_locked(registry_guard, expected.sha256)
            if artifact != expected:
                raise ValidationError("bounded hypothesis evaluation authority changed during commit")
            final_registry = registry._verify_all_locked(registry_guard, raise_on_error=True)
            final_ledger = ledger._validate_bytes(ledger._read_raw_locked(ledger_guard))
            expected_records = {item.sha256: item for item in current_registry.records}
            expected_records[expected.sha256] = expected
            expected_events = (*current_ledger.events, event) if event_missing else current_ledger.events
            if (not final_ledger.valid or final_ledger.events != expected_events
                    or {item.sha256: item for item in final_registry.records} != expected_records):
                raise ValidationError("bounded hypothesis evaluation commit has an unexpected delta")
            registry._verify_mutation_namespace(registry_guard)
        finally:
            ledger._unlock(ledger_guard)
    finally:
        registry._unlock_mutation(registry_guard)
    require_hypothesis_evaluation_authority(
        registry, ledger, authority_artifact_hash=artifact.sha256,
        expected_run_id=authority.run_id, expected_hypothesis_id=authority.hypothesis_id,
    )
    return artifact


def register_hypothesis_evaluation_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    authority_id: str,
    run_id: str,
    prior_hypothesis_state_artifact_hash: str,
    result_state_artifact_hash: str,
    statistical_test_state_artifact_hash: str,
    evaluation_contract_artifact_hash: str,
    evaluated_at: str,
) -> ArtifactRecord:
    """Evaluate a preregistered Hypothesis without accepting a caller outcome."""

    validate_identifier(authority_id, "hypothesis evaluation authority ID")
    validate_identifier(run_id, "hypothesis evaluation run ID")
    for value, label in (
        (
            prior_hypothesis_state_artifact_hash,
            "prior Hypothesis state artifact SHA-256",
        ),
        (result_state_artifact_hash, "Result state artifact SHA-256"),
        (
            statistical_test_state_artifact_hash,
            "StatisticalTest state artifact SHA-256",
        ),
        (
            evaluation_contract_artifact_hash,
            "evaluation contract artifact SHA-256",
        ),
    ):
        validate_sha256(value, label)
    _utc_timestamp(evaluated_at, "hypothesis evaluation timestamp")
    identity_candidates: list[ArtifactRecord] = []
    for artifact in registry.list_records():
        if artifact.logical_type != HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE:
            continue
        try:
            candidate = HypothesisEvaluationAuthority.from_dict(
                safe_json_loads(
                    registry.get_bytes(artifact.sha256),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
            )
        except Exception:
            continue
        if candidate.run_id == run_id and candidate.authority_id == authority_id:
            identity_candidates.append(artifact)
    if len(identity_candidates) > 1:
        raise ValidationError("hypothesis evaluation authority identity is ambiguous")
    if identity_candidates:
        existing_record = identity_candidates[0]
        existing = require_hypothesis_evaluation_authority(
            registry,
            ledger,
            authority_artifact_hash=existing_record.sha256,
            expected_run_id=run_id,
        )
        if (
            existing.prior_hypothesis_state_artifact_hash
            != prior_hypothesis_state_artifact_hash
            or existing.result_state_artifact_hash != result_state_artifact_hash
            or existing.statistical_test_state_artifact_hash
            != statistical_test_state_artifact_hash
            or existing.evaluation_contract_artifact_hash
            != evaluation_contract_artifact_hash
            or existing_record.created_at != evaluated_at
        ):
            raise ValidationError(
                "hypothesis evaluation authority identity conflicts with its source"
            )
        return existing_record
    source = _resolve_hypothesis_evaluation_sources(
        registry,
        ledger,
        run_id=run_id,
        prior_hypothesis_state_artifact_hash=prior_hypothesis_state_artifact_hash,
        result_state_artifact_hash=result_state_artifact_hash,
        statistical_test_state_artifact_hash=statistical_test_state_artifact_hash,
        evaluation_contract_artifact_hash=evaluation_contract_artifact_hash,
    )
    if source.get("bounded_fields"):
        return _register_bounded_hypothesis_evaluation_authority(
            registry, ledger, source=source, authority_id=authority_id, evaluated_at=evaluated_at,
        )
    binding = _hypothesis_evaluation_event_binding(
        source,
        authority_id=authority_id,
    )
    event, event_index = _hypothesis_evaluation_event(
        ledger,
        run_id=run_id,
        repository=source["repository"],
        binding=binding,
        source_hashes=source["source_hashes"],
        evaluated_at=evaluated_at,
    )
    authority = _hypothesis_evaluation_authority_from_source(
        source,
        authority_id=authority_id,
        run_id=run_id,
        event=event,
        event_index=event_index,
    )
    slot_candidates: list[ArtifactRecord] = []
    for artifact in registry.list_records():
        if artifact.logical_type != HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE:
            continue
        try:
            candidate = HypothesisEvaluationAuthority.from_dict(
                safe_json_loads(registry.get_bytes(artifact.sha256))
            )
        except Exception:
            continue
        if (
            candidate.run_id == run_id
            and candidate.hypothesis_id == authority.hypothesis_id
            and candidate.prior_hypothesis_content_hash
            == authority.prior_hypothesis_content_hash
            and candidate.result_content_hash == authority.result_content_hash
            and candidate.statistical_test_content_hash
            == authority.statistical_test_content_hash
            and candidate.evaluation_policy_sha256 == authority.evaluation_policy_sha256
        ):
            slot_candidates.append(artifact)
    if slot_candidates:
        if len(slot_candidates) != 1:
            raise ValidationError("hypothesis evaluation authority branch is ambiguous")
        existing = slot_candidates[0]
        if (
            registry.get_bytes(existing.sha256)
            != canonical_json_bytes(authority.to_dict()) + b"\n"
        ):
            raise ValidationError("hypothesis evaluation authority branch conflicts")
        require_hypothesis_evaluation_authority(
            registry,
            ledger,
            authority_artifact_hash=existing.sha256,
            expected_run_id=run_id,
            expected_hypothesis_id=authority.hypothesis_id,
        )
        return existing
    artifact = registry.put_json(
        authority.to_dict(),
        logical_type=HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE,
        origin="source-owned prospective hypothesis evaluation authority",
        creator_role=Role.SCIENTIFIC_REVIEWER,
        creation_command=("scientist-one", "evaluate-hypothesis"),
        parent_artifacts=authority.source_artifact_hashes,
        schema_version=authority.artifact_schema_version,
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
        created_at=evaluated_at,
    )
    require_hypothesis_evaluation_authority(
        registry,
        ledger,
        authority_artifact_hash=artifact.sha256,
        expected_run_id=run_id,
        expected_hypothesis_id=authority.hypothesis_id,
    )
    return artifact


def require_hypothesis_evaluation_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    authority_artifact_hash: str,
    expected_run_id: str,
    expected_hypothesis_id: str | None = None,
) -> HypothesisEvaluationAuthority:
    """Freshly replay one unique, uncorrected hypothesis evaluation branch."""

    validate_sha256(
        authority_artifact_hash,
        "hypothesis evaluation authority SHA-256",
    )
    validate_identifier(expected_run_id, "expected hypothesis evaluation run ID")
    if expected_hypothesis_id is not None:
        validate_identifier(
            expected_hypothesis_id,
            "expected hypothesis evaluation Hypothesis ID",
        )
    before = _locked_research_state_source_snapshot(registry, ledger, run_id=expected_run_id)
    registry.verify(authority_artifact_hash, raise_on_error=True)
    artifact = registry.get_metadata(authority_artifact_hash)
    raw = registry.get_bytes(authority_artifact_hash)
    try:
        authority = HypothesisEvaluationAuthority.from_dict(
            safe_json_loads(raw, max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1)
        )
    except Exception as exc:
        raise ValidationError(
            "hypothesis evaluation authority cannot be safely rehydrated"
        ) from exc
    if authority.run_id != expected_run_id or (
        expected_hypothesis_id is not None
        and authority.hypothesis_id != expected_hypothesis_id
    ):
        raise ValidationError("hypothesis evaluation authority identity differs")
    source = _resolve_hypothesis_evaluation_sources(
        registry,
        ledger,
        run_id=expected_run_id,
        prior_hypothesis_state_artifact_hash=(
            authority.prior_hypothesis_state_artifact_hash
        ),
        result_state_artifact_hash=authority.result_state_artifact_hash,
        statistical_test_state_artifact_hash=(
            authority.statistical_test_state_artifact_hash
        ),
        evaluation_contract_artifact_hash=(authority.evaluation_contract_artifact_hash),
        authority_artifact_hash=authority_artifact_hash,
    )
    binding = _hypothesis_evaluation_event_binding(
        source,
        authority_id=authority.authority_id,
    )
    event, event_index = _hypothesis_evaluation_event(
        ledger,
        run_id=expected_run_id,
        repository=source["repository"],
        binding=binding,
        source_hashes=source["source_hashes"],
        evaluated_at=None,
    )
    expected = _hypothesis_evaluation_authority_from_source(
        source,
        authority_id=authority.authority_id,
        run_id=expected_run_id,
        event=event,
        event_index=event_index,
    )
    if authority.is_bounded_mean:
        _require_bounded_hypothesis_evaluation_chronology(source, event, event_index, before[1].events)
    candidate_values: list[ArtifactRecord] = []
    for candidate in registry.list_records():
        if authority.is_bounded_mean:
            break
        if candidate.logical_type != HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE:
            continue
        try:
            parsed = HypothesisEvaluationAuthority.from_dict(
                safe_json_loads(
                    registry.get_bytes(candidate.sha256),
                    max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
                )
            )
        except Exception:
            continue
        if (
            parsed.run_id == authority.run_id
            and parsed.hypothesis_id == authority.hypothesis_id
            and parsed.prior_hypothesis_content_hash
            == authority.prior_hypothesis_content_hash
            and parsed.result_content_hash == authority.result_content_hash
            and parsed.statistical_test_content_hash
            == authority.statistical_test_content_hash
            and parsed.evaluation_policy_sha256 == authority.evaluation_policy_sha256
        ):
            candidate_values.append(candidate)
    candidates = (
        _matching_hypothesis_evaluation_authority_slots(registry, before[0].records, authority)
        if authority.is_bounded_mean else tuple(candidate_values)
    )
    if len(candidates) != 1:
        raise ValidationError(
            "hypothesis evaluation authority branch is absent or ambiguous"
        )
    if (
        authority != expected
        or raw != canonical_json_bytes(authority.to_dict()) + b"\n"
        or artifact.logical_type != HYPOTHESIS_EVALUATION_AUTHORITY_LOGICAL_TYPE
        or artifact.schema_version != authority.artifact_schema_version
        or artifact.mime_type != "application/json"
        or artifact.creator_role is not Role.SCIENTIFIC_REVIEWER
        or artifact.origin != "source-owned prospective hypothesis evaluation authority"
        or artifact.creation_command != ("scientist-one", "evaluate-hypothesis")
        or artifact.validation_result != "PASS"
        or artifact.frozen is not True
        or artifact.created_at != event.timestamp
        or artifact.parent_artifacts != authority.source_artifact_hashes
        or candidates[0] != artifact
    ):
        raise ValidationError(
            "hypothesis evaluation authority differs from fresh source replay"
        )
    if _locked_research_state_source_snapshot(registry, ledger, run_id=expected_run_id) != before:
        raise ValidationError("hypothesis evaluation authority sources changed during readback")
    return authority


def build_evaluated_hypothesis_revision(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    authority_artifact_hash: str,
    expected_run_id: str,
    prior_hypothesis: Hypothesis,
    created_at: str,
) -> Hypothesis:
    """Build the exact append-only r1→r2 projection from source authority."""

    if not isinstance(prior_hypothesis, Hypothesis):
        raise ValidationError("evaluated hypothesis predecessor must be Hypothesis")
    authority = require_hypothesis_evaluation_authority(
        registry,
        ledger,
        authority_artifact_hash=authority_artifact_hash,
        expected_run_id=expected_run_id,
        expected_hypothesis_id=prior_hypothesis.object_id,
    )
    if (
        prior_hypothesis.revision != 1
        or prior_hypothesis.hypothesis_status is not HypothesisStatus.UNTESTED
        or prior_hypothesis.content_hash != authority.prior_hypothesis_content_hash
    ):
        raise ValidationError(
            "evaluated hypothesis authority names another preregistered revision"
        )
    _utc_timestamp(created_at, "evaluated hypothesis revision timestamp")
    if not ResearchStateRepository._timestamp_strictly_after(
        created_at,
        registry.get_metadata(authority_artifact_hash).created_at,
    ):
        raise ValidationError(
            "evaluated hypothesis revision must follow its evaluation authority"
        )
    return revise_research_object(
        prior_hypothesis,
        producer=Role.SCIENTIFIC_REVIEWER,
        created_at=created_at,
        status=RecordStatus.COMPLETE,
        parents=(
            ObjectReference(
                "Result",
                authority.result_id,
                authority.result_content_hash,
                "evaluated_by",
                True,
            ),
            ObjectReference(
                "StatisticalTest",
                authority.statistical_test_id,
                authority.statistical_test_content_hash,
                "evaluated_by",
                True,
            ),
        ),
        authority_artifact_hashes=(authority_artifact_hash,),
        hypothesis_status=authority.outcome,
    )


def _matching_scoped_materialization_events(
    repository: ResearchStateRepository,
    item: _StoredObject,
    events: tuple[LedgerEvent, ...],
) -> tuple[LedgerEvent, ...]:
    """Match canonical publication semantics without resolving any authority.

    Event IDs alone do not establish uniqueness: a different ID can carry the
    same materialization.  Both scoped readers use this exact predicate, then
    require its sole match to be the deterministic materialization event.
    """

    record = item.research_object
    expected_operation = "MATERIALIZED" if record.revision == 1 else "SUPERSEDED"
    expected_event_type = "CHECKPOINT" if record.revision == 1 else "CORRECTION"
    return tuple(
        event
        for event in events
        if event.run_id == repository.run_id
        and event.actor_role is record.producer
        and event.timestamp == record.created_at
        and event.code_version == repository.code_version
        and event.configuration_hash == repository.configuration_hash
        and event.state_before == repository.state
        and event.requested_state_after == repository.state
        and event.event_type == expected_event_type
        and tuple(event.artifact_hashes) == (item.artifact.sha256,)
        and event.metadata.get("research_state_operation") == expected_operation
        and event.metadata.get("object_type") == record.object_type
        and event.metadata.get("object_id") == record.object_id
        and event.metadata.get("revision") == record.revision
        and event.metadata.get("content_hash") == record.content_hash
        and event.metadata.get("artifact_hash") == item.artifact.sha256
        and event.metadata.get("schema_version") == record.schema_version
        and event.metadata.get("supersedes_content_hash")
        == record.supersedes_content_hash
    )


def _resolve_current_research_state_bindings(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    state_artifact_hashes: tuple[str, ...],
    allowed_object_types: frozenset[str],
    _review_replay: _SameRoundReviewReplay | None = None,
) -> ScopedResearchStateAuthority:
    """Replay exact current named bindings without a whole-state snapshot.

    The internal type allowlist lets ClaimSemantics replay upstream evidence
    without recursing through the later Claim that consumes it.  The public
    wrapper below remains restricted to Experiment/Result/StatisticalTest.
    """

    if type(registry) is not ArtifactRegistry or type(ledger) is not EventLedger:
        raise ValidationError(
            "scoped state authority requires the concrete registry and ledger"
        )
    validate_identifier(run_id, "scoped research-state run ID")
    if (
        not isinstance(allowed_object_types, frozenset)
        or not allowed_object_types
        or not allowed_object_types.issubset(_RECORD_TYPES)
    ):
        raise ValidationError("scoped state object-type allowlist is invalid")
    _require_run_scoped_authority_paths(
        registry,
        ledger,
        run_id=run_id,
    )
    if _review_replay is not None:
        _require_same_round_review_snapshot(
            registry, ledger, replay=_review_replay, run_id=run_id,
        )
    if (
        not isinstance(state_artifact_hashes, tuple)
        or not state_artifact_hashes
        or len(state_artifact_hashes) > MAX_SEQUENCE_ITEMS
    ):
        raise ValidationError(
            "scoped state authority requires a bounded non-empty artifact tuple"
        )
    requested_hashes = _hash_tuple(
        state_artifact_hashes,
        "scoped canonical state artifact hashes",
        allow_empty=False,
    )
    if len(set(requested_hashes)) != len(requested_hashes):
        raise ValidationError("scoped state artifact hashes must be unique")

    registry.verify_all(raise_on_error=True)
    ledger_result = ledger.validate(raise_on_error=True)
    if ledger_result.head_hash is None or not ledger_result.events:
        raise ValidationError("scoped state authority requires a non-empty ledger")

    seed_hash = requested_hashes[0]
    seed_events = tuple(
        event
        for event in ledger_result.events
        if event.run_id == run_id
        and tuple(event.artifact_hashes) == (seed_hash,)
        and event.metadata.get("research_state_operation")
        in {"MATERIALIZED", "SUPERSEDED"}
        and event.metadata.get("artifact_hash") == seed_hash
    )
    if len(seed_events) != 1:
        raise ValidationError(
            "scoped state seed lacks one exact same-run materialization event"
        )
    seed_event = seed_events[0]
    seed_artifact = registry.get_metadata(seed_hash)
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=seed_event.code_version,
        configuration_hash=seed_event.configuration_hash,
        state=seed_event.state_before,
        creation_command=seed_artifact.creation_command,
    )
    stored = repository._stored_objects()
    by_content, by_identity = repository._indexes(stored)
    by_artifact = {item.artifact.sha256: item for item in stored}
    if len(by_artifact) != len(stored):
        raise ValidationError("canonical state artifact identities are ambiguous")
    targets: list[_StoredObject] = []
    for digest in requested_hashes:
        item = by_artifact.get(digest)
        if item is None:
            raise ValidationError("scoped target is not canonical research state")
        if item.research_object.object_type not in allowed_object_types:
            raise ValidationError("unsupported scoped research object type")
        targets.append(item)

    ledger_index = {
        event.event_id: index for index, event in enumerate(ledger_result.events)
    }
    validated: dict[
        str,
        tuple[_ResolvedObjectAuthority, LedgerEvent, int],
    ] = {}
    visiting: set[str] = set()
    lineage_cache: dict[tuple[str, str], tuple[_StoredObject, ...]] = {}

    def exact_event(item: _StoredObject) -> tuple[LedgerEvent, int]:
        record = item.research_object
        matches = _matching_scoped_materialization_events(
            repository, item, ledger_result.events
        )
        expected = repository._materialization_event(item.artifact.sha256, record)
        if (
            len(matches) != 1
            or expected is None
            or matches[0].event_id != expected.event_id
        ):
            raise ValidationError(
                "scoped canonical object lacks one exact materialization event"
            )
        event = matches[0]
        event_index = ledger_index.get(event.event_id)
        if event.event_hash is None or event_index is None:
            raise ValidationError("scoped materialization event is incomplete")
        return event, event_index

    def validate_lineage(identity: tuple[str, str]) -> tuple[_StoredObject, ...]:
        cached = lineage_cache.get(identity)
        if cached is not None:
            return cached
        revisions = tuple(
            sorted(
                by_identity.get(identity, ()),
                key=lambda item: item.research_object.revision,
            )
        )
        if not revisions:
            raise ValidationError("scoped canonical identity is absent")
        previous: _StoredObject | None = None
        for expected_revision, item in enumerate(revisions, start=1):
            record = item.research_object
            if record.revision != expected_revision or (
                previous is None and record.supersedes_content_hash is not None
            ):
                raise ValidationError("scoped canonical revision lineage has a gap")
            if previous is not None and (
                record.supersedes_content_hash != previous.research_object.content_hash
            ):
                raise ValidationError(
                    "scoped canonical revision does not bind its predecessor"
                )
            lineage_event, lineage_index = exact_event(item)
            successor = (
                revisions[expected_revision]
                if expected_revision < len(revisions)
                else None
            )
            allowed_correction_id = (
                f"rs-{successor.artifact.sha256[:48]}"
                if successor is not None
                else None
            )
            if any(
                event.event_type == "CORRECTION"
                and event.supersedes_event_id == lineage_event.event_id
                and event.event_id != allowed_correction_id
                for event in ledger_result.events[lineage_index + 1 :]
            ):
                raise ValidationError(
                    "scoped canonical materialization has a non-lineage correction"
                )
            if (
                record.code_version is not None
                and record.code_version != repository.code_version
            ):
                raise ValidationError(
                    "scoped canonical lineage uses another code version"
                )
            repository._validate_producer_authority(record)
            _resolve_object_with_replayed_review(
                repository, item, by_content, replay=_review_replay,
            )
            lineage_parents = set(repository._embedded_artifact_hashes(record))
            for authority_hash in lineage_parents:
                registry.verify(authority_hash, raise_on_error=True)
            for parent in record.parents:
                parent_item = by_content.get(parent.content_hash)
                if (
                    parent_item is None
                    or parent_item.research_object.object_type != parent.object_type
                    or parent_item.research_object.object_id != parent.object_id
                ):
                    raise ValidationError(
                        "scoped canonical lineage parent is missing or substituted"
                    )
                parent_event, parent_index = exact_event(parent_item)
                if parent_event.event_hash is None or parent_index >= lineage_index:
                    raise ValidationError(
                        "scoped canonical lineage became visible before its parent"
                    )
                lineage_parents.add(parent_item.artifact.sha256)
            if previous is not None:
                lineage_parents.add(previous.artifact.sha256)
            if tuple(item.artifact.parent_artifacts) != tuple(sorted(lineage_parents)):
                raise ValidationError(
                    "scoped canonical lineage registry parents differ"
                )
            if (
                item.artifact.origin
                != (
                    f"research-state:{record.object_type}:"
                    f"{record.object_id}:r{record.revision}"
                )
                or item.artifact.creation_command != repository.creation_command
            ):
                raise ValidationError(
                    "scoped canonical lineage materialization metadata differs"
                )
            if previous is not None:
                predecessor_event, predecessor_index = exact_event(previous)
                if (
                    lineage_event.supersedes_event_id != predecessor_event.event_id
                    or predecessor_index >= lineage_index
                ):
                    raise ValidationError(
                        "scoped correction does not follow and supersede its predecessor"
                    )
            previous = item
        lineage_cache[identity] = revisions
        return revisions

    def visit(item: _StoredObject) -> tuple[_ResolvedObjectAuthority, LedgerEvent, int]:
        contexts: dict[
            str,
            tuple[
                _StoredObject,
                _ResolvedObjectAuthority,
                LedgerEvent,
                int,
                tuple[_StoredObject, ...],
                bool,
            ],
        ] = {}
        stack: list[tuple[_StoredObject, int, bool]] = [(item, 0, False)]
        node_count = 0
        edge_count = 0
        while stack:
            current_item, depth, exiting = stack.pop()
            digest = current_item.artifact.sha256
            record = current_item.research_object
            if exiting:
                (
                    stored_item,
                    resolved,
                    event,
                    event_index,
                    revisions,
                    source_bound_result,
                ) = contexts[digest]
                expected_parent_artifacts = set(
                    repository._embedded_artifact_hashes(record)
                )
                for authority_hash in expected_parent_artifacts:
                    registry.verify(authority_hash, raise_on_error=True)
                for parent in record.parents:
                    parent_item = by_content[parent.content_hash]
                    parent_index = (
                        repository._validate_source_bound_parent_lineage(
                            parent_item.research_object,
                            by_content,
                        )
                        if source_bound_result
                        else validated[parent_item.artifact.sha256][2]
                    )
                    if parent_index >= event_index:
                        raise ValidationError(
                            "scoped canonical object became visible before its parent"
                        )
                    expected_parent_artifacts.add(parent_item.artifact.sha256)
                if record.revision > 1:
                    expected_parent_artifacts.add(revisions[-2].artifact.sha256)
                if tuple(stored_item.artifact.parent_artifacts) != tuple(
                    sorted(expected_parent_artifacts)
                ):
                    raise ValidationError(
                        "scoped canonical registry parents differ from exact dependencies"
                    )
                if (
                    stored_item.artifact.origin
                    != (
                        f"research-state:{record.object_type}:"
                        f"{record.object_id}:r{record.revision}"
                    )
                    or stored_item.artifact.creation_command
                    != repository.creation_command
                ):
                    raise ValidationError(
                        "scoped canonical artifact materialization metadata differs"
                    )
                for relationship in record.relationships:
                    if (
                        relationship.required
                        and (
                            relationship.object_type,
                            relationship.object_id,
                        )
                        not in by_identity
                    ):
                        raise ValidationError(
                            "scoped canonical required relationship is absent"
                        )
                visiting.remove(digest)
                validated[digest] = (resolved, event, event_index)
                continue
            if digest in validated:
                continue
            if digest in visiting:
                raise ValidationError("scoped canonical parent graph contains a cycle")
            if depth > MAX_CANONICAL_ANCESTRY_DEPTH:
                raise ValidationError(
                    "scoped canonical parent graph exceeds the ancestry depth limit"
                )
            node_count += 1
            if node_count > MAX_CANONICAL_ANCESTRY_NODES:
                raise ValidationError(
                    "scoped canonical parent graph exceeds the ancestry node limit"
                )
            edge_count += len(record.parents)
            if edge_count > MAX_CANONICAL_ANCESTRY_EDGES:
                raise ValidationError(
                    "scoped canonical parent graph exceeds the ancestry edge limit"
                )
            identity = (record.object_type, record.object_id)
            revisions = validate_lineage(identity)
            if revisions[-1].artifact.sha256 != digest:
                raise ValidationError("scoped canonical object has been superseded")
            if (
                record.code_version is not None
                and record.code_version != repository.code_version
            ):
                raise ValidationError(
                    "scoped canonical object uses another code version"
                )
            repository._validate_producer_authority(record)
            resolved = _resolve_object_with_replayed_review(
                repository, current_item, by_content, replay=_review_replay,
            )
            event, event_index = exact_event(current_item)
            source_bound_result = isinstance(record, Result) and any(
                authority.logical_type
                in {
                    "scientific_result_promotion_authority",
                    "scientific_result_promotion_authority_v3",
                }
                for authority in resolved.records
            )
            for parent in record.parents:
                parent_item = by_content.get(parent.content_hash)
                if (
                    parent_item is None
                    or parent_item.research_object.object_type != parent.object_type
                    or parent_item.research_object.object_id != parent.object_id
                ):
                    raise ValidationError(
                        "scoped canonical parent is missing or substituted"
                    )
            contexts[digest] = (
                current_item,
                resolved,
                event,
                event_index,
                revisions,
                source_bound_result,
            )
            visiting.add(digest)
            stack.append((current_item, depth, True))
            if not source_bound_result:
                for parent in reversed(record.parents):
                    stack.append((by_content[parent.content_hash], depth + 1, False))

        result = validated.get(item.artifact.sha256)
        if result is None:  # pragma: no cover - non-empty traversal proves this
            raise ValidationError("scoped canonical target was not validated")
        return result

    entries: list[ResearchStateAuthorityBinding] = []
    for item in sorted(targets, key=lambda value: value.artifact.sha256):
        resolved, event, event_index = visit(item)
        entries.append(
            ResearchStateAuthorityBinding(
                research_object=item.research_object,
                artifact_sha256=item.artifact.sha256,
                artifact_record_hash=str(item.artifact.record_hash),
                materialization_event_id=event.event_id,
                materialization_event_hash=str(event.event_hash),
                materialization_event_index=event_index,
                authority_artifact_hashes=tuple(
                    value.sha256 for value in resolved.records
                ),
                authority_artifact_record_hashes=tuple(
                    str(value.record_hash) for value in resolved.records
                ),
                authority_logical_types=tuple(
                    value.logical_type for value in resolved.records
                ),
                authority_creator_roles=tuple(
                    value.creator_role for value in resolved.records
                ),
                scientific_evidence_eligible=resolved.scientific_evidence_eligible,
                claim_semantics=resolved.claim_semantics,
            )
        )
    if _review_replay is not None:
        _require_same_round_review_snapshot(
            registry, ledger, replay=_review_replay, run_id=run_id,
        )
    return ScopedResearchStateAuthority(
        run_id=run_id,
        ledger_head_hash=ledger_result.head_hash,
        ledger_event_count=ledger_result.event_count,
        code_version=repository.code_version,
        configuration_hash=repository.configuration_hash,
        entries=tuple(entries),
    )


def resolve_current_research_state_bindings(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    state_artifact_hashes: tuple[str, ...],
) -> ScopedResearchStateAuthority:
    """Replay exact current Experiment/Result/Test bindings without a snapshot.

    This public resolver validates only the named targets and their recursive
    canonical parents.  Unrelated later objects therefore cannot create a
    soundness/state cycle, while a superseded target or ancestor, a substituted
    registry edge, or a mismatched materialization event still fails closed.
    """

    return _resolve_current_research_state_bindings(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hashes=state_artifact_hashes,
        allowed_object_types=frozenset({"Experiment", "Result", "StatisticalTest"}),
    )


@dataclass(frozen=True, slots=True)
class _ScientificExecutionProtocolContext:
    """Inert protocol identities derived from a fully replayed canonical Run.

    There is no Result, statistic, selected baseline, or scientific verdict in
    this context.  It is used only to share exact protocol comparisons between
    execution-owned Run readback and the existing Result admission owner.
    """

    contract_artifact_sha256: str
    frozen_run_spec_artifact_sha256: str
    output_manifest_artifact_sha256: str
    raw_source_artifact_hashes: tuple[str, ...]
    run_id: str
    experiment_id: str
    hypothesis_id: str
    execution_code_revision: str
    run_started_at: str
    run_completed_at: str


def _require_scientific_execution_protocol_lineage(
    repository: ResearchStateRepository,
    *,
    run: Run,
    protocol_source: _ScientificExecutionProtocolContext,
    by_content: Mapping[str, _StoredObject],
) -> None:
    """Verify exact source-bound protocol state without downstream discovery.

    The entry owner must first replay the Run's execution authority.  This
    helper adds no authority: it preserves the exact contract/spec/Method and
    Dataset/Split joins, canonical lifecycle, source hashes and materialized
    current lineage, including only the existing approved Hypothesis successor
    exception.  In particular, it never calls the general ancestor resolver,
    which may select a containing Result and recurse back into this Run.
    """

    if type(protocol_source) is not _ScientificExecutionProtocolContext:
        raise ValidationError("scientific Run protocol context is not source-derived")
    repository._validate_scientific_protocol_parent_join(
        run=run,
        protocol_source=protocol_source,
        by_content=by_content,
    )
    events = repository.ledger.events()
    event_indexes = {event.event_id: index for index, event in enumerate(events)}

    def exact_event(item: _StoredObject) -> tuple[LedgerEvent, int]:
        matches = _matching_scoped_materialization_events(repository, item, events)
        expected = repository._materialization_event(
            item.artifact.sha256, item.research_object, events=events
        )
        if (
            len(matches) != 1
            or expected is None
            or matches[0].event_id != expected.event_id
        ):
            raise ValidationError(
                "scientific Run protocol lacks one exact materialization event"
            )
        event = matches[0]
        event_index = event_indexes.get(event.event_id)
        if event.event_hash is None or event_index is None:
            raise ValidationError("scientific Run protocol materialization is incomplete")
        return event, event_index

    def validate_successor_custody(
        prior: _StoredObject, successor: _StoredObject
    ) -> None:
        # This is only the storage/currentness tail of the already-recognized
        # historical r1 -> r2 exception.  Result/Test parent events are checked,
        # never their semantic owners or their downstream ancestry.
        record = successor.research_object
        event, event_index = exact_event(successor)
        prior_event, prior_index = exact_event(prior)
        if any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in events[event_index + 1 :]
        ):
            raise ValidationError("scientific Run Hypothesis successor was corrected")
        if (
            record.code_version != repository.code_version
            or event.supersedes_event_id != prior_event.event_id
            or prior_index >= event_index
        ):
            raise ValidationError("scientific Run Hypothesis successor lineage differs")
        repository._validate_producer_authority(record)
        expected_parents = set(repository._embedded_artifact_hashes(record))
        for digest in expected_parents:
            repository.registry.verify(digest, raise_on_error=True)
        for parent in record.parents:
            parent_item = by_content.get(parent.content_hash)
            if (
                parent_item is None
                or parent_item.research_object.object_type != parent.object_type
                or parent_item.research_object.object_id != parent.object_id
            ):
                raise ValidationError("scientific Run Hypothesis successor parent differs")
            parent_record = parent_item.research_object
            parent_revisions = tuple(
                item for item in by_content.values()
                if item.research_object.object_type == parent_record.object_type
                and item.research_object.object_id == parent_record.object_id
            )
            # The evaluation source owner requires one retained Result/Test
            # revision.  An amended or withdrawn input cannot keep r2 approved
            # solely to excuse r1's otherwise-stale protocol ancestry.
            if (
                len(parent_revisions) != 1
                or parent_record.revision != 1
                or parent_record.supersedes_content_hash is not None
            ):
                raise ValidationError(
                    "scientific Run Hypothesis successor parent is stale or revised"
                )
            parent_event, parent_index = exact_event(parent_item)
            if any(
                later.event_type == "CORRECTION"
                and later.supersedes_event_id == parent_event.event_id
                for later in events[parent_index + 1 :]
            ):
                raise ValidationError(
                    "scientific Run Hypothesis successor parent was corrected"
                )
            if parent_index >= event_index:
                raise ValidationError(
                    "scientific Run Hypothesis successor precedes its parent"
                )
            expected_parents.add(parent_item.artifact.sha256)
        expected_parents.add(prior.artifact.sha256)
        if successor.artifact.parent_artifacts != tuple(sorted(expected_parents)):
            raise ValidationError("scientific Run Hypothesis successor parents differ")
        if (
            successor.artifact.origin
            != f"research-state:Hypothesis:{record.object_id}:r2"
            or successor.artifact.creation_command != repository.creation_command
        ):
            raise ValidationError("scientific Run Hypothesis successor metadata differs")

        authority = HypothesisEvaluationAuthority.from_dict(
            safe_json_loads(
                repository.registry.get_bytes(record.authority_artifact_hashes[0]),
                max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
            )
        )
        # The source-bound exception already authenticates this exact event's
        # ID/hash/index against the frozen authority.  Preserve the ordinary
        # owner's one-slot and uncorrected-event rules without deriving facts.
        evaluation_event = events[authority.evaluation_event_index]
        binding = evaluation_event.metadata["hypothesis_evaluation"]
        slot_keys = (
            "hypothesis_id", "prior_hypothesis_content_hash", "result_content_hash",
            "statistical_test_content_hash", "evaluation_policy_sha256",
        )
        slot = tuple(binding.get(key) for key in slot_keys)
        candidates = tuple(
            candidate for candidate in events
            if isinstance(candidate.metadata.get("hypothesis_evaluation"), Mapping)
            and tuple(
                candidate.metadata["hypothesis_evaluation"].get(key)
                for key in slot_keys
            ) == slot
        )
        if len(candidates) != 1:
            raise ValidationError("scientific Run Hypothesis evaluation is ambiguous")
        if any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == evaluation_event.event_id
            for later in events[authority.evaluation_event_index + 1 :]
        ):
            raise ValidationError("scientific Run Hypothesis evaluation was corrected")

    root_types = (Method, Hypothesis, Dataset, Metric, Baseline)
    protocol_types = (*root_types, Implementation, Split, Experiment, Run)
    pending: list[CanonicalResearchObject] = [run]
    seen: set[str] = set()
    while pending:
        current = pending.pop()
        if current.content_hash in seen:
            continue
        seen.add(current.content_hash)
        stored = by_content[current.content_hash]
        exact_event(stored)
        if isinstance(current, Hypothesis):
            revisions = tuple(
                item.research_object for item in by_content.values()
                if isinstance(item.research_object, Hypothesis)
                and item.research_object.object_id == current.object_id
            )
            successor = repository._source_bound_hypothesis_evaluation_successor(
                current, revisions, by_content, events
            )
            if successor is not None:
                validate_successor_custody(stored, successor)
        # The shared protocol and lineage owners have already bounded and
        # authenticated this ancestry; none of these values is a Result view.
        if (
            type(current) not in protocol_types
            or current.relationships
            or (isinstance(current, root_types) and current.parents)
            or (not isinstance(current, Run) and thaw_json(current.metadata) != {})
            or current.status
            is not (
                RecordStatus.COMPLETE
                if isinstance(current, Run)
                else RecordStatus.FROZEN
            )
        ):
            raise ValidationError("scientific Run protocol lifecycle differs")
        if not isinstance(current, Run):
            expected = repository._expected_scientific_result_ancestor_authority(
                current, protocol_source
            )
            records = repository._authority_records(current)
            if (
                tuple(sorted(current.authority_artifact_hashes)) != expected
                or tuple(sorted(item.sha256 for item in records)) != expected
            ):
                raise ValidationError("scientific Run protocol authority differs")
        # The sole Run's complete source set is checked by the execution owner
        # before this protocol-only helper; no execution verdict is reconstructed
        # from a protocol context or from its canonical ancestor labels.
        pending.extend(
            by_content[parent.content_hash].research_object for parent in current.parents
        )


def require_current_scientific_execution_run(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    run_state_artifact_sha256: str,
    expected_execution_run_id: str,
) -> ResearchStateAuthorityBinding:
    """Replay an execution-owned Run without selecting its downstream Results.

    Execution owns the Run's scientific scope; the exact frozen protocol and
    its prior-visible canonical lineage own the ancestor assertions.  A later
    Result consumes those sources and cannot become their readback authority.
    The general scoped canonical resolver deliberately remains unchanged.
    """

    validate_identifier(expected_execution_run_id, "expected execution run ID")
    validate_sha256(
        run_state_artifact_sha256,
        "canonical Run state artifact SHA-256",
    )
    before = _locked_research_state_source_snapshot(registry, ledger, run_id=run_id)
    seed_events = tuple(
        (index, event)
        for index, event in enumerate(before[1].events)
        if event.run_id == run_id
        and event.artifact_hashes == (run_state_artifact_sha256,)
        and event.metadata.get("research_state_operation")
        in {"MATERIALIZED", "SUPERSEDED"}
        and event.metadata.get("artifact_hash") == run_state_artifact_sha256
    )
    if len(seed_events) != 1:
        raise ValidationError(
            "scientific execution Run authority is absent or ambiguous"
        )
    event_index, event = seed_events[0]
    artifact = registry.get_metadata(run_state_artifact_sha256)
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=event.code_version,
        configuration_hash=event.configuration_hash,
        state=event.state_before,
        creation_command=artifact.creation_command,
    )
    stored = repository._stored_objects()
    by_content, _by_identity = repository._indexes(stored)
    selected = tuple(item for item in stored if item.artifact.sha256 == artifact.sha256)
    if len(selected) != 1:
        raise ValidationError("scientific execution Run is not canonical research state")
    record = selected[0].research_object
    if (
        not isinstance(record, Run)
        or record.object_id != expected_execution_run_id
        or thaw_json(record.metadata).get("schema_version")
        != "scientific-execution-canonical-run/v1"
    ):
        raise ValidationError(
            "canonical Run is not exact current scientific execution state"
        )
    records = repository._authority_records(record)
    resolution = repository._resolve_scientific_execution_canonical_run(
        record, records, by_content
    )
    if (
        resolution is None
        or resolution.scientific_evidence_eligible is not True
        or sum(item.logical_type == "scientific_execution_authority" for item in records)
        != 1
    ):
        raise ValidationError("canonical Run lacks exact scientific execution authority")
    from .experiments import require_scientific_execution_run_spec

    spec = require_scientific_execution_run_spec(
        registry,
        frozen_run_spec_artifact_sha256=record.output_artifact_hashes[0],
    )
    protocol_source = _ScientificExecutionProtocolContext(
        contract_artifact_sha256=spec.parent_artifacts[0],
        frozen_run_spec_artifact_sha256=record.output_artifact_hashes[0],
        output_manifest_artifact_sha256=record.output_artifact_hashes[1],
        raw_source_artifact_hashes=record.output_artifact_hashes[2:],
        run_id=record.object_id,
        experiment_id=spec.experiment_id,
        hypothesis_id=spec.hypothesis_id,
        execution_code_revision=record.code_revision,
        run_started_at=record.started_at,
        run_completed_at=record.completed_at,
    )
    _require_scientific_execution_protocol_lineage(
        repository,
        run=record,
        protocol_source=protocol_source,
        by_content=by_content,
    )
    materialization = repository._materialization_event(artifact.sha256, record)
    if materialization != event or event.event_hash is None:
        raise ValidationError("scientific execution Run materialization differs")
    binding = ResearchStateAuthorityBinding(
        research_object=record,
        artifact_sha256=artifact.sha256,
        artifact_record_hash=str(artifact.record_hash),
        materialization_event_id=event.event_id,
        materialization_event_hash=event.event_hash,
        materialization_event_index=event_index,
        authority_artifact_hashes=tuple(item.sha256 for item in records),
        authority_artifact_record_hashes=tuple(str(item.record_hash) for item in records),
        authority_logical_types=tuple(item.logical_type for item in records),
        authority_creator_roles=tuple(item.creator_role for item in records),
        scientific_evidence_eligible=resolution.scientific_evidence_eligible,
        claim_semantics=resolution.claim_semantics,
    )
    if _locked_research_state_source_snapshot(registry, ledger, run_id=run_id) != before:
        raise ValidationError("scientific execution Run sources changed during replay")
    return binding


def _locked_research_state_source_snapshot(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
) -> tuple[RegistryValidationResult, LedgerValidationResult]:
    """Capture one registry->ledger co-locked source snapshot."""

    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    registry_guard = registry._open_mutation_lock()
    try:
        ledger_guard = ledger._open_lock()
        try:
            registry_result = registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            ledger_result = ledger._validate_bytes(
                ledger._read_raw_locked(ledger_guard)
            )
            if not ledger_result.valid:
                raise ValidationError("canonical scientific source ledger is invalid")
            return registry_result, ledger_result
        finally:
            ledger._unlock(ledger_guard)
    finally:
        registry._unlock_mutation(registry_guard)


def build_scientific_reproducibility_package(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    package_id: str,
    clean_rerun_authority_artifact_sha256: str,
    original_result_state_artifact_sha256: str,
    original_run_state_artifact_sha256: str,
    rerun_run_state_artifact_sha256: str,
    created_at: str,
) -> ReproducibilityPackage:
    """Build the sole canonical package projection of one clean authority."""

    validate_identifier(run_id, "scientific reproduction ledger run ID")
    validate_identifier(package_id, "scientific reproduction package ID")
    source_state_hashes = _hash_tuple(
        (
            original_result_state_artifact_sha256,
            original_run_state_artifact_sha256,
            rerun_run_state_artifact_sha256,
        ),
        "scientific reproduction canonical source hashes",
        allow_empty=False,
    )
    if len(set(source_state_hashes)) != 3:
        raise ValidationError(
            "scientific reproduction canonical sources must be distinct"
        )
    validate_sha256(
        clean_rerun_authority_artifact_sha256,
        "scientific clean-rerun authority artifact SHA-256",
    )
    _utc_timestamp(created_at, "scientific reproduction package timestamp")
    scoped = _resolve_current_research_state_bindings(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hashes=source_state_hashes,
        allowed_object_types=frozenset({"Result", "Run"}),
    )
    by_artifact = {item.artifact_sha256: item for item in scoped.entries}
    if set(by_artifact) != set(source_state_hashes):
        raise ValidationError(
            "scientific reproduction canonical source selection changed"
        )
    result_binding = by_artifact[original_result_state_artifact_sha256]
    original_run_binding = by_artifact[original_run_state_artifact_sha256]
    rerun_run_binding = by_artifact[rerun_run_state_artifact_sha256]
    result = result_binding.research_object
    original_run = original_run_binding.research_object
    rerun_run = rerun_run_binding.research_object
    if (
        not isinstance(result, Result)
        or not isinstance(original_run, Run)
        or not isinstance(rerun_run, Run)
        or any(
            item.scientific_evidence_eligible is not True
            for item in (
                result_binding,
                original_run_binding,
                rerun_run_binding,
            )
        )
    ):
        raise ValidationError(
            "scientific reproduction requires eligible Result and Run state"
        )
    try:
        from .reproduction import require_scientific_clean_rerun_authority

        clean = require_scientific_clean_rerun_authority(
            registry,
            ledger,
            authority_artifact_sha256=(clean_rerun_authority_artifact_sha256),
            expected_ledger_run_id=run_id,
            expected_original_execution_run_id=original_run.object_id,
            expected_rerun_execution_run_id=rerun_run.object_id,
        )
    except (AuthorizationError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "scientific reproduction clean authority failed fresh replay"
        ) from exc
    clean_record = registry.get_metadata(clean_rerun_authority_artifact_sha256)
    events = ledger.events()
    if clean.verification_event_index >= len(events):
        raise ValidationError(
            "scientific reproduction clean verification event is absent"
        )
    verification_event = events[clean.verification_event_index]
    expected_created_before = (
        clean_record.created_at,
        result.created_at,
        original_run.created_at,
        rerun_run.created_at,
    )
    if (
        clean_record.record_hash is None
        or result.object_id != clean.original_result_id
        or result.run_ids != (original_run.object_id,)
        or result.evaluation_artifact_hashes
        != (clean.original_result_promotion_artifact_sha256,)
        or clean.original_execution_run_id != original_run.object_id
        or clean.rerun_execution_run_id != rerun_run.object_id
        or original_run.experiment_id != rerun_run.experiment_id
        or original_run.code_revision != rerun_run.code_revision
        or original_run.evaluator_version != rerun_run.evaluator_version
        or original_run.output_artifact_hashes[1:2]
        != (clean.original_output_manifest_artifact_sha256,)
        or rerun_run.output_artifact_hashes[1:2]
        != (clean.rerun_output_manifest_artifact_sha256,)
        or verification_event.event_id != clean.verification_event_id
        or verification_event.event_hash != clean.verification_event_hash
        or not all(
            ResearchStateRepository._timestamp_strictly_after(
                created_at,
                source_created_at,
            )
            for source_created_at in expected_created_before
        )
    ):
        raise ValidationError(
            "scientific reproduction sources disagree with clean authority"
        )
    manifest_hashes = (
        clean.original_output_manifest_artifact_sha256,
        clean.rerun_output_manifest_artifact_sha256,
    )
    environment_hashes = (
        clean.original_environment_artifact_sha256,
        clean.rerun_environment_artifact_sha256,
    )
    return ReproducibilityPackage(
        object_id=package_id,
        producer=Role.REPRODUCTION_VERIFIER,
        status=RecordStatus.COMPLETE,
        created_at=created_at,
        code_version=scoped.code_version,
        parents=(
            ObjectReference(
                "Result",
                result.object_id,
                result.content_hash,
                "reproduces",
                True,
            ),
            ObjectReference(
                "Run",
                original_run.object_id,
                original_run.content_hash,
                "packages",
                True,
            ),
            ObjectReference(
                "Run",
                rerun_run.object_id,
                rerun_run.content_hash,
                "packages",
                True,
            ),
        ),
        authority_artifact_hashes=tuple(
            sorted(
                {
                    clean_record.sha256,
                    *manifest_hashes,
                    *environment_hashes,
                }
            )
        ),
        metadata={
            "schema_version": (SCIENTIFIC_REPRODUCIBILITY_PACKAGE_METADATA_SCHEMA),
            "authority_scope": clean.authority_scope,
            "scientific_evidence": True,
            "clean_rerun_authority_artifact_sha256": clean_record.sha256,
            "original_result_id": clean.original_result_id,
            "original_result_promotion_artifact_sha256": (
                clean.original_result_promotion_artifact_sha256
            ),
            "cross_host_replication_claimed": False,
        },
        run_ids=(original_run.object_id, rerun_run.object_id),
        manifest_artifact_hashes=manifest_hashes,
        environment_artifact_hashes=environment_hashes,
        source_revision=original_run.code_revision,
        evaluator_version=original_run.evaluator_version,
        reproduction_status=ReproductionStatus(clean.outcome.value),
        reproduced_at=verification_event.timestamp,
    )


def require_scientific_reproducibility_package(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    package_state_artifact_sha256: str,
    expected_ledger_run_id: str,
    expected_package_id: str,
) -> ScientificReproducibilityPackageAuthority:
    """Freshly replay one current canonical two-run reproduction package."""

    validate_identifier(expected_package_id, "expected reproduction package ID")
    validate_sha256(
        package_state_artifact_sha256,
        "reproducibility package state artifact SHA-256",
    )
    entry_registry, entry_ledger = _locked_research_state_source_snapshot(
        registry,
        ledger,
        run_id=expected_ledger_run_id,
    )
    package_record = registry.get_metadata(package_state_artifact_sha256)
    canonical_parent_hashes = tuple(
        digest
        for digest in package_record.parent_artifacts
        if registry.get_metadata(digest).logical_type
        in {"research_state.result", "research_state.run"}
    )
    if len(canonical_parent_hashes) != 3:
        raise ValidationError(
            "scientific reproducibility package lacks exact canonical parents"
        )
    scoped = _resolve_current_research_state_bindings(
        registry,
        ledger,
        run_id=expected_ledger_run_id,
        state_artifact_hashes=(
            package_state_artifact_sha256,
            *canonical_parent_hashes,
        ),
        allowed_object_types=frozenset({"ReproducibilityPackage", "Result", "Run"}),
    )
    package_binding = scoped.binding_for_artifact(package_state_artifact_sha256)
    package = package_binding.research_object
    if (
        not isinstance(package, ReproducibilityPackage)
        or package.object_id != expected_package_id
        or package_binding.scientific_evidence_eligible is not True
    ):
        raise ValidationError(
            "canonical scientific reproducibility package identity differs"
        )
    result_bindings = tuple(
        item for item in scoped.entries if isinstance(item.research_object, Result)
    )
    run_by_id = {
        item.research_object.object_id: item
        for item in scoped.entries
        if isinstance(item.research_object, Run)
    }
    if len(result_bindings) != 1 or set(run_by_id) != set(package.run_ids):
        raise ValidationError(
            "scientific reproducibility package state closure is ambiguous"
        )
    metadata = thaw_json(package.metadata)
    clean_hash = metadata.get("clean_rerun_authority_artifact_sha256")
    validate_sha256(clean_hash, "clean-rerun package authority SHA-256")
    clean_record = registry.get_metadata(clean_hash)
    try:
        from .reproduction import require_scientific_clean_rerun_authority

        clean = require_scientific_clean_rerun_authority(
            registry,
            ledger,
            authority_artifact_sha256=clean_record.sha256,
            expected_ledger_run_id=expected_ledger_run_id,
            expected_original_execution_run_id=package.run_ids[0],
            expected_rerun_execution_run_id=package.run_ids[1],
        )
    except (AuthorizationError, ValidationError):
        raise
    except Exception as exc:
        raise ValidationError(
            "canonical package clean authority failed fresh replay"
        ) from exc
    if clean_record.record_hash is None:
        raise ValidationError("clean-rerun package authority lacks record hash")
    result = ScientificReproducibilityPackageAuthority(
        ledger_run_id=expected_ledger_run_id,
        package_binding=package_binding,
        clean_rerun_authority_artifact_sha256=clean_record.sha256,
        clean_rerun_authority_record_hash=str(clean_record.record_hash),
        clean_rerun_authority=clean,
        original_result_binding=result_bindings[0],
        run_bindings=tuple(run_by_id[run_id] for run_id in package.run_ids),
    )
    final_registry, final_ledger = _locked_research_state_source_snapshot(
        registry,
        ledger,
        run_id=expected_ledger_run_id,
    )
    if final_registry != entry_registry or final_ledger != entry_ledger:
        raise ValidationError(
            "scientific reproducibility package sources changed during replay"
        )
    return result


def _read_canonical_research_state_snapshot(
    registry: ArtifactRegistry,
    snapshot_artifact_hash: str,
) -> tuple[
    ArtifactRecord,
    tuple[str, ...],
    tuple[str, ...],
    Mapping[str, Any],
]:
    """Read the immutable snapshot projection without asserting live freshness."""

    snapshot_record = registry.get_metadata(snapshot_artifact_hash)
    expected_origin = (
        "issued canonical research-state snapshot"
        if snapshot_record.logical_type == "canonical_research_state_snapshot"
        else "issued final canonical research-state snapshot"
    )
    if (
        snapshot_record.logical_type
        not in {
            "canonical_research_state_snapshot",
            "canonical_research_state_final_snapshot",
        }
        or snapshot_record.creator_role is not Role.ORCHESTRATOR
        or snapshot_record.validation_result != "PASS"
        or snapshot_record.frozen is not True
        or snapshot_record.mime_type != "application/json"
        or snapshot_record.schema_version
        != RESEARCH_STATE_SNAPSHOT_ARTIFACT_SCHEMA_VERSION
        or snapshot_record.creation_command != RESEARCH_STATE_SNAPSHOT_CREATION_COMMAND
        or snapshot_record.origin != expected_origin
    ):
        raise ValidationError(
            "artifact is not an authoritative canonical-state snapshot"
        )
    raw_snapshot = registry.get_bytes(snapshot_artifact_hash)
    if len(raw_snapshot) > MAX_CANONICAL_OBJECT_BYTES:
        raise ValidationError(
            "canonical research-state snapshot exceeds its byte bound"
        )
    snapshot_value = safe_json_loads(raw_snapshot, max_bytes=MAX_CANONICAL_OBJECT_BYTES)
    required_keys = {
        "canonical_object_count",
        "current_artifact_hashes",
        "current_artifact_record_hashes",
        "issued_at",
        "ledger_event_count_before_snapshot",
        "ledger_head_hash_before_snapshot",
        "materialization_creation_command",
        "object_types",
        "prior_snapshot_artifact_hash",
        "repository_code_version",
        "repository_configuration_hash",
        "repository_state",
        "run_id",
        "snapshot_id",
        "snapshot_schema_version",
        "state_valid",
    }
    if (
        not isinstance(snapshot_value, Mapping)
        or raw_snapshot != canonical_json_bytes(snapshot_value) + b"\n"
        or frozenset(snapshot_value)
        not in {
            frozenset(required_keys),
            frozenset(required_keys | {"fixture_notice"}),
        }
    ):
        raise ValidationError("canonical-state snapshot payload is malformed")
    current_value = snapshot_value.get("current_artifact_hashes")
    current_record_value = snapshot_value.get("current_artifact_record_hashes")
    object_types_value = snapshot_value.get("object_types")
    materialization_command = snapshot_value.get("materialization_creation_command")
    event_count_before = snapshot_value.get("ledger_event_count_before_snapshot")
    if (
        snapshot_value.get("snapshot_schema_version")
        != RESEARCH_STATE_SNAPSHOT_PAYLOAD_SCHEMA
        or snapshot_value.get("state_valid") is not True
        or not isinstance(current_value, list)
        or not current_value
        or any(not isinstance(item, str) for item in current_value)
        or len(set(current_value)) != len(current_value)
        or current_value != sorted(current_value)
        or len(current_value) > MAX_SEQUENCE_ITEMS
        or not isinstance(current_record_value, list)
        or len(current_record_value) != len(current_value)
        or any(not isinstance(item, str) for item in current_record_value)
        or not isinstance(object_types_value, list)
        or any(not isinstance(item, str) for item in object_types_value)
        or len(set(object_types_value)) != len(object_types_value)
        or object_types_value != sorted(object_types_value)
        or any(item not in _RECORD_TYPES for item in object_types_value)
        or snapshot_value.get("canonical_object_count") != len(current_value)
        or not isinstance(materialization_command, list)
        or not materialization_command
        or any(
            not isinstance(item, str) or not item or len(item) > 4096
            for item in materialization_command
        )
        or isinstance(event_count_before, bool)
        or not isinstance(event_count_before, int)
        or event_count_before <= 0
        or event_count_before > MAX_LEDGER_EVENTS
    ):
        raise ValidationError("canonical-state snapshot claims an invalid object set")
    current_hashes = tuple(current_value)
    for digest in current_hashes:
        validate_sha256(digest, "snapshot canonical artifact SHA-256")
    for digest in current_record_value:
        validate_sha256(digest, "snapshot canonical artifact record hash")
    snapshot_run_id = snapshot_value.get("run_id")
    if not isinstance(snapshot_run_id, str):
        raise ValidationError("canonical-state snapshot run ID is malformed")
    validate_identifier(snapshot_run_id, "snapshot run ID")
    snapshot_id = snapshot_value.get("snapshot_id")
    if not isinstance(snapshot_id, str):
        raise ValidationError("canonical-state snapshot ID is malformed")
    validate_identifier(snapshot_id, "canonical-state snapshot ID")
    if snapshot_value.get("issued_at") != snapshot_record.created_at:
        raise ValidationError(
            "canonical-state snapshot timestamp differs from its payload"
        )
    _bounded_text(
        snapshot_value.get("repository_code_version"),
        "snapshot repository code version",
        maximum=512,
    )
    validate_sha256(
        snapshot_value.get("repository_configuration_hash"),
        "snapshot repository configuration SHA-256",
    )
    parse_state(snapshot_value.get("repository_state"))
    validate_sha256(
        snapshot_value.get("ledger_head_hash_before_snapshot"),
        "snapshot prior ledger head",
    )
    if "fixture_notice" in snapshot_value:
        _bounded_text(
            snapshot_value["fixture_notice"],
            "snapshot fixture notice",
            maximum=MAX_SHORT_TEXT_LENGTH,
        )
    actual_record_hashes = tuple(
        str(registry.get_metadata(digest).record_hash) for digest in current_hashes
    )
    if tuple(current_record_value) != actual_record_hashes:
        raise ValidationError(
            "canonical-state snapshot artifact-record projection is false"
        )

    prior_snapshot = snapshot_value.get("prior_snapshot_artifact_hash")
    if snapshot_record.logical_type == "canonical_research_state_snapshot":
        if (
            prior_snapshot is not None
            or snapshot_record.parent_artifacts != current_hashes
        ):
            raise ValidationError(
                "canonical-state snapshot parents differ from the declared current set"
            )
    else:
        if not isinstance(prior_snapshot, str):
            raise ValidationError(
                "final canonical-state snapshot lacks its prior snapshot identity"
            )
        validate_sha256(prior_snapshot, "prior canonical-state snapshot SHA-256")
        if snapshot_record.parent_artifacts != (prior_snapshot, *current_hashes):
            raise ValidationError(
                "final canonical-state snapshot has substituted direct parents"
            )
        prior = registry.get_metadata(prior_snapshot)
        if (
            prior.logical_type != "canonical_research_state_snapshot"
            or prior.creator_role is not Role.ORCHESTRATOR
            or prior.validation_result != "PASS"
            or prior.frozen is not True
        ):
            raise ValidationError(
                "final canonical-state snapshot lacks its exact prior snapshot"
            )
    return (
        snapshot_record,
        current_hashes,
        tuple(object_types_value),
        snapshot_value,
    )


def _research_state_snapshot_event_metadata(
    snapshot_record: ArtifactRecord,
    snapshot_value: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "artifact_record_hashes": [str(snapshot_record.record_hash)],
        "artifact_types": [snapshot_record.logical_type],
        "canonical_state_artifact_hashes": list(
            snapshot_value["current_artifact_hashes"]
        ),
        "canonical_state_artifact_record_hashes": list(
            snapshot_value["current_artifact_record_hashes"]
        ),
        "ledger_event_count_before_snapshot": snapshot_value[
            "ledger_event_count_before_snapshot"
        ],
        "ledger_head_hash_before_snapshot": snapshot_value[
            "ledger_head_hash_before_snapshot"
        ],
        "prior_snapshot_artifact_hash": snapshot_value["prior_snapshot_artifact_hash"],
        "research_state_operation": "SNAPSHOT_ISSUED",
        "snapshot_artifact_hash": snapshot_record.sha256,
        "snapshot_artifact_record_hash": str(snapshot_record.record_hash),
        "snapshot_id": snapshot_value["snapshot_id"],
        "snapshot_issued_at": snapshot_value["issued_at"],
        "snapshot_logical_type": snapshot_record.logical_type,
        "snapshot_schema_version": RESEARCH_STATE_SNAPSHOT_PAYLOAD_SCHEMA,
    }


def _event_names_research_state_snapshot(event: LedgerEvent, digest: str) -> bool:
    """Select direct snapshot subjects/references, not nested consumer context."""

    return (
        digest in event.artifact_hashes
        or event.metadata.get("snapshot_artifact_hash") == digest
    )


def _require_research_state_snapshot_issuance(
    ledger_result: LedgerValidationResult,
    *,
    snapshot_record: ArtifactRecord,
    snapshot_value: Mapping[str, Any],
) -> tuple[int, LedgerEvent]:
    """Require the exact ledger event that made a snapshot authoritative."""

    event_id = f"rss-{snapshot_record.sha256[:48]}"
    matches = tuple(
        (index, event)
        for index, event in enumerate(ledger_result.events)
        if event.event_id == event_id
    )
    if len(matches) != 1:
        raise ValidationError("canonical-state snapshot lacks one exact issuance event")
    event_index, event = matches[0]
    count_before = snapshot_value["ledger_event_count_before_snapshot"]
    head_before = snapshot_value["ledger_head_hash_before_snapshot"]
    if (
        event_index != count_before
        or count_before <= 0
        or count_before >= len(ledger_result.events)
        or ledger_result.events[count_before - 1].event_hash != head_before
    ):
        raise ValidationError(
            "canonical-state snapshot issuance prefix is absent or changed"
        )
    issued_at = datetime.fromisoformat(
        snapshot_record.created_at.replace("Z", "+00:00")
    )
    prefix_latest = max(
        datetime.fromisoformat(candidate.timestamp.replace("Z", "+00:00"))
        for candidate in ledger_result.events[:count_before]
    )
    if issued_at < prefix_latest:
        raise ValidationError("canonical-state snapshot predates its ledger prefix")
    expected = LedgerEvent.create(
        run_id=snapshot_value["run_id"],
        actor_role=Role.ORCHESTRATOR,
        state_before=parse_state(snapshot_value["repository_state"]),
        requested_state_after=parse_state(snapshot_value["repository_state"]),
        artifact_hashes=(snapshot_record.sha256,),
        code_version=snapshot_value["repository_code_version"],
        configuration_hash=snapshot_value["repository_configuration_hash"],
        reason=(
            "issued exact final canonical research-state snapshot"
            if snapshot_record.logical_type == "canonical_research_state_final_snapshot"
            else "issued exact canonical research-state snapshot"
        ),
        prior_event_hash=head_before,
        event_id=event_id,
        timestamp=snapshot_record.created_at,
        event_type="CHECKPOINT",
        metadata=_research_state_snapshot_event_metadata(
            snapshot_record,
            snapshot_value,
        ),
    )
    if event != expected:
        raise ValidationError("canonical-state snapshot issuance event was substituted")
    if any(
        candidate.event_type == "CORRECTION"
        and candidate.supersedes_event_id == event_id
        for candidate in ledger_result.events[event_index + 1 :]
    ):
        raise ValidationError("canonical-state snapshot issuance was later corrected")
    # An exact issued snapshot can be cited by downstream audit/other source
    # events. References do not issue it again and grant no consumer authority.
    # Keep damaged ownership-shaped aliases fail-closed: testing key presence
    # prevents a misspelled operation from masquerading as an ordinary use.
    issuance_fields = frozenset({
        "research_state_operation", "snapshot_artifact_hash",
        "snapshot_artifact_record_hash", "snapshot_id", "snapshot_issued_at",
        "snapshot_logical_type", "snapshot_schema_version",
    })
    for index, candidate in enumerate(ledger_result.events):
        if candidate.event_id == event_id or not _event_names_research_state_snapshot(
            candidate, snapshot_record.sha256,
        ):
            continue
        if (index < event_index or candidate.event_id.startswith("rss-")
                or issuance_fields.intersection(candidate.metadata)):
            raise ValidationError(
                "canonical-state snapshot has ambiguous ledger admissions"
            )
        if datetime.fromisoformat(candidate.timestamp.replace("Z", "+00:00")) < issued_at:
            raise ValidationError("canonical-state snapshot reference predates issuance")
    return event_index, event


def _require_final_snapshot_prior(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    ledger_result: LedgerValidationResult,
    *,
    snapshot_record: ArtifactRecord,
    snapshot_value: Mapping[str, Any],
    enclosing_prefix_count: int,
    _review_replay: _SameRoundReviewReplay | None = None,
) -> ResearchStateAuthoritySnapshot | None:
    """Replay the ordinary snapshot explicitly parented by a final snapshot."""

    if snapshot_record.logical_type != "canonical_research_state_final_snapshot":
        return None
    prior_hash = snapshot_value["prior_snapshot_artifact_hash"]
    if not isinstance(prior_hash, str):  # reader already enforces this
        raise ValidationError("final canonical-state snapshot prior is absent")
    prior_record, prior_hashes, _prior_types, prior_value = (
        _read_canonical_research_state_snapshot(registry, prior_hash)
    )
    if prior_record.logical_type != "canonical_research_state_snapshot":
        raise ValidationError("final snapshot prior is not an ordinary snapshot")
    prior_index, prior_event = _require_research_state_snapshot_issuance(
        ledger_result,
        snapshot_record=prior_record,
        snapshot_value=prior_value,
    )
    identity_fields = (
        "run_id",
        "repository_code_version",
        "repository_configuration_hash",
        "repository_state",
        "materialization_creation_command",
    )
    if (
        prior_index >= enclosing_prefix_count
        or datetime.fromisoformat(prior_record.created_at.replace("Z", "+00:00"))
        > datetime.fromisoformat(snapshot_record.created_at.replace("Z", "+00:00"))
        or any(prior_value[field] != snapshot_value[field] for field in identity_fields)
        or prior_event.event_hash is None
    ):
        raise ValidationError(
            "final canonical-state snapshot prior identity or order differs"
        )
    return _resolve_bound_research_state_authority(
        registry,
        ledger,
        run_id=prior_value["run_id"],
        snapshot_artifact_hash=prior_record.sha256,
        state_artifact_hashes=prior_hashes,
        ledger_head_hash=prior_event.event_hash,
        ledger_event_count=prior_index + 1,
        expected_code_version=prior_value["repository_code_version"],
        expected_configuration_hash=prior_value["repository_configuration_hash"],
        _review_replay=_review_replay,
    )


def register_research_state_snapshot(
    repository: ResearchStateRepository,
    *,
    snapshot_id: str,
    created_at: str,
    fixture_notice: str | None = None,
    prior_snapshot_artifact_hash: str | None = None,
) -> ArtifactRecord:
    """Atomically issue a derived whole-state snapshot and ledger checkpoint."""

    if type(repository) is not ResearchStateRepository:
        raise ValidationError(
            "snapshot issuance requires the concrete research-state repository"
        )
    validate_identifier(snapshot_id, "canonical-state snapshot ID")
    if fixture_notice is not None:
        _bounded_text(
            fixture_notice,
            "snapshot fixture notice",
            maximum=MAX_SHORT_TEXT_LENGTH,
        )
    _utc_timestamp(created_at, "snapshot creation timestamp")

    ledger_result = repository.ledger.validate(raise_on_error=True)
    repository._ensure_ledger_file_for_atomic_commit(ledger_result)
    registry_result = repository.registry.verify_all(raise_on_error=True)
    is_final = prior_snapshot_artifact_hash is not None
    logical_type = (
        "canonical_research_state_final_snapshot"
        if is_final
        else "canonical_research_state_snapshot"
    )
    origin = (
        "issued final canonical research-state snapshot"
        if is_final
        else "issued canonical research-state snapshot"
    )
    registry_records = {
        record.sha256: record for record in repository.registry.list_records()
    }
    identity_candidates: list[tuple[ArtifactRecord, Mapping[str, Any]]] = []
    for candidate in registry_records.values():
        if candidate.logical_type != logical_type:
            continue
        try:
            candidate_value = safe_json_loads(
                repository.registry.get_bytes(candidate.sha256),
                max_bytes=MAX_CANONICAL_OBJECT_BYTES + 1,
            )
        except (ArtifactError, ValidationError):
            continue
        if (
            isinstance(candidate_value, Mapping)
            and candidate_value.get("run_id") == repository.run_id
            and candidate_value.get("snapshot_id") == snapshot_id
        ):
            identity_candidates.append((candidate, candidate_value))
    if len(identity_candidates) > 1:
        raise ValidationError("canonical-state snapshot identity is ambiguous")
    existing_identity: (
        tuple[
            ArtifactRecord,
            Mapping[str, Any],
            tuple[str, ...],
            tuple[str, ...],
        ]
        | None
    ) = None
    if identity_candidates:
        candidate, candidate_value = identity_candidates[0]
        exact, hashes, types, value = _read_canonical_research_state_snapshot(
            repository.registry,
            candidate.sha256,
        )
        requested_stable = {
            "issued_at": created_at,
            "materialization_creation_command": list(repository.creation_command),
            "prior_snapshot_artifact_hash": prior_snapshot_artifact_hash,
            "repository_code_version": repository.code_version,
            "repository_configuration_hash": repository.configuration_hash,
            "repository_state": repository.state.value,
            "run_id": repository.run_id,
            "snapshot_id": snapshot_id,
            "snapshot_schema_version": RESEARCH_STATE_SNAPSHOT_PAYLOAD_SCHEMA,
            "state_valid": True,
        }
        if fixture_notice is not None:
            requested_stable["fixture_notice"] = fixture_notice
        observed_stable = {key: value[key] for key in requested_stable if key in value}
        if (
            candidate_value != value
            or exact != candidate
            or observed_stable != requested_stable
            or ("fixture_notice" in value) != (fixture_notice is not None)
        ):
            raise ValidationError("canonical-state snapshot identity collides")
        existing_event_id = f"rss-{candidate.sha256[:48]}"
        if any(event.event_id == existing_event_id for event in ledger_result.events):
            issuance_index, _issuance_event = _require_research_state_snapshot_issuance(
                ledger_result,
                snapshot_record=candidate,
                snapshot_value=value,
            )
            _require_final_snapshot_prior(
                repository.registry,
                repository.ledger,
                ledger_result,
                snapshot_record=candidate,
                snapshot_value=value,
                enclosing_prefix_count=issuance_index,
            )
            return candidate
        existing_identity = (candidate, value, hashes, types)

    stored = repository._preflight_repository_identity(
        ledger_result=ledger_result,
    )
    validation = repository.validate_state(
        expected_code_version=repository.code_version
    )
    if not validation.valid or not validation.current_artifact_hashes:
        details = "; ".join(item.detail for item in validation.issues)
        raise ValidationError(f"canonical-state snapshot source is invalid: {details}")
    _by_content, by_identity = repository._indexes(stored)
    expected_current = tuple(
        sorted(
            max(
                revisions,
                key=lambda item: item.research_object.revision,
            ).artifact.sha256
            for revisions in by_identity.values()
        )
    )
    if validation.current_artifact_hashes != expected_current:
        raise ValidationError(
            "canonical-state snapshot source changed during derivation"
        )
    if not ledger_result.events or ledger_result.head_hash is None:
        raise ValidationError(
            "canonical-state snapshot requires a non-empty ledger prefix"
        )

    current_hashes = validation.current_artifact_hashes
    if len(current_hashes) > MAX_SEQUENCE_ITEMS:
        raise ValidationError(
            "canonical-state snapshot exceeds the bounded object count"
        )
    if datetime.fromisoformat(created_at.replace("Z", "+00:00")) < max(
        datetime.fromisoformat(event.timestamp.replace("Z", "+00:00"))
        for event in ledger_result.events
    ):
        raise ValidationError(
            "canonical-state snapshot cannot predate its ledger prefix"
        )
    current_records = tuple(
        repository.registry.get_metadata(digest) for digest in current_hashes
    )
    if any(
        record.creation_command != repository.creation_command
        for record in current_records
    ):
        raise ValidationError("canonical-state snapshot mixes materialization commands")
    object_types = tuple(
        sorted(
            {repository.load_artifact(digest).object_type for digest in current_hashes}
        )
    )

    if len(current_hashes) + int(is_final) > MAX_ARTIFACT_PARENTS:
        raise ValidationError(
            "canonical-state snapshot exceeds the artifact parent bound"
        )
    if is_final:
        validate_sha256(
            prior_snapshot_artifact_hash,
            "prior canonical-state snapshot SHA-256",
        )
        (
            prior_record,
            _prior_hashes,
            _prior_types,
            prior_value,
        ) = _read_canonical_research_state_snapshot(
            repository.registry,
            prior_snapshot_artifact_hash,
        )
        if prior_record.logical_type != "canonical_research_state_snapshot":
            raise ValidationError(
                "final snapshot prior is not an initial state snapshot"
            )
        _require_research_state_snapshot_issuance(
            ledger_result,
            snapshot_record=prior_record,
            snapshot_value=prior_value,
        )

    existing: ArtifactRecord | None = None
    if existing_identity is not None:
        existing, existing_value, existing_hashes, existing_types = existing_identity
        expected_stable = {
            "canonical_object_count": len(current_hashes),
            "current_artifact_hashes": list(current_hashes),
            "current_artifact_record_hashes": [
                str(record.record_hash) for record in current_records
            ],
            "issued_at": created_at,
            "materialization_creation_command": list(repository.creation_command),
            "object_types": list(object_types),
            "prior_snapshot_artifact_hash": prior_snapshot_artifact_hash,
            "repository_code_version": repository.code_version,
            "repository_configuration_hash": repository.configuration_hash,
            "repository_state": repository.state.value,
            "run_id": repository.run_id,
            "snapshot_id": snapshot_id,
            "snapshot_schema_version": RESEARCH_STATE_SNAPSHOT_PAYLOAD_SCHEMA,
            "state_valid": True,
        }
        if fixture_notice is not None:
            expected_stable["fixture_notice"] = fixture_notice
        observed_stable = {
            key: value
            for key, value in existing_value.items()
            if key
            not in {
                "ledger_event_count_before_snapshot",
                "ledger_head_hash_before_snapshot",
            }
        }
        if (
            existing_hashes != current_hashes
            or existing_types != object_types
            or observed_stable != expected_stable
        ):
            raise ValidationError("canonical-state snapshot identity collides")
        if (
            existing_value["ledger_event_count_before_snapshot"]
            != ledger_result.event_count
            or existing_value["ledger_head_hash_before_snapshot"]
            != ledger_result.head_hash
            or any(
                _event_names_research_state_snapshot(event, existing.sha256)
                for event in ledger_result.events
            )
        ):
            raise ValidationError(
                "canonical-state snapshot orphan cannot resume after ledger change"
            )
        snapshot_value = dict(existing_value)
        snapshot_bytes = repository.registry.get_bytes(existing.sha256)
        snapshot_digest = existing.sha256
        expected_record = existing
    else:
        snapshot_value = {
            "canonical_object_count": len(current_hashes),
            "current_artifact_hashes": list(current_hashes),
            "current_artifact_record_hashes": [
                str(record.record_hash) for record in current_records
            ],
            "issued_at": created_at,
            "ledger_event_count_before_snapshot": ledger_result.event_count,
            "ledger_head_hash_before_snapshot": ledger_result.head_hash,
            "materialization_creation_command": list(repository.creation_command),
            "object_types": list(object_types),
            "prior_snapshot_artifact_hash": prior_snapshot_artifact_hash,
            "repository_code_version": repository.code_version,
            "repository_configuration_hash": repository.configuration_hash,
            "repository_state": repository.state.value,
            "run_id": repository.run_id,
            "snapshot_id": snapshot_id,
            "snapshot_schema_version": RESEARCH_STATE_SNAPSHOT_PAYLOAD_SCHEMA,
            "state_valid": True,
        }
        if fixture_notice is not None:
            snapshot_value["fixture_notice"] = fixture_notice
        snapshot_bytes = canonical_json_bytes(snapshot_value) + b"\n"
        if len(snapshot_bytes) > MAX_CANONICAL_OBJECT_BYTES:
            raise ValidationError("canonical-state snapshot exceeds byte bound")
        snapshot_digest = sha256_bytes(snapshot_bytes)
        parent_artifacts = (
            (prior_snapshot_artifact_hash, *current_hashes)
            if prior_snapshot_artifact_hash is not None
            else current_hashes
        )
        object_path = (
            repository.registry.objects_path / snapshot_digest[:2] / snapshot_digest
        )
        metadata_path = (
            repository.registry.metadata_path
            / snapshot_digest[:2]
            / f"{snapshot_digest}.json"
        )
        expected_record = ArtifactRecord(
            sha256=snapshot_digest,
            path=object_path.as_posix(),
            relative_path=object_path.as_posix(),
            metadata_path=metadata_path.as_posix(),
            logical_type=logical_type,
            schema_version=RESEARCH_STATE_SNAPSHOT_ARTIFACT_SCHEMA_VERSION,
            mime_type="application/json",
            size=len(snapshot_bytes),
            origin=origin,
            creator_role=Role.ORCHESTRATOR,
            creation_command=RESEARCH_STATE_SNAPSHOT_CREATION_COMMAND,
            parent_artifacts=parent_artifacts,
            validation_result="PASS",
            frozen=True,
            created_at=created_at,
        )
        digest_collision = registry_records.get(snapshot_digest)
        if digest_collision is not None:
            raise ValidationError("canonical-state snapshot artifact collides")
    _require_final_snapshot_prior(
        repository.registry,
        repository.ledger,
        ledger_result,
        snapshot_record=expected_record,
        snapshot_value=snapshot_value,
        enclosing_prefix_count=ledger_result.event_count,
    )
    if len(registry_records) + int(existing is None) > MAX_REGISTRY_RECORDS:
        raise ValidationError("canonical-state snapshot exceeds registry capacity")

    event_id = f"rss-{snapshot_digest[:48]}"
    if any(
        event.event_id == event_id or _event_names_research_state_snapshot(event, snapshot_digest)
        for event in ledger_result.events
    ):
        raise ValidationError("canonical-state snapshot issuance event collides")
    event_to_append = LedgerEvent.create(
        run_id=repository.run_id,
        actor_role=Role.ORCHESTRATOR,
        state_before=repository.state,
        requested_state_after=repository.state,
        artifact_hashes=(snapshot_digest,),
        code_version=repository.code_version,
        configuration_hash=repository.configuration_hash,
        reason=(
            "issued exact final canonical research-state snapshot"
            if is_final
            else "issued exact canonical research-state snapshot"
        ),
        prior_event_hash=ledger_result.head_hash,
        event_id=event_id,
        timestamp=created_at,
        event_type="CHECKPOINT",
        metadata=_research_state_snapshot_event_metadata(
            expected_record,
            snapshot_value,
        ),
    )
    event_bytes = canonical_json_bytes(event_to_append.to_dict()) + b"\n"
    if ledger_result.event_count + 1 > MAX_LEDGER_EVENTS:
        raise ValidationError("canonical-state snapshot exceeds ledger capacity")
    if ledger_result.valid_prefix_bytes + len(event_bytes) > MAX_LEDGER_BYTES:
        raise ValidationError("canonical-state snapshot exceeds ledger byte capacity")

    registry_guard = repository.registry._open_mutation_lock()
    try:
        ledger_guard = repository.ledger._open_lock()
        try:
            locked_registry = repository.registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            locked_ledger = repository.ledger._validate_bytes(
                repository.ledger._read_raw_locked(ledger_guard)
            )
            if (
                not locked_ledger.valid
                or locked_registry != registry_result
                or locked_ledger != ledger_result
            ):
                raise ValidationError(
                    "canonical-state snapshot source changed before issuance"
                )
            if existing is None:
                snapshot_record = repository.registry._put_bytes_locked(
                    registry_guard,
                    snapshot_bytes,
                    logical_type=expected_record.logical_type,
                    origin=expected_record.origin,
                    creator_role=expected_record.creator_role,
                    creation_command=expected_record.creation_command,
                    parent_artifacts=expected_record.parent_artifacts,
                    schema_version=expected_record.schema_version,
                    mime_type=expected_record.mime_type,
                    validation_result=expected_record.validation_result,
                    frozen=expected_record.frozen,
                    created_at=expected_record.created_at,
                )
            else:
                snapshot_record = repository.registry._get_metadata_locked(
                    registry_guard,
                    snapshot_digest,
                )
            if snapshot_record != expected_record:
                raise ValidationError(
                    "canonical-state snapshot changed during issuance"
                )

            def build_event(current: LedgerValidationResult) -> LedgerEvent:
                if current != locked_ledger:
                    raise ValidationError(
                        "canonical-state snapshot ledger changed during issuance"
                    )
                return event_to_append

            appended = repository.ledger._append_locked(
                ledger_guard,
                build_event,
            )
            if appended != event_to_append:
                raise ValidationError("canonical-state snapshot issuance event changed")
            repository.registry._verify_mutation_namespace(registry_guard)
        finally:
            repository.ledger._unlock(ledger_guard)
    finally:
        repository.registry._unlock_mutation(registry_guard)
    return snapshot_record


def resolve_research_state_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    snapshot_artifact_hash: str,
    expected_code_version: str | None = None,
) -> ResearchStateAuthoritySnapshot:
    """Resolve a state snapshot through live registry, ledger, and semantics.

    The returned bindings are safe downstream inputs; the serialized snapshot
    itself is never treated as proof that its booleans or object list are true.
    """

    if not isinstance(registry, ArtifactRegistry) or not isinstance(
        ledger, EventLedger
    ):
        raise ValidationError("state authority resolution requires registry and ledger")
    if registry.policy.root != ledger.policy.root:
        raise ValidationError("state authority registry and ledger roots differ")
    validate_identifier(run_id, "research-state authority run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    validate_sha256(snapshot_artifact_hash, "research-state snapshot SHA-256")
    registry.verify_all(raise_on_error=True)
    ledger_result = ledger.validate(raise_on_error=True)
    if ledger_result.head_hash is None or not ledger_result.events:
        raise ValidationError("research-state authority requires a non-empty ledger")
    snapshot_record, current_hashes, object_types_value, snapshot_value = (
        _read_canonical_research_state_snapshot(
            registry,
            snapshot_artifact_hash,
        )
    )
    issuance_index, issuance_event = _require_research_state_snapshot_issuance(
        ledger_result,
        snapshot_record=snapshot_record,
        snapshot_value=snapshot_value,
    )
    if snapshot_value["run_id"] != run_id:
        raise ValidationError("canonical snapshot belongs to another run")
    _require_final_snapshot_prior(
        registry,
        ledger,
        ledger_result,
        snapshot_record=snapshot_record,
        snapshot_value=snapshot_value,
        enclosing_prefix_count=issuance_index,
    )

    candidate_events: dict[str, tuple[int, LedgerEvent]] = {}
    code_versions: set[str] = set()
    configurations: set[str] = set()
    repository_states: set[State] = set()
    for digest in current_hashes:
        matches = tuple(
            (index, event)
            for index, event in enumerate(ledger_result.events)
            if tuple(event.artifact_hashes) == (digest,)
            and event.run_id == run_id
            and event.metadata.get("research_state_operation")
            in {"MATERIALIZED", "SUPERSEDED"}
            and event.metadata.get("artifact_hash") == digest
        )
        if len(matches) != 1:
            raise ValidationError(
                "snapshot canonical artifact lacks one exact same-run materialization event"
            )
        candidate_events[digest] = matches[0]
        if matches[0][0] >= issuance_index:
            raise ValidationError(
                "snapshot canonical artifact was materialized after issuance"
            )
        code_versions.add(matches[0][1].code_version)
        configurations.add(matches[0][1].configuration_hash)
        repository_states.add(matches[0][1].state_before)
        if matches[0][1].requested_state_after != matches[0][1].state_before:
            raise ValidationError(
                "canonical materialization event changes the macro state"
            )
    if (
        len(code_versions) != 1
        or len(configurations) != 1
        or len(repository_states) != 1
    ):
        raise ValidationError(
            "canonical snapshot mixes code, configuration, or repository state"
        )
    code_version = next(iter(code_versions))
    configuration_hash = next(iter(configurations))
    if (
        code_version != snapshot_value["repository_code_version"]
        or configuration_hash != snapshot_value["repository_configuration_hash"]
        or next(iter(repository_states)).value != snapshot_value["repository_state"]
    ):
        raise ValidationError(
            "canonical snapshot repository identity differs from its issuance"
        )
    if expected_code_version is not None and code_version != expected_code_version:
        raise ValidationError("canonical snapshot was produced by unexpected code")

    state_records = tuple(registry.get_metadata(digest) for digest in current_hashes)
    creation_commands = {item.creation_command for item in state_records}
    if len(creation_commands) != 1 or next(iter(creation_commands)) != tuple(
        snapshot_value["materialization_creation_command"]
    ):
        raise ValidationError("canonical snapshot mixes materialization commands")
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=code_version,
        configuration_hash=configuration_hash,
        state=next(iter(repository_states)),
        creation_command=next(iter(creation_commands)),
    )
    report = repository.validate_state(expected_code_version=code_version)
    if not report.valid:
        details = "; ".join(item.detail for item in report.issues)
        raise ValidationError(f"canonical research state is invalid: {details}")
    if report.current_artifact_hashes != current_hashes:
        raise ValidationError("snapshot is stale relative to live canonical state")

    stored = repository._stored_objects()
    by_content, by_identity = repository._indexes(stored)
    latest = {
        item.artifact.sha256: item
        for values in by_identity.values()
        for item in (max(values, key=lambda value: value.research_object.revision),)
    }
    if tuple(sorted(latest)) != current_hashes:
        raise ValidationError("snapshot does not name every latest canonical identity")
    observed_types = sorted(
        {item.research_object.object_type for item in latest.values()}
    )
    if observed_types != sorted(object_types_value):
        raise ValidationError("snapshot object-type projection is false")

    entries: list[ResearchStateAuthorityBinding] = []
    for digest in sorted(current_hashes):
        item = latest[digest]
        resolved = repository._resolve_object_authority(
            item.research_object, by_content
        )
        event_index, event = candidate_events[digest]
        if event.event_hash is None:
            raise ValidationError("canonical materialization event hash is absent")
        entries.append(
            ResearchStateAuthorityBinding(
                research_object=item.research_object,
                artifact_sha256=digest,
                artifact_record_hash=str(item.artifact.record_hash),
                materialization_event_id=event.event_id,
                materialization_event_hash=event.event_hash,
                materialization_event_index=event_index,
                authority_artifact_hashes=tuple(
                    value.sha256 for value in resolved.records
                ),
                authority_artifact_record_hashes=tuple(
                    str(value.record_hash) for value in resolved.records
                ),
                authority_logical_types=tuple(
                    value.logical_type for value in resolved.records
                ),
                authority_creator_roles=tuple(
                    value.creator_role for value in resolved.records
                ),
                scientific_evidence_eligible=resolved.scientific_evidence_eligible,
                claim_semantics=resolved.claim_semantics,
            )
        )
    return ResearchStateAuthoritySnapshot(
        run_id=run_id,
        snapshot_artifact_sha256=snapshot_artifact_hash,
        snapshot_artifact_record_hash=str(snapshot_record.record_hash),
        ledger_head_hash=str(issuance_event.event_hash),
        ledger_event_count=issuance_index + 1,
        code_version=code_version,
        configuration_hash=configuration_hash,
        entries=tuple(entries),
    )


def resolve_bound_research_state_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    snapshot_artifact_hash: str,
    state_artifact_hashes: tuple[str, ...],
    ledger_head_hash: str,
    ledger_event_count: int,
    expected_code_version: str,
    expected_configuration_hash: str,
) -> ResearchStateAuthoritySnapshot:
    """Replay a frozen whole-state projection after unrelated later appends.

    The snapshot and ledger prefix prove what the complete canonical state was
    when the downstream authority was issued.  Every named object and recursive
    parent is nevertheless replayed against live bytes and must remain the
    unsuperseded revision of its identity.  Later unrelated state and ledger
    appends therefore do not retroactively change an immutable paper bundle.
    """

    return _resolve_bound_research_state_authority(
        registry, ledger, run_id=run_id,
        snapshot_artifact_hash=snapshot_artifact_hash,
        state_artifact_hashes=state_artifact_hashes,
        ledger_head_hash=ledger_head_hash, ledger_event_count=ledger_event_count,
        expected_code_version=expected_code_version,
        expected_configuration_hash=expected_configuration_hash,
    )


def _resolve_bound_research_state_authority(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    run_id: str,
    snapshot_artifact_hash: str,
    state_artifact_hashes: tuple[str, ...],
    ledger_head_hash: str,
    ledger_event_count: int,
    expected_code_version: str,
    expected_configuration_hash: str,
    _review_replay: _SameRoundReviewReplay | None = None,
) -> ResearchStateAuthoritySnapshot:
    """Shared full bound owner; only exact completed reviews may be reused."""

    if type(registry) is not ArtifactRegistry or type(ledger) is not EventLedger:
        raise ValidationError(
            "bound state authority requires the concrete registry and ledger"
        )
    if registry.policy.root != ledger.policy.root:
        raise ValidationError("bound state authority registry and ledger roots differ")
    validate_identifier(run_id, "bound research-state run ID")
    _require_run_scoped_authority_paths(registry, ledger, run_id=run_id)
    if _review_replay is not None:
        _require_same_round_review_snapshot(
            registry, ledger, replay=_review_replay, run_id=run_id,
        )
        if (
            _review_replay.code_version != expected_code_version
            or _review_replay.configuration_hash != expected_configuration_hash
        ):
            raise ValidationError("same-round bound state identity changed")
    validate_sha256(snapshot_artifact_hash, "bound research-state snapshot SHA-256")
    validate_sha256(ledger_head_hash, "bound research-state ledger head")
    _bounded_text(
        expected_code_version,
        "bound research-state code version",
        maximum=512,
    )
    validate_sha256(
        expected_configuration_hash,
        "bound research-state configuration SHA-256",
    )
    if (
        isinstance(ledger_event_count, bool)
        or not isinstance(ledger_event_count, int)
        or ledger_event_count <= 0
    ):
        raise ValidationError("bound research-state ledger event count is invalid")
    expected_hashes = _hash_tuple(
        state_artifact_hashes,
        "bound canonical state artifact hashes",
        allow_empty=False,
    )
    if len(set(expected_hashes)) != len(expected_hashes) or expected_hashes != tuple(
        sorted(expected_hashes)
    ):
        raise ValidationError(
            "bound canonical state artifact hashes must be unique and canonical"
        )

    registry.verify_all(raise_on_error=True)
    ledger_result = ledger.validate(raise_on_error=True)
    snapshot_record, snapshot_hashes, object_types, snapshot_value = (
        _read_canonical_research_state_snapshot(
            registry,
            snapshot_artifact_hash,
        )
    )
    issuance_index, issuance_event = _require_research_state_snapshot_issuance(
        ledger_result,
        snapshot_record=snapshot_record,
        snapshot_value=snapshot_value,
    )
    if (
        snapshot_value["run_id"] != run_id
        or snapshot_value["repository_code_version"] != expected_code_version
        or snapshot_value["repository_configuration_hash"]
        != expected_configuration_hash
        or ledger_event_count != issuance_index + 1
        or issuance_event.event_hash != ledger_head_hash
    ):
        raise ValidationError("bound research-state snapshot issuance identity differs")
    _require_final_snapshot_prior(
        registry,
        ledger,
        ledger_result,
        snapshot_record=snapshot_record,
        snapshot_value=snapshot_value,
        enclosing_prefix_count=issuance_index,
        _review_replay=_review_replay,
    )
    if snapshot_hashes != expected_hashes:
        raise ValidationError(
            "bound research-state artifacts differ from the immutable snapshot"
        )

    scoped = _resolve_current_research_state_bindings(
        registry,
        ledger,
        run_id=run_id,
        state_artifact_hashes=expected_hashes,
        allowed_object_types=frozenset(_RECORD_TYPES),
        _review_replay=_review_replay,
    )
    entries = tuple(sorted(scoped.entries, key=lambda item: item.artifact_sha256))
    if (
        scoped.code_version != expected_code_version
        or scoped.configuration_hash != expected_configuration_hash
        or tuple(item.artifact_sha256 for item in entries) != expected_hashes
        or sorted({item.research_object.object_type for item in entries})
        != sorted(object_types)
    ):
        raise ValidationError(
            "bound research-state identity or object projection changed"
        )

    events = ledger_result.events
    state_prefix_count = snapshot_value["ledger_event_count_before_snapshot"]
    bound_event_ids: set[str] = set()
    for entry in entries:
        if entry.materialization_event_index >= state_prefix_count:
            raise ValidationError(
                "bound canonical object was materialized after the frozen prefix"
            )
        event = events[entry.materialization_event_index]
        if (
            event.event_id != entry.materialization_event_id
            or event.event_hash != entry.materialization_event_hash
        ):
            raise ValidationError("bound canonical materialization event changed")
        bound_event_ids.add(event.event_id)
    if any(
        event.event_type == "CORRECTION"
        and event.supersedes_event_id in bound_event_ids
        for event in events[ledger_event_count:]
    ):
        raise ValidationError(
            "a bound canonical materialization event was later corrected"
        )

    seed = entries[0]
    seed_event = events[seed.materialization_event_index]
    seed_artifact = registry.get_metadata(seed.artifact_sha256)
    if seed_event.state_before.value != snapshot_value[
        "repository_state"
    ] or seed_artifact.creation_command != tuple(
        snapshot_value["materialization_creation_command"]
    ):
        raise ValidationError(
            "bound research-state repository identity differs from snapshot"
        )
    repository = ResearchStateRepository(
        registry,
        ledger,
        run_id=run_id,
        code_version=expected_code_version,
        configuration_hash=expected_configuration_hash,
        state=seed_event.state_before,
        creation_command=seed_artifact.creation_command,
    )
    stored = repository._stored_objects()
    by_artifact = {item.artifact.sha256: item for item in stored}
    if len(by_artifact) != len(stored):
        raise ValidationError("bound canonical artifact identities are ambiguous")
    prefix_latest: dict[tuple[str, str], tuple[_StoredObject, LedgerEvent]] = {}
    for index, event in enumerate(events[:state_prefix_count]):
        operation = event.metadata.get("research_state_operation")
        if operation not in {"MATERIALIZED", "SUPERSEDED"}:
            continue
        if (
            len(event.artifact_hashes) != 1
            or event.metadata.get("artifact_hash") != event.artifact_hashes[0]
        ):
            raise ValidationError("bound prefix contains a malformed state event")
        item = by_artifact.get(event.artifact_hashes[0])
        if item is None:
            raise ValidationError("bound prefix state event has no canonical artifact")
        if item.artifact.creation_command != repository.creation_command:
            raise ValidationError("bound prefix mixes repository creation commands")
        exact = repository._materialization_event(
            item.artifact.sha256,
            item.research_object,
        )
        if exact is None or exact.event_id != event.event_id:
            raise ValidationError("bound prefix state event differs from its artifact")
        identity = (
            item.research_object.object_type,
            item.research_object.object_id,
        )
        previous = prefix_latest.get(identity)
        if item.research_object.revision == 1:
            if previous is not None or operation != "MATERIALIZED":
                raise ValidationError("bound prefix canonical lineage is ambiguous")
        else:
            if (
                previous is None
                or operation != "SUPERSEDED"
                or item.research_object.revision
                != previous[0].research_object.revision + 1
                or item.research_object.supersedes_content_hash
                != previous[0].research_object.content_hash
                or event.supersedes_event_id != previous[1].event_id
            ):
                raise ValidationError("bound prefix canonical lineage has a gap")
        prefix_latest[identity] = (item, event)
        if event.event_hash is None or index >= state_prefix_count:
            raise ValidationError("bound prefix state event is incomplete")
    if {item.artifact.sha256 for item, _event in prefix_latest.values()} != set(
        expected_hashes
    ):
        raise ValidationError(
            "snapshot was not the complete canonical state at the bound prefix"
        )

    if _review_replay is not None:
        _require_same_round_review_snapshot(
            registry, ledger, replay=_review_replay, run_id=run_id,
        )
    return ResearchStateAuthoritySnapshot(
        run_id=run_id,
        snapshot_artifact_sha256=snapshot_artifact_hash,
        snapshot_artifact_record_hash=str(snapshot_record.record_hash),
        ledger_head_hash=ledger_head_hash,
        ledger_event_count=ledger_event_count,
        code_version=expected_code_version,
        configuration_hash=expected_configuration_hash,
        entries=entries,
    )


def render_markdown(record: CanonicalResearchObject) -> str:
    if not isinstance(record, CanonicalResearchObject):
        raise ValidationError("Markdown view requires a typed research object")
    return record.to_markdown()


